ioBaseChar::~ioBaseChar()
{
	SAFEDELETE( m_pCharSpeicalState );

	if( IsNeedProcess() )
	{
		m_FishingResultInfo.ClearInfo();
	}

	ClearAttackFireTimeAndSkill();
	
	ErrorReport::SetPosition( 1250, 1 );
	ErrorReport::SetFormat( "" );

	for( int i=0 ; i<3 ; i++ )
	{
		EndMapEffect( m_ChampObjID[i], false );
		m_ChampObjID[i] = -1;
	}

	ErrorReport::SetPosition( 1250, 2 );

	RemoveAllBuff();

	ErrorReport::SetPosition( 1250, 3 );
	ReleaseObejctEquipState();
	ErrorReport::SetPosition( 1250, 4 );
	ReleaseWeaponItemState();
	ErrorReport::SetPosition( 1250, 5 );
	DestroyMagicCircle();
	ErrorReport::SetPosition( 1250, 6 );

	SAFEDELETE( m_aBuffArray );	
	ErrorReport::SetPosition( 1250, 10 );

	SAFEDELETE( m_pAniCollisionBoxGrp );
	ErrorReport::SetPosition( 1250, 11 );
	SAFEDELETE( m_pWoundedCollisionBoxGrp );
	ErrorReport::SetPosition( 1250, 12 );
	SAFEDELETE( m_pSpecialBox );
	ErrorReport::SetPosition( 1250, 13 );

	SAFEDELETE( m_pEquipSlot );
	ErrorReport::SetPosition( 1250, 14 );

	SAFEDELETE( m_pDefaultPriority );
	ErrorReport::SetPosition( 1250, 19 );
	SAFEDELETE( m_pExtendDash );
	ErrorReport::SetPosition( 1250, 20 );
	SAFEDELETE( m_pExtendJump );
	SAFEDELETE( m_pCounterAttack );
	ErrorReport::SetPosition( 1250, 21 );
	SAFEDELETE( m_pPushPowerEnhance );
	ErrorReport::SetPosition( 1250, 22 );
	SAFEDELETE( m_pWoundPushPowerEnhance );
	ErrorReport::SetPosition( 1250, 23 );

	m_WoundedRateList.clear();
	m_vAniRotateInfoList.clear();
	m_ReserveBuffInfoList.clear();
	m_vDamageDefenseBuffInfoList.clear();
	ErrorReport::SetPosition( 1250, 24 );

	m_dwAttachWeaponIndex = 0;

	// Roulette
	m_RouletteState = RS_NONE;
	m_dwRouletteAniEndTime = 0;
	m_bSetRouletteEmoticon = false;
	m_fCurRouletteAniMoveSpeed = 0.0f;

	m_bEnableDashOnHideBuff = false;

	m_vBuffOnDoubleJumpBuff.clear();
	m_bSetBuffOnDoubleJumpBuff = false;

	m_dwExtendJumpAttackEndTime = 0;
	m_fExtendJumpAttackEndJumpAmt = 0.0f;
	ErrorReport::SetPosition( 1250, 25 );

	std::vector<ioChampionAI*> vCopyAI = m_vecChampionAI;
	int nSize = vCopyAI.size();
	for( int i = 0; i < nSize; ++i )
		vCopyAI[i]->ChangeTarget();
	ErrorReport::SetPosition( 1250, 26 );
}

