void ioBaseChar::SetTargetRotAndMoveDirChange( const D3DXQUATERNION &qtRot, bool bRotateOnly )
{
	SetTargetRot( qtRot );

	if( !bRotateOnly )
	{
		SetMoveDirByRotate( qtRot );
	}
}

void ioBaseChar::SetTargetRot( const D3DXQUATERNION &qtRot )
{
	m_qtTargetRot = qtRot;
	D3DXVECTOR3 vAngle;
	Quat2Angle( m_qtTargetRot, vAngle );
	OutputVec2Half( vAngle, m_halfRot );
}

void ioBaseChar::SetMoveDirection( const D3DXVECTOR3 &vDir )
{
	m_vMoveDir = vDir;
	UpdateMoveDir2BYTE();
}

void ioBaseChar::SetMoveDirByRotate( const D3DXQUATERNION &qtRot )
{
	m_vMoveDir = qtRot * D3DXVECTOR3( 0.0f, 0.0f, -FLOAT1 );
	D3DXVec3Normalize( &m_vMoveDir, &m_vMoveDir );
	UpdateMoveDir2BYTE();
}

void ioBaseChar::SetInputDirection( const D3DXVECTOR3 &vDir )
{
	m_vInputDir = vDir;
	UpdateInputDir2BYTE();
}

void ioBaseChar::SetTargetRotToTargetPos( const ioBaseChar *pTarget,
										  bool bImmediately,
										  bool bRotateOnly )
{
	ioDummyChar *pDummy = FindDummyChar( m_AutoTargetType );
	ioBall *pBall = FindBall();
	if( pTarget )
	{
		D3DXVECTOR3 vAimedDir = pTarget->GetWorldPosition() - GetWorldPosition();
		D3DXVec3Normalize( &vAimedDir, &vAimedDir );

		D3DXVECTOR3 vXZDir( vAimedDir.x, 0.0f, vAimedDir.z );
		D3DXVec3Normalize( &vXZDir, &vXZDir );

		D3DXQUATERNION qtRot;
		ioMath::CalcDirectionQuaternion( qtRot, -vXZDir );

		m_ForceSightTarget = pTarget->GetCharName();

		if( bImmediately )
		{
			SetTargetRotAndMoveDirChange( qtRot, bRotateOnly );
			SetWorldOrientation( qtRot );
		}
		else
		{
			SetTargetRotAndMoveDirChange( qtRot, bRotateOnly );
		}
	}
	else if( m_bAutoTargetBall && pBall )
	{
		D3DXVECTOR3 vAimedDir = pBall->GetWorldPosition() - GetWorldPosition();
		D3DXVec3Normalize( &vAimedDir, &vAimedDir );

		D3DXVECTOR3 vXZDir( vAimedDir.x, 0.0f, vAimedDir.z );
		D3DXVec3Normalize( &vXZDir, &vXZDir );

		D3DXQUATERNION qtRot;
		ioMath::CalcDirectionQuaternion( qtRot, -vXZDir );

		m_ForceSightTarget.Clear();

		if( bImmediately )
		{
			SetTargetRotAndMoveDirChange( qtRot, bRotateOnly );
			SetWorldOrientation( qtRot );
		}
		else
		{
			SetTargetRotAndMoveDirChange( qtRot, bRotateOnly );
		}
	}
	else if( m_bAutoTargetDummyChar && pDummy )
	{
		D3DXVECTOR3 vAimedDir = pDummy->GetWorldPosition() - GetWorldPosition();
		D3DXVec3Normalize( &vAimedDir, &vAimedDir );

		D3DXVECTOR3 vXZDir( vAimedDir.x, 0.0f, vAimedDir.z );
		D3DXVec3Normalize( &vXZDir, &vXZDir );

		D3DXQUATERNION qtRot;
		ioMath::CalcDirectionQuaternion( qtRot, -vXZDir );

		m_ForceSightTarget.Clear();

		if( bImmediately )
		{
			SetTargetRotAndMoveDirChange( qtRot, bRotateOnly );
			SetWorldOrientation( qtRot );
		}
		else
		{
			SetTargetRotAndMoveDirChange( qtRot, bRotateOnly );
		}
	}
}

void ioBaseChar::SetTargetRotToTargetPos( const D3DXVECTOR3 &vPos,
										  bool bImmediately,
										  bool bRotateOnly )
{
	D3DXVECTOR3 vAimedDir = vPos - GetWorldPosition();
	D3DXVec3Normalize( &vAimedDir, &vAimedDir );

	D3DXVECTOR3 vXZDir( vAimedDir.x, 0.0f, vAimedDir.z );
	D3DXVec3Normalize( &vXZDir, &vXZDir );

	if( vXZDir == ioMath::VEC3_ZERO )
		return;

	D3DXQUATERNION qtRot;
	ioMath::CalcDirectionQuaternion( qtRot, -vXZDir );

	m_ForceSightTarget.Clear();

	if( bImmediately )
	{
		SetTargetRotAndMoveDirChange( qtRot, bRotateOnly );
		SetWorldOrientation( qtRot );
	}
	else
	{
		SetTargetRotAndMoveDirChange( qtRot, bRotateOnly );
	}
}

void ioBaseChar::SetTargetRotToRotate( const D3DXQUATERNION &qtRot, bool bImmediately, bool bRotateOnly )
{
	m_ForceSightTarget.Clear();

	if( bImmediately )
	{
		SetTargetRotAndMoveDirChange( qtRot, bRotateOnly );
		SetWorldOrientation( qtRot );
	}
	else
	{
		SetTargetRotAndMoveDirChange( qtRot, bRotateOnly );
	}
}

void ioBaseChar::SetTargetRotToDir( const D3DXVECTOR3 &vDir,
									bool bImmediately,
									bool bRotateOnly )
{
	D3DXVECTOR3 vAimedDir = vDir;
	D3DXVec3Normalize( &vAimedDir, &vAimedDir );

	D3DXVECTOR3 vXZDir( vAimedDir.x, 0.0f, vAimedDir.z );
	D3DXVec3Normalize( &vXZDir, &vXZDir );

	if( vXZDir == ioMath::VEC3_ZERO )
		return;

	D3DXQUATERNION qtRot;
	ioMath::CalcDirectionQuaternion( qtRot, -vXZDir );

	m_ForceSightTarget.Clear();

	if( bImmediately )
	{
		SetTargetRotAndMoveDirChange( qtRot, bRotateOnly );
		SetWorldOrientation( qtRot );
	}
	else
	{
		SetTargetRotAndMoveDirChange( qtRot, bRotateOnly );
	}
}

void ioBaseChar::SetTargetRotToDirKey( ioUserKeyInput::DirKeyInput eDirKey )
{
	if( eDirKey != ioUserKeyInput::DKI_NONE )
	{
		float fYawD = 180.0f + 45.0f * ( eDirKey - ioUserKeyInput::DKI_UP );
		fYawD = ioMath::ArrangeHead( fYawD );

		float fYawR = DEGtoRAD( fYawD );
		D3DXQUATERNION qtRotate;
		D3DXQuaternionRotationYawPitchRoll( &qtRotate, fYawR, 0.0f, 0.0f );

		m_CurDirKey = eDirKey;

		SetTargetRot( qtRotate );
		SetMoveDirByRotate( qtRotate );
	}
}

void ioBaseChar::SetCurMoveSpeed( float fSpeed )
{
	m_fCurMoveSpeed = fSpeed;
}

float ioBaseChar::GetCurSpeed()
{
	return m_fCurMoveSpeed;
}

float ioBaseChar::GetAccelSpeed() const
{
	return m_fMoveAccelSpeed * m_fSpeedRate;
}

float ioBaseChar::GetMaxSpeed( bool bExtra ) const
{
	float fMaxSpeed = (m_fMaxMoveSpeed + m_fExtraMoveSpeed) * m_fSpeedRate;
	if( fMaxSpeed < 0.0f )
		fMaxSpeed = 0.0f;

	if( !bExtra && (m_CharState == CS_USING_SKILL || m_CharState == CS_DELAY) )
		fMaxSpeed = m_fMaxMoveSpeed * m_fSpeedRate;

	if( HasBuff( BT_CHANGE_MOVE_SPEED ) || HasBuff( BT_TARGET_CONTROL ) )
	{
		float fTemp = CheckChangeMoveSpeedBuff();
		if( fTemp != 0 )
			fMaxSpeed = fTemp;
	}

	float fDashRunMaxSpeedRate = m_fDashRunMaxSpeedRate;
	float fDashAttackSpeedRate = 0.0f;
	float fDefenseMaxSpeedRate = m_fDefenseMaxSpeedRate;
	float fAttackMaxSpeedRate = m_fAttackMaxSpeedRate;
	float fJumpMaxSpeedRate = FLOAT1;
	float fSkillMaxSpeedRate = FLOAT1;
	float fGrapplingSpeedRate = FLOAT1;

	ioAttackableItem *pItem = GetPriorityItem( SPT_DASH );
	if( pItem )
	{
		fDashRunMaxSpeedRate = pItem->GetDashSpeedRate();
		fDashAttackSpeedRate = pItem->GetDashAttackSpeedRate();
	}

	pItem = GetPriorityItem( SPT_DEFENSE );
	if( pItem )
	{
		fDefenseMaxSpeedRate = pItem->GetDefenseSpeedRate();
		if( fDefenseMaxSpeedRate == 0.0f )
			fDefenseMaxSpeedRate = m_fDefenseMaxSpeedRate;
	}

	pItem = GetPriorityItem( SPT_ATTACK );
	if( pItem )
	{
		fAttackMaxSpeedRate = pItem->GetAttackSpeedRate();
		if( fAttackMaxSpeedRate == 0.0f )
		{
			if( ToLinearChargeItem(pItem) && pItem->IsChargeRotate() )
				fAttackMaxSpeedRate = 0.0f;
			else if( ToCrossBowItem(pItem) && pItem->IsChargeRotate() )
				fAttackMaxSpeedRate = 0.0f;
			else
				fAttackMaxSpeedRate = m_fAttackMaxSpeedRate;
		}

		ioGrapplingItem *pGrappling = ToGrapplingItem( pItem );
		ioGrapplingExpansionItem *pGrapplingExpansion = ToGrapplingExpansionItem( pItem );
		ioHeraclesItem* pHeracles = ToHeraclesItem( pItem );
		if( pGrappling )
		{
			fGrapplingSpeedRate = pGrappling->GetGrapplingMoveSpeedRate();
			if( fGrapplingSpeedRate == 0.0f )
				fGrapplingSpeedRate = FLOAT1;
		}
		else if( pGrapplingExpansion )
		{
			fGrapplingSpeedRate = pGrapplingExpansion->GetGrapplingMoveSpeedRate();
			if( fGrapplingSpeedRate == 0.0f )
				fGrapplingSpeedRate = FLOAT1;
		}
		else if( pHeracles )
		{
			fGrapplingSpeedRate = pHeracles->GetGrapplingMoveSpeedRate();
			if( fGrapplingSpeedRate == 0.0f )
				fGrapplingSpeedRate = FLOAT1;
		}
	}

	pItem = GetPriorityItem( SPT_JUMP );
	if( pItem )
	{
		fJumpMaxSpeedRate = pItem->GetExtraJumpSpeedRate( GetMoveDir(), GetTargetRot() );
		
		if( m_CharState == CS_JUMP )
		{
			float fBuffJumpSpeedRate = 0.0f;
			
			if( m_UsedBuffMultiFlyJump == BJUT_CUR || m_UsedBuffMultiFlyJump == BJUT_USED )
			{
				if( !m_vBuffMultiFlyJumpInfoList.empty() )
					fBuffJumpSpeedRate = m_vBuffMultiFlyJumpInfoList[0].m_fBuffJumpSpeedRate;

				fJumpMaxSpeedRate = fBuffJumpSpeedRate+m_fBuffJumpSpeedGrowthRate;
			}
			else if( m_UsedBuffFlyJump == BJUT_CUR || m_UsedBuffFlyJump == BJUT_CONTINUE )
			{
				if( !m_vBuffFlyJumpInfoList.empty() )
					fBuffJumpSpeedRate = m_vBuffFlyJumpInfoList[0].m_fBuffJumpSpeedRate;

				fJumpMaxSpeedRate = fBuffJumpSpeedRate+m_fBuffJumpSpeedGrowthRate;
			}
			else if( m_UsedBuffJump == BJUT_CUR )
			{
				if( !m_vBuffJumpInfoList.empty() )
					fBuffJumpSpeedRate = m_vBuffJumpInfoList[0].m_fBuffJumpSpeedRate;

				fJumpMaxSpeedRate = fBuffJumpSpeedRate+m_fBuffJumpSpeedGrowthRate;
			}
			else if ( m_UsedBuffFlyJump == BJUT_WALK )
			{
				if( !m_vBuffFlyJumpInfoList.empty() )
					fBuffJumpSpeedRate = m_vBuffFlyJumpInfoList[0].m_fBuffJumpSpeedRate;

				fJumpMaxSpeedRate = fBuffJumpSpeedRate+m_fBuffJumpSpeedGrowthRate;
			}
		}
	}

	if( m_pActiveSkill )
	{
		if( m_bSkillMoveEnable )
			fSkillMaxSpeedRate = m_pActiveSkill->GetSkillMoveRate();
		else if( ToBreathSkill(m_pActiveSkill) && ToBreathSkill(m_pActiveSkill)->IsEnableMoveState() )
			fSkillMaxSpeedRate = m_pActiveSkill->GetSkillMoveRate();
	}

	// buff accumlate speed rate
	float fBuffAccumSpeedRate = GetBuffAccumSpeedRate();
	if( fBuffAccumSpeedRate != 0.0f )
	{
		float fGapValue = fMaxSpeed * fBuffAccumSpeedRate;
		fMaxSpeed += fGapValue;
	}
	
	if( m_bPrisonerMode )
		fMaxSpeed = m_fPrisonerSpeed;
	else if( m_bCatchState )
		fMaxSpeed = m_fCatchMoveSpeed;
	else
	{
		switch( m_CharState )
		{
		case CS_ATTACK:
			fMaxSpeed *= fAttackMaxSpeedRate;
			break;
		case CS_OBJECT_ATTACH:
		case CS_THUNDER_BIRD_OBJECT_SPECIAL:
		case CS_CYVOGUE_STATE:
		case CS_MEPHISTO_STATE:
		case CS_DARKSEAS_STATE:
			fMaxSpeed *= fAttackMaxSpeedRate;
			break;
		case CS_FLY:
			fMaxSpeed = m_fFlyMoveSpeed;
			break;
		case CS_PETERPAN_FLY:
			fMaxSpeed = m_fFlyMoveSpeed;
			break;
		case CS_EXTEND_DEFENSE:
			if(m_bDefenseMoveEnable || m_bReloadMoveEnable)
				fMaxSpeed *= fDefenseMaxSpeedRate;
			break;
		case CS_DASH:
		case CS_EXTEND_DASH:
			fMaxSpeed *= fDashRunMaxSpeedRate;
			fMaxSpeed *= m_fExtraDashSpeedRate;
			break;
		case CS_DASH_ATTACK:
			fMaxSpeed *= fDashRunMaxSpeedRate;
			fMaxSpeed *= m_fExtraDashSpeedRate;

			if( fDashAttackSpeedRate > 0.0f )
				fMaxSpeed *= fDashAttackSpeedRate;
			break;
		case CS_JUMP:
			if( m_JumpState != JS_LANDING && m_JumpState != JS_READY )
			{
				fMaxSpeed = m_fJumpMaxMoveSpeed * fJumpMaxSpeedRate;
				fMaxSpeed *= m_fSylphidJumpSpeedRate;

				if( HasBuff( BT_BUFF_AIR_WALK, GetCharName() ) && m_UsedBuffFlyJump == BJUT_WALK )
				{
					ioBuff* pBuff = GetBuffConst( BT_BUFF_AIR_WALK );
					ioAirWalkBuff *pAirWalkBuff = ToAirWalkBuff( pBuff );
					if( pAirWalkBuff )
						fMaxSpeed = pAirWalkBuff->GetFixedSpeed();
				}

				// 점프 부스트 버프 있을때 점프 한 후 부스트를 사용하면 FlyMoveSpeed변수 사용하도록 함
				if ( HasBuff(BT_JUMP_BOOST_BUFF) && IsJumpBoost() )
				{
					fMaxSpeed = m_fFlyMoveSpeed;
				}

				iolupinItem* pLupin = ToLupinItem( m_pEquipSlot->GetWeapon() );
				if(pLupin && pLupin->IsLupinSpecialFallState())
				{
					fMaxSpeed = pLupin->GetActionJumpMaxSpeed() * fJumpMaxSpeedRate;
				}
			}
			break;
		case CS_USING_SKILL:
			if( m_pActiveSkill )
			{
				if( m_bSkillMoveEnable )
					fMaxSpeed *= fSkillMaxSpeedRate;
				else if( ToBreathSkill(m_pActiveSkill) && ToBreathSkill(m_pActiveSkill)->IsEnableMoveState() )
					fMaxSpeed *= fSkillMaxSpeedRate;
			}
			break;
		case CS_GRAPPLING:
		case CS_GRAPPLING_EXPANSION:
			fMaxSpeed *= fGrapplingSpeedRate;
			break;
		case CS_FLOAT_STATE:	// CS_FLOAT_STATE 는 아랫쪽 처리없이 바로 넘긴다.
			fMaxSpeed *= m_FloatBuffInfo.m_fFloatSpeedRate;
			return fMaxSpeed;
		//서든 어택때 모드에 따른 이동속도 처리
		case CS_RUN:
			if( pItem && ToSuddenAttackItem( pItem ) )
				fMaxSpeed *= fAttackMaxSpeedRate;
			else if( pItem && ToObjectWereWolfItem( pItem ) )
				fMaxSpeed *= fAttackMaxSpeedRate;
			break;
		case CS_NANGIN_SPECIAL:
			if( pItem && ToNanginItem( pItem ) )
				fMaxSpeed *= fAttackMaxSpeedRate;
			break;
		case CS_DRUID_CROUCH_GATHERING_STATE:
			if( pItem && ToDruidObjectItem( pItem ) )
				fMaxSpeed *= fAttackMaxSpeedRate;
			break;
		case CS_EARTHQUAKE_SPECIAL:
			{
				ioEarthQuakeItem *pEarthQuakeItem = ToEarthQuakeItem( pItem );
				if( pEarthQuakeItem && pEarthQuakeItem->IsEnableMoveState() )
					fMaxSpeed *= fAttackMaxSpeedRate;
			}
			break;
		case CS_SASINMU_SPECIAL:
			{
				ioSasinmuItem *pSasinmuItem = ToSasinmuItem( pItem );
				if( pSasinmuItem && pSasinmuItem->IsEnableMoveState() )
					fMaxSpeed *= fAttackMaxSpeedRate;
			}
			break;
		case CS_PREDATOR_SPECIAL:
			{
				ioPredatorItem *pPredatorItem = ToPredatorItem( pItem );
				if( pPredatorItem && pPredatorItem->IsEnableMoveState() )
					fMaxSpeed *= fAttackMaxSpeedRate;
			}
			break;
		default:
			if( m_pCharSpeicalState && m_pCharSpeicalState->IsEnableMoveState( this ) )
			{
				fMaxSpeed *= fAttackMaxSpeedRate;
			}
		}
	}

	// 성장요소 관련 처리(이동력)
	bool bExceptGrowth = false;
	if( HasBuff( BT_EXCEPT_GROWTH_BUFF ) )
	{
		ioBuff* pBuff = GetBuff( BT_EXCEPT_GROWTH_BUFF );
		ioExceptGrowthBuff* pExceptGrowthBuff = ToExceptGrowthBuff( pBuff );
		if( pExceptGrowthBuff )
		{
			DWORDVec exceptType = pExceptGrowthBuff->GetExceptGrowthType();
			for( int i = 0; i < (int)exceptType.size(); i++ )
			{
				if( exceptType[i] == GT_CHAR_MOVE_SPEED )
				{
					bExceptGrowth = true;
					break;
				}
			}
		}
	}
	int iClassType = m_CharInfo.m_class_type;
	ioGrowthLevel *pGrowthLevel = m_pCreator->GetGrowthLevel( GetCharName() );
	if( !bExceptGrowth && pGrowthLevel && !ToGangsiMode( m_pModeParent ) )
	{
		int iGrowthNum = 0;
		int iInfoNum = GetGrowthInfoNumByType( GT_CHAR_MOVE_SPEED, iGrowthNum );
		int iLevel = pGrowthLevel->GetCharGrowthLevel( iClassType, iGrowthNum-1, false );

		if( m_pEquipSlot )
		{
			ioItem *pEquipedItem = m_pEquipSlot->GetEquipedItem( ES_HELMET );
			if( pEquipedItem )
			{
				int nReinforce = pEquipedItem->GetItemReinforce();
				//강화레벨에 따른 추가 스탯
				if ( nReinforce <= g_CompoundMaterialMgr.GetFixedFailReinforce() )
					iLevel += nReinforce;
				else
					iLevel += g_GrowthInfoMgr.GetReinforceAddStat( nReinforce );
			}
		}

		GetMedalItemGrowth( iLevel, true, 2 );

		//펫 성장
		GetPetGrowth( iLevel, true, 2 );

		//각성
		GetAwakeCharGrowth( iLevel, 2 );

		GetRSoldierGrowth( iLevel, true, 2 );

		GetSoldierSetGrowth( iLevel, true, 2 );

		GetGrowthLevelByMode( iLevel, true, 2 );

		float fGrowthValue = 0.0f;
		ioGrowthNormalUpInfo *pUpInfo = ToNormalUpInfo( g_GrowthInfoMgr.GetGrowthUpInfo(iInfoNum, iLevel) );
		if( pUpInfo )
		{
			fGrowthValue = pUpInfo->GetValue( m_pCreator );
		}

		fGrowthValue += m_fGrowthMoveSpeedRate;
		fGrowthValue = FLOAT1 + fGrowthValue/FLOAT100;
		fMaxSpeed *= fGrowthValue;
	}

	if( !bExceptGrowth )
		fMaxSpeed = g_MathManager.RecalculateSpeedBySpeedClass( fMaxSpeed, m_fCurSpeedClass );

	if( m_pCreator )
		fMaxSpeed *= m_pCreator->GetRoomMoveSpeedRate( m_TeamType );

	return fMaxSpeed;
}

float ioBaseChar::GetAttackDamageRate( ioWeapon *pWeapon )
{
	ioWeapon::WeaponType eType = pWeapon->GetType();

	int iRateCount = m_AttackRateList.size();
	for( int i=0; i<iRateCount; i++ )
	{
		if( m_AttackRateList[i].iType == eType )
			return m_AttackRateList[i].fRate;
	}

	return FLOAT1;
}

float ioBaseChar::GetAttackNPCDamageRate( ioWeapon *pWeapon )
{
	ioWeapon::WeaponType eType = pWeapon->GetType();

	int iRateCount = m_AttackRateNPCList.size();
	for( int i=0; i<iRateCount; i++ )
	{
		if( m_AttackRateNPCList[i].iType == eType )
			return m_AttackRateNPCList[i].fRate;
	}

	return FLOAT1;
}

