float ioBaseChar::GetFirstFireTime( const ioHashString &rkAniName )
{
	if( !m_pGroup )	return 0.0f;

	int iAniID = m_pGroup->GetAnimationIdx( rkAniName );
	if( iAniID == -1 )	return 0.0f;

	AniEventConstPtrList vFireStartList;
	m_pGroup->GetAnimationEventConstPtrList_e( iAniID, "fire_s", vFireStartList );

	if( vFireStartList.empty() )
		return 0.0f;

	return vFireStartList.front()->fEventTime;
}

