bool ioBaseChar::IsItemCanPickUpByKey()
{
	bool bResult = true;
	if( m_CharState != CS_DELAY && m_CharState != CS_RUN )
		bResult = false;
	
	if( ToHookItem( GetWeapon() ) && ToHookItem( GetWeapon() )->CheckOnHand() )	// 폭탄 장착시에는 아이템을 집을수 없음
		bResult = false;

	if( ToGunnerItem( GetWeapon() ) && ToGunnerItem( GetWeapon() )->CheckOnHand() )	// 폭탄 장착시에는 아이템을 집을수 없음
	
	if( GetObject() )
		bResult = false;

	if( m_pEquipSlot && m_pEquipSlot->IsEquipWait( ES_OBJECT ) )
		bResult = false;
	
	return bResult;
}

bool ioBaseChar::IsItemCanPickUp()
{
	bool bResult = true;
	if( m_CharState != CS_DELAY )
		bResult = false;

	if( m_bCatchState || m_bPrisonerMode )
		bResult = false;

	if( m_ChatModeState != CMS_NONE )
		bResult = false;
	
	if( ToHookItem( GetWeapon() ) && ToHookItem( GetWeapon() )->CheckOnHand() )	// 폭탄 장착시에는 아이템을 집을수 없음
		bResult = false;

	if( ToGunnerItem( GetWeapon() ) && ToGunnerItem( GetWeapon() )->CheckOnHand() )	// 폭탄 장착시에는 아이템을 집을수 없음
		bResult = false;
	
	/*if( GetObject() )
		bResult = false;*/

	if( m_pEquipSlot && m_pEquipSlot->IsEquipWait( ES_OBJECT ) )
		bResult = false;

	if( IsGangsi() )
		bResult = false;
	
	/*if( IsObejctEquipState() )
		bResult = false;*/

	if( bResult && m_dwDelayStateStartTime > 0 && m_dwItemPickUpStandardTime < FRAMEGETTIME() - m_dwDelayStateStartTime )
		bResult = true;

	if( !bResult && m_bSetPickEmoticon )
		m_bSetPickEmoticon = false;

	return bResult;
}

bool ioBaseChar::IsCanDefenseMove( bool bCheckDefense ) const
{
	if( bCheckDefense )
	{
		if( !m_bDefenseMoveEnable && !m_bDefenseMoveRotate )
			return false;
	}
	else
	{
		if( !m_bDefenseMoveEnable )
			return false;
	}

	return true;
}

