ioUserKeyInput::DirKeyInput ioBaseChar::GetXformDir( ioUserKeyInput::DirKeyInput eDirKey )
{
	return m_KeyInput.GetXformDir( eDirKey, CheckCurDirKey() );
}

ioUserKeyInput::DirKeyInput ioBaseChar::CheckCurDirKey()
{
	ioUserKeyInput::DirKeyInput eDir = m_KeyInput.GetCurDirKey();
	ioUserKeyInput::DirKeyInput eReturn = eDir;

	if( m_bReverseDirection )
	{
		switch( eDir )
		{
		case ioUserKeyInput::DKI_UP:
			eReturn = ioUserKeyInput::DKI_DOWN;
			break;
		case ioUserKeyInput::DKI_RIGHTUP:
			eReturn = ioUserKeyInput::DKI_LEFTDOWN;
			break;
		case ioUserKeyInput::DKI_RIGHT:
			eReturn = ioUserKeyInput::DKI_LEFT;
			break;
		case ioUserKeyInput::DKI_RIGHTDOWN:
			eReturn = ioUserKeyInput::DKI_LEFTUP;
			break;
		case ioUserKeyInput::DKI_DOWN:
			eReturn = ioUserKeyInput::DKI_UP;
			break;
		case ioUserKeyInput::DKI_LEFTDOWN:
			eReturn = ioUserKeyInput::DKI_RIGHTUP;
			break;
		case ioUserKeyInput::DKI_LEFT:
			eReturn = ioUserKeyInput::DKI_RIGHT;
			break;
		case ioUserKeyInput::DKI_LEFTUP:
			eReturn = ioUserKeyInput::DKI_RIGHTDOWN;
			break;
		}
	}

	return eReturn;
}

