float ioBaseChar::CheckKeyReserveTime( int iAniID, float fTimeRate, DWORD dwPredelay )
{
	DWORD dwCurTime = FRAMEGETTIME();

	float fEventTime = m_pGroup->GetAnimationEventTime_e( iAniID, "key_reserve" ) * fTimeRate;
	if( fEventTime > 0 )
	{
		m_dwReserveEnableTime = dwCurTime + fEventTime + dwPredelay;
	}

	return fEventTime;
}

void ioBaseChar::CheckJumpState()
{
	ioOrientBox kBox = GetWorldCollisionBox();
	DWORD dwCurTime = FRAMEGETTIME();

	ioAttackableItem *pItem = GetPriorityItem( SPT_JUMP );
	ioAttackableItem *pJumpAttackItem = GetPriorityItemByAttackType( AT_JUMP_ATTACK );

	ioFieldItem *pPickItem = NULL;

	float fHeightGap = GetWorldPosition().y - GetBottomHeight();

	if( m_bUseGhostState )
	{
		if( m_JumpState == JS_JUMP_ATTACK && GetBottomHeight() > 0.0f )
			m_fPreHeightForGhostState = GetBottomHeight();

		fHeightGap = GetWorldPosition().y - m_fPreHeightForGhostState;
	}

	if( CheckExtendJumpAttackEndJump() )
		return;

	ioBangtanItem *pBangtanItem = ToBangtanItem(GetPriorityItem( SPT_ATTACK ));
	if( IsNeedProcess() && IsDefenseKey() && pBangtanItem && pBangtanItem->IsEnableTarget( this ) )
	{
		pBangtanItem->SetTeleport( this, true, true, true );
		return;
	}
	
	switch( m_JumpState )
	{
	case JS_READY:
		if( dwCurTime <= m_dwJumpMoveStartTime )
		{
			if( IsNeedProcess() )
			{
				if( !m_KeyInput.IsJumpKeyDown() )
				{
					SetJumpping( false );
					m_dwJumpMoveStartTime = dwCurTime;
				}
			}
		}
		else
		{
			if( IsNeedProcess() )
			{
				SetJumpping( true );
			}
		}
		break;
	case JS_JUMPPING:
		// ActionStop : 렉으로 인해 점프 상태에서 프리징 걸릴수 있음.
		//				그러므로 점프 상태에서 프리징 걸려도 키 입력 정상 처리할 것
		if( IsNeedProcess() )
		{
			// HARDCODE :: SUMMON DUMMY jumpping
			if( m_KeyInput.IsDefenseKey() )
			{
				CheckSummonDummyChar( ioAttackableItem::SDT_JUMP );
				CheckGraffitiWeaponAction();
			}
			ioObjectWereWolfItem *pObjectWere = ToObjectWereWolfItem( GetObject() );
			if( IsDefenseKey() && pObjectWere && pObjectWere->IsEnableDefenseRelease() )
			{
				pObjectWere->ChangeToRelease( this );
				return;
			}

			// 2020-06-08
			ioObjectBankruptcyItem *pObjectBankruptcyItem = ToObjectBankruptcyItem( GetObject() );
			if( IsDefenseKey() && pObjectBankruptcyItem && pObjectBankruptcyItem->IsEnableDefenseRelease() )
			{
				pObjectBankruptcyItem->ChangeToRelease( this );
				return;
			}

			if( m_UsedBuffMultiFlyJump == BJUT_CUR && !m_KeyInput.IsJumpKeyDown() )
			{
				SetBuffMultiFlyJumpEnd();
			}
			else if( m_UsedBuffFlyJump == BJUT_CUR && !m_KeyInput.IsJumpKeyDown() )
			{
				SetBuffFlyJumpEnd();
			}
			else if( m_UsedBuffFlyJump == BJUT_WALK && !m_KeyInput.IsJumpKeyDown() )
			{
				SetBuffAirWalkEnd();
			}

			if( IsCanBuffMultiFlyJump( fHeightGap ) )
			{
				SetBuffMultiFlyJump();

				//SkillEvent
				CheckSkillEvent( BT_BUFF_MULTI_FLY_JUMP );
			}
			else if( IsCanBuffFlyJump( fHeightGap ) )
			{
				SetBuffFlyJump();

				//SkillEvent
				if( IsOwnerChar() && m_UsedBuffFlyJump != BJUT_CONTINUE )
					CheckSkillEvent( BT_BUFF_FLY_JUMP );
			}
			else if( IsCanBuffJump( fHeightGap ) )
			{
				bool bBuffJump = true;
				if( m_iBuffJumpCurCnt == 1 )
				{
					for( int i=ES_WEAPON; i<ES_CLOAK+1; ++i )
					{
						ioSkill *pSkill = GetEquipedSkill( i );
						ioPassiveSkill *pPassive = ToPassiveSkill( pSkill );
						if( pPassive && pPassive->HasBuff( m_vBuffJumpInfoList[0].m_Name ) && pPassive->UsePassiveGauge() )
						{
							if( pPassive->GetCurPassiveGauge() <= m_vBuffJumpInfoList[0].m_fBuffJumpEnableGauge )
							{
								bBuffJump = false;
							}
						}
					}
				}
				if( bBuffJump )
				{
					SetBuffJump();

					//SkillEvent
					if( IsOwnerChar() )
						CheckSkillEvent( BT_DOUBLE_JUMP );
				}
			}
			else if ( IsCanBuffAirWalk( fHeightGap) )
			{
				SetBuffAirWalk();

				//SkillEvent
				CheckSkillEvent( BT_BUFF_AIR_WALK );
			}

			if( pItem )
			{
				pItem->ProcessJumpping( this, fHeightGap );
			}
			else if( m_pExtendJump )
			{
				m_pExtendJump->ProcessJumpping( this, fHeightGap, m_fJumpNeedGauge );
			}

			// reload
			if( pItem && IsCanJumpReload( pItem, fHeightGap ) )
			{
				SetJumpReload();
			}

			if ( IsEnableJumpAttack() )
			{
				// JumpAttack Check
				if( pItem && IsCanFlashJumpAttack( fHeightGap ) )
				{
					pItem->SetFlashJumpAttack( this );
					g_TutorialMgr.ActionJumpAttack();
				}
				else if( pItem && IsCanComboFlashAttack( fHeightGap ) )
				{
					pItem->SetComboFlashAttack( this );
					g_TutorialMgr.ActionJumpAttack();
				}
				else if( pItem && IsCanComboJumpAttack( fHeightGap ) )
				{
					pItem->CheckComboJumpAttack( this );
					g_TutorialMgr.ActionJumpAttack();
				}
				else if( pItem && IsCanCollectJumpAttack( fHeightGap ) )
				{
					pItem->SetCollectJumpAttack( this );
					g_TutorialMgr.ActionJumpAttack();
				}
				else if( pItem && IsCanRJumpAttack( fHeightGap ) )
				{
					ioRagnaJump *pRagna = ToRagnaJump( pItem->GetCurExtendJump() );
					ioRachelJump *pRachel = ToRachelJump( pItem->GetCurExtendJump() );
					ioTrinityJump *pTrinity = ToTrinityJump( pItem->GetCurExtendJump() );
					ioHakumenJump *pHakumen = ToHakumenJump( pItem->GetCurExtendJump() );
					ioParkilpyoJump *pParkilpyo = ToParkilpyoJump( pItem->GetCurExtendJump() );

					if( pRagna )
					{
						if( pRagna->IsCanFlashJumpAttack( this ) )
						{
							pRagna->SetFlashJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
						else
						{
							pRagna->CheckComboJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
					}
					else if( pRachel )
					{
						if( pRachel->IsCanDoubleJumpAttack() )
						{
							pRachel->SetDoubleJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
						else
						{
							pRachel->CheckComboJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
					}
					else if( pParkilpyo )
					{
						pParkilpyo->CheckComboJumpAttack( this );
						g_TutorialMgr.ActionJumpAttack();
					}
					else if( pTrinity )
					{
						pTrinity->CheckComboJumpAttack( this );
						g_TutorialMgr.ActionJumpAttack();
					}
					else if( pHakumen )
					{
						if( pHakumen->IsCanDoubleJumpAttack() )
						{
							pHakumen->SetDoubleJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
						else
						{
							pHakumen->CheckComboJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
					}
				}
				else if( pItem && IsCanChargeComboJumpAttack( fHeightGap ) )
				{
					ioGatotkacaJump *pGatotkaca = ToGatotkacaJump( pItem->GetCurExtendJump() );
					ioChargeComboJump *pChargeCombo = ToChargeComboJump( pItem->GetCurExtendJump() );
					ioChargeComboJump2 *pChargeCombo2 = ToChargeComboJump2( pItem->GetCurExtendJump() );
					ioChargeComboJump3 *pChargeCombo3 = ToChargeComboJump3( pItem->GetCurExtendJump() );
					ioChargeComboJump4 *pChargeCombo4 = ToChargeComboJump4( pItem->GetCurExtendJump() );
					ioChargeComboDefenseJump *pChargeComboDefenseJump = ToChargeComboDefenseJump( pItem->GetCurExtendJump() );
					ioSuddenAttackJump *pSuddenJump = ToSuddenAttackJump( pItem->GetCurExtendJump() );
					ioTraceJump *pTraceJump = ToTraceJump( pItem->GetCurExtendJump() );
					ioJoroExpansionJump *pJoroExpansionJump = ToJoroExpansionJump( pItem->GetCurExtendJump() );
					ioSaberJump *pSaberJump = ToSaberJump( pItem->GetCurExtendJump() );
					ioNataJump *pNataJump = ToNataJump( pItem->GetCurExtendJump() );
					ioGrapplingExpansionJump *pGrapplingExpansionJump = ToGrapplingExpansionJump( pItem->GetCurExtendJump() );
					ioAimJump* pAimJump = ToAimJump( pItem->GetCurExtendJump() );	// 2020-02-10
					ioGwonwangJump *pGwonwangJump = ToGwonwangJump( pItem->GetCurExtendJump() );
					ioEvaComboJump *pEvaComboJump = ToEvaComboJump( pItem->GetCurExtendJump() );	// 이브 2020-11-05

					if( pChargeCombo )
					{
						if( pChargeCombo->IsCanFlashJumpAttack( this ) )
						{
							pChargeCombo->SetFlashJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
						else
						{
							pChargeCombo->CheckComboJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
					}
					else if( pChargeCombo2 )
					{
						if( pChargeCombo2->IsCanFlashJumpAttack( this ) )
						{
							pChargeCombo2->SetFlashJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
						else
						{
							pChargeCombo2->CheckComboJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
					}
					else if( pChargeCombo3 )
					{
						if( pChargeCombo3->IsCanFlashJumpAttack( this ) )
						{
							pChargeCombo3->SetFlashJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
						else
						{
							pChargeCombo3->CheckComboJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
					}
					else if( pChargeCombo4 )
					{
						if( pChargeCombo4->IsCanFlashJumpAttack( this ) )
						{
							pChargeCombo4->SetFlashJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
						else
						{
							pChargeCombo4->CheckComboJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
					}
					else if( pGrapplingExpansionJump )
					{
						pGrapplingExpansionJump->CheckComboJumpAttack( this );	
					}
					else if( pSuddenJump )
					{
						if( pSuddenJump->IsCanFlashJumpAttack( this ) )
						{
							pSuddenJump->SetFlashJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
						else
						{
							pSuddenJump->CheckComboJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
					}
					else if( pChargeComboDefenseJump )
					{
						pChargeComboDefenseJump->CheckComboJumpAttack( this );
						g_TutorialMgr.ActionJumpAttack();
					}
					else if( pGatotkaca )
					{
						if( pGatotkaca->IsCanFlashJumpAttack( this ) )
						{
							pGatotkaca->SetFlashJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
						else
						{
							pGatotkaca->CheckComboJumpAttack( this );
							g_TutorialMgr.ActionJumpAttack();
						}
					}
					else if( pTraceJump )
					{
						pTraceJump->CheckComboJumpAttack( this );
						g_TutorialMgr.ActionJumpAttack();
					}
					else if( pJoroExpansionJump )
					{
						pJoroExpansionJump->CheckComboJumpAttack( this );
						g_TutorialMgr.ActionJumpAttack();
					}
					else if ( pSaberJump )
					{
						pSaberJump->CheckComboJumpAttack( this );
						g_TutorialMgr.ActionJumpAttack();
					}
					else if ( pNataJump )
					{
						pNataJump->CheckComboJumpAttack( this );
						g_TutorialMgr.ActionJumpAttack();
					}

					else if( pAimJump && pAimJump->GetEnableJumpChargeAttack() )	// 2020-02-10
					{
						pAimJump->CheckComboJumpAttack( this );	
					}
					else if( pGwonwangJump )	// 권왕 2020-06-03
					{
						pGwonwangJump->CheckComboJumpAttack( this );	
					}
					else if( pEvaComboJump )	// 이브 2020-11-05
					{
						pEvaComboJump->CheckComboJumpAttack( this );
					}
				}
				else if( IsCanJumpAttack( fHeightGap ) )
				{
					if( m_CurJumpType == JT_AIM_JUMP )
					{
						SetAimState();
						CheckLanding( fHeightGap, dwCurTime );
						break;
					}
					else if( m_CurJumpType == JT_AIM_JUMP2 )
					{
						SetCrossBowJumpAimState();
						CheckLanding( fHeightGap, dwCurTime );
						break;
					}
					else if( m_CurJumpType == JT_AUTO_SHOT_JUMP )
					{
						SetJumpAutoShotState();
						CheckLanding( fHeightGap, dwCurTime );
						break;
					}
					else if( m_CurJumpType == JT_POWER_CHARGE_JUMP || m_CurJumpType == JT_CHARGE_FLASH_JUMP )
					{
						pItem->SetPowerChargeJumpAttack( this );
						g_TutorialMgr.ActionJumpAttack();
						CheckLanding( fHeightGap, dwCurTime );
						break;
					}
					else
					{
						if( pItem && pItem->IsEnableNewJumpAttack() )
						{
							SetNewJumpAttackState();
							return;
						}
						else
							SetJumpAttack();

						g_TutorialMgr.ActionJumpAttack();
					}
				}
				//else if( IsCan_D_JumpAttack( fHeightGap ) )
				//{
				//	if( m_CurJumpType == JT_POWER_CHARGE_JUMP || m_CurJumpType == JT_CHARGE_FLASH_JUMP )
				//	{
				//		pItem->SetPowerChargeJumpAttack( this );
				//		g_TutorialMgr.ActionJumpAttack();
				//		CheckLanding( fHeightGap, dwCurTime );
				//		//break;
				//	}
				//}

			}

			// 부스터 스킬 체크
			if( CheckJumpingSkill() )
				return;
		}
		else
		{
			if( pItem )
			{
				pItem->ProcessJumppingByNoNeedProcess( this, fHeightGap );
			}
		}

		if( !m_bNowDefenseEnable )
		{
			if( m_dwDefenseEnableTime > 0 )
			{
				if( m_dwDefenseEnableTime + m_dwActionStopTotalDelay < dwCurTime )
				{
					m_bNowDefenseEnable = true;
				}
			}
		}

		if( m_bNowDefenseEnable )
		{
			// 방어종료시간
			if( m_dwDefenseReleaseTime + m_dwActionStopTotalDelay < dwCurTime && m_bReleaseJumpDefense )
			{
				m_dwDefenseEnableTime = 0;
				m_dwDefenseReleaseTime = 0;

				m_bNowDefenseEnable = false;
				m_bUsedJumpDefense = false;
				m_bReleaseJumpDefense = false;

				m_pGroup->ClearAllActionAni( FLOAT100, true );
				m_pGroup->ClearAllLoopAni( FLOAT100, true );

				m_pGroup->SetActionAni( GetJumppingAnimationIdx(),
										0.0f, 0.0f,
										1.0f, FLOAT1,
										0.0f, 0.0f,
										true );
			}
		}

		CheckLanding( fHeightGap, dwCurTime );
		break;
	case JS_AIM_JUMP:
		if( pItem && m_CurJumpType == JT_AIM_JUMP )
		{
			if( pItem->ProcessAimJump( this, fHeightGap ) )
				return;

			if( IsCanAimJumpAttack( fHeightGap ) )
			{
				SetJumpAttack();
				g_TutorialMgr.ActionJumpAttack();
			}
			else
			{
				pItem->CheckAimJumpState( this );
			}
		}
		else
		if( pItem && ( m_CurJumpType == JT_ROBIN_EXPANSION_JUMP || m_CurJumpType == JT_PHOENIX_JUMP ) )
		{
			pItem->ProcessJumpAttack( this, fHeightGap );
		}
		else
		if( pItem && m_CurJumpType == JT_SUDDEN_ATTACK_JUMP )
		{
			pItem->ProcessJumpAttack( this, fHeightGap );
		}

		CheckLanding( fHeightGap, dwCurTime );
		break;
	case JS_AIM_JUMP2:
		if( pItem && m_CurJumpType == JT_AIM_JUMP2 )
		{
			if( IsCanAimJumpAttack( fHeightGap ) )
			{
				SetJumpAttack();
				g_TutorialMgr.ActionJumpAttack();
			}
			else
			{
				pItem->CheckAimJumpState( this );
			}
		}
		CheckLanding( fHeightGap, dwCurTime );
		break;
	case JS_JUMP_ATTACK:
		if( IsNeedProcess() )
		{
			// HARDCODE :: SUMMON DUMMY jumpp att
			if( m_KeyInput.IsDefenseKey() )
			{
				CheckSummonDummyChar( ioAttackableItem::SDT_JUMP_ATT );
				CheckGraffitiWeaponAction();
			}

			// 더미 탑승한 상태의 닥터 스파이더라면 방어키로 더미 탑승 해제
			ioObjectWereWolfItem *pObjectWere = ToObjectWereWolfItem( GetObject() );
			ioDrSpiderItem *pDrSpiderItem = ToDrSpiderItem( m_pEquipSlot->GetWeapon() );
			if( IsDefenseKey() && pObjectWere && pObjectWere->IsEnableDefenseRelease() && pDrSpiderItem )
			{
				pObjectWere->ChangeToRelease( this );
				return;
			}

			// 2020-06-08
			ioObjectBankruptcyItem *pObjectBankruptcyItem = ToObjectBankruptcyItem( GetObject() );
			if( IsDefenseKey() && pObjectBankruptcyItem && pObjectBankruptcyItem->IsEnableDefenseRelease() && pDrSpiderItem )
			{
				pObjectWere->ChangeToRelease( this );
				return;
			}
		}

		if( pItem )
		{
			pItem->ProcessJumpAttack( this, fHeightGap );

			if( m_CurJumpType == JT_RAGNA_JUMP ||
				m_CurJumpType == JT_RACHEL_JUMP ||
				m_CurJumpType == JT_CHARGE_COMBO2 ||
				m_CurJumpType == JT_CHARGE_COMBO3 ||
				m_CurJumpType == JT_CHARGE_COMBO4 ||
				m_CurJumpType == JT_CHARGE_COMBO_DEFENSE ||
				m_CurJumpType == JT_ILJIMAE_JUMP ||
				m_CurJumpType == JT_LEE_JUMP ||
				m_CurJumpType == JT_DESPERADO_JUMP ||
				m_CurJumpType == JT_TRINITY_JUMP ||
				m_CurJumpType == JT_SUDDEN_ATTACK_JUMP ||
				m_CurJumpType == JT_PARKILPYO_JUMP ||
				m_CurJumpType == JT_ROBIN_EXPANSION_JUMP || 
				m_CurJumpType == JT_PHOENIX_JUMP || 
				m_CurJumpType == JT_TIMEGATE_JUMP ||
				m_CurJumpType == JT_OMEN_JUMP || 
				m_CurJumpType == JT_POSEIDON_JUMP ||
				m_CurJumpType == JT_GENISYSARMY_JUMP ||	// 2020-06-30 제네시스 
				m_CurJumpType == JT_HERACLES_JUMP ||
				m_CurJumpType == JT_EVACOMBO_JUMP ||
				m_CurJumpType == JT_MAGNETIC_JUMP ||	// 마그네틱 2020-11-25 
				m_CurJumpType == JT_TAOIST_JUMP )		
			{
				if( IsNeedProcess() && CheckJumpingSkill() ) 
					return;
			}
		}

		if( m_CurJumpType == JT_AIM_JUMP || m_CurJumpType == JT_AIM_JUMP2 )
		{
			if( m_dwJumpAttackEndTime > dwCurTime )
			{
				if( pJumpAttackItem )
				{
					pJumpAttackItem->CheckJumpAttack( this );
				}
			}
			else
			{
				m_JumpState = JS_JUMPPING;
			}
		}
		else if( pItem && IsCanComboJumpAttack( fHeightGap ) )
		{
			pItem->CheckComboJumpAttack( this );
		}
		else if( pItem && IsCanRJumpAttack( fHeightGap ) )
		{
			ioRagnaJump *pRagna = ToRagnaJump( pItem->GetCurExtendJump() );
			ioRachelJump *pRachel = ToRachelJump( pItem->GetCurExtendJump() );
			ioTrinityJump *pTrinity = ToTrinityJump( pItem->GetCurExtendJump() );
			ioHakumenJump *pHakumen = ToHakumenJump( pItem->GetCurExtendJump() );
			ioParkilpyoJump *pParkilpyo = ToParkilpyoJump( pItem->GetCurExtendJump() );

			if( pRagna )
			{
				if( pRagna->IsCanFlashJumpAttack( this ) )
					pRagna->SetFlashJumpAttack( this );
				else
					pRagna->CheckComboJumpAttack( this );
			}
			else if( pRachel )
			{
				if( pRachel->IsCanDoubleJumpAttack() )
					pRachel->SetDoubleJumpAttack( this );
				else
					pRachel->CheckComboJumpAttack( this );
			}
			else if( pParkilpyo )
			{
				pParkilpyo->CheckComboJumpAttack( this );
			}
			else if( pTrinity )
			{
				pTrinity->CheckComboJumpAttack( this );
			}
			else if( pHakumen )
			{
				if( pHakumen->IsCanDoubleJumpAttack() )
					pHakumen->SetDoubleJumpAttack( this );
				else
					pHakumen->CheckComboJumpAttack( this );
			}
		}
		else if( pItem && IsCanChargeComboJumpAttack( fHeightGap ) )
		{
			ioChargeComboJump *pChargeCombo = ToChargeComboJump( pItem->GetCurExtendJump() );
			ioChargeComboJump2 *pChargeCombo2 = ToChargeComboJump2( pItem->GetCurExtendJump() );
			ioChargeComboJump3 *pChargeCombo3 = ToChargeComboJump3( pItem->GetCurExtendJump() );
			ioChargeComboJump4 *pChargeCombo4 = ToChargeComboJump4( pItem->GetCurExtendJump() );
			ioChargeComboDefenseJump *pChargeComboDefenseJump = ToChargeComboDefenseJump( pItem->GetCurExtendJump() );
			ioSuddenAttackJump *pSuddenJump = ToSuddenAttackJump( pItem->GetCurExtendJump() );
			ioJoroExpansionJump *pJoroExpansionJump = ToJoroExpansionJump( pItem->GetCurExtendJump() );
			ioSaberJump *pSaberJump = ToSaberJump( pItem->GetCurExtendJump() );
			ioNataJump *pNataJump = ToNataJump( pItem->GetCurExtendJump() );

			if( pChargeCombo )
			{
				if( pChargeCombo->IsCanFlashJumpAttack( this ) )
					pChargeCombo->SetFlashJumpAttack( this );
				else
					pChargeCombo->CheckComboJumpAttack( this );
			}
			else if( pChargeCombo2 )
			{
				if( pChargeCombo2->IsCanFlashJumpAttack( this ) )
					pChargeCombo2->SetFlashJumpAttack( this );
				else
					pChargeCombo2->CheckComboJumpAttack( this );
			}
			else if( pChargeCombo3 )
			{
				if( pChargeCombo3->IsCanFlashJumpAttack( this ) )
					pChargeCombo3->SetFlashJumpAttack( this );
				else
					pChargeCombo3->CheckComboJumpAttack( this );
			}
			else if( pChargeCombo4 )
			{
				if( pChargeCombo4->IsCanFlashJumpAttack( this ) )
					pChargeCombo4->SetFlashJumpAttack( this );
				else
					pChargeCombo4->CheckComboJumpAttack( this );
			}
			else if( pSuddenJump )
			{
				if( pSuddenJump->IsCanFlashJumpAttack( this ) )
					pSuddenJump->SetFlashJumpAttack( this );
				else
					pSuddenJump->CheckComboJumpAttack( this );
			}
			else if( pChargeComboDefenseJump )
			{
				pChargeComboDefenseJump->CheckComboJumpAttack( this );
			}
			else if( pJoroExpansionJump )
			{
				pJoroExpansionJump->CheckComboJumpAttack( this );
			}
			else if ( pSaberJump )
			{
				pSaberJump->CheckComboJumpAttack( this );
			}
			else if ( pNataJump )
			{
				pNataJump->CheckComboJumpAttack( this );
			}
		}
		else if( m_CurJumpType == JT_DOUBLE_SHOT_JUMP )
		{
			ioObjectDoubleShotItem *pObjectDoubleShot = ToObjectDoubleShotItem( GetObject() );
			if( pObjectDoubleShot )
			{
				if( !pObjectDoubleShot->CheckJumpShotState( this ) )
				{
					m_bUsedJumpAttack = false;
					m_JumpState = JS_JUMPPING;
				}
			}
		}
		{
			ioObjectItem *pObjItem = GetObject();
			ioSmartBoomObjectItem *pSmart = ToSmartBoomObjectItem( pObjItem );
			if( pSmart && pSmart->GetJumpAttackEndNextJumpAmt() > 0.0f )
			{
				if( m_dwJumpAttackEndTime < dwCurTime )
				{
					m_fCurSkillEndJumpAmt = pSmart->GetJumpAttackEndNextJumpAmt();
					SetSKillEndJumpState( m_fCurSkillEndJumpAmt );
				}
			}

			ioObjectWeaponItem *pObjWeapon = ToObjectWeaponItem( pObjItem );
			if( pObjWeapon && pObjWeapon->IsEnableReturnJumpping() )
			{
				if( m_dwJumpAttackEndTime < dwCurTime )
				{
					m_bUsedJumpAttack = false;
					SetJumppingState();
				}
			}
		}

		CheckJumpBoostBuff();

		CheckLanding( fHeightGap, dwCurTime );
		break;
	case JS_AUTO_SHOT:
		if( pItem )
		{
			pItem->ProcessJumpAttack( this, fHeightGap );
		}

		if( m_CurJumpType == JT_AUTO_SHOT_JUMP )
		{
			ioAutoShotItem *pAutoShot = ToAutoShotItem( pJumpAttackItem );
			if( pAutoShot )
			{
				if( !pAutoShot->CheckJumpAutoShotState( this ) )
					m_JumpState = JS_JUMPPING;
			}
			else
			{
				m_JumpState = JS_JUMPPING;
			}
		}
		else
		{
			m_JumpState = JS_JUMPPING;
		}

		CheckLanding( fHeightGap, dwCurTime );
		break;
	case JS_JUMP_RELOAD:
		if( pItem )
		{
			pItem->CheckJumpReloadState( this );
		}
		CheckLanding( fHeightGap, dwCurTime );
		break;
	case JS_COMBO_DASH:
		if( pItem )
		{
			ioComboJump *pComboJump = ToComboJump( pItem->GetCurExtendJump() );
			if( pComboJump )
				pComboJump->ProcessComboDash( this );

			ioPowerChargeJump *pPowerChargeJump = ToPowerChargeJump( pItem->GetCurExtendJump() );
			if( pPowerChargeJump )
				pPowerChargeJump->ProcessDash( this );

			ioIljimaeJump *pIljimaeJump = ToIljimaeJump( pItem->GetCurExtendJump() );
			if( pIljimaeJump )
				pIljimaeJump->ProcessComboDash( this );

			ioLeeJump *pLeeJump = ToLeeJump( pItem->GetCurExtendJump() );
			if( pLeeJump )
				pLeeJump->ProcessComboDash( this );

			ioRobinExpansionJump *pRobinExpansionJump = ToRobinExpansionJump( pItem->GetCurExtendJump() );
			if( pRobinExpansionJump )
				pRobinExpansionJump->ProcessComboDash( this );
			ioChargeComboJump2 *pChargeComboJump2 = ToChargeComboJump2( pItem->GetCurExtendJump() );
			if( pChargeComboJump2 )
				pChargeComboJump2->ProcessComboDash( this );

			ioPhoenixJump *pPhoenixJump = ToPhoenixJump( pItem->GetCurExtendJump() );
			if( pPhoenixJump )
				pPhoenixJump->ProcessComboDash( this );

			ioTimeGateJump *pTimeGateJump = ToTimeGateJump( pItem->GetCurExtendJump() );
			if( pTimeGateJump )
				pTimeGateJump->ProcessComboDash( this );

			ioOmenJump *pOmenJump = ToOmenJump( pItem->GetCurExtendJump() );
			if( pOmenJump )
				pOmenJump->ProcessComboDash( this );
		}

		CheckLanding( fHeightGap, dwCurTime );
		break;
	case JS_BREAK_FALL:
		// HARDCODE: CheckLanding 체크 하지않음.
		//			 ioBreakFallBuff에서 Landing 처리하게되어있음.
		//			 단, 어떠한 이유로 버프가 존재하지 않게 되었다면 예외처리.
		if( !HasBuff(BT_BREAK_FALL) )
		{
			CheckLanding( fHeightGap, dwCurTime );
		}
		break;
	case JS_EXTRA_JUMP:
		if( pItem )
			pItem->ProcessExtraJump( this );
		
		CheckLanding( fHeightGap, dwCurTime );
		break;
	case JS_LANDING:

		if( pItem )
		{
			pItem->ProcessLanding( this );
		}
		else if( m_pExtendJump )
		{
			m_pExtendJump->ProcessLanding( this );
		}

		if( m_dwJumpStateEndTime < dwCurTime )
		{
			ClearDirDoubleClick();

			SetMoveDirByRotate( m_qtTargetRot );

			// Check LandAfter
			if( pJumpAttackItem )
			{
				bool bUseLandAfter = false;
				ioExtendJump *pExtendJump = pJumpAttackItem->GetCurExtendJump();
				if( pExtendJump && pExtendJump->IsEnableLandAfterState() )
				{
					bUseLandAfter = true;

					ioLandAttackJump *pLandJump = ToLandAttackJump(pExtendJump);
					if( pLandJump && m_CharLandType != CLT_EXTEDN_LAND_ATTTACK )
						bUseLandAfter = false;

					ioGrapplingExpansionJump *pGrapplingExpansionJump = ToGrapplingExpansionJump(pExtendJump);
					if( pGrapplingExpansionJump && m_CharLandType != CLT_EXTEDN_LAND_ATTTACK )
						bUseLandAfter = false;

					ioPowerChargeJump *pPowerChargeJump = ToPowerChargeJump(pExtendJump);
					if( pPowerChargeJump && m_CharLandType != CLT_USE_LAND_AFTER )
						bUseLandAfter = false;

					// 권왕 2020-06-03
					ioGwonwangJump *pGwonwangJump = ToGwonwangJump(pExtendJump);
					if( pGwonwangJump && m_CharLandType != CLT_EXTEDN_LAND_ATTTACK )
						bUseLandAfter = false;
				}

				if( bUseLandAfter )
				{
					m_bUsedJumpDefense = false;
					m_bReleaseJumpDefense = false;

					m_bUsedJumpAttack = false;
					m_bUsedBuffJumpAttack = false;
					m_bObjectItemJumpAttack = false;
					m_bUsedChangeJump = false;
					m_bUsedJumpReload = false;

					m_JumpState = JS_NONE;

					m_pGroup->ClearAllLoopAni( FLOAT100, true );
					m_pGroup->ClearAllActionAni( FLOAT100, true );

					ioHashString szAniName = pExtendJump->GetLandAfterAni( m_bSuccessJumpAttack );
					float fAniRate = pExtendJump->GetLandAfterAniRate( m_bSuccessJumpAttack );
					if( fAniRate <= 0.0f )
						fAniRate = FLOAT1;

					int iAniID = m_pGroup->GetAnimationIdx( szAniName );
					m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate );

					m_AnimationTime.dwStartTime = dwCurTime;
					m_AnimationTime.dwFullTime = m_pGroup->GetAnimationFullTime( iAniID ) * fAniRate;

					CheckKeyReserveTime( iAniID, fAniRate );

					SetState( CS_LAND_AFTER_STATE );
					return;
				}
			}

			if( m_bUsedJumpDefense && IsNeedProcess() )		// Jump Defense
			{
				if( IsDefenseKeyDown() )
				{
					m_bChangeDirection = true;
					SetDefenseState();
					return;
				}
			}

			// Key Resesrve & JumpEnd
			if( IsReserveKeyInput() )
			{
				ProcessReserveKeyInput();
			}
			else
			{
				ioObjectAttachItem *pAttachItem = ToObjectAttachItem( pItem );
				if ( pAttachItem )
				{
					pAttachItem->Init();
					SetState( CS_OBJECT_ATTACH );
				}
				else if( m_CurJumpType == JT_AIM_JUMP && IsNeedProcess() )
				{
					SetAimState();
				}
				else if( m_CurJumpType == JT_AIM_JUMP2 && IsNeedProcess() )
				{
					SetCrossBowAimState();
				}
				else if( m_CurJumpType == JT_SUDDEN_ATTACK_JUMP && IsNeedProcess() )
				{
					SetAimState();
				}
				else if( m_CurJumpType == JT_AUTO_SHOT_JUMP && IsNeedProcess() && !IsChatModeState( true ) )
				{
					if( (m_KeyInput.IsAttackKey() || m_KeyInput.IsAttackKeyDown() ) && IsCanNormalAttack() && !IsBuffLimitAttack() )
						SetNormalAttack( m_iAttackCombo );
					else
						SetState( CS_DELAY );
				}
				else if( pJumpAttackItem && IsNeedProcess() && !IsChatModeState( true ) )
				{
					ioExtendJump *pExtendJump = pJumpAttackItem->GetCurExtendJump();
					if( pExtendJump && pExtendJump->IsEnableLandAfterAttackByKeyDown() && (m_KeyInput.IsAttackKey() || m_KeyInput.IsAttackKeyDown() ) && IsCanNormalAttack() && !IsBuffLimitAttack() )
						SetNormalAttack( m_iAttackCombo );
					else
						SetState( CS_DELAY );
				}
				else
				{
					SetState( CS_DELAY );
				}

				m_bUsedJumpAttack = false;
				m_bUsedBuffJumpAttack = false;
				m_bObjectItemJumpAttack = false;
				m_bUsedChangeJump = false;
				m_bUsedJumpReload = false;
				
				m_bSuccessJumpAttack = false;
			}

			if( m_CharState != CS_JUMP )
				m_JumpState = JS_NONE;
		}
		else
		{
			if( pItem && pItem->CheckAimState() )
			{
				if( m_CurJumpType == JT_AIM_JUMP || m_CurJumpType == JT_AIM_JUMP2 )
				{
					pItem->CheckAimJumpState( this );
				}
			}

			if( IsNeedProcess() )
			{
				ioObjectAttachItem *pAttachItem = ToObjectAttachItem( pItem );
				if ( pAttachItem )
					return;

				// HARDCODE :: Check Cmd Input
				ioChargeCommandItem *pCmdItem = ToChargeCommandItem( GetPriorityItem( SPT_JUMP ) );
				ioNakoruruItem *pCmdItem2 = ToNakoruruItem( GetPriorityItem( SPT_JUMP ) );
				ioParkilpyoItem *pParkilpyoItem = ToParkilpyoItem( GetWeapon() );
				ioShieldWeaponItem3 *pShieldWeaponItem3 = ToShieldWeaponItem3( GetWeapon() );
				ioGanesa* pGanesa = ToGanesa( GetPriorityItem( SPT_JUMP ) );
				ioGalfordItem *pGalford = ToGalfordItem( GetPriorityItem( SPT_JUMP ) );
				ioGunnerItem *pGunnerItem = ToGunnerItem( GetPriorityItem( SPT_JUMP ) );
				ioMidnightItem* pMidnight = ToMidnightItem( GetPriorityItem( SPT_JUMP ) );

				if( pCmdItem )
				{
					if( pCmdItem->CheckCmdInputState( this ) )
						return;

					if( pCmdItem->CheckSkillInputState( this ) )
						return;
				}
				else if( pCmdItem2 )
				{
					if( pCmdItem2->CheckCmdInputState( this ) )
						return;

					if( pCmdItem2->CheckSkillInputState( this ) )
						return;
				}
				else if ( pParkilpyoItem )
				{
					if( pParkilpyoItem->CheckCmdInputState( this ) )
						return;
				}
				else if ( pShieldWeaponItem3 )
				{
					if ( pShieldWeaponItem3->IsJumpEndSpecialDash() && IsDirKeyDoubleClick() )
					{
						SetTargetRotToDirKey( m_KeyInput.GetCurDirKey() );
						pShieldWeaponItem3->ChangeConditionSpecialDash( this );
						return;
					}
				}
				else if( pGanesa )
				{
					if( pGanesa->CheckCmdInputState( this ) )
						return;

					if( pGanesa->CheckSkillInputState( this ) )
						return;
				}
				else if ( pGalford )
				{
					if( pGalford->CheckCmdInputState( this ) )
						return;
				}
				else if( pGunnerItem )
				{
					if( pGunnerItem->CheckCmdInputState( this ) )
						return;
				}
				else if( pMidnight )
				{
					if( pMidnight->CheckCmdInputState( this ) )
						return;
				}

				if( pItem && pItem->IsEnableJumpLandEndDash() && IsSettedDirection() )
				{
					SetTargetRotToDirKey( m_KeyInput.GetCurDirKey() );

					ClearDirDoubleClick();

					SetDashState();
					SendDashState( false );
					return;
				}

				if( IsEnableReserveKeyInput() )
				{					
					if ( pItem && pItem->IsEnableJumpLandingExtraState() && m_KeyInput.IsAttackKey() )
					{
						if ( pItem->SetJumpLandingExtraState( this ) )
							return;
					}

					CheckReserveKeyInput();
				}

				if( IsChatModeState( true ) )
				{
					if( m_KeyInput.IsAttackKey() || m_KeyInput.IsDefenseKey() )
						SetChatModeBox();
				}
			}
		}
		break;
	}
}

void ioBaseChar::SetAimJumpState( bool bFullTime )
{
	CheckCurJumpType();

	m_dwJumpStateEndTime = 0;
	m_dwJumpStateEndStart = 0;
	m_dwJumpAttackEndTime = 0;
	m_dwNewJumpAttackEndTime = 0;
	m_fNewJumpAttackGravity = 0.0f;
	m_fAirAttackGravity = 0.f;

	m_bUsedJumpAttack = false;
	m_bUsedBuffJumpAttack = false;
	m_bObjectItemJumpAttack = false;
	m_bSkillNextJump = false;
	m_bUsedFlashJump = false;
	m_bUsedChangeJump = false;
	m_bUsedJumpReload = false;
	
	m_bSuccessJumpAttack = false;
	m_bCrossBowJump = false;

	m_UsedBuffJump = BJUT_NONE;
	m_UsedBuffFlyJump = BJUT_NONE;
	m_UsedBuffMultiFlyJump = BJUT_NONE;

	m_fCurMoveSpeed = max( m_fCurMoveSpeed, FLOAT1 );
	m_fJumpMaxMoveSpeed = GetJumpMaxSpeed();
	m_fJumpPreMoveSpeed = m_fCurMoveSpeed;
	m_fCurMoveSpeed = 0.0f;

	// HARDCODE: 점프중에 랙보정이 오히려 동기화에 해가 되는 느낌
	SetState( CS_JUMP );
	m_fRackMoveAmt = 0.0f;

	ioUserKeyInput::DirKeyInput eDir = CheckCurDirKey();
	if( eDir != ioUserKeyInput::DKI_NONE )
	{
		float fYawD = 180.0f + 45.0f * ( eDir - ioUserKeyInput::DKI_UP );
		fYawD = ioMath::ArrangeHead( fYawD );

		float fYawR = DEGtoRAD( fYawD );
		D3DXQUATERNION qtRotate;
		D3DXQuaternionRotationYawPitchRoll( &qtRotate, fYawR, 0.0f, 0.0f );
		SetMoveDirByRotate( qtRotate );
	}
	m_vInputDir = m_vMoveDir;
	m_byAngleInputDir = m_byAngleMoveDir;

	m_fCurMoveSpeed = m_fJumpPreMoveSpeed;
	
	ioAttackableItem *pItem = GetPriorityItem( SPT_JUMP );
	if( pItem )
	{
		pItem->SetJumpState();
		pItem->SetJumpping( this, bFullTime );
		if( m_CharState != CS_JUMP )
			return;
	}

	int iAniID = GetJumppingAnimationIdx();
	m_pGroup->ClearAllActionAni( FLOAT100, true );

	m_bAimState = true;
	m_JumpState = JS_AIM_JUMP;
}

bool ioBaseChar::IsCanJumpAttack( float fHeightGap )
{
	if( m_bCatchState || m_bPrisonerMode || m_bUsedJumpDefense || m_bUsedJumpReload )
	{
		return false;
	}

	if( IsBuffLimitAttack() )
		return false;

	if( m_iChangeJumppingLimit > 0 && m_iChangeJumppingLimit <= m_iChangeJumppingCnt )
		return false;

	ioAttackableItem *pAttackable = GetPriorityItem( SPT_JUMP );

	// KeyCheck
	if( m_UsedBuffMultiFlyJump == BJUT_CUR || m_UsedBuffMultiFlyJump == BJUT_USED )
	{
		if( !m_KeyInput.IsAttackKeyDown() )
			return false;
	}
	else if( m_UsedBuffFlyJump == BJUT_CUR )
	{
		if( !m_KeyInput.IsAttackKeyDown() )
			return false;
	}
	else if ( m_UsedBuffFlyJump == BJUT_WALK )
	{
		if( !m_KeyInput.IsAttackKeyDown() )
			return false;
	}
	else
	{
		if( m_CurJumpType == JT_AUTO_SHOT_JUMP )
		{
			if( !m_KeyInput.IsAttackKeyDown() )
				return false;

			if( m_KeyInput.IsDefenseKeyDown() )
				return false;

			if( m_KeyInput.IsJumpKeyDown() )
				return false;
		}
		else if( m_CurJumpType != JT_AUTO_SHOT_JUMP && !m_KeyInput.IsAttackKey() )
		{
			switch( m_CurJumpType )
			{
			case JT_BADGUY_JUMP:
			case JT_KISARAGI_JUMP:
			case JT_RAGNA_JUMP:
			case JT_AIM_JUMP:
			case JT_CHARGE_COMBO:
			case JT_DOUBLE_JUMP:
			case JT_RACHEL_JUMP:
			case JT_CHARGE_COMBO3:
			case JT_TRINITY_JUMP:
			case JT_CHARGE_FLASH_JUMP:
			case JT_HAKUMEN_JUMP:
			case JT_SUDDEN_ATTACK_JUMP:
			case JT_PARKILPYO_JUMP:
				break;
			default:
				return false;
			}

			if( !pAttackable )
				return false;

			ioBadGuyJump *pBadGuyJump = ToBadGuyJump( pAttackable->GetCurExtendJump() );
			if( pBadGuyJump && !pBadGuyJump->IsJumpAttackReserve() )
				return false;

			ioKisaragiJump *pKisaragiJump = ToKisaragiJump( pAttackable->GetCurExtendJump() );
			if( pKisaragiJump && !pKisaragiJump->IsJumpAttackReserve() )
				return false;

			ioRagnaJump *pRagnaJump = ToRagnaJump( pAttackable->GetCurExtendJump() );
			if( pRagnaJump && !pRagnaJump->IsJumpAttackReserve() )
				return false;

			ioDoubleJump *pDoubleJump = ToDoubleJump( pAttackable->GetCurExtendJump() );
			if( pDoubleJump && !pDoubleJump->IsJumpAttackReserve() )
				return false;

			ioAimJump *pAimJump = ToAimJump( pAttackable->GetCurExtendJump() );
			if( pAimJump && !pAimJump->IsJumpAttackReserve() )
				return false;

			ioChargeComboJump *pChargeComboJump = ToChargeComboJump( pAttackable->GetCurExtendJump() );
			if( pChargeComboJump && !pChargeComboJump->IsJumpAttackReserve() )
				return false;

			ioChargeComboJump2 *pChargeComboJump2 = ToChargeComboJump2( pAttackable->GetCurExtendJump() );
			if( pChargeComboJump2 && !pChargeComboJump2->IsJumpAttackReserve() )
				return false;

			ioChargeComboJump3 *pChargeComboJump3 = ToChargeComboJump3( pAttackable->GetCurExtendJump() );
			if( pChargeComboJump3 && !pChargeComboJump3->IsJumpAttackReserve() )
				return false;

			ioChargeComboJump4 *pChargeComboJump4 = ToChargeComboJump4( pAttackable->GetCurExtendJump() );
			if( pChargeComboJump4 && !pChargeComboJump4->IsJumpAttackReserve() )
				return false;

			ioSuddenAttackJump *pSuddenJump = ToSuddenAttackJump( pAttackable->GetCurExtendJump() );
			if( pSuddenJump && !pSuddenJump->IsJumpAttackReserve() )
				return false;

			ioChargeComboDefenseJump *pChargeComboDefenseJump = ToChargeComboDefenseJump( pAttackable->GetCurExtendJump() );
			if( pChargeComboDefenseJump && !pChargeComboDefenseJump->IsJumpAttackReserve() )
				return false;

			ioRachelJump *pRachelJump = ToRachelJump( pAttackable->GetCurExtendJump() );
			if( pRachelJump && !pRachelJump->IsJumpAttackReserve() )
				return false;

			ioTrinityJump *pTrinityJump = ToTrinityJump( pAttackable->GetCurExtendJump() );
			if( pTrinityJump && !pTrinityJump->IsJumpAttackReserve() )
				return false;

			ioHakumenJump *pHakumenJump = ToHakumenJump( pAttackable->GetCurExtendJump() );
			if( pHakumenJump && !pHakumenJump->IsJumpAttackReserve() )
				return false;

			ioChargeFlashJump *pChargeFlashJump = ToChargeFlashJump( pAttackable->GetCurExtendJump() );
			if( pChargeFlashJump && !pChargeFlashJump->IsJumpAttackReserve() )
				return false;

			ioParkilpyoJump *pParkilpyoJump = ToParkilpyoJump( pAttackable->GetCurExtendJump() );
			if( pParkilpyoJump )
				return false;
		}
	}

	// check buff
	if( !CheckBuffJumpEnableAttack() )
		return false;

	if( IsChatModeState( true ) )
	{
		SetChatModeBox();
		return false;
	}

	if( m_bUsedJumpAttack || m_bUsedBuffJumpAttack )
		return false;

	if( ToDrinkItem( GetObject() ) )
		return false;

	// 높이 체크
	float fEnableHeight = m_fMinJumpAttackEnableHeight;
	if( pAttackable )
	{
		float fItemEnableHeight = pAttackable->GetJumpAttackEnableHeight();
		if( fItemEnableHeight > 0.0f )
			fEnableHeight = fItemEnableHeight;
	}

	if( m_fCurJumpPowerAmt - m_fGravityAmt < 0.0f && fHeightGap < fEnableHeight )
		return false;

	// 시간체크
	if( !IsCanJumpAttackEnableTime() )
		return false;

	if( pAttackable )
	{
		if( !pAttackable->IsCanJumpAttack( this ) )
			return false;

		if( !pAttackable->IsCanFire( this, 1) )
			return false;
	}
	else
	{
		if(	!m_bJumpAttackEnable )
			return false;
	}

	return true;
}

bool ioBaseChar::IsCan_D_JumpAttack( float fHeightGap )
{
	ioAttackableItem *pAttackable = GetPriorityItem( SPT_JUMP );

	if( pAttackable )
	{
		if( !pAttackable->IsCanJump_D_Attack( this ) )
			return false;
	}

	return true;
}

bool ioBaseChar::IsCanComboJumpAttack( float fHeightGap )
{
	if( m_CurJumpType != JT_COMBO_JUMP &&
		m_CurJumpType != JT_ILJIMAE_JUMP &&
		m_CurJumpType != JT_LEE_JUMP &&
		m_CurJumpType != JT_DESPERADO_JUMP &&
		m_CurJumpType != JT_ROBIN_EXPANSION_JUMP &&
		m_CurJumpType != JT_DOUBLE_JUMP2 &&	
		m_CurJumpType != JT_DOUBLE_JUMP3 &&	
		m_CurJumpType != JT_COMBO_FLASH &&
		m_CurJumpType != JT_STRIDER_JUMP && 
		m_CurJumpType != JT_URIEL_JUMP &&
		m_CurJumpType != JT_PHOENIX_JUMP &&
		m_CurJumpType != JT_TIMEGATE_JUMP && 
		m_CurJumpType != JT_OMEN_JUMP &&
		m_CurJumpType != JT_POSEIDON_JUMP &&
		m_CurJumpType != JT_SKY_WALKER_JUMP &&
		m_CurJumpType != JT_GWONWANG_JUMP &&	// 2020-06-04 권왕
		m_CurJumpType != JT_HERACLES_JUMP &&
		m_CurJumpType != JT_SIZECOMBO_JUMP && 	// 2020-09-24 사이즈	
		m_CurJumpType != JT_EVACOMBO_JUMP &&	// 2020-10-16 이브
		m_CurJumpType != JT_MAGNETIC_JUMP &&	// 마그네틱 2020-11-25
		m_CurJumpType != JT_TAOIST_JUMP )	
	{
		return false;
	}

	if( IsBuffLimitAttack() )
		return false;

	if( m_iChangeJumppingLimit > 0 && m_iChangeJumppingLimit <= m_iChangeJumppingCnt )
		return false;

	if( m_bCatchState || m_bPrisonerMode || m_bUsedJumpDefense || m_bUsedBuffJumpAttack || m_bUsedJumpReload )
	{
		return false;
	}

	// KeyCheck
	if( m_UsedBuffMultiFlyJump == BJUT_CUR || m_UsedBuffMultiFlyJump == BJUT_USED )
	{
		if( !m_KeyInput.IsAttackKeyDown() )
			return false;
	}
	else if( m_UsedBuffFlyJump == BJUT_CUR )
	{
		if( !m_KeyInput.IsAttackKeyDown() )
			return false;
	}
	else if ( m_UsedBuffFlyJump == BJUT_WALK )
	{
		if( !m_KeyInput.IsAttackKeyDown() )
			return false;
	}
	else
	{
		if( !m_KeyInput.IsAttackKey() )
		{
			return false;
		}
	}

	// check buff
	if( !CheckBuffJumpEnableAttack() )
		return false;

	if( IsChatModeState( true ) )
	{
		SetChatModeBox();
		return false;
	}

	if( ToDrinkItem( GetObject() ) )
		return false;

	float fEnableHeight = m_fMinJumpAttackEnableHeight;
	ioAttackableItem *pAttackable = GetPriorityItem( SPT_JUMP );
	if( pAttackable )
	{
		float fItemEnableHeight = pAttackable->GetJumpAttackEnableHeight();
		if( fItemEnableHeight > 0.0f )
			fEnableHeight = fItemEnableHeight;
	}

	if( m_fCurJumpPowerAmt - m_fGravityAmt < 0.0f && fHeightGap < fEnableHeight )
	{
		return false;
	}

	DWORD dwCurTime = FRAMEGETTIME();
	DWORD dwEnableTime = m_dwMinJumpAttackEnableTime;
	if( pAttackable )
	{
		DWORD dwItemEnableTime = pAttackable->GetJumpAttackEnableTime();
		if( dwItemEnableTime > 0 )
			dwEnableTime = dwItemEnableTime;
	}

	if( m_dwJumpMoveStartTime > 0 && dwCurTime < m_dwJumpMoveStartTime + dwEnableTime )
		return false;

	if( pAttackable )
	{
		if( !pAttackable->IsCanJumpAttack( this ) )
		{
			return false;
		}

		if( !pAttackable->IsCanFire( this, 1 ) )
		{
			return false;
		}
	}
	else
	{
		if(	!m_bJumpAttackEnable )
		{
			return false;
		}
	}

	return true;
}

bool ioBaseChar::IsCanFlashJumpAttack( float fHeightGap )
{
	if( (m_CurJumpType != JT_FLASH_JUMP)/* && ( m_CurJumpType != JT_JORO_EXPANSION_JUMP )*/ )
	{
		return false;
	}

	ioAttackableItem *pItem = GetPriorityItemByAttackType( AT_JUMP_ATTACK );
	if( pItem )
	{
		bool bUsedExtend = false;
		if( pItem->CheckUseExtendJump( this ) || m_iBuffJumpCurCnt > 1 )
		{
			bUsedExtend = true;
		}

		ioFlashJump *pFlash = ToFlashJump(pItem->GetCurExtendJump());
		if( pFlash && !pFlash->IsCanFlashJumpAttack(this) && !bUsedExtend )
			return false;
	}

	if( IsBuffLimitAttack() )
		return false;

	if( m_iChangeJumppingLimit > 0 && m_iChangeJumppingLimit <= m_iChangeJumppingCnt )
		return false;

	if( m_bCatchState || m_bPrisonerMode || m_bUsedJumpDefense || m_bUsedBuffJumpAttack || m_bUsedJumpReload )
	{
		return false;
	}

	// KeyCheck
	if( m_UsedBuffMultiFlyJump == BJUT_CUR || m_UsedBuffMultiFlyJump == BJUT_USED )
	{
		if( !m_KeyInput.IsAttackKeyDown() )
			return false;
	}
	else if( m_UsedBuffFlyJump == BJUT_CUR )
	{
		if( !m_KeyInput.IsAttackKeyDown() )
			return false;
	}
	else if ( m_UsedBuffFlyJump == BJUT_WALK )
	{
		if( !m_KeyInput.IsAttackKeyDown() )
			return false;
	}
	else
	{
		if( !m_KeyInput.IsAttackKey() )
			return false;
	}

	// check buff
	if( !CheckBuffJumpEnableAttack() )
		return false;

	if( IsChatModeState( true ) )
	{
		SetChatModeBox();
		return false;
	}

	if( ToDrinkItem( GetObject() ) )
		return false;

	float fEnableHeight = m_fMinJumpAttackEnableHeight;
	ioAttackableItem *pAttackable = GetPriorityItem( SPT_JUMP );
	if( pAttackable )
	{
		float fItemEnableHeight = pAttackable->GetJumpAttackEnableHeight();
		if( fItemEnableHeight > 0.0f )
			fEnableHeight = fItemEnableHeight;
	}

	if( m_fCurJumpPowerAmt - m_fGravityAmt < 0.0f && fHeightGap < fEnableHeight )
	{
		return false;
	}

	DWORD dwCurTime = FRAMEGETTIME();
	DWORD dwEnableTime = m_dwMinJumpAttackEnableTime;
	if( pAttackable )
	{
		DWORD dwItemEnableTime = pAttackable->GetJumpAttackEnableTime();
		if( dwItemEnableTime > 0 )
			dwEnableTime = dwItemEnableTime;
	}

	if( m_dwJumpMoveStartTime > 0 && dwCurTime < m_dwJumpMoveStartTime + dwEnableTime )
		return false;

	if( pAttackable )
	{
		if( !pAttackable->IsCanJumpAttack( this ) )
		{
			return false;
		}

		if( !pAttackable->IsCanFire( this, 1 ) )
		{
			return false;
		}
	}
	else
	{
		if(	!m_bJumpAttackEnable )
		{
			return false;
		}
	}

	return true;
}


