bool ioBaseChar::HasBuff( int iBuffType ) const
{
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		if( pBuff )
		{
			if( pBuff->GetTypeID() == iBuffType )
			{
				//보호 버프의 상태에 따라 값이 다름
				ioStateProtectionByPassiveBuff *pProtectBuffByPassive = ToStateProtectByPassiveBuff( pBuff );
				if ( pProtectBuffByPassive )
				{
					if ( pProtectBuffByPassive->IsProtectState() )
						return true;
					return false;
				}

				return true;	
			}					
		}
	}

	return false;
}

