void ioBaseChar::SetStartMotionState()
{
	int iAniID = GetDelayAnimationIdx();
	m_pGroup->ClearAllLoopAni( FLOAT100, true );
	m_pGroup->ClearAllActionAni( FLOAT100, true );

	bool bWeaponAni = false;
	const ioHashString &szAniStartMotion = GetAniStartAction( bWeaponAni );
	if( bWeaponAni )
	{
		iAniID = GetAnimationIdxAfterConvertName( szAniStartMotion, m_bMale );
	}
	else
	{
		iAniID = m_pGroup->GetAnimationIdx( szAniStartMotion );
	}

	float fTimeRate = m_pGroup->GetAnimationFullTime( iAniID ) / GetNoInputDelayTime();
	m_pGroup->SetActionAni( iAniID, 0.0f, FLOAT100, FLOAT1, fTimeRate, 0.0f, 0.0f, true );

	m_AnimationTime.dwStartTime = FRAMEGETTIME();
	m_AnimationTime.dwFullTime = GetNoInputDelayTime();

	SetState( CS_STARTMOTION );
	m_dwSetStartTime = FRAMEGETTIME();
	if( m_pModeParent )
	{
		m_pModeParent->CheckNonePlayTime( NULL, true );
		m_pModeParent->SetStartBuffList( this );
	}

	SetUserRankEmoticon();

	for( int i=0; i<4; i++ )
	{
		ioItem *pItem = NULL;
		if( m_pEquipSlot )
			pItem = m_pEquipSlot->GetEquipedItem( i );
		if( pItem && pItem->HasSkillGauge() )
		{
			// 게이지 틱 초기화
			if( IsNeedProcess() )
			{
				pItem->ResetTicCheck();
			}

			// 게이지 풀 체크
			if( m_pModeParent && m_pModeParent->IsSafetyLevelRoom() )
			{
				if( m_pModeParent->GetModeType() == MT_KING ||
					m_pModeParent->GetModeType() == MT_SYMBOL || 
					m_pModeParent->GetModeType() == MT_SURVIVAL ||
					m_pModeParent->GetModeType() == MT_FIGHT_CLUB ||
					m_pModeParent->GetModeType() == MT_TEAM_SURVIVAL || 
					m_pModeParent->GetModeType() == MT_DOUBLE_CROWN ||
					m_pModeParent->GetModeType() == MT_SHUFFLE_BONUS ||
					m_pModeParent->GetModeType() == MT_TEAM_SURVIVAL_AI ||
					m_pModeParent->GetModeType() == MT_RAID ||
					m_pModeParent->GetModeType() == MT_FLAG_CAPTURE ||
					Help::IsMonsterDungeonMode(m_pModeParent->GetModeType()))
				{
					pItem->SetCurSkillGauge( FLOAT100 );
				}
			}
		}
	}

	//Accessory
	for( int i=0; i<MAX_EQUIP_SLOT; i++ )
	{
		if ( i == ES_OBJECT || i == ES_WEAR )
			continue;
		ioItem *pItem = NULL;
		if( m_pEquipSlot )
			pItem = m_pEquipSlot->GetEquipedItem( i );
		if( pItem && pItem->HasSkillGauge() )
		{
			// 게이지 틱 초기화
			if( IsNeedProcess() )
			{
				pItem->ResetTicCheck();
			}

			// 게이지 풀 체크
			if( m_pModeParent && m_pModeParent->IsSafetyLevelRoom() )
			{
				if( m_pModeParent->GetModeType() == MT_KING ||
					m_pModeParent->GetModeType() == MT_SYMBOL || 
					m_pModeParent->GetModeType() == MT_SURVIVAL ||
					m_pModeParent->GetModeType() == MT_FIGHT_CLUB ||
					m_pModeParent->GetModeType() == MT_TEAM_SURVIVAL || 
					m_pModeParent->GetModeType() == MT_DOUBLE_CROWN ||
					m_pModeParent->GetModeType() == MT_SHUFFLE_BONUS ||
					m_pModeParent->GetModeType() == MT_TEAM_SURVIVAL_AI ||
					m_pModeParent->GetModeType() == MT_RAID ||
					m_pModeParent->GetModeType() == MT_FLAG_CAPTURE ||
					Help::IsMonsterDungeonMode(m_pModeParent->GetModeType()))
				{
					pItem->SetCurSkillGauge( FLOAT100 );
				}
			}
		}
	}
}

void ioBaseChar::CheckStartMotionState()
{
	if( m_AnimationTime.EndTime() < FRAMEGETTIME() )
	{
		SetState( CS_DELAY );

		if( m_pModeParent && m_pModeParent->GetModeType() != MT_MYROOM )
		{
			bool bEmoticon = false;
			if( m_pModeParent->GetRevivalCnt(this) > 0 )
				bEmoticon = true;

			if( m_pModeParent->GetModeType() == MT_BOSS && GetTeam() == TEAM_BLUE )
			{
				ioBossMode *pBossMode = ToBossMode( m_pModeParent );
				if( pBossMode )
				{
					pBossMode->SetBossProtected( this );
				}
			}
			else if( m_pModeParent->GetModeType() == MT_TEAM_SURVIVAL || m_pModeParent->GetModeType() == MT_DOUBLE_CROWN || m_pModeParent->GetModeType() == MT_TEAM_SURVIVAL_AI )
			{
				if( bEmoticon )
					SetProtectionMode( PM_REVIVAL, m_dwStartProtectionTime2, bEmoticon );
				else
					SetProtectionMode( PM_START, m_dwStartProtectionTime2, bEmoticon );				
			}
			else if( m_pModeParent->GetModeType() == MT_FIGHT_CLUB )
			{
				// 챔피온모드는 시작무적이 없다
			}
			else if( m_ChatModeState == CMS_NONE )
			{
				// 대화모드가 가능한 것은 대화광장뿐, 부활 상황이 없다
				SetProtectionMode( PM_START, GetStartProtectionTime(), bEmoticon );
			}
			else
			{
				if( bEmoticon )
					SetProtectionMode( PM_REVIVAL, GetStartProtectionTime(), false );
				else
					SetProtectionMode( PM_START, GetStartProtectionTime(), false );
			}
		}
		else
		{
			SetProtectionMode( PM_START, GetStartProtectionTime(), false );
		}
	}
}

