	DWORD dwCurTime = FRAMEGETTIME();
	m_AnimationTime.dwStartTime = dwCurTime;
	m_AnimationTime.dwFullTime = m_pGroup->GetAnimationFullTime( iAniID ) - FLOAT100;

	// 집기 동작은 하기 위해 여기서 체크
	if( !pPickItem ) return;

