//확대/축소 설정 함수
void ioBaseChar::CheckScaleList()
{
	int iSize = m_ScaleList.size();
	if( iSize == 0 ) return;

	ioBiped *pBiped = NULL;
	DWORD dwCurTime = FRAMEGETTIME();
	EnlargeList::iterator iter = m_ScaleList.begin();

	while( iter != m_ScaleList.end() )
	{
		ioScaleInfo &rkScale = *iter;

		if( COMPARE( dwCurTime, rkScale.dwFire_s, rkScale.dwFire_e+rkScale.dwSlerpTime ) )
		{
			D3DXVECTOR3 vPreScale, vScale;
			vPreScale.x = FLOAT1 / rkScale.vPreScale.x;
			vPreScale.y = FLOAT1 / rkScale.vPreScale.y;
			vPreScale.z = FLOAT1 / rkScale.vPreScale.z;

			switch( rkScale.szSubInfo )
			{
			case ACT_LEFT_HAND:
			case ACT_LEFT_WEAPON:
				if( !m_blHandScale )
				{
					pBiped = m_pGroup->GetBiped("Bip01 L Hand");
					if( pBiped )
						pBiped->Scale( UpdateScale( rkScale ) );
					m_blHandScale = true;
				}
				else
				{
					pBiped = m_pGroup->GetBiped("Bip01 L Hand");
					if( pBiped )
					{
						pBiped->Scale( vPreScale );
						pBiped->Scale( UpdateScale( rkScale ) );
					}
				}
				break;
			case ACT_RIGHT_WEAPON:
			case ACT_RIGHT_HAND:
				if( !m_brHandScale )
				{
					pBiped = m_pGroup->GetBiped("Bip01 R Hand");

					if( pBiped )
						pBiped->Scale( UpdateScale( rkScale ) );

					m_brHandScale = true;
				}
				else
				{
					pBiped = m_pGroup->GetBiped("Bip01 R Hand");

					if( pBiped )
					{
						pBiped->Scale( vPreScale );
						pBiped->Scale( UpdateScale( rkScale ) );
					}
				}
				break;
			case ACT_LEFT_FOOT:
				if( !m_blFootScale )
				{
					pBiped = m_pGroup->GetBiped("Bip01 L Foot");

					if( pBiped )
						pBiped->Scale( UpdateScale( rkScale ) );

					m_blFootScale = true;
				}
				else
				{
					pBiped = m_pGroup->GetBiped("Bip01 L Foot");

					if( pBiped )
					{
						pBiped->Scale( vPreScale );
						pBiped->Scale( UpdateScale( rkScale ) );
					}
				}
				break;
			case ACT_RIGHT_FOOT:
				if( !m_brFootScale )
				{
					pBiped = m_pGroup->GetBiped("Bip01 R Foot");

					if( pBiped )
						pBiped->Scale( UpdateScale( rkScale ) );

					m_brFootScale = true;
				}
				else
				{
					pBiped = m_pGroup->GetBiped("Bip01 R Foot");

					if( pBiped )
					{
						pBiped->Scale( vPreScale );
						pBiped->Scale( UpdateScale( rkScale ) );
					}
				}
				break;
			}
		}

		++iter;
	}

	// 스케일 종료 체크
	ClearScaleList( false );

	m_dwScaleTime = dwCurTime;
}

D3DXVECTOR3& ioBaseChar::UpdateScale( ioScaleInfo &rkScale )
{
	DWORD dwCurTime = FRAMEGETTIME();
	DWORD dwGapTime = 0;
	float fRate = FLOAT1;

	if( rkScale.dwSlerpTime == 0 )
	{
		rkScale.vPreScale = rkScale.vScale;
		return rkScale.vPreScale;
	}

	if( dwCurTime < rkScale.dwFire_e )
	{
		dwGapTime = dwCurTime - rkScale.dwFire_s;
		dwGapTime = min( dwGapTime, rkScale.dwSlerpTime );

		fRate = (float)dwGapTime / (float)rkScale.dwSlerpTime;
	}
	else
	{
		dwGapTime =  dwCurTime - rkScale.dwFire_e;
		dwGapTime = min( dwGapTime, rkScale.dwSlerpTime );

		fRate = 0.0f;
		if( dwCurTime <= rkScale.dwFire_e+rkScale.dwSlerpTime )
		{
			fRate = (float)dwGapTime / (float)rkScale.dwSlerpTime;
			fRate = FLOAT1 - fRate;
		}
	}

	rkScale.vPreScale.x = FLOAT1 + fRate * (rkScale.vScale.x - FLOAT1);
	rkScale.vPreScale.y = FLOAT1 + fRate * (rkScale.vScale.y - FLOAT1);
	rkScale.vPreScale.z = FLOAT1 + fRate * (rkScale.vScale.z - FLOAT1);

	return rkScale.vPreScale;
}

void ioBaseChar::UpdateSightTarget( float fTimePerSec )
{
	ioNpcChar *pNpcChar = ToNpcChar( this );
	if( pNpcChar )
	{
		if( (pNpcChar->GetNpcType() == NT_NEXUSGUARD) ||  (pNpcChar->GetNpcType() == NT_NEXUS))
			return;
	}

	switch( m_CharState )
	{
	case CS_DIE:
	case CS_CHANGE_WAIT:
	case CS_BLOW_WOUNDED:
	case CS_BOUND_BLOW_WOUNDED:
	case CS_BLOW_EXTEND_WOUND:
	case CS_DROP_ZONE_DOWN:
	case CS_ESCAPE_PRISONER:
	case CS_FROZEN:
	case CS_STOP_MOTION:
	case CS_VIEW:
	case CS_OBSERVER:
	case CS_LOADING:
	case CS_ENDMOTION:
	case CS_SPECIAL_MOTION:
	case CS_ETCITEM_MOTION:
	case CS_NOT_MOVE_PROTECT:
	case CS_ICE_STATE:
		return;
	}

	ioBiped *pBiped = m_pGroup->GetBiped( "Bip01 Head" );
	if(!pBiped)	return;

	bool bAimState = false;
	ioAttackableItem *pItem = GetPriorityItem( SPT_ATTACK );
	if( pItem && pItem->CheckAimState(true) )
	{
		bAimState = true;
	}

	ioBaseChar *pTargetChar = NULL;
	FD_SightTarget kSightPred( this, m_fSightAngle, m_fSightRange );
	if( !bAimState && m_CharState != CS_USING_SKILL )
	{
		if( m_ForceSightTarget.IsEmpty() )
		{
			pTargetChar = m_pCreator->FindUser( kSightPred );
		}
		else
		{
			pTargetChar = m_pCreator->GetBaseChar( m_ForceSightTarget );
			if( !kSightPred.CheckUser( pTargetChar ) )
			{
				pTargetChar = NULL;
				m_ForceSightTarget.Clear();
			}
		}
	}

	if( !bAimState && m_CharState == CS_ATTACK && pItem && pItem->IsChargeAttackState( this ) )
	{
		pTargetChar = NULL;
		m_ForceSightTarget.Clear();

		ReleaseExtraRotate();
		return;
	}

	D3DXQUATERNION qtExtraRot;
	float fGap = m_fAngleSpeed * fTimePerSec;

	if( pTargetChar )
	{
		D3DXVECTOR3 vSightDir = pTargetChar->GetWorldPosition() - GetWorldPosition();
		D3DXVec3Normalize( &vSightDir, &vSightDir );

		D3DXVECTOR3 vXZDir( vSightDir.x, 0.0f, vSightDir.z );
		D3DXVec3Normalize( &vXZDir, &vXZDir );

		D3DXQUATERNION qtTargetRot;
		ioMath::CalcDirectionQuaternion( qtTargetRot, -vXZDir );

		float fCurYaw, fTargetYaw;
		fTargetYaw = RADtoDEG( ioMath::QuaterToYaw( qtTargetRot ) );
		fTargetYaw = ioMath::ArrangeHead( fTargetYaw );
		fCurYaw = RADtoDEG( ioMath::QuaterToYaw(m_qtTargetRot) );
		fCurYaw = ioMath::ArrangeHead( fCurYaw );

		float fRotAngle = DEGtoRAD( ioMath::AngleGap( fCurYaw, fTargetYaw ) );
		if( pTargetChar != m_pSightTarget )
		{
			if( fRotAngle > 0.0f )
			{
				m_fSightExtraRot += fGap;
				if( m_fSightExtraRot < fRotAngle )
				{
					D3DXQuaternionRotationYawPitchRoll( &qtExtraRot, 0.0f, m_fSightExtraRot, 0.0f );
					pBiped->SetExtraRotation( qtExtraRot, true );
				}
				else
				{
					D3DXQuaternionRotationYawPitchRoll( &qtExtraRot, 0.0f, fRotAngle, 0.0f );
					pBiped->SetExtraRotation( qtExtraRot, true );

					m_fSightExtraRot = fRotAngle;
					m_pSightTarget = pTargetChar;
				}
			}
			else
			{
				m_fSightExtraRot -= fGap;
				if( m_fSightExtraRot > fRotAngle )
				{
					D3DXQuaternionRotationYawPitchRoll( &qtExtraRot, 0.0f, m_fSightExtraRot, 0.0f );
					pBiped->SetExtraRotation( qtExtraRot, true );
				}
				else
				{
					D3DXQuaternionRotationYawPitchRoll( &qtExtraRot, 0.0f, fRotAngle, 0.0f );
					pBiped->SetExtraRotation( qtExtraRot, true );

					m_fSightExtraRot = fRotAngle;
					m_pSightTarget = pTargetChar;
				}
			}
		}
		else
		{
			D3DXQuaternionRotationYawPitchRoll( &qtExtraRot, 0.0f, fRotAngle, 0.0f );
			pBiped->SetExtraRotation( qtExtraRot, true );
			m_fSightExtraRot = fRotAngle;
		}
	}
	else
	{
		m_pSightTarget = NULL;

		if( m_fSightExtraRot > 0.0f )
		{
			m_fSightExtraRot = max( 0.0f, m_fSightExtraRot - fGap );
		}
		else if( m_fSightExtraRot < 0.0f )
		{
			m_fSightExtraRot = min( 0.0f, m_fSightExtraRot + fGap );
		}

		if( m_fSightExtraRot != 0.0f )
		{
			D3DXQuaternionRotationYawPitchRoll( &qtExtraRot, 0.0f, m_fSightExtraRot, 0.0f );
			pBiped->SetExtraRotation( qtExtraRot, true );
		}
		else
		{
			pBiped->ReleaseExtraRotation();
		}
	}
}

void ioBaseChar::ReleaseExtraRotate()
{
	if( m_pGroup )
		m_pGroup->ReleaseAllExtraRotate();

	m_fSightExtraRot = 0.0f;
	m_pSightTarget = NULL;
}

//Reduction(and clear) function
void ioBaseChar::ClearScaleList(bool bAll )
{
	ioBiped *pBiped = NULL;
	DWORD dwCurTime = FRAMEGETTIME();
	EnlargeList::iterator iter = m_ScaleList.begin();

	// 종료 체크
	while( iter != m_ScaleList.end() )
	{
		ioScaleInfo &rkScale = *iter;

		D3DXVECTOR3 vScale(1.0f, FLOAT1, FLOAT1);

		if( rkScale.vPreScale.x != FLOAT1 )
			vScale.x = FLOAT1 / rkScale.vPreScale.x;

		if( rkScale.vPreScale.y != FLOAT1 )
			vScale.y = FLOAT1 / rkScale.vPreScale.y;

		if( rkScale.vPreScale.z != FLOAT1 )
			vScale.z = FLOAT1 / rkScale.vPreScale.z;

		if( bAll || dwCurTime > rkScale.dwFire_e+rkScale.dwSlerpTime )
		{
			switch( rkScale.szSubInfo )
			{
			case ACT_LEFT_HAND:
			case ACT_LEFT_WEAPON:
				if( m_blHandScale )
				{
					pBiped = m_pGroup->GetBiped("Bip01 L Hand");

					if( pBiped )
						pBiped->Scale( vScale );

					m_blHandScale = false;
				}
				break;
			case ACT_RIGHT_WEAPON:
			case ACT_RIGHT_HAND:
				if( m_brHandScale )
				{
					pBiped = m_pGroup->GetBiped("Bip01 R Hand");

					if( pBiped )
						pBiped->Scale( vScale );

					m_brHandScale = false;
				}
				break;
			case ACT_LEFT_FOOT:
				if( m_blFootScale )
				{
					pBiped = m_pGroup->GetBiped("Bip01 L Foot");

					if( pBiped )
						pBiped->Scale( vScale );

					m_blFootScale = false;
				}
				break;
			case ACT_RIGHT_FOOT:
				if( m_brFootScale )
				{
					pBiped = m_pGroup->GetBiped("Bip01 R Foot");

					if( pBiped )
						pBiped->Scale( vScale );

					m_brFootScale = false;
				}
				break;
			}
		}

		++iter;
	}

	if( bAll )
	{
		m_ScaleList.clear();
	}
}

