ioSkill* ioBaseChar::GetUseEnableSkill( int iSlot, SkillUseType eType, bool bHelpMsg )
{
	// 캐릭터가 스킬 사용 가능상태인지 체크
	// 캐릭터 상태
	if( m_bPrisonerMode || IsChatModeState( true ) )
	{
		return NULL;
	}

	// 오브젝트 아이템 장착 여부
	ioWeaponItem *pWeapon = GetWeapon();
	ioHookItem *pHook = ToHookItem( pWeapon );
	ioGunnerItem *pGunnerItem = ToGunnerItem( pWeapon );
	ioKungfuMasterItem *pKungfuItem = ToKungfuMasterItem( pWeapon );
	ioBuffAddItem *pBuffAddItem = ToBuffAddItem( pWeapon );
	ioUFCItem *pUFCItem = ToUFCItem( pWeapon );
	iolupinItem *pLupinItem = ToLupinItem( pWeapon );

	// 상태 체크
	ioPaparazziItem* pPaparazziItem = ToPaparazziItem( pWeapon );

	if( pHook )
	{
		if( pHook->CheckOnHand() )
			return NULL;
	}
	else if( pGunnerItem )
	{
		if( pGunnerItem->CheckOnHand() )
			return NULL;
	}
	else if( pKungfuItem )
	{
		if( pKungfuItem->CheckOnHand() && ( iSlot != ES_WEAPON || pKungfuItem->CheckPoseChange() ) )
			return NULL;
	}
	else if( pBuffAddItem && pBuffAddItem->CheckBuffAddState(this) )
	{
		if( iSlot != ES_WEAPON )
			return NULL;
	}
	else if( pLupinItem && pLupinItem->CheckLupinState(this) )
	{
		if( iSlot != ES_WEAPON )
			return NULL;
	}
	else if( pUFCItem )
	{
		if( pUFCItem->CheckOnHand() && iSlot != ES_WEAPON )
			return NULL;
	}

	// 상태 확인 중 처리 작업
	if( pPaparazziItem )
		pPaparazziItem->CheckPaparazziState( this );

	if( GetObject() )
	{
		if( GetObject()->IsOneTimeWeaponItem() )
			return NULL;

		ioCreateItemBuffSkill *pCheckSkill = ToCreateItemBuffSkill( m_pEquipSlot->GetEquipedSkill( iSlot ) );
		if( !pCheckSkill )
		{
			if( !GetObject()->CheckEnableUseSkill( iSlot, this ) )
			{
				return NULL;
			}
		}
		else if( IsObejctEquipState() )
			return NULL;	
		else if( pCheckSkill && !GetObject()->CheckEnableUseSkill( iSlot, this ) )
			return NULL;
	}

	if( m_pEquipSlot )
	{
		if( m_pEquipSlot->IsEquipWait() )
			return NULL;
	}
	
	// 스킬이 사용가능 상태인지 체크
	ioSkill *pEnableSkill = NULL;
	if( m_pEquipSlot )
		pEnableSkill = m_pEquipSlot->GetUseEnableSkill( iSlot, bHelpMsg );
	if( !pEnableSkill )
		return NULL;

	// 스킬 사용 여부 체크 2020-11-13
	if( !pEnableSkill->IsCheckEnableSkill( iSlot, this ) )
		return NULL;

	if( pEnableSkill->IsOnlyDownSkill() && eType != SUT_DOWN )
		return NULL;
	else if( pEnableSkill->IsOnlyJumppingSkill() && eType != SUT_JUMP )
		return NULL;

	if( CheckDisableSkillByMode( pEnableSkill->GetName() ) )
		return NULL;

	if( HasBuff( BT_SEAL_SKILL ) )
	{
		ioBuffSkill *pBuffSkill = ToBuffSkill(pEnableSkill);
		if( ToBuffSkill(pEnableSkill) && ToBuffSkill(pEnableSkill)->IsCanStateEscape() )
			return pEnableSkill;
		else
			return NULL;
	}

	if( m_bCatchState )
	{
		ioStateEscapeSkill *pEscapeSkill = ToStateEscapeSkill( pEnableSkill );
		ioBuffSkill *pBuffSkill = ToBuffSkill( pEnableSkill );
		ioRangeSkill	*pRangeSkill = ToRangeSkill( pEnableSkill );
		ioAttackSkill	*pAttackSkill = ToAttackSkill( pEnableSkill );
		if( !pEscapeSkill && !pBuffSkill && !pAttackSkill && !pRangeSkill )
			return NULL;

		if( pBuffSkill && !pBuffSkill->IsCanStateEscape() )
			return NULL;

		if( pAttackSkill )
		{
			if( pAttackSkill->IsCanStateEscape() )
			{
				if( pAttackSkill->IsCanStateEscapeOnStand( this ) )
					return pEnableSkill;

				else if( pAttackSkill->IsCanStateEscapeOnAir( this ) )
					return pEnableSkill;

				else if( pAttackSkill->IsCanStateEscapeOnDown( this ) )
					return pEnableSkill;
			}
			return NULL;
		}

		if( pRangeSkill )
		{
			if( pRangeSkill->IsCanStateEscape() )
			{
				if( pRangeSkill->IsCanStateEscapeOnStand( this ) )
					return pEnableSkill;

				else if( pRangeSkill->IsCanStateEscapeOnAir( this ) )
					return pEnableSkill;

				else if( pRangeSkill->IsCanStateEscapeOnDown( this ) )
					return pEnableSkill;
			}
			return NULL;
		}
	}

	for( int i=0; i<m_aBuffArray->MaxCount(); ++i )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);

		ioCreateDummyChar5Buff *pCreateDummy5Buff = ToCreateDummyChar5Buff( pBuff );
		if( pCreateDummy5Buff && !pCreateDummy5Buff->CheckEnableUseSkill( iSlot ) )
			return NULL;

		ioTargetCreateWeaponBuff *pTargetCreateWeaponBuff = ToTargetCreateWeaponBuff( pBuff );
		if( pTargetCreateWeaponBuff && !pTargetCreateWeaponBuff->CheckEnableUseSkill( iSlot ) )
			return NULL;

		ioTargetCreateWeaponBuff2 *pTargetCreateWeaponBuff2 = ToTargetCreateWeaponBuff2( pBuff );
		if( pTargetCreateWeaponBuff2 && !pTargetCreateWeaponBuff2->CheckEnableUseSkill( iSlot ) )
			return NULL;

		ioTargetMoveBuff *pTargetMoveBuff = ToTargetMoveBuff( pBuff );
		if( pTargetMoveBuff && !pTargetMoveBuff->CheckEnableUseSkill( iSlot ) )
			return NULL;

		ioDummyAttachBuff3 *pDummyAttachBuff3 = ToDummyAttachBuff3( pBuff );
		if( pDummyAttachBuff3 && !pDummyAttachBuff3->CheckEnableUseSkill( iSlot ) )
			return NULL;

		ioHelipCopterAttachBuff *pHelipCopterAttachBuff = ToHelipCopterAttachBuff( pBuff );
		if( pHelipCopterAttachBuff && !pHelipCopterAttachBuff->CheckEnableUseSkill( iSlot ) )
			return NULL;

		ioTargetRushAttackBuff *pTargetRushAttackBuff = ToTargetRushAttackBuff( pBuff );
		if( pTargetRushAttackBuff && !pTargetRushAttackBuff->CheckEnableUseSkill( iSlot ) )
			return NULL;

		ioDummyChainBuff *pDummyChainBuff = ToDummyChainBuff( pBuff );
		if( pDummyChainBuff && !pDummyChainBuff->CheckEnableUseSkill( iSlot ) )
			return NULL;

		ioMoveAttackBuff *pMoveAttackBuff = ToMoveAttackBuff( pBuff );
		if( pMoveAttackBuff && !pMoveAttackBuff->CheckEnableUseSkill( iSlot ) )
			return NULL;

		ioTargetMoveAttackBuff *pTargetMoveAttackBuff = ToTargetMoveAttackBuff( pBuff );
		if( pTargetMoveAttackBuff && !pTargetMoveAttackBuff->CheckEnableUseSkill( iSlot ) )
			return NULL;

		ioCreateDummyChar9Buff *pCreateDummyChar9Buff = ToCreateDummyChar9Buff( pBuff );
		if( pCreateDummyChar9Buff && !pCreateDummyChar9Buff->CheckEnableUseSkill( iSlot ) )
			return NULL;

		ioMoveAttackBuff2 *pMoveAttackBuff2 = ToMoveAttackBuff2( pBuff );
		if( pMoveAttackBuff2 && !pMoveAttackBuff2->CheckEnableUseSkill( iSlot ) )
			return NULL;
	}

	return pEnableSkill;
}

