bool ioBaseChar::CheckCharChangeStateByEquipItem()
{
	for( int i = 0; i < MAX_INVENTORY; ++i )
	{
		if( !GetEquipedItem( i ) )
			return false;
	}

	ioWearItem *pWearItem = GetWear();
	if( pWearItem && !pWearItem->CharCanChange() )
		return false;

	return true;
}

ioAttackableItem* ioBaseChar::GetEquipedAttackableItem( DWORD dwItemCode, int iCreateIndex ) const
{
	ioAttackableItem *pWeapon = GetPriorityItem( SPT_ATTACK );
	if( pWeapon )
	{
		if( pWeapon->GetItemCode() == dwItemCode )
		{
			return pWeapon;
		}
	}

	ioArmorItem *pArmor = GetArmor();
	if( pArmor )
	{
		if( pArmor->GetItemCode() == dwItemCode )
		{
			return pArmor;
		}
	}

	return NULL;
}

ioAttackableItem* ioBaseChar::GetPriorityItem( StatePriorityType eType ) const
{
	ioWeaponItem *pWeapon = GetWeapon();
	ioArmorItem *pArmor = GetArmor();
	ioObjectItem *pObject = GetObject();

	int iCharPriority = GetDefaultPriority( eType );

	if( pObject )
	{
		if( pObject->GetPriority( eType ) >= iCharPriority )
		{
			return pObject;
		}
		else
		{
			if( pWeapon && pWeapon->GetPriority( eType ) >= iCharPriority )
			{
				if( pArmor )
				{
					if( pWeapon->GetPriority( eType ) >= pArmor->GetPriority( eType ) )
						return pWeapon;
					else
						return pArmor;
				}
				else
					return pWeapon;
			}
			else
			{
				if( pArmor )
				{
					if( iCharPriority >= pArmor->GetPriority( eType ) )
						return NULL;
					else
						return pArmor;
				}
				else
					return NULL;
			}
		}
	}
	else if( pWeapon )
	{
		if( pWeapon->GetPriority( eType ) >= iCharPriority )
		{
			if( pArmor )
			{
				if( pWeapon->GetPriority( eType ) >= pArmor->GetPriority( eType ) )
					return pWeapon;
				else
					return pArmor;
			}
			else
				return pWeapon;
		}
		else
		{
			if( pArmor )
			{
				if( iCharPriority >= pArmor->GetPriority( eType ) )
					return NULL;
				else
					return pArmor;
			}
			else
				return NULL;
		}
	}
	else if( pArmor )
	{
		if( pArmor->GetPriority( eType ) > iCharPriority )
			return pArmor;
		else
			return NULL;
	}

	return NULL;
}

int ioBaseChar::GetDefaultPriority( StatePriorityType eType ) const
{
	if( COMPARE( eType, SPT_DEFENSE, MAX_SPT_TYPE ) )
		return m_pDefaultPriority->GetPriority( eType );
	
	return -1;
}

ioAttackableItem* ioBaseChar::GetPriorityItemByAttackType( AttackType eType ) const
{
	switch( eType )
	{
	case AT_NORMAL:
		return GetPriorityItem( SPT_ATTACK );
	case AT_COUNTER_ATTACK:
		return GetPriorityItem( SPT_DEFENSE );
	case AT_DASH_ATTACK:
	case AT_EXTRA_DASH_ATTACK:
	case AT_EXTRA_OTHER_DASH_ATTACK:
		return GetPriorityItem( SPT_DASH );
	case AT_JUMP_ATTACK:
	case AT_EXTEND_JUMP_ATTACK:
	case AT_LAND_JUMP_ATTACK:
	case AT_EXTEND_LAND_JUMP_ATTACK:
	case AT_HIGH_JUMP_ATTACK:
		return GetPriorityItem( SPT_JUMP );
	}

	return NULL;
}

bool ioBaseChar::GetPriorityFeature( StatePriorityType eType,
									 ItemFeature eFeature,
									 bool bNullTrue ) const
{
	ioAttackableItem *pItem = GetPriorityItem( eType );
	if( pItem )
	{
		return pItem->HasFeature( eFeature );
	}

	return bNullTrue;
}

