void ioBaseChar::SetProtectionMode( ProtectionMode eMode, DWORD dwDuration, bool bUseEmoticon )
{
	m_ProtectionMode = eMode;

	EndEffect( m_BossProtectEffect );
	switch( m_ProtectionMode )
	{
	case PM_NONE:
		m_dwProtectionStartTime = 0;
		m_dwProtectionModeTime = 0;

		if( m_iProtectionColorIndex != -1 )
		{
			RestoreMaterialColor( m_iProtectionColorIndex );
			m_iProtectionColorIndex = -1;

			RestoreOutLineChange( COT_SYSTEM_PROTECTION );
		}

		m_bProtectionColor = false;
		m_dwProtectionChangeTime = 0;

		if( m_CurProtectionEffect != -1 )
		{
			EndEffect( m_CurProtectionEffect, false );
			m_CurProtectionEffect = -1;
		}
		break;
	case PM_START:
	case PM_REVIVAL:
	case PM_GETUP:
	case PM_CATCH:
	case PM_ESCAPE:
	case PM_BOSS:
		if( dwDuration > 0 )
		{
			m_dwProtectionStartTime = FRAMEGETTIME();
			if ( m_ProtectionMode == PM_GETUP && HasBuff( BT_ACC_GETUP_PROTECTION_DELAY_BUFF ) )
			{
				ioAccGetUpProtectionDelayBuff *pGetUpBuff = ToAccGetUpProtectionDelayBuff( GetBuff(BT_ACC_GETUP_PROTECTION_DELAY_BUFF,m_Name ) );
				if ( pGetUpBuff )
					pGetUpBuff->CheckGetUpDelayDuration( dwDuration, m_pModeParent->GetModeType() );

			}
			m_dwProtectionModeTime = dwDuration;
			

			if( bUseEmoticon && m_ProtectionMode == PM_REVIVAL )
			{
				CheckNamedEmoticon( ioModeHelpManager::HT_REVIVAL_BLOCK, true );
			}

			if( m_ProtectionMode == PM_BOSS )
				ApplyOutLineChange( COT_SYSTEM_PROTECTION, m_ProtectionColorBoss, m_fProtectionLineWidth );
			else if( GetTeam() == TEAM_RED )
				ApplyOutLineChange( COT_SYSTEM_PROTECTION, m_ProtectionColorRed, m_fProtectionLineWidth );
			else if( GetTeam() == TEAM_BLUE )
				ApplyOutLineChange( COT_SYSTEM_PROTECTION, m_ProtectionColorBlue, m_fProtectionLineWidth );
			else // 개인전
			{
				if( GetSingleConvertTeam() == TEAM_BLUE )
					ApplyOutLineChange( COT_SYSTEM_PROTECTION, m_ProtectionColorBlue, m_fProtectionLineWidth );
				else
					ApplyOutLineChange( COT_SYSTEM_PROTECTION, m_ProtectionColorRed, m_fProtectionLineWidth );
			}

			if( m_ProtectionMode == PM_BOSS )
			{				
				// 보스 이펙트
				AttachEffect( m_BossProtectEffect );
			}

			//
			if( m_CurProtectionEffect != -1 )
			{
				EndEffect( m_CurProtectionEffect, false );
				m_CurProtectionEffect = -1;
			}

			ioItem *pItem = GetEquipedItem( ES_WEAPON );
			if( pItem )
			{
				ioHashString szEffect = pItem->GetProtectionEffect();
				if( !szEffect.IsEmpty() )
				{
					ioEffect* pEffect = AttachEffect( szEffect );
					if( pEffect )
						m_CurProtectionEffect = pEffect->GetUniqueID();
				}
			}

			if( m_CurProtectionEffect == -1 && !m_ProtectionEffect.IsEmpty() )
			{
				ioEffect* pEffect = AttachEffect( m_ProtectionEffect );
				if( pEffect )
					m_CurProtectionEffect = pEffect->GetUniqueID();
			}

			m_bProtectionColor = true;
			m_dwProtectionChangeTime = FRAMEGETTIME();

			if( m_iProtectionColorIndex != -1 )
			{
				RestoreMaterialColor( m_iProtectionColorIndex );
				m_iProtectionColorIndex = -1;
			}

			if( GetTeam() == TEAM_RED )
				m_iProtectionColorIndex = ModifyMaterialColor( m_ProtectionRedSkinColor );
			else if( GetTeam() == TEAM_BLUE )
				m_iProtectionColorIndex = ModifyMaterialColor( m_ProtectionBlueSkinColor );
			else // 개인전
			{
				if( GetSingleConvertTeam() == TEAM_BLUE )
					m_iProtectionColorIndex = ModifyMaterialColor( m_ProtectionBlueSkinColor );
				else
					m_iProtectionColorIndex = ModifyMaterialColor( m_ProtectionRedSkinColor );
			}
		}
		else
		{
			m_ProtectionMode = PM_NONE;
			m_dwProtectionStartTime = 0;
			m_dwProtectionModeTime = 0;

			if( m_iProtectionColorIndex != -1 )
			{
				RestoreMaterialColor( m_iProtectionColorIndex );
				m_iProtectionColorIndex = -1;
			}

			RestoreOutLineChange( COT_SYSTEM_PROTECTION );

			m_bProtectionColor = false;
			m_dwProtectionChangeTime = 0;
		}
		break;
	}
}

void ioBaseChar::ProcessProtectionMode()
{
	if( m_ProtectionMode == PM_NONE || m_dwProtectionStartTime == 0 )
		return;

	DWORD dwCurTime = FRAMEGETTIME();
	if( m_dwProtectionStartTime + m_dwProtectionModeTime < dwCurTime )
	{
		if( m_ProtectionMode == PM_REVIVAL )
		{
			EndUnLimitedEmoticon();
		}

		if( m_ProtectionMode == PM_BOSS )
		{
			AttachEffect( m_BossProtectEndEffect );
		}

		if( m_iProtectionColorIndex != -1 )
		{
			RestoreMaterialColor( m_iProtectionColorIndex );
			m_iProtectionColorIndex = -1;
		}

		RestoreOutLineChange( COT_SYSTEM_PROTECTION );
		SetProtectionMode( PM_NONE, 0 );
	}
	else if( m_dwProtectionChangeTime > 0 )
	{
		if( m_bProtectionColor )
		{
			if( m_dwProtectionChangeTime + m_dwProtectionCheckTime2 < dwCurTime )
			{
				m_bProtectionColor = false;
				m_dwProtectionChangeTime = dwCurTime;

				if( m_iProtectionColorIndex != -1 )
				{
					RestoreMaterialColor( m_iProtectionColorIndex );
					m_iProtectionColorIndex = -1;
				}
			}
		}
		else
		{
			if( m_dwProtectionChangeTime + m_dwProtectionCheckTime1 < dwCurTime )
			{
				m_bProtectionColor = true;
				m_dwProtectionChangeTime = dwCurTime;

				if( m_iProtectionColorIndex != -1 )
				{
					RestoreMaterialColor( m_iProtectionColorIndex );
					m_iProtectionColorIndex = -1;
				}

				if( m_iSkillColorIndex == -1 )
				{
					if( GetTeam() == TEAM_RED )
						m_iProtectionColorIndex = ModifyMaterialColor( m_ProtectionRedSkinColor );
					else if( GetTeam() == TEAM_BLUE )
						m_iProtectionColorIndex = ModifyMaterialColor( m_ProtectionBlueSkinColor );
					else // 개인전
					{
						if( GetSingleConvertTeam() == TEAM_BLUE )
							m_iProtectionColorIndex = ModifyMaterialColor( m_ProtectionBlueSkinColor );
						else
							m_iProtectionColorIndex = ModifyMaterialColor( m_ProtectionRedSkinColor );
					}
				}
			}
		}
	}
}

void ioBaseChar::ProcessActionStopDelay( float fTimePerSec, float fLooseRate )
{
	if( m_dwActionStopCurDelay == 0 )
		return;

	DWORD dwCurTime = (DWORD)( fTimePerSec * FLOAT1000 );
	if( m_dwActionStopCurDelay >= dwCurTime )
	{
		m_dwActionStopCurDelay -= dwCurTime;
	}
	else
	{
		m_dwActionStopCurDelay = 0;
	}

	// 적용된 시간만큼 추가
	DWORD dwAdd = dwCurTime - dwCurTime * fLooseRate;
	m_dwActionStopCurAdd += dwAdd;
	m_dwActionStopTotalDelay += dwAdd;
}

DWORD ioBaseChar::AddPushPowerEnhanceRate( EnhanceOwnerType eType, float fRate, bool bWound )
{
	if( bWound )
	{
		if( m_pWoundPushPowerEnhance )
			return m_pWoundPushPowerEnhance->AddEnhanceRate( eType, fRate );
	}
	else
	{
		if( m_pPushPowerEnhance )
			return m_pPushPowerEnhance->AddEnhanceRate( eType, fRate );
	}

	return 0;
}

void ioBaseChar::RemovePushPowerEnhanceRate( EnhanceOwnerType eType, DWORD dwID, bool bWound )
{
	if( bWound )
	{
		if( m_pWoundPushPowerEnhance )
			m_pWoundPushPowerEnhance->RemoveEnhanceRate( eType, dwID );
	}
	else
	{
		if( m_pPushPowerEnhance )
			m_pPushPowerEnhance->RemoveEnhanceRate( eType, dwID );
	}
}

bool ioBaseChar::HasPushPowerEnhanceRate( EnhanceOwnerType eType, bool bWound )
{
	if( bWound )
	{
		if( m_pWoundPushPowerEnhance )
			return m_pWoundPushPowerEnhance->HasEnhanceRate( eType );
	}
	else
	{
		if( m_pPushPowerEnhance )
			return m_pPushPowerEnhance->HasEnhanceRate( eType );
	}

	return false;
}

