void ioBaseChar::SendCurrentPositionToAllUser( const ioHashString rkName /*= "" */ )
{
	if( m_CharState == CS_GRAPPLING_WOUNDED || 
		m_CharState == CS_GRAPPLING_WOUNDED_SKILL ||
		m_CharState == CS_GRAPPLING_WOUNDED_SWING ||
		m_CharState == CS_JUMP_GRAPPLING_WOUNDED ||
		m_CharState == CS_CHARGE_FLY ||
		m_CharState == CS_PANIC_MOVE ||
		m_CharState == CS_GRAPPLING_WOUNDED_ITEM ||
		m_CharState == CS_GRAPPLING_WOUNDED_BUFF ||
		m_CharState == CS_GRAPPLING_EXPANSION )
		return;

	if( m_CharState == CS_USING_SKILL && m_pActiveSkill && !m_pActiveSkill->IsCanSendControl() )
		return;

	ioWeaponItem* pWeapon = GetWeapon();
	if( m_CharState == CS_ATTACK && pWeapon && !pWeapon->IsCanSendControl() )
		return;

	if( m_pCharSpeicalState && !m_pCharSpeicalState->IsSendControlInfoToUser( this ) )
		return;

	if( rkName.IsEmpty() && IsNeedSendNetwork() )
	{
		SP2Packet kPacket( CUPK_CHAR_CONTROL );
		FillControlInfo( kPacket );
		P2PNetwork::SendToAllPlayingUser( kPacket );

		if( m_pCreator )
		{
			m_pCreator->NotifyOwnerSendControlInfo();
		}
	}
	else if( !rkName.IsEmpty() )
	{
		SP2Packet kPacket( CUPK_CHAR_CONTROL );
		FillControlInfo( kPacket );
		P2PNetwork::SendToUser( rkName, kPacket );
	}
}

void ioBaseChar::SendControlInfoToUser( const ioHashString &rkName )
{
	SendCurrentPositionToAllUser( rkName );
}

void ioBaseChar::FillControlInfo( SP2Packet &rkPacket )
{
	//패킷 최적화 작업
	rkPacket << GetCharName();

	rkPacket << P2PNetwork::GetNextSendIndex( IsNpcChar( this ) );
	rkPacket << g_GlobalTimer.GetGlobalTime();
	rkPacket << (BYTE)m_KeyInput.GetCurDirKey();

	BYTE byPack8 = (((int)m_bForcePowerLinear << 3) | 
		((int)m_bReverseDirection << 2) |
		((int)IsFloatingState() << 1) |
		((int)IsFloating() << 0));
	rkPacket << byPack8;

	UpdateMoveDir2BYTE();
	UpdateInputDir2BYTE();
	UpdateForceDir2BYTE();
	//dir 3개..
	rkPacket << m_byAngleMoveDir << m_byAngleInputDir << m_byAngleForceDirX << m_byAngleForceDirY << m_byAngleForceDirZ;
	//qt
	rkPacket << m_halfRot[0] << m_halfRot[1] << m_halfRot[2];

	rkPacket << floatToHALF( m_fCurMoveSpeed );
	rkPacket << floatToHALF( m_fForceAmt );
	rkPacket << floatToHALF( m_fForceFrictionRate );

	rkPacket << (BYTE)m_CharState;

	D3DXVECTOR3 vPos = GetWorldPosition();
	rkPacket << floatToHALF( vPos.x ) << floatToHALF( vPos.y ) << floatToHALF( vPos.z );
}

void ioBaseChar::ApplyCharControl( SP2Packet &rkPacket )
{
	DWORD dwHostTime;
	D3DXVECTOR3 vMoveDir;
	D3DXVECTOR3 vRecvPos;
	D3DXQUATERNION qtRot;
	BYTE cCharState;
	bool bFloatingState = false;
	bool bFloating = false;

	BYTE byDirKey;
	BYTE bPack8;

	rkPacket >> dwHostTime;
	rkPacket >> byDirKey;

	rkPacket >> bPack8;
	m_bForcePowerLinear = ((bPack8 >> 3) & 1) == 1;
	m_bReverseDirection = ((bPack8 >> 2) & 1) == 1;
	bFloatingState = ((bPack8 >> 1) & 1) == 1;
	bFloating = (bPack8 & 1) == 1;

	BYTE byAngleMoveDir,byAngleInputDir,byAngleForceDirX,byAngleForceDirY,byAngleForceDirZ;
	rkPacket >> byAngleMoveDir >> byAngleInputDir >> byAngleForceDirX >> byAngleForceDirY >> byAngleForceDirZ;
	ConvertPackAngle2Vec( byAngleMoveDir, vMoveDir );
	ConvertPackAngle2Vec( byAngleInputDir, m_vInputDir );
	ConvertForceXYZ2Vec( D3DXVECTOR3(byAngleForceDirX, byAngleForceDirY, byAngleForceDirZ), m_vForceDir );

	HALF half[3];
	D3DXVECTOR3 vAngle;
	rkPacket >> half[0] >> half[1] >> half[2];
	InputHalf2Vec( half, vAngle );
	D3DXQuaternionRotationYawPitchRoll( &qtRot, vAngle.y, vAngle.x, vAngle.z );

	HALF halfTemp;
	rkPacket >> halfTemp;
	m_fCurMoveSpeed = HALFToFloat( halfTemp );
	rkPacket >> halfTemp;
	m_fForceAmt = HALFToFloat( halfTemp );
	rkPacket >> halfTemp;
	m_fForceFrictionRate = HALFToFloat( halfTemp );

	rkPacket >> cCharState;
	int iCharState = cCharState;

	rkPacket >> half[0] >> half[1] >> half[2];
	InputHalf2Vec( half, vRecvPos );

	m_KeyInput.SetNetworkKeyInput( (ioUserKeyInput::DirKeyInput)byDirKey );

	// 예외체크
	if( iCharState == CS_ENDMOTION )
		return;

	// 방향값 적용에 대한 판단.
	switch( m_CharState )
	{
	case CS_JUMP:
		if( m_JumpState != JS_LANDING )
			SetTargetRot( qtRot );
		else
			SetTargetRotAndMoveDirChange( qtRot );
		break;
	case CS_NEW_JUMP_ATTACK:
		SetTargetRot( qtRot );
		break;
	case CS_DEFENSE:
	case CS_WOUNDED_DEFENSE:
		SetTargetRot( qtRot );
		m_vMoveDir = vMoveDir;
		break;
	case CS_EXTEND_DEFENSE:
		if( m_bDefenseMoveEnable )
		{
			SetTargetRot( qtRot );
			m_vMoveDir = vMoveDir;
		}
		else
		{
			SetTargetRotAndMoveDirChange( qtRot );
		}
		break;
	case CS_CLOSEORDER:
		SetTargetRotAndMoveDirChange( qtRot, true );
		break;
	case CS_USING_SKILL:
		if( m_bSkillMoveEnable && m_pActiveSkill )
		{
			SetTargetRot( qtRot );
			m_vMoveDir = vMoveDir;
		}
		else if( m_bSkillMoveChangeDir && m_pActiveSkill &&
				 (ToLinearComboSkill(m_pActiveSkill) || ToMultiDummyCharSkill(m_pActiveSkill) || ToChargeLineComboSkill(m_pActiveSkill) ) )
		{
			SetTargetRot( qtRot );
			m_vMoveDir = vMoveDir;
		}
		else if( ToDefenseAttackSkill(m_pActiveSkill) && m_pActiveSkill->IsCanDefenseStateSkill() )
		{
			SetTargetRot( qtRot );
			m_vMoveDir = vMoveDir;
		}
		else if( ToDefenseAttack2Skill(m_pActiveSkill) && m_pActiveSkill->IsCanDefenseStateSkill() )
		{
			SetTargetRot( qtRot );
			m_vMoveDir = vMoveDir;
		}
		break;
	case  CS_ATTACK:
		if( m_bAttackMoveEnable )
		{
			SetTargetRot( qtRot );
			m_vMoveDir = vMoveDir;
			break;
		}
		// break 일부로 뺀 것
	default:
		SetTargetRot( qtRot );
		m_vMoveDir = vMoveDir;
		break;
	}

	// 상태전환에 대한 판단
	if( m_CharState != iCharState &&
		m_CharState != CS_DIE &&
		m_CharState != CS_READY &&
		m_CharState != CS_LOADING &&
		m_CharState != CS_OBSERVER &&
		m_CharState != CS_VIEW &&
		m_CharState != CS_DRINK &&			 //물약 먹는 모션이 간혹 딜레이 상태로 전환된다...
		m_CharState != CS_STARTMOTION &&
		m_CharState != CS_BATTLE_WAITING)      //시작모션이 끝나기 전에 딜레이로 전환되어 무적 아웃라인 처리가 안된다.
	{
		switch( iCharState )
		{
		case CS_DELAY:
			SetState( CS_DELAY );
			break;
		case CS_RUN:
			if( byDirKey != 0 )
			{
				SetState( CS_RUN );
			}
			break;
		case CS_DASH:
			if( byDirKey != 0 )
			{
				SetDashState();
			}
			break;
		}
	}

	if( Help::CheckEnableTimeGapUser() )
	{
		DWORD dwCurGTime = g_GlobalTimer.GetGlobalTime();
		if( dwHostTime > dwCurGTime && (dwHostTime-dwCurGTime) > 100 )
		{
			LOG.PrintTimeAndLog( 0, "TC - ControlTCheck1: %s, %d", GetCharName().c_str(), (dwHostTime-dwCurGTime) );
		}
		else if( dwHostTime <= dwCurGTime && (dwCurGTime-dwHostTime) > 100 )
		{
			LOG.PrintTimeAndLog( 0, "TC - ControlTCheck2: %s, %d", GetCharName().c_str(), (dwCurGTime-dwHostTime) );
		}
	}

	bool bNoGhostWalk = false;

	if( bNoGhostWalk )
		m_fRackMoveAmt = 0.0f;
	else
		GhostWalk( vRecvPos, dwHostTime, bFloatingState, bFloating );
}

void ioBaseChar::ApplyNormalAttack( SP2Packet &rkPacket )
{
	DWORD dwWeaponIdx;
	rkPacket >> dwWeaponIdx;
	SetWeaponIndexBase( dwWeaponIdx );

	rkPacket >> m_qtTargetRot;
	rkPacket >> m_vMoveDir;

	int iCurCombo;
	rkPacket >> iCurCombo;

	float fCurHP;
	rkPacket >> fCurHP;

	ioHashString szAutoTarget;
	rkPacket >> szAutoTarget;

	D3DXVECTOR3 vTrackingBasisDir;
	rkPacket >> vTrackingBasisDir;

	DWORD dwAutoTrackingDuration = 0;
	rkPacket >> dwAutoTrackingDuration;

	int iType;
	rkPacket >> iType;
	m_AutoTargetType = (AutoTargetType)iType;

	bool bAutoTargetBall;
	rkPacket >> bAutoTargetBall;

	bool bAutoTargetDummyChar = false;
	rkPacket >> bAutoTargetDummyChar;

	bool bExistItem;
	rkPacket >> bExistItem;

	// 아이템 정보확인 -> 공격실행 -> 오토타겟 세팅 순으로 처리되야 함
	if( bExistItem )
	{
		int iItemIndex;
		DWORD dwItemCode;
		rkPacket >> dwItemCode >> iItemIndex;

		ioAttackableItem *pAttackItem = GetEquipedAttackableItem( dwItemCode, iItemIndex );
		if( pAttackItem )
		{
			pAttackItem->ApplyNormalAttackExtraInfo( rkPacket );
		}
	}

	SetNormalAttack( iCurCombo );
	SetCurHP( fCurHP );

	// 오토타겟이 나중에 처리되야해서 ApplyAutoTargetInfo를 수동으로 처리
	SetAutoTargetExplicit( szAutoTarget, vTrackingBasisDir, dwAutoTrackingDuration, m_AutoTargetType, bAutoTargetBall, bAutoTargetDummyChar );

	// weaponindex 맞춰주기
	IncreaseWeaponIndexBase();
}

void ioBaseChar::ApplyDashAttack( SP2Packet &rkPacket )
{
	DWORD dwWeaponIdx;
	rkPacket >> dwWeaponIdx;
	SetWeaponIndexBase( dwWeaponIdx );

	D3DXQUATERNION qtRot;
	rkPacket >> qtRot;

	SetTargetRotToRotate( qtRot, true, false );

	float fCurHP;
	rkPacket >> fCurHP;
	SetCurHP( fCurHP );

	bool bExtend, bExtendOther, bEndDash;
	rkPacket >> bExtend >> bExtendOther >> bEndDash;

	rkPacket >> m_iCurExtraDashAttack >> m_iCurExtraOtherDashAttack;

	if( bExtend )
		SetExtraDashAttack();
	else if( bExtendOther )
		SetExtraOtherDashAttack( false );
	else if( bEndDash )
		SetExtraOtherDashAttack( true );
	else
		SetDashAttack();

	ApplyAutoTargetInfo( rkPacket );
}

void ioBaseChar::ApplyJumpState( SP2Packet &rkPacket )
{
	bool bSetJump;
	rkPacket >> bSetJump;

	if( !bSetJump )
	{
		D3DXQUATERNION qtRot;
		rkPacket >> qtRot;

		SetTargetRotToRotate( qtRot, true, false );
		SetState( CS_DELAY );
		return;
	}

	ClearAttackFireTimeAndSkill();
	ClearReservedSliding();

	int iDirKey;
	rkPacket >> iDirKey;
	rkPacket >> m_bReverseDirection;
	m_KeyInput.SetNetworkKeyInput( (ioUserKeyInput::DirKeyInput)iDirKey );

	float fCurHP;
	rkPacket >> fCurHP;
	SetCurHP( fCurHP );

	int iJumpType;
	float fSkillEndJumpAmt;
	bool bUsedJumpAttack;

	rkPacket >> iJumpType >> fSkillEndJumpAmt;
	rkPacket >> bUsedJumpAttack;
	m_CurJumpType = (JumpType)iJumpType;

	bool bInitLandRate;
	bool bMustJump;
	bool bExtedJumpAni;
	rkPacket >> bMustJump;
	rkPacket >> bExtedJumpAni;
	rkPacket >> bInitLandRate;
	rkPacket >> m_fCurSkillEndNextLandRate;

	float fMaxSpeed, fPreSpeed, fCurSpeed;
	D3DXQUATERNION qtRot;
	rkPacket >> fMaxSpeed;
	rkPacket >> fPreSpeed;
	rkPacket >> fCurSpeed;
	rkPacket >> qtRot;

	m_fCurMoveSpeed = m_fJumpPreMoveSpeed;

	if( fSkillEndJumpAmt > 0.0f )
		SetSKillEndJumpState( fSkillEndJumpAmt, bUsedJumpAttack, bInitLandRate, false, bMustJump, bExtedJumpAni );//, bInitPreMoveSpeed  );
	else
		SetJumpState();

	m_fJumpMaxMoveSpeed = fMaxSpeed;
	m_fJumpPreMoveSpeed = fPreSpeed;
	m_fCurMoveSpeed = fCurSpeed;
	m_qtTargetRot = qtRot;

	bool bSetRandomSeed = false;
	DWORD dwRandomSeed;
	rkPacket >> bSetRandomSeed;
	if( bSetRandomSeed )
	{
		rkPacket >> dwRandomSeed;
		SetRandomSeed( dwRandomSeed );
	}

	if( IsChangeDirection() )
	{
		ChangeJDirectionByInputDir((ioUserKeyInput::DirKeyInput)iDirKey );
	}
}

void ioBaseChar::ApplyCrossBowJumpState( SP2Packet &rkPacket )
{
	ClearAttackFireTimeAndSkill();
	ClearReservedSliding();

	int iDirKey;
	rkPacket >> iDirKey;
	rkPacket >> m_bReverseDirection;
	m_KeyInput.SetNetworkKeyInput( (ioUserKeyInput::DirKeyInput)iDirKey );

	float fCurHP;
	rkPacket >> fCurHP;
	SetCurHP( fCurHP );

	int iJumpType;

	rkPacket >> iJumpType;
	m_CurJumpType = (JumpType)iJumpType;
	rkPacket >> m_fCurSkillEndNextLandRate;

	SetCrossBowJumpState();

	rkPacket >> m_fJumpMaxMoveSpeed;
	rkPacket >> m_fJumpPreMoveSpeed;
	rkPacket >> m_qtTargetRot;

	if( IsChangeDirection() )
	{
		ChangeJDirectionByInputDir((ioUserKeyInput::DirKeyInput)iDirKey );
	}
}

void ioBaseChar::ApplyFlyJumpState( SP2Packet &rkPacket )
{
	int iType;
	rkPacket >> iType;

	switch( iType )
	{
	case FLY_BOOST:
		{
			int iDirKey;
			rkPacket >> iDirKey;
			rkPacket >> m_bReverseDirection;

			float fCurHP;
			rkPacket >> fCurHP;
			SetCurHP( fCurHP );

			m_bSetBoost = true;

			if( m_FlyMoveType == FMT_NORMAL )
			{
				m_KeyInput.SetNetworkKeyInput( (ioUserKeyInput::DirKeyInput)iDirKey );

				if( IsChangeDirection() )
				{
					ChangeDirectionByInputDir( false );
				}
			}
		}
		break;
	case FLY_CHANGE_DIR:
		{
			int iDir;
			rkPacket >> iDir;
			rkPacket >> m_bFlyLeftRot;

			m_bFlyTargetRot = false;

			m_CurDirKey = (ioUserKeyInput::DirKeyInput)iDir;
		}
		break;
	case FLY_HEIGHT_OFF:
		CheckUseBuffSkill( m_FlyBuffName );
		break;
	}
}

void ioBaseChar::ApplyBoostJumpState( SP2Packet &rkPacket )
{
	int iType;
	rkPacket >> iType;

	switch( iType )
	{
	case JUMP_BOOST:
		{
			int iDirKey;
			rkPacket >> iDirKey;
			rkPacket >> m_bReverseDirection;

			float fCurHP;
			rkPacket >> fCurHP;
			SetCurHP( fCurHP );

			m_bSetBoost = true;
			m_bJumpBoost = true;

			if( m_FlyMoveType == FMT_NORMAL )
			{
				m_KeyInput.SetNetworkKeyInput( (ioUserKeyInput::DirKeyInput)iDirKey );

				if( IsChangeDirection() )
				{
					ChangeDirectionByInputDir( false );
				}
			}
		}
		break;
	case JUMP_BOOST_CHANGE_DIR:
		{
			int iDir;
			rkPacket >> iDir;
			rkPacket >> m_bFlyLeftRot;

			m_bFlyTargetRot = false;

			m_CurDirKey = (ioUserKeyInput::DirKeyInput)iDir;
		}
		break;
	}
}

void ioBaseChar::ApplyDoubleJump( SP2Packet &rkPacket )
{
	ioAttackableItem *pItem = GetPriorityItem( SPT_JUMP );
	if( pItem )
	{
		int iType;
		rkPacket >> iType;

		if( pItem->GetCurExtendJump() )
		{
			if( pItem->GetCurExtendJump()->GetType() != iType )
				return;
		}

		D3DXVECTOR3 vMoveDir;
		rkPacket >> vMoveDir;
		
		m_vMoveDir = vMoveDir;
		//HARDCODE: 방향설정후 수행.
		pItem->ApplyJump( this, rkPacket );
		m_bEnableHide = false;
		m_bChangeMotion = false;
		m_bChangeTeamBuff = false;
	}
}

void ioBaseChar::ApplyBuffJump( SP2Packet &rkPacket )
{
	D3DXVECTOR3 vDir;
	int iIndex, iIndex2;
	float fRate, fJumpPower, fJumpForce;
	D3DXQUATERNION qtRotate;
	int iDirKey = 0;

	rkPacket >> vDir >> iIndex >> iIndex2 >> fRate;
	rkPacket >> fJumpPower >> fJumpForce;
	rkPacket >> qtRotate;
	rkPacket >> iDirKey;

	if( m_vBuffJumpInfoList.empty() )
		return;

	if( fJumpPower < 0.0f )
		return;

	SetCurJumpPowerAmt( 0.0f );
	SetForcePowerAmt( 0.0f );
	SetGravityAmt( 0.0f );

	if( m_vBuffJumpInfoList[0].m_bEnableRotate && iDirKey != ioUserKeyInput::DKI_NONE )
		SetTargetRotToDirKey( (ioUserKeyInput::DirKeyInput)iDirKey );
	else
		SetTargetRot( qtRotate );
	SetJumpPower( fJumpPower );

	if( fJumpForce > 0.0f )
		SetForcePower( vDir, fabs(fJumpForce), FLOAT1, true );
	else
		SetForcePower( -vDir, fabs(fJumpForce), FLOAT1, true );

	m_bEnableHide = false;
	m_bChangeMotion = false;
	m_bChangeTeamBuff = false;

	m_pGroup->ClearAllActionAni( FLOAT100, true );

	int iCnt = m_vBuffJumpInfoList[0].m_vBuffJumpAnimationList.size();
	float fAniRate = m_vBuffJumpInfoList[0].m_fBuffJumpAniRate;
	if( COMPARE( iIndex, 0, iCnt ) && COMPARE( iIndex2, 0, iCnt ) )
	{
		if ( m_vBuffJumpInfoList[0].m_bAniLoop )
			m_pGroup->SetLoopAni( m_vBuffJumpInfoList[0].m_vBuffJumpAnimationList[iIndex], FLOAT100 );
		else if( !m_vBuffJumpInfoList[0].m_vBuffJumpAnimationList[iIndex].IsEmpty() && !m_vBuffJumpInfoList[0].m_vBuffJumpAnimationList[iIndex2].IsEmpty() )
		{
			if( fRate <= FLOAT05 )
				m_pGroup->SetActionAni( m_vBuffJumpInfoList[0].m_vBuffJumpAnimationList[iIndex], FLOAT100, FLOAT100, (1.0f - fRate), FLOAT1/fAniRate, 0.0f, 0, true );
			else
				m_pGroup->SetActionAni( m_vBuffJumpInfoList[0].m_vBuffJumpAnimationList[iIndex2], FLOAT100, FLOAT100, fRate, FLOAT1/fAniRate, 0.0f, 0, true );
		}
		else if( !m_vBuffJumpInfoList[0].m_vBuffJumpAnimationList[iIndex].IsEmpty() && m_vBuffJumpInfoList[0].m_vBuffJumpAnimationList[iIndex2].IsEmpty() )
		{
			m_pGroup->SetActionAni( m_vBuffJumpInfoList[0].m_vBuffJumpAnimationList[iIndex], FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate, 0.0f, 0, true );
		}
		else if( !m_vBuffJumpInfoList[0].m_vBuffJumpAnimationList[iIndex2].IsEmpty() && m_vBuffJumpInfoList[0].m_vBuffJumpAnimationList[iIndex].IsEmpty() )
		{
			m_pGroup->SetActionAni( m_vBuffJumpInfoList[0].m_vBuffJumpAnimationList[iIndex2], FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate, 0.0f, 0, true );
		}
		else
		{
			int iAniID = -1;
			iAniID = GetJumppingAnimationIdx();
			m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate, 0.0f, 0, true );
		}
	}
	else
	{
		int iAniID = -1;
		iAniID = GetJumppingAnimationIdx();
		m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate, 0.0f, 0, true );
	}

	CheckPassvieDoubleJumpBuff();

	m_UsedBuffJump = BJUT_CUR;
	m_bEnableHide = false;
	m_bChangeMotion = false;
	m_bChangeTeamBuff = false;

	SetJumpBuffOnDoubleJumpBuff();
}

void ioBaseChar::ApplyBuffFlyJump( SP2Packet &rkPacket )
{
	bool bJumpKeyDown;
	rkPacket >> bJumpKeyDown;

	if( !bJumpKeyDown )
	{
		if ( m_UsedBuffFlyJump == BJUT_WALK )
		{
			SetExtendAttackEndJump( m_vBuffFlyJumpInfoList[0].m_fBuffJumpEndJumpPower, m_vBuffFlyJumpInfoList[0].m_fBuffJumpLandingRate, false, false );
			return;
		}
		int iAniID = GetJumppingAnimationIdx();
		m_pGroup->ClearAllActionAni( FLOAT100, true );
		m_pGroup->SetActionAni( iAniID,	0.0f, 0.0f, FLOAT1, FLOAT1,	0.0f, 0.0f,	true );

		if( !IsDisableEquipObject() )
			m_UsedBuffFlyJump = BJUT_END;

		return;
	}

	D3DXVECTOR3 vDir;
	int iIndex, iIndex2;
	float fRate, fJumpPower, fJumpForce;
	D3DXQUATERNION qtRotate;

	rkPacket >> vDir >> iIndex >> iIndex2 >> fRate;
	rkPacket >> fJumpPower >> fJumpForce;
	rkPacket >> qtRotate;

	if( m_vBuffFlyJumpInfoList.empty() )
		return;

	if( fJumpPower < 0.0f )
		return;

	SetCurJumpPowerAmt( 0.0f );
	SetForcePowerAmt( 0.0f );
	SetGravityAmt( 0.0f );

	SetTargetRot( qtRotate );
	SetJumpPower( fJumpPower );

	if( fJumpForce > 0.0f )
		SetForcePower( vDir, fabs(fJumpForce), FLOAT1, true );
	else
		SetForcePower( -vDir, fabs(fJumpForce), FLOAT1, true );

	m_bEnableHide = false;
	m_bChangeMotion = false;
	m_bChangeTeamBuff = false;

	m_pGroup->ClearAllActionAni( FLOAT100, true );

	int iCnt = m_vBuffFlyJumpInfoList[0].m_vBuffJumpAnimationList.size();
	float fAniRate = m_vBuffFlyJumpInfoList[0].m_fBuffJumpAniRate;
	if( COMPARE( iIndex, 0, iCnt ) && COMPARE( iIndex2, 0, iCnt ) )
	{
		if ( m_vBuffFlyJumpInfoList[0].m_bAniLoop )
			m_pGroup->SetLoopAni( m_vBuffFlyJumpInfoList[0].m_vBuffJumpAnimationList[iIndex], FLOAT100 );
		else if( !m_vBuffFlyJumpInfoList[0].m_vBuffJumpAnimationList[iIndex].IsEmpty() && !m_vBuffFlyJumpInfoList[0].m_vBuffJumpAnimationList[iIndex2].IsEmpty() )
		{
			if( fRate <= FLOAT05 )
				m_pGroup->SetActionAni( m_vBuffFlyJumpInfoList[0].m_vBuffJumpAnimationList[iIndex], FLOAT100, FLOAT100, (1.0f - fRate), FLOAT1/fAniRate, 0.0f, 0, true );
			else
				m_pGroup->SetActionAni( m_vBuffFlyJumpInfoList[0].m_vBuffJumpAnimationList[iIndex2], FLOAT100, FLOAT100, fRate, FLOAT1/fAniRate, 0.0f, 0, true );
		}
		else if( !m_vBuffFlyJumpInfoList[0].m_vBuffJumpAnimationList[iIndex].IsEmpty() && m_vBuffFlyJumpInfoList[0].m_vBuffJumpAnimationList[iIndex2].IsEmpty() )
		{
			m_pGroup->SetActionAni( m_vBuffFlyJumpInfoList[0].m_vBuffJumpAnimationList[iIndex], FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate, 0.0f, 0, true );
		}
		else if( !m_vBuffFlyJumpInfoList[0].m_vBuffJumpAnimationList[iIndex2].IsEmpty() && m_vBuffFlyJumpInfoList[0].m_vBuffJumpAnimationList[iIndex].IsEmpty() )
		{
			m_pGroup->SetActionAni( m_vBuffFlyJumpInfoList[0].m_vBuffJumpAnimationList[iIndex2], FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate, 0.0f, 0, true );
		}
		else
		{
			int iAniID = -1;
			iAniID = GetJumppingAnimationIdx();
			m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate, 0.0f, 0, true );
		}
	}
	else
	{
		int iAniID = -1;
		iAniID = GetJumppingAnimationIdx();
		m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate, 0.0f, 0, true );
	}

	int iType;
	rkPacket >> iType;
	m_UsedBuffFlyJump = (BuffJumpUsedType)iType;
	
	if ( m_UsedBuffFlyJump != BJUT_CONTINUE )
		m_iBuffFlyJumpCurCnt++;
	
	m_bEnableHide = false;
	m_bChangeMotion = false;
	m_bChangeTeamBuff = false;

	for( int i=ES_WEAPON; i < ES_OBJECT; i++ )
	{
		float fCurGauge;
		rkPacket >> fCurGauge;

		ioSkill *pSkill = GetEquipedSkill( i );
		if( ToPassiveSkill(pSkill) )
			ToPassiveSkill(pSkill)->SetCurPassiveGauge( fCurGauge );
	}

	rkPacket >> m_vBuffFlyJumpInfoList[0].m_bEnableMoveRotate;
	rkPacket >> m_vBuffFlyJumpInfoList[0].m_dwMoveRotateSpeed;

	int iDirKey;
	rkPacket >> iDirKey;
	m_CurDirKey = (ioUserKeyInput::DirKeyInput)iDirKey;
}

void ioBaseChar::ApplyBuffMultiFlyJump( SP2Packet &rkPacket )
{
	int iState;
	rkPacket >> iState;

	if( iState == BJUT_END )
	{
		int iAniID = GetJumppingAnimationIdx();
		m_pGroup->ClearAllActionAni( FLOAT100, true );
		m_pGroup->SetActionAni( iAniID,	0.0f, 0.0f, FLOAT1, FLOAT1,	0.0f, 0.0f,	true );

		if( !IsDisableEquipObject() )
			m_UsedBuffMultiFlyJump = BJUT_END;

		return;
	}

	D3DXVECTOR3 vDir;
	int iIndex, iIndex2;
	float fRate, fJumpPower, fJumpForce;
	D3DXQUATERNION qtRotate;

	rkPacket >> vDir >> iIndex >> iIndex2 >> fRate;
	rkPacket >> qtRotate;

	rkPacket >> fJumpPower >> fJumpForce;

	if( m_vBuffMultiFlyJumpInfoList.empty() )
		return;

	SetCurJumpPowerAmt( 0.0f );
	SetForcePowerAmt( 0.0f );
	SetGravityAmt( 0.0f );
	SetTargetRot( qtRotate );

	m_UsedBuffMultiFlyJump = (BuffJumpUsedType)iState;

	CharBuffJumpInfo rkInfo = m_vBuffMultiFlyJumpInfoList[0];

	bool bExtra = false;
	if( rkInfo.m_BuffJumpType == BJT_MULT_FLY )
	{
		if( m_UsedBuffMultiFlyJump == BJUT_CUR )
			bExtra = true;
	}

	SetJumpPower( fJumpPower );

	if( fJumpForce > 0.0f )
		SetForcePower( vDir, fabs(fJumpForce), FLOAT1, true );
	else
		SetForcePower( -vDir, fabs(fJumpForce), FLOAT1, true );

	m_bEnableHide = false;
	m_bChangeMotion = false;
	m_bChangeTeamBuff = false;

	m_pGroup->ClearAllActionAni( FLOAT100, true );

	ioHashStringVec vAniList;
	if( bExtra )
	{
		vAniList.clear();
		int iCnt = rkInfo.m_vBuffJumpExtraAnimationList.size();
		for( int i=0; i < iCnt; i++ )
			vAniList.push_back( rkInfo.m_vBuffJumpExtraAnimationList[i] );
	}
	else
	{
		vAniList.clear();
		int iCnt = rkInfo.m_vBuffJumpAnimationList.size();
		for( int i=0; i < iCnt; i++ )
			vAniList.push_back( rkInfo.m_vBuffJumpAnimationList[i] );
	}

	int iCnt = vAniList.size();
	float fAniRate = rkInfo.m_fBuffJumpAniRate;
	if( COMPARE( iIndex, 0, iCnt ) && COMPARE( iIndex2, 0, iCnt ) )
	{
		if ( rkInfo.m_bAniLoop )
			m_pGroup->SetLoopAni( vAniList[iIndex], FLOAT100 );
		else if( !vAniList[iIndex].IsEmpty() && !vAniList[iIndex2].IsEmpty() )
		{
			if( fRate <= FLOAT05 )
				m_pGroup->SetActionAni( vAniList[iIndex], FLOAT100, FLOAT100, (1.0f - fRate), FLOAT1/fAniRate, 0.0f, 0, true );
			else
				m_pGroup->SetActionAni( vAniList[iIndex2], FLOAT100, FLOAT100, fRate, FLOAT1/fAniRate, 0.0f, 0, true );
		}
		else if( !vAniList[iIndex].IsEmpty() && vAniList[iIndex2].IsEmpty() )
		{
			m_pGroup->SetActionAni( vAniList[iIndex], FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate, 0.0f, 0, true );
		}
		else if( !vAniList[iIndex2].IsEmpty() && vAniList[iIndex].IsEmpty() )
		{
			m_pGroup->SetActionAni( vAniList[iIndex2], FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate, 0.0f, 0, true );
		}
		else
		{
			int iAniID = -1;
			iAniID = GetJumppingAnimationIdx();
			m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate, 0.0f, 0, true );
		}
	}
	else
	{
		int iAniID = -1;
		iAniID = GetJumppingAnimationIdx();
		m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fAniRate, 0.0f, 0, true );
	}

	m_iBuffJumpCurCnt++;

	rkPacket >> m_vBuffMultiFlyJumpInfoList[0].m_bEnableMoveRotate;
	rkPacket >> m_vBuffMultiFlyJumpInfoList[0].m_dwMoveRotateSpeed;

	int iDirKey;
	rkPacket >> iDirKey;
	m_CurDirKey = (ioUserKeyInput::DirKeyInput)iDirKey;
}

void ioBaseChar::ApplyExtendJump( SP2Packet &rkPacket )
{
	ioAttackableItem *pItem = GetPriorityItem( SPT_JUMP );
	if( pItem )
	{
		int iType;
		float fCurHP;
		rkPacket >> iType;
		
		if( pItem->GetCurExtendJump() )
		{
			if( pItem->GetCurExtendJump()->GetType() != iType )
				return;
		}

		rkPacket >> fCurHP;
		SetCurHP( fCurHP );

		pItem->ApplyJump( this, rkPacket );
	}
}

void ioBaseChar::ApplyJumpDash( SP2Packet &rkPacket )
{
	ioAttackableItem *pItem = GetPriorityItem( SPT_JUMP );
	if( pItem )
	{
		int iType;
		rkPacket >> iType;

		if( pItem->GetCurExtendJump() )
		{
			if( pItem->GetCurExtendJump()->GetType() != iType )
				return;
		}

		D3DXVECTOR3 vMoveDir;
		rkPacket >> vMoveDir;

		m_vMoveDir = vMoveDir;
		//HARDCODE: 방향설정후 수행.
		pItem->ApplyJump( this, rkPacket );

		m_bEnableHide = false;
		m_bChangeMotion = false;
		m_bChangeTeamBuff = false;
	}
}

void ioBaseChar::ApplyChangeDashRun( SP2Packet &rkPacket )
{
	int iDirKey;
	rkPacket >> iDirKey;
	rkPacket >> m_bReverseDirection;
	m_KeyInput.SetNetworkKeyInput( (ioUserKeyInput::DirKeyInput)iDirKey );

	int iState;
	rkPacket >> iState;

	bool bAim;
	rkPacket >> bAim;

	bool bPassAutoTarget;
	rkPacket >> bPassAutoTarget;

	if( iState == CS_RUN )
	{
		SetState( CS_RUN );
	}
	else if( iState == CS_DASH || iState == CS_EXTEND_DASH )
	{
		SetTargetRotToDirKey( (ioUserKeyInput::DirKeyInput)iDirKey );

		SetDashState( bAim );

		if( iState == CS_EXTEND_DASH && !bPassAutoTarget )
		{
			ApplyAutoTargetInfo( rkPacket );
		}
	}
	else if( iState == CS_DASH_FAIL )
	{
		SetDashFailState();
	}
}

