void ioBaseChar::ClearAttackFireTimeAndSkill( ClearAttackFireType eType /*= CAFT_NONE */ )
{
	if( m_pActiveSkill )
	{
		ErrorReport::SetPosition( 2102, 1 );
		ioHashString szSkillName = m_pActiveSkill->GetName();

		ErrorReport::SetPosition( 2102, 2 );
		ioCameraEvent* pCamera = g_CameraEventMgr.GetCurCameraEvent();
		if( pCamera && m_pActiveSkill->GetCameraEventCode() == pCamera->GetCECode() )
		{
			ErrorReport::SetPosition( 2102, 3 );
			g_CameraEventMgr.NotifyCEDestroyed();
			pCamera = NULL;
		}

		ErrorReport::SetPosition( 2102, 4 );
		ioHashString szSkillStartBuff = m_pActiveSkill->GetOwnerSkillStartBuff();
		if( !szSkillStartBuff.IsEmpty() )
		{
			ErrorReport::SetPosition( 2102, 5 );
			RemoveBuff( szSkillStartBuff );
		}

		ErrorReport::SetPosition( 2102, 6 );
		if( eType == CAFT_APPLY_WOUNDED )
		{
			m_pActiveSkill->OnSkillEndByWounded( this );
		}
		m_pActiveSkill->OnSkillEnd( this );
		m_pActiveSkill = NULL;
		ErrorReport::SetPosition( 2102, 7 );

	}

	g_WeaponMgr.DestroyReserveContactWeapon( m_Name );
	g_WeaponMgr.DestroyReserveZoneWeapon( m_Name );

	ClearAttackFireTimeList();
	ClearScaleList(true);
	ErrorReport::SetPosition( 2102, 9 );
}

void ioBaseChar::ClearAttackFireTimeList()
{
	m_vAttackFireTimeList.clear();
}

void ioBaseChar::SetLastAttackerName( const ioHashString &rkName, const ioHashString &rkSkillName )
{
	if( rkName.IsEmpty() ) return;

	ioBaseChar *pAttacker = GetBaseChar( rkName );
	if( pAttacker )
	{
		m_dwLastAttackerItemCode = pAttacker->GetWeaponItemCode();
		m_LastAttackerTeam       = pAttacker->GetTeam();
	}
	else
	{
		m_dwLastAttackerItemCode = 0;
		m_LastAttackerTeam       = TEAM_NONE;
	}

	m_LastAttackerName		= rkName;
	m_LastAttackerSkillName = rkSkillName;
	m_dwLastAttackedTime	= FRAMEGETTIME();	
	m_bForceDropping		= false;
}

void ioBaseChar::SetDieLastAttackerInfo( const ioHashString &rkName, const ioHashString &rkSkillName, const TeamType eTeam, const DWORD dwLastItem )
{
	m_LastAttackerName		= rkName;
	m_LastAttackerSkillName = rkSkillName;
	m_LastAttackerTeam		= eTeam;
	m_dwLastAttackerItemCode= dwLastItem;
}

void ioBaseChar::CheckLastAttackerTime( bool bCallProcess /* = true  */ )
{
	if( bCallProcess )
	{
		// 보스 모드에서 프로세스마다 체크하여 날라가는 중 초기화하지 않는다.
		if( !IsNeedProcess() ) return;
		if( m_LastAttackerName.IsEmpty() ) return;
		if( m_pModeParent && m_pModeParent->GetModeType() != MT_BOSS ) return;

		// 아래 4가지 상태에서는 마지막 타격자를 계속 기억한다.
		if( m_CharState == CS_WOUNDED_DEFENSE ||
			m_CharState == CS_WOUNDED ||
			m_CharState == CS_BLOW_WOUNDED ||
			m_CharState == CS_BOUND_BLOW_WOUNDED ||
			m_CharState == CS_BLOW_EXTEND_WOUND ||
			m_CharState == CS_FALL )
		{
			if( m_dwLastAttackedTime + m_dwLastAttackedCheckTime >= FRAMEGETTIME() )
			{
				m_dwLastAttackedTime = FRAMEGETTIME();
			}
		}
	}
	else
	{
		if( m_dwLastAttackedTime + m_dwLastAttackedCheckTime < FRAMEGETTIME() )
		{
			m_LastAttackerName.Clear();
			m_LastAttackerSkillName.Clear();
			m_LastAttackerTeam = TEAM_NONE;
			m_dwLastAttackerItemCode = 0;
		}		
	}	
}

void ioBaseChar::GetCharInfoInNetwork( SP2Packet &rkPacket )
{
	rkPacket << GetWorldPosition();
	rkPacket << GetTargetRot();
	rkPacket << m_HP.m_fCurValue;

	for( int i=0; i < 4; i++ )
	{
		ioItem *pItem = GetEquipedItem( i );
		if( pItem )
			rkPacket << pItem->GetCurSkillGuage();
		else
			rkPacket << 0.0f;
	}
}

void ioBaseChar::ApplyCharInfoInNetwork( SP2Packet &rkPacket )
{
	D3DXVECTOR3 vPos;
	rkPacket >> vPos;
	SetWorldPosition( vPos );

	D3DXQUATERNION qtRot;
	rkPacket >> qtRot;

	SetTargetRotAndMoveDirChange( qtRot );

	float fCurHP, fCurGauge;
	rkPacket >> fCurHP;
	SetCurHP( fCurHP );

	for( int i=0; i < 4; i++ )
	{
		rkPacket >> fCurGauge;

		ioItem *pItem = GetEquipedItem( i );
		if( pItem )
		{
			pItem->SetCurSkillGauge( fCurGauge );
		}
	}
}

RaceDetailType ioBaseChar::GetRaceDetailType() const
{
	switch( m_RaceType )
	{
	case RT_HUMAN:
		if( m_bMale )
			return RDT_HUMAN_MAN;
		else
			return RDT_HUMAN_WOMAN;
		break;
	case RT_ELF:
		if( m_bMale )
			return RDT_ELF_MAN;
		else
			return RDT_ELF_WOMAN;
		break;
	case RT_DWARF:
		if( m_bMale )
			return RDT_DWARF_MAN;
		else
			return RDT_DWARF_WOMAN;
		break;
	}

	LOG.PrintTimeAndLog( 0, "ioBaseChar::GetRaceDetailType - UnknownType Race:%d, male:%d",
							m_RaceType, m_bMale );

	return RDT_HUMAN_MAN;
}

int ioBaseChar::GetAnimationEventCnt( const ioHashString &szAnimation,
									  const ioHashString &szEventType ) const
{
	int iAniID = m_pGroup->GetAnimationIdx( szAnimation );
	if( iAniID == -1 )
		return 0;

	return m_pGroup->GetAnimationEventCnt( iAniID, szEventType );
}

bool ioBaseChar::CheckViewChange() const
{
	if( !m_pCreator->IsCameraFixedBlock() )
	{
		// 배틀모드이고 대기자라면 뷰 체인지되지 않아야 함(출전하고 있는 용병 시점으로 고정되어야하기 때문)
		if( m_pCreator->GetModeType() == MT_BATTLE /*&& GetState() == CS_BATTLE_WAITING*/ )
			return false;
		if( IsDefenseKeyPress() || IsAttackKeyPress() )
		{
			//if( m_pCreator->GetModeType() == MT_BATTLE && ioEdit::m_pKeyFocusEdit )		// 배틀모드이고 채팅 엔터 친 상태이면 시점변경 막음(만일을 위해 주석처리만)
			//	return false;
			return true;
		}
	}
	return false;
}

bool ioBaseChar::CheckSpecialViewChange() const
{
	if( !m_pCreator->IsCameraFixedBlock() )
	{
		if( IsSpaceKeyPress() )
			return true;
	}
	return false;
}

bool ioBaseChar::CheckMovieModeChange() const
{
	if( GetState() != CS_DIE && GetState() != CS_VIEW && GetState() != CS_OBSERVER && GetState() != CS_LOADING )
		return false;

	// 배틀모드이고 죽은 상태일때 점프키를 누르면 영화모드 되지 않도록 함
	if( IsJumpKeyPress() && m_pCreator->GetModeType() == MT_BATTLE && GetState() == CS_DIE )
		return false;

	return IsJumpKeyPress();
}

bool ioBaseChar::CheckUseMonsterCoin() const
{
	if( !IsOwnerChar() ) return false;
	if( !m_pCreator ) return false;
	if( m_pCreator->GetModeType() != MT_MONSTER_SURVIVAL && m_pCreator->GetModeType() != MT_DUNGEON_A ) return false;
	if( m_pModeParent->GetModeState() != ioPlayMode::MS_PLAY ) return false;
	
	if( m_bPrisonerMode || GetState() == CS_DIE )
        return IsAttackKeyPress();
	return false;
}

