void ioBaseChar::ApplyModifiedMaterial()
{
	if( m_CharState == CS_STOP_MOTION || m_CharState == CS_NOT_MOVE_PROTECT )
		return;

	SetSkinColor( m_SkinColor, m_SkinOutLineColor );
	SetHairColor( m_HairColorTex, m_HairOutLineColor );
	SetBeardColor( m_BeardColorTex, m_BeardOutLineColor );

	ApplyModifiedOutLine();
	ApplyModifiedMaterialColor();
}

void ioBaseChar::FixedOutLine()
{
	if( HasOutLineType( COT_FIXED_OUTLINE ) )
		return;

	ApplyOutLineChange( COT_FIXED_OUTLINE, m_FixedOutlineColor, m_fProtectionLineWidth );
}

void ioBaseChar::ApplyOutLineChange( ChangeOutLineType eType, const D3DCOLORVALUE &rkColor, float fSize )
{
	RemoveChangeOutLineRecord( eType );

	OutLineRecord kRecord;
	kRecord.m_Type   = eType;
	kRecord.m_Color  = rkColor;
	kRecord.m_fThick = fSize;
	m_OutLineChangeList.push_front( kRecord );

	ChangeOutLine( rkColor, fSize );
}

void ioBaseChar::RestoreOutLineChange( ChangeOutLineType eType )
{
	RemoveChangeOutLineRecord( eType );

	if( !m_OutLineChangeList.empty() )
	{
		const OutLineRecord &rkRecord = m_OutLineChangeList.front();
		ChangeOutLine( rkRecord.m_Color, rkRecord.m_fThick );
	}
	else
	{
		// 최초 상태로 원상복구
		RestoreOutLine();
	}
}

bool ioBaseChar::HasOutLineType( ChangeOutLineType eType )
{
	OutLineRecordList::iterator iter;
	for( iter=m_OutLineChangeList.begin() ; iter!=m_OutLineChangeList.end() ; ++iter )
	{
		if( iter->m_Type == eType )
			return true;
	}

	return false;
}

void ioBaseChar::RemoveChangeOutLineRecord( ChangeOutLineType eType )
{
	OutLineRecordList::iterator iter = m_OutLineChangeList.begin();
	while( iter != m_OutLineChangeList.end() )
	{
		if( iter->m_Type == eType )
		{
			iter = m_OutLineChangeList.erase( iter );
		}
		else
		{
			++iter;
		}
	}
}

void ioBaseChar::ChangeOutLine( const D3DCOLORVALUE &rkOutLineColor, float fOutLineSize )
{
	m_OutLineColor = rkOutLineColor;
	m_fOutLineSize = fOutLineSize;
	m_bOutLineModified = true;

	ApplyModifiedOutLine();
}

void ioBaseChar::RestoreOutLine()
{
	if( !m_bOutLineModified )	return;

	int iNumEntity = m_pGroup->GetNumEntities();
	for( int i=0 ; i<iNumEntity ; i++ )
	{
		ioEntity *pEntity = m_pGroup->GetEntity( i );

		int iNumSubEntity = pEntity->GetNumSubEntity();
		for( int j=0 ; j<iNumSubEntity ; j++ )
		{
			ioSubEntity *pSubEntity = pEntity->GetSubEntity( j );
			if( !pSubEntity )	continue;

			ioTechnique *pCloneTech = NULL;
			ioMaterial *pClone = pSubEntity->GetMaterial();
			if( pClone )
			{
				pCloneTech = pClone->GetBestTechnique();
			}

			ioTechnique *pSrcTech = NULL;
			ioMaterial *pSrc = ioMaterialManager::GetSingleton().GetMaterial( pSubEntity->GetMaterialName() );
			if( pSrc )
			{
				pSrcTech = pSrc->GetBestTechnique();
			}

			if( !pSrcTech || !pCloneTech )
				continue;

			ioPass *pClonePass = pCloneTech->GetPassByShaderGrp( SGT_OUTLINE );
			ioPass *pSrcPass = pSrcTech->GetPassByShaderGrp( SGT_OUTLINE );

			if( !pClonePass || !pSrcPass )
				continue;

			ioShaderCustomArg *pArg = pSrcPass->GetCustomArg( "OutLineColor" );
			if( pArg )
			{
				if( pCloneTech->IsCustomTex() )
				{
					D3DCOLORVALUE kColor;
					Help::InitColorValue( kColor, 0.240f, 0.240f, 0.240f, FLOAT1 );
					pArg->SetValue( kColor );
				}
				pClonePass->AddCustomParameter( *pArg );
			}

			pArg = pSrcPass->GetCustomArg( "OutLineThickness" );
			if( pArg )
			{
				pClonePass->AddCustomParameter( *pArg );
			}

			if( !Setting::UseObjectEdge() )
			{
				pClonePass->SetPassEnable( false );
			}
		}
	}

	m_bOutLineModified = false;

	if( m_CharState == CS_STOP_MOTION || m_CharState == CS_NOT_MOVE_PROTECT )
		return;

	SetSkinColor( m_SkinColor, m_SkinOutLineColor );
	SetHairColor( m_HairColorTex, m_HairOutLineColor );
	SetBeardColor( m_BeardColorTex, m_BeardOutLineColor );
}

void ioBaseChar::ApplyModifiedOutLine()
{
	if( !m_bOutLineModified )	return;

	ioShaderCustomArg kLineColor( "OutLineColor" );
	kLineColor.SetValue( m_OutLineColor );

	ioShaderCustomArg kLineThickness( "OutLineThickness" );
	kLineThickness.SetValue( m_fOutLineSize );

	int iNumEntity = m_pGroup->GetNumEntities();
	for( int i=0; i<iNumEntity; i++ )
	{
		ioEntity *pEntity = m_pGroup->GetEntity( i );

		int iNumSubEntity = pEntity->GetNumSubEntity();
		for( int j=0 ; j<iNumSubEntity ; j++ )
		{
			ioSubEntity *pSubEntity = pEntity->GetSubEntity( j );
			
			ioMaterial *pMaterial = pSubEntity->GetMaterial();
			if( !pMaterial ) continue;

			ioTechnique *pTech = pMaterial->GetBestTechnique();
			if( !pTech ) continue;

			ioPass *pOutLine = pTech->GetPassByShaderGrp( SGT_OUTLINE );
			if( pOutLine )
			{
				pOutLine->SetPassEnable( true );
				pOutLine->AddCustomParameter( kLineColor );
				pOutLine->AddCustomParameter( kLineThickness );
			}
		}
	}
}

int ioBaseChar::ModifyMaterialColor( const D3DCOLORVALUE &rkColor )
{
	m_iCurChangeColorIndex++;

	ChangeMaterialInfo kInfo;
	
	kInfo.m_dwTime = FRAMEGETTIME();
	kInfo.m_ChangeColor = rkColor;
	kInfo.m_iChangeColorIndex = m_iCurChangeColorIndex;

	m_ModifiedList.push_back( kInfo );

	std::sort( m_ModifiedList.begin(), m_ModifiedList.end(), ChangeMaterialInfoSort() );

	ApplyModifiedMaterialColor();

	return m_iCurChangeColorIndex;
}

void ioBaseChar::AddMaterialModifyExcept( const ioHashString &szEntity )
{
	if( !szEntity.IsEmpty() )
	{
		m_ModifyExceptList.push_back( szEntity );
	}
}

void ioBaseChar::RemoveMaterialModifyExcept( const ioHashString &szEntity )
{
	if( szEntity.IsEmpty() )	return;

	ioHashStringVec::iterator iter = std::find( m_ModifyExceptList.begin(),
												m_ModifyExceptList.end(),
												szEntity );

	if( iter!=m_ModifyExceptList.end() )
	{
		m_ModifyExceptList.erase( iter );
	}
}

void ioBaseChar::RestoreMaterialColor( int iChangeIndex )
{
	if( m_ModifiedList.empty() ) return;

	int i = 0;
	bool bErase = false;

	ChangeMaterialInfoList::iterator iter = m_ModifiedList.begin();
	while( iter != m_ModifiedList.end() )
	{
		ChangeMaterialInfo kInfo = *iter;
		if( kInfo.m_iChangeColorIndex == iChangeIndex )
		{
			m_ModifiedList.erase( iter );
			bErase = true;
			break;
		}

		iter++;
	}

	bool bModified = false;
	D3DCOLORVALUE kModifiedColor;
	if( !m_ModifiedList.empty() )
	{
		if( bErase )
			std::sort( m_ModifiedList.begin(), m_ModifiedList.end(), ChangeMaterialInfoSort() );

		kModifiedColor = m_ModifiedList[0].m_ChangeColor;
		bModified = true;
	}
	

	int iEntityCnt = m_pGroup->GetNumEntities();
	for( i=0 ; i<iEntityCnt ; i++ )
	{
		ioEntity *pEntity = m_pGroup->GetEntity( i );
		if( !pEntity ) continue;

		if( IsModifyExceptEntity( pEntity->GetMeshName() ) )
			continue;

		int iSubEntityCnt = pEntity->GetNumSubEntity();
		for( int j=0 ; j<iSubEntityCnt ; j++ )
		{
			ioSubEntity *pSub = pEntity->GetSubEntity( j );
			ioMaterial *pClone = pSub->GetMaterial();

			if( pClone )
			{
				if( bModified )
				{
					pClone->SetAmbient( kModifiedColor );
					pClone->SetDiffuse( kModifiedColor );
					pClone->SetSpecular( kModifiedColor );
					pClone->SetEmissive( kModifiedColor );
				}
				else
				{
					const ioMaterial *pSrc = ioMaterialManager::GetSingleton().GetMaterial( pSub->GetMaterialName() );
					if( pSrc )
					{
						pClone->SetAmbient( pSrc->GetAmbient() );
						pClone->SetDiffuse( pSrc->GetDiffuse() );
						pClone->SetSpecular( pSrc->GetSpecular() );
						pClone->SetEmissive( pSrc->GetEmissive() );
						m_ModifyExceptList.clear();
					}
				}
			}
		}
	}
}

bool ioBaseChar::IsModifyExceptEntity( const ioHashString &szName )
{
	if( m_ModifyExceptList.empty() )
		return false;

	ioHashStringVec::iterator iter = std::find( m_ModifyExceptList.begin(),
												m_ModifyExceptList.end(),
												szName );

	if( iter != m_ModifyExceptList.end() )
		return true;

	return false;
}

void ioBaseChar::ApplyModifiedMaterialColor()
{
	if( m_ModifiedList.empty() )
		return;

	D3DCOLORVALUE kModifiedColor = m_ModifiedList[0].m_ChangeColor;

	int iEntityCnt = m_pGroup->GetNumEntities();
	for( int i=0 ; i<iEntityCnt ; i++ )
	{
		ioEntity *pEntity = m_pGroup->GetEntity( i );
		if( !pEntity ) continue;

		if( IsModifyExceptEntity( pEntity->GetMeshName() ) )
			continue;

		int iSubEntityCnt = pEntity->GetNumSubEntity();
		for( int j=0 ; j<iSubEntityCnt ; j++ )
		{
			ioMaterial *pMtl = NULL;
			if( pEntity->GetSubEntity(j) )
				pMtl = pEntity->GetSubEntity(j)->GetMaterial();

			if( pMtl )
			{
				pMtl->SetAmbient( kModifiedColor );
				pMtl->SetDiffuse( kModifiedColor );
				pMtl->SetSpecular( kModifiedColor );
				pMtl->SetEmissive( kModifiedColor );
			}
		}
	}
}

bool ioBaseChar::AddGlowLine( const ioHashString &rkEntity,
							  const D3DCOLORVALUE &rkColor,
							  float fThick )
{
	ioEntity *pEntity = m_pGroup->GetEntity( rkEntity );
	if( !pEntity )	return false;

	ioShaderCustomArg kGlowColor( "GlowColor" );
	kGlowColor.SetValue( rkColor );

	ioShaderCustomArg kLineThickness( "GlowThickness" );
	kLineThickness.SetValue( fThick );

	int iNumSubEntity = pEntity->GetNumSubEntity();
	for( int i=0 ; i<iNumSubEntity ; i++ )
	{
		ioSubEntity *pSubEntity = pEntity->GetSubEntity( i );
		if( !pSubEntity ) continue;

		ioMaterial *pClone = pSubEntity->GetMaterial();
		if( !pClone ) continue;

		ioTechnique *pTech = pClone->GetBestTechnique();
		if( !pTech )	continue;

		if( !pTech->HasShaderGroupPass( SGT_GLOW ) )
		{
			ioPass *pPass = pTech->CreatePass();
			if( pPass )
			{
				pPass->SetDepthWriteEnable( false );
				pPass->SetSceneBlending( BLEND_ADD );
				pPass->SetShaderGroup( "AnimateToonShadeGlow" );
				pPass->AddCustomParameter( kGlowColor );
				pPass->AddCustomParameter( kLineThickness );

				ioTextureUnitState *pState = pPass->CreateTextureUnitState();
				if( pState )
				{
					pState->SetColorStageBlendOp( D3DTOP_SELECTARG2, D3DTA_TEXTURE, D3DTA_DIFFUSE );
					pState->SetAlphaStageBlendOp( D3DTOP_SELECTARG2, D3DTA_TEXTURE, D3DTA_DIFFUSE );
				}
			}
		}
		else
		{
			ioPass *pGlow = pTech->GetPassByShaderGrp( SGT_GLOW );
			if( pGlow )
			{
				pGlow->AddCustomParameter( kGlowColor );
				pGlow->AddCustomParameter( kLineThickness );
			}
		}
	}

	return true;
}

bool ioBaseChar::RemoveGlowLine( const ioHashString &rkEntity )
{
	ioEntity *pEntity = m_pGroup->GetEntity( rkEntity );
	if( !pEntity )	return false;

	int iNumSubEntity = pEntity->GetNumSubEntity();
	for( int i=0 ; i<iNumSubEntity ; i++ )
	{
		ioSubEntity *pSubEntity = pEntity->GetSubEntity(i);
		if( !pSubEntity ) continue;

		ioMaterial *pMtl = pSubEntity->GetMaterial();
		if( !pMtl ) continue;

		ioTechnique *pTech = pMtl->GetBestTechnique();
		if( pTech && pTech->HasShaderGroupPass( SGT_GLOW ) )
		{
			ioPass *pGlow = pTech->GetPassByShaderGrp( SGT_GLOW );
			pTech->RemovePass( pGlow->GetPassIndex() );
		}
	}

	return true;
}

void ioBaseChar::FaceChange( const char *szTexPostfix, int iDuration )
{
	ioHashString szNewFaceName;
	if( !GetFaceChangeName( szNewFaceName, szTexPostfix, m_bMale, m_CharInfo.m_face ) )
		return;

	if( !m_bMale )
	{
		char szFullName[MAX_PATH]="";
		StringCbPrintf( szFullName, sizeof( szFullName ), "resource\\texture\\%s" , szNewFaceName.c_str() );
		if( !g_ResourceLoader.IsFileExist( szFullName ) )
		{
			if( !GetFaceChangeName( szNewFaceName, szTexPostfix, true, m_CharInfo.m_face ) ) // 남자로 설정.
				return;
		}
	}

	m_dwFaceChangeTime = FRAMEGETTIME() + iDuration;

	if( m_pEquipSlot && !m_pEquipSlot->GetCurFaceMesh().IsEmpty() )
	{
		ioEntity *pFace = m_pGroup->GetEntity( m_pEquipSlot->GetCurFaceMesh() );
		if( pFace )
		{
			Help::FaceChangeColorTexAndOutLine( pFace, szNewFaceName );
			m_szFaceChangeName = szNewFaceName;

			if( m_pModeParent )
			{
				ModeType eType = m_pModeParent->GetModeType();

				if(eType == MT_FIGHT_CLUB )
				{
					FightClubTimeGaugeWnd *pFightClubGauge = dynamic_cast< FightClubTimeGaugeWnd * >( g_GUIMgr.FindWnd( FIGHTCLUB_TIME_GAUGE_WND ) );
					if( pFightClubGauge )
						pFightClubGauge->SetFaceChange( GetCharName(), szNewFaceName.c_str(), iDuration );
				}
				else if(Help::IsMonsterDungeonMode(eType) || eType == MT_RAID)
				{
					TowerDefWnd *pUserGauge = dynamic_cast< TowerDefWnd * >( g_GUIMgr.FindWnd( TOWERDEF_USER_GAUGE_WND ) );
					if( pUserGauge )
						pUserGauge->SetFaceChange( GetCharName(), szNewFaceName.c_str(), iDuration );
				}
			}
		}
	}
}

void ioBaseChar::CheckFaceChanging()
{
	if( m_dwFaceChangeTime == 0 )
		return;

	if( m_CharState == CS_STOP_MOTION || m_CharState == CS_NOT_MOVE_PROTECT )
		return;

	if( m_dwFaceChangeTime < FRAMEGETTIME() &&
		m_CharState != CS_BLOW_WOUNDED &&
		m_CharState != CS_BOUND_BLOW_WOUNDED &&
		m_CharState != CS_BLOW_EXTEND_WOUND )
	{
		StopFaceChange();
	}
}

void ioBaseChar::StopFaceChange()
{
	if( m_dwFaceChangeTime == 0 )
		return;

	if( m_pEquipSlot && !m_pEquipSlot->GetCurFaceMesh().IsEmpty() )
	{
		ioEntity *pFace = m_pGroup->GetEntity( m_pEquipSlot->GetCurFaceMesh() );
		if( pFace )
		{
			Help::FaceChangeColorTexAndOutLine( pFace, m_pEquipSlot->GetDefaultFaceTexture() );
		}
	}
	else
	{
		LOG.PrintTimeAndLog( 0, "ioBaseChar::StopFaceChange() - %s, Has not DefaultFaceMesh", GetCharName().c_str() );
	}

	m_dwFaceChangeTime = 0;
	m_szFaceChangeName.Clear();
}

bool ioBaseChar::CheckAimedTarget( float fAimAngle,
								   float fAimMinRange,
								   float fAimRange,
								   ioHashString &rkTarget,
								   bool bDownAim,
								   bool bOwnerTeam )
{
	ioFootballMode *pFootBall = ToFootballMode( m_pModeParent );
	if( pFootBall && pFootBall->IsDisableAttackMode() )
		return false;

	FD_AimTarget kAimPred( this, fAimAngle, fAimMinRange, fAimRange, bDownAim, bOwnerTeam );

	ioBaseChar *pTarget = m_pCreator->FindUser( kAimPred );
	if( pTarget )
	{
		rkTarget = pTarget->GetCharName();
		return true;
	}

	return false;
}

