bool ioBaseChar::ApplyItemGauge( SP2Packet &rkPacket )
{
	DWORD dwCharIndex;
	rkPacket >> dwCharIndex;

	if( GetIndex() != dwCharIndex )
	{
		if( g_App.IsMeDeveloper() )
			LOG.PrintTimeAndLog( 0, "ioBaseChar::ApplyItemGauge(%s) Not Match CharIndex : %d - %d", GetCharName().c_str(), GetIndex(), dwCharIndex );

		return false;
	}

	DWORD dwItemCode;
	int iItemCreateIndex;
	rkPacket >> dwItemCode >> iItemCreateIndex;

	ioAttackableItem *pOwnerItem = GetEquipedAttackableItem( dwItemCode, iItemCreateIndex );
	if( !pOwnerItem )
	{
		if( g_App.IsMeDeveloper() )
			LOG.PrintTimeAndLog( 0, "ioBaseChar::ApplyItemGauge - %s Not Has %d Item", GetCharName().c_str(), dwItemCode );

		return false;
	}

	if( rkPacket.GetPacketID() == CUPK_ITEM_GAUGE_OK )
	{
		pOwnerItem->OnItemGaugeOK( this, rkPacket );
	}
	else
	{
		pOwnerItem->OnItemGaugeCancel( this, rkPacket );
	}

	return true;
}

void ioBaseChar::SetCurItemSkillGauge( int iSkillNum, float fGauge )
{
	ioSkill *pSkill = NULL;
	if( m_pEquipSlot )
		pSkill = m_pEquipSlot->GetEquipedSkill( iSkillNum );
	if( !pSkill )	return;

	ioItem *pOwnerItem = pSkill->GetOwnerItem();
	if( pOwnerItem && pOwnerItem->HasSkillGauge() )
	{
		pOwnerItem->SetCurSkillGauge( fGauge );
	}
}

void ioBaseChar::SetCurItemSkillGauge( const ioHashString &szName, float fGauge )
{
	ioItem *pItem = NULL;
	if( szName.IsEmpty() )
		return;

	for( int i=0; i < ES_OBJECT; ++i )
	{
		ioItem *pEquip = GetEquipedItem( i );
		if( pEquip && pEquip->GetName() == szName )
		{
			pItem = pEquip;
			break;
		}
	}

	if( pItem && pItem->HasSkillGauge() )
	{
		pItem->SetCurSkillGauge( fGauge );
	}
}

float ioBaseChar::GetCurItemSkillGauge( ioItem *pItem )
{
	if( pItem )
	{
		if( pItem->HasSkillGauge() )
			return pItem->GetCurSkillGuage();
	}
	else
	{
		ioItem *pWeapon = GetEquipedItem( ES_WEAPON );
		if( pWeapon && pWeapon->HasSkillGauge() )
			return pWeapon->GetCurSkillGuage();
	}

	return 0.0f;
}

float ioBaseChar::GetCurItemSkillGauge( const ioHashString &szName )
{
	ioItem *pItem = NULL;
	if( szName.IsEmpty() )
		return 0.0f;
	
	for( int i=0; i < ES_OBJECT; ++i )
	{
		ioItem *pEquip = GetEquipedItem( i );
		if( pEquip && pEquip->GetName() == szName )
		{
			pItem = pEquip;
			break;
		}
	}

	if( pItem && pItem->HasSkillGauge() )
	{
		return pItem->GetCurSkillGuage();
	}

	return 0.0f;
}

float ioBaseChar::ReduceCurSkillGaugeBySkill( const ioHashString &szName, float fUseGauge )
{
	ioItem *pItem = NULL;
	if( szName.IsEmpty() )
		return 0.0f;

	for( int i=0; i < ES_OBJECT; ++i )
	{
		ioItem *pEquip = GetEquipedItem( i );
		if( pEquip && pEquip->GetName() == szName )
		{
			pItem = pEquip;
			break;
		}
	}

	if( pItem && pItem->HasSkillGauge() )
	{
		pItem->ReduceSkillGauge( fUseGauge );

		return pItem->GetCurSkillGuage();
	}

	return 0.0f;
}

float ioBaseChar::ReduceCurSkillGaugeBySkill( ioItem *pItem, float fUseGauge )
{
	if( pItem )
	{
		if( pItem->HasSkillGauge() )
		{
			pItem->ReduceSkillGauge( fUseGauge );
		}

		return pItem->GetCurSkillGuage();
	}
	else
	{
		if( m_CharState == CS_USING_SKILL && m_pActiveSkill )
		{
			ioItem *pSkillItem = m_pActiveSkill->GetOwnerItem();
			if( pSkillItem && pSkillItem->HasSkillGauge() )
			{
				pSkillItem->ReduceSkillGauge( fUseGauge );
				return pSkillItem->GetCurSkillGuage();
			}
		}

		ioItem *pWeapon = GetEquipedItem( ES_WEAPON );
		if( pWeapon && pWeapon->HasSkillGauge() )
		{
			pWeapon->ReduceSkillGauge( fUseGauge );
			return pWeapon->GetCurSkillGuage();
		}
	}

	return 0.0f;
}

float ioBaseChar::ReduceNeedGaugeBySkill( ioSkill *pSkill, float fUseGauge )
{
	ioItem *pItem = pSkill->GetOwnerItem();
	if( pItem )
	{
		if( pItem->HasSkillGauge() )
		{
			pItem->ReduceNeedGauge( fUseGauge, this );
		}

		return pItem->GetCurSkillGuage();
	}
	else
	{
		if( m_CharState == CS_USING_SKILL && m_pActiveSkill )
		{
			ioItem *pSkillItem = m_pActiveSkill->GetOwnerItem();
			if( pSkillItem && pSkillItem->HasSkillGauge() )
			{
				pSkillItem->ReduceNeedGauge( fUseGauge, this );
				return pSkillItem->GetCurSkillGuage();
			}
		}

		ioItem *pWeapon = GetEquipedItem( ES_WEAPON );
		if( pWeapon && pWeapon->HasSkillGauge() && fUseGauge > 0.f /* 몬던에서 스킬 버그 수정 by 윤태철 */ )
		{
			pWeapon->ReduceNeedGauge( fUseGauge, this );
			return pWeapon->GetCurSkillGuage();
		}
	}

	return 0.0f;
}

bool ioBaseChar::IsDamageProtect()
{
	if( HasBuff(BT_PROTECTION) )
		return true;

	return false;
}

bool ioBaseChar::IsStateProtect( AttackSide eAttackSide, DefenseBreakType eBreakType )
{
	if( HasBuff(BT_STATE_PROTECTION) || HasBuff(BT_STATE_PROTECTION_BY_PASSIVE) )
	{
		AttackSide eProtectSide = GetStateProtectSide( eAttackSide );
		if( eAttackSide != AS_NONE && eProtectSide != AS_NONE && eAttackSide != eProtectSide )
			return false;

		if( IsNoDefenseBreakStateProtect( eAttackSide ) && eBreakType != DBT_NONE )
			return false;

		return true;
	}
	
	return false;
}

int ioBaseChar::GetStateProtectHPCancelType()
{
	int iCancelType = 0;

	if( HasBuff(BT_STATE_PROTECTION) )
	{
		for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
		{
			ioBuff *pBuff = m_aBuffArray->GetAt(i);
			ioStateProtectionBuff *pProtectBuff = ToStateProtectBuff(pBuff);

			if( pProtectBuff )
			{
				int iCurCancelType = pProtectBuff->GetHPCancelType();
				
				if( iCancelType <= 0 )
					iCancelType = iCurCancelType;
				else if( iCancelType < iCurCancelType )
					iCancelType = iCurCancelType;
			}
		}
	}

	if( HasBuff(BT_STATE_PROTECTION_BY_PASSIVE) )
	{
		for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
		{
			ioBuff *pBuff = m_aBuffArray->GetAt(i);
			ioStateProtectionByPassiveBuff *pProtectBuffByPassive = ToStateProtectByPassiveBuff(pBuff);

			if( pProtectBuffByPassive && pProtectBuffByPassive->IsProtectState() )
			{
				int iCurCancelType = pProtectBuffByPassive->GetHPCancelType();

				if( iCancelType <= 0 )
					iCancelType = iCurCancelType;
				else if( iCancelType < iCurCancelType )
					iCancelType = iCurCancelType;
			}
		}
	}

	return iCancelType;
}

bool ioBaseChar::IsRangeProtect( AttackMethodType eType )
{
	if( HasBuff(BT_RANGE_PROTECT_BUFF) && eType == AMT_RANGE )
		return true;

	return false;
}

bool ioBaseChar::CheckIgnoreWeaponBuff( DWORD dwWeaponIndex )
{
	ioBuff *pBuff = GetBuff( BT_WEAPON_IGNORE_BUFF );
	ioWeaponIgnoreBuff *pWeaponIgnoreBuff = ToWeaponIgnoreBuff( pBuff );
	if( pWeaponIgnoreBuff && pWeaponIgnoreBuff->CheckWeaponIndex( dwWeaponIndex ) )
		return true;

	pBuff = GetBuff( BT_WEAPON_REVERSE_IGNORE_BUFF );
	ioWeaponReverseIgnoreBuff *pWeaponReverseIgnoreBuff = ToWeaponReverseIgnoreBuff( pBuff );
	if( pWeaponReverseIgnoreBuff && !pWeaponReverseIgnoreBuff->CheckWeaponIndex( dwWeaponIndex ) )
		return true;

	return false;
}

float ioBaseChar::GetCurStateProtectRate( AttackSide eAttackSide )
{
	float fCurRate = FLOAT1;
	AttackSide eBuffSide = AS_NONE;

	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioStateProtectionBuff *pProtectBuff = ToStateProtectBuff(pBuff);

		if( pProtectBuff )
		{
			eBuffSide = pProtectBuff->GetProtectSide();

			if( eBuffSide == AS_NONE || eBuffSide == eAttackSide )
			{
				if( pProtectBuff->GetProtectionRate() < fCurRate )
				{
					fCurRate = pProtectBuff->GetProtectionRate();
				}
			}
		}

		ioStateProtectionByPassiveBuff *pProtectBuffByPassive = ToStateProtectByPassiveBuff(pBuff);
		if( pProtectBuffByPassive && pProtectBuffByPassive->IsProtectState() )
		{
			eBuffSide = pProtectBuffByPassive->GetProtectSide();

			if( eBuffSide == AS_NONE || eBuffSide == eAttackSide )
			{
				if( pProtectBuffByPassive->GetProtectionRate() < fCurRate )
				{
					fCurRate = pProtectBuffByPassive->GetProtectionRate();
				}
			}
		}
	}

	return fCurRate;
}

float ioBaseChar::GetCurDefenseDamageBuffRate()
{
	float fCurRate = FLOAT1;

	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioDefenseDamageBuff *pDefenseBuff = ToDefenseDamageBuff(pBuff);

		if( pDefenseBuff && pDefenseBuff->GetDefenseRate() < fCurRate )
			fCurRate = pDefenseBuff->GetDefenseRate();
	}

#ifndef SHIPPING 
	if( Setting::ShowExtraInfo() )
	{
		LOG.PrintTimeAndLog( 0, "DefenseDamageBuffRate: %f", fCurRate );
	}
#endif
	return fCurRate;
}

AttackSide ioBaseChar::GetStateProtectSide( AttackSide eAttackSide )
{
	bool bFirst = true;
	AttackSide eCurSide = AS_NONE;
	AttackSide eBuffSide = AS_NONE;

	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioStateProtectionBuff *pProtectBuff = ToStateProtectBuff(pBuff);

		if( pProtectBuff )
		{
			if( bFirst )
			{
				bFirst = false;
				eCurSide = pProtectBuff->GetProtectSide();
			}
			else
			{
				eBuffSide = pProtectBuff->GetProtectSide();

				switch( eAttackSide )
				{
				case AS_FRONT:
					if( eBuffSide == AS_FRONT || eBuffSide == AS_NONE )
						eCurSide = eBuffSide;
					break;
				case AS_BACK:
					if( eBuffSide == AS_BACK || eBuffSide == AS_NONE )
						eCurSide = eBuffSide;
					break;
				}
			}

			if( eCurSide == AS_NONE )
				break;
		}

		ioStateProtectionByPassiveBuff *pProtectBuffByPassive = ToStateProtectByPassiveBuff(pBuff);
		if( pProtectBuffByPassive && pProtectBuffByPassive->IsProtectState() )
		{
			if( bFirst )
			{
				bFirst = false;
				eCurSide = pProtectBuffByPassive->GetProtectSide();
			}
			else
			{
				eBuffSide = pProtectBuffByPassive->GetProtectSide();

				switch( eAttackSide )
				{
				case AS_FRONT:
					if( eBuffSide == AS_FRONT || eBuffSide == AS_NONE )
						eCurSide = eBuffSide;
					break;
				case AS_BACK:
					if( eBuffSide == AS_BACK || eBuffSide == AS_NONE )
						eCurSide = eBuffSide;
					break;
				}
			}

			if( eCurSide == AS_NONE )
				break;
		}
	}

	return eCurSide;
}

bool ioBaseChar::IsNoBlockStateProtect( AttackSide eAttackSide )
{
	bool bNoBlock = false;
	AttackSide eBuffSide = AS_NONE;

	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioStateProtectionBuff *pProtectBuff = ToStateProtectBuff(pBuff);

		if( pProtectBuff )
		{
			eBuffSide = pProtectBuff->GetProtectSide();

			if( eBuffSide == AS_NONE || eBuffSide == eAttackSide )
			{
				bNoBlock = pProtectBuff->IsNoBlockState();

				if( !bNoBlock )
					break;
			}
		}

		ioStateProtectionByPassiveBuff *pProtectBuffByPassive = ToStateProtectByPassiveBuff(pBuff);
		if( pProtectBuffByPassive && pProtectBuffByPassive->IsProtectState() )
		{
			eBuffSide = pProtectBuffByPassive->GetProtectSide();

			if( eBuffSide == AS_NONE || eBuffSide == eAttackSide )
			{
				bNoBlock = pProtectBuffByPassive->IsNoBlockState();

				if( !bNoBlock )
					break;
			}
		}
	}

	return bNoBlock;
}

bool ioBaseChar::IsNoDefenseBreakStateProtect( AttackSide eAttackSide )
{
	bool bBreakState = false;
	AttackSide eBuffSide = AS_NONE;

	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioStateProtectionBuff *pProtectBuff = ToStateProtectBuff(pBuff);
		
		if( pProtectBuff )
		{
			eBuffSide = pProtectBuff->GetProtectSide();

			if( eBuffSide == AS_NONE || eBuffSide == eAttackSide )
			{
				bBreakState = pProtectBuff->IsNoDefenseBreakState();

				if( !bBreakState )
					break;
			}
		}

		ioStateProtectionByPassiveBuff *pProtectBuffByPassive = ToStateProtectByPassiveBuff(pBuff);
		if( pProtectBuffByPassive && pProtectBuffByPassive->IsProtectState() )
		{
			eBuffSide = pProtectBuffByPassive->GetProtectSide();

			if( eBuffSide == AS_NONE || eBuffSide == eAttackSide )
			{
				bBreakState = pProtectBuffByPassive->IsNoDefenseBreakState();

				if( !bBreakState )
					break;
			}
		}
	}

	return bBreakState;
}

void ioBaseChar::AddReflectInfo( const ReflectInfo &rkReflectInfo )
{
	ReflectInfo *pNewInfo = new ReflectInfo;
	if( !pNewInfo )
		return;

	*pNewInfo = rkReflectInfo;

	ReflectInfoList::iterator iter = m_vReflectInfoList.begin();
	while( iter != m_vReflectInfoList.end() )
	{
		if( !(*iter) )
		{
			iter++;
			continue;
		}

		if( (*iter)->m_Name == pNewInfo->m_Name )
		{
			SAFEDELETE( *iter );
			iter = m_vReflectInfoList.erase( iter );
		}
		else
			iter++;
	}

	m_vReflectInfoList.push_back( pNewInfo );
}

void ioBaseChar::RemoveReflectInfo( const ioHashString &szName )
{
	ReflectInfoList::iterator iter = m_vReflectInfoList.begin();
	while( iter != m_vReflectInfoList.end() )
	{
		if( !(*iter) )
		{
			iter++;
			continue;
		}

		if( (*iter)->m_Name == szName )
		{
			SAFEDELETE( *iter );
			iter = m_vReflectInfoList.erase( iter );
		}
		else
			iter++;
	}
}

void ioBaseChar::SetWeakBombType( ioHashString &szName, float fRate, int eType )
{
	WeakBombInfo kBombInfo;

	kBombInfo.m_Name = szName;
	kBombInfo.m_fWeakBombRate = fRate;
	kBombInfo.m_iWeakBombType = eType;

	m_vWeakBombInfoList.push_back( kBombInfo );
}

void ioBaseChar::RemoveWeakBomb( ioHashString &szName )
{
	WeakBombInfoList::iterator iter = m_vWeakBombInfoList.begin();

	while( iter != m_vWeakBombInfoList.end() )
	{
		if( (*iter).m_Name == szName )
		{
			m_vWeakBombInfoList.erase( iter );
			return;
		}

		++iter;
	}
}

float ioBaseChar::GetWeakBombType( int eType )
{
	WeakBombInfoList::iterator iter = m_vWeakBombInfoList.begin();

	while( iter != m_vWeakBombInfoList.end() )
	{
		if( (*iter).m_iWeakBombType == eType )
		{
			return (*iter).m_fWeakBombRate;
		}

		++iter;
	}

	return -FLOAT1;
}

void ioBaseChar::SetWeakMagic( ioHashString &szName, float fRate, int eType, int eWeakType )
{
	WeakMagicInfo kMagicInfo;

	kMagicInfo.m_Name			= szName;
	kMagicInfo.m_fWeakMagicRate = fRate;
	kMagicInfo.m_iWeakMagicType = eType;
	kMagicInfo.m_iProtectionType = eWeakType;

	m_vWeakMagicInfoList.push_back( kMagicInfo );
}

void ioBaseChar::RemoveWeakMagic( ioHashString &szName )
{
	WeakMagicInfoList::iterator iter = m_vWeakMagicInfoList.begin();

	while( iter != m_vWeakMagicInfoList.end() )
	{
		if( (*iter).m_Name == szName )
		{
			m_vWeakMagicInfoList.erase( iter );
			return;
		}

		++iter;
	}
}

float ioBaseChar::GetWeakMagicType( int eType )
{
	WeakMagicInfoList::iterator iter = m_vWeakMagicInfoList.begin();

	while( iter != m_vWeakMagicInfoList.end() )
	{
		if( (*iter).m_iWeakMagicType == eType )
		{
			return (*iter).m_fWeakMagicRate;
		}

		++iter;
	}

	return -FLOAT1;
}

bool ioBaseChar::IsProtectionMagicType( int eType )
{
	WeakMagicInfoList::iterator iter = m_vWeakMagicInfoList.begin();

	while( iter != m_vWeakMagicInfoList.end() )
	{
		if( (*iter).m_iWeakMagicType == eType && (*iter).m_iProtectionType == EPT_WEAK_PROTECTION )
		{
			return true;
		}

		++iter;
	}

	return false;
}
