void ioBaseChar::SetPushStructState( int iPushStructIndex )
{
	ioPushStruct *pStruct = g_PushStructListMgr.FindPushStruct( iPushStructIndex );
	if( !pStruct )
	{
		LOG.PrintTimeAndLog( 0, "ioBaseChar::SetPushStructState - %d Not Exist", iPushStructIndex );
		return;
	}

	SetState( CS_STRUCT_PUSH );

	ioWeaponItem *pAttackItem = GetWeapon();
	if( pAttackItem )
	{
		pAttackItem->SetVisible( this, false );
		m_pGroup->SetEntityVisible( pAttackItem->GetEquipMesh(this), false );
	}

	m_iCurPushStructIndex = iPushStructIndex;
	pStruct->SetMoveState( this );

	//상태 전환된 사항 전달
	if( IsNeedSendNetwork() )
	{
		SP2Packet kPacket( CUPK_PUSHSTRUCT_MOVE );
		kPacket << GetCharName();
		kPacket << GetTargetRot();
		kPacket << iPushStructIndex;
		kPacket << pStruct->GetWorldPosition();
		P2PNetwork::SendToAllPlayingUser( kPacket );
	}
}

void ioBaseChar::ProcessPushMove( float fTimePerSec )
{
	if( m_iCurPushStructIndex == -1 )	return;

	ioPushStruct *pStruct = g_PushStructListMgr.FindPushStruct( m_iCurPushStructIndex );
	if( !pStruct )
	{
		LOG.PrintTimeAndLog( 0, "ioBaseChar::ProcessPushMove - %d Not Exist", m_iCurPushStructIndex );
		SetState( CS_DELAY );
		return;
	}

	float fPushSpeed = pStruct->GetCurMoveSpeed();
	if( fPushSpeed > 0.0f )
	{
		// 등속운동이기때문에 별다른 조치를 취하지 않음
		bool bCol = false;
		D3DXVECTOR3 vMoveAmt = m_vMoveDir * ( fPushSpeed * fTimePerSec );
		if( m_pCreator->ReCalculateMoveVectorByTerrain( this, &vMoveAmt, bCol ) )
		{
			Translate( vMoveAmt );
		}
	}

	D3DXVECTOR3 vRackMove;
	if( !g_WeaponMgr.HasControlReturnWeapon(this) && ProcessRackMove( fTimePerSec, vRackMove ) )
	{
		Translate( vRackMove );
	}

	D3DXVECTOR3 vPos = GetWorldPosition();
	if( m_fCurJumpPowerAmt > 0.0f )
	{
		vPos.y += m_fCurJumpPowerAmt * fTimePerSec;
	}

	bool bPreFrameIsHigh = false;
	float fMapHeight = GetBottomHeight();
	if( vPos.y > fMapHeight )
	{
		m_fGravityAmt += m_fFlyGravityAmt * fTimePerSec;
		vPos.y -= m_fGravityAmt * fTimePerSec;
		bPreFrameIsHigh = true;
	}

	m_bCurFrameDrop = false;
	m_fCurGravityGapAmt = m_fGravityAmt - m_fCurJumpPowerAmt;

	if( m_fCurJumpPowerAmt <= m_fGravityAmt && vPos.y <= fMapHeight )
	{
		vPos.y = fMapHeight;

		m_fCurJumpPowerAmt = 0.0f;
		m_fGravityAmt = 0.0f;
		m_bCurFrameDrop = bPreFrameIsHigh;
	}

	SetWorldPosition( vPos );
}

void ioBaseChar::CheckPushStructState()
{
	if( P2PNetwork::IsNetworkPlaying() && m_pCreator->IsNetworkMode() && !m_bOwnerChar ) 
		return;

	ioPushStruct *pStruct = NULL;
	if( m_iCurPushStructIndex != -1 )
	{
		pStruct = g_PushStructListMgr.FindPushStruct( m_iCurPushStructIndex );
	}

	if( !pStruct || pStruct->GetState() == ioPushStruct::PS_DIE )
	{
		if( IsNeedSendNetwork() )
		{
			SP2Packet kPacket( CUPK_PUSHSTRUCT_DELAY );
			kPacket << GetCharName();
			kPacket << 0;
			P2PNetwork::SendToAllPlayingUser( kPacket );
		}

		SetState( CS_DELAY );
		return;
	}
	
	if( !m_KeyInput.IsAttackKeyDown() )
	{
		if( IsNeedSendNetwork() )
		{
			SP2Packet kPacket( CUPK_PUSHSTRUCT_DELAY );
			kPacket << GetCharName();
			kPacket << pStruct->GetPushArrayIdx();
			kPacket << pStruct->GetWorldPosition();
			P2PNetwork::SendToAllPlayingUser( kPacket );
		}

		SetState( CS_DELAY );
		return;
	}

	D3DXVECTOR3 vDiff = pStruct->GetWorldPosition() - GetWorldPosition();

	float fHeightGap = fabs( GetWorldPosition().y - pStruct->GetWorldPosition().y );
	if( fHeightGap > pStruct->GetHeightGap() )
	{
		if( IsNeedSendNetwork() )
		{
			SP2Packet kPacket( CUPK_PUSHSTRUCT_DELAY );
			kPacket << GetCharName();
			kPacket << pStruct->GetPushArrayIdx();
			kPacket << pStruct->GetWorldPosition();
			P2PNetwork::SendToAllPlayingUser( kPacket );
		}

		SetState( CS_DELAY );
		return;
	}

	if( D3DXVec3Length( &vDiff ) > pStruct->GetPushRange() )
	{
		if( IsNeedSendNetwork() )
		{
			SP2Packet kPacket( CUPK_PUSHSTRUCT_DELAY );
			kPacket << GetCharName();
			kPacket << pStruct->GetPushArrayIdx();
			kPacket << pStruct->GetWorldPosition();
			P2PNetwork::SendToAllPlayingUser( kPacket );
		}

		SetState( CS_DELAY );
		return;
	}

	float fCosine = cosf( DEGtoRAD( 50.0f ) );
	D3DXVECTOR3 vTargetDir = GetMoveDir();
	D3DXVec3Normalize( &vDiff, &vDiff );
	if( D3DXVec3Dot( &vDiff, &vTargetDir ) < fCosine )
	{
		if( IsNeedSendNetwork() )
		{
			SP2Packet kPacket( CUPK_PUSHSTRUCT_DELAY );
			kPacket << GetCharName();
			kPacket << pStruct->GetPushArrayIdx();
			kPacket << pStruct->GetWorldPosition();
			P2PNetwork::SendToAllPlayingUser( kPacket );
		}

		SetState( CS_DELAY );
		return;
	}

	if( pStruct->GetState() != ioPushStruct::PS_MOVE )
	{
		if( IsNeedSendNetwork() )
		{
			SP2Packet kPacket( CUPK_PUSHSTRUCT_DELAY );
			kPacket << GetCharName();
			kPacket << pStruct->GetPushArrayIdx();
			kPacket << pStruct->GetWorldPosition();
			P2PNetwork::SendToAllPlayingUser( kPacket );
		}

		SetState( CS_DELAY );
	}
}

void ioBaseChar::SetCurPushStructByNetwork( int iIndex )
{
	m_iCurPushStructIndex = iIndex;
}

