bool ioBaseChar::HasExtendDash()
{
	if( m_pExtendDash )
		return true;
	
	return false;
}

bool ioBaseChar::SetExtendDash()
{
	if( m_pExtendDash )
	{
		return m_pExtendDash->StartDash( this );
	}

	return false;
}

void ioBaseChar::CheckExtendDashLoopEffect()
{
	if( GetPreState() == CS_EXTEND_DASH && GetState() != CS_EXTEND_DASH )
	{
		if( !m_szExtendDashLoopEffect.IsEmpty() )
		{
			EndEffect( m_szExtendDashLoopEffect, true );
			m_szExtendDashLoopEffect.Clear();
		}
	}
}

float ioBaseChar::GetWeakAttackPushRate()
{
	ioAttackableItem *pItem = GetPriorityItem( SPT_DEFENSE );
	if( pItem )
		return pItem->GetWeakAttackPushRate();

	return m_fWeakAttackPushRate;
}

void ioBaseChar::CheckEnableDashCheck()
{
	ioAttackableItem *pItem = GetPriorityItem( SPT_ATTACK );

	m_bEnableDashCheck = false;
	DWORD dwCurTime = FRAMEGETTIME();

	if( m_CharState == CS_ATTACK &&
		(m_CurDashType == DT_ROLLING_AIM ||
		 m_CurDashType == DT_DASH_AIM ||
		 m_CurDashType == DT_ASSAULT ||
		 m_CurDashType == DT_EXTEND_ASSAULT ||
		 m_CurDashType == DT_ATTACK ||
		 m_CurDashType == DT_POWER_CHARGE ||
		 m_CurDashType == DT_POWER_CHARGE2 ||
		 m_CurDashType == DT_POWER_CHARGE3 ||
		 m_CurDashType == DT_SHAOLIN ||
		 m_CurDashType == DT_ASSAULT_CHARGE ||
		 m_CurDashType == DT_CHARGE_COMBO ||
		 m_CurDashType == DT_NORMAL_COMBO ||
		 m_CurDashType == DT_DASH_ATTACK2 ||
		 m_CurDashType == DT_SUDDEN_ATTACK ||
		 m_CurDashType == DT_TELEPORT ||
		 m_CurDashType == DT_FROZEN_COMBO ||	// 얼음 신 2020-03-03
		 m_CurDashType == DT_GENISYSARMY	||	// 제네시스 2020-06-26
		 m_CurDashType == DT_EVA			||	// 이브 2020-10-20
		 m_CurDashType == DT_MAGNETIC	||		// 마그넥티 2020-11-25
		 m_CurDashType == DT_TAOIST ))			
	{
		if( pItem && pItem->IsEnableAttackDashCheck( this, true ) )
		{
			m_bEnableDashCheck = true;
		}
		else if( pItem && pItem->IsEnableItemDashCheck( this, true) )
		{
			m_bEnableDashCheck = true;
		}
		else if( m_CurDashType == DT_EXTEND_ASSAULT )
		{
			if( m_AnimationTime.EndTime() < dwCurTime )
			{
				m_bEnableDashCheck = true;
			}

			iolupinItem *pLupinItem = ToLupinItem( m_pEquipSlot->GetWeapon() );
			if( pLupinItem )
				m_bEnableDashCheck = true;
		}
	}
	else if( m_CharState == CS_ATTACK )
	{
		if( pItem && pItem->IsChargeAttackState(this) )
		{
			m_bEnableDashCheck = false;
		}
		else
		{
			if( m_AnimationTime.EndTime() < dwCurTime )
			{
				m_bEnableDashCheck = true;
			}
			else if( m_CurDashType == DT_ROLLING )
			{
				ioAttackableItem *pDashItem = GetPriorityItem( SPT_DASH );
				if( pDashItem && pDashItem->IsEnableAttackDashCheck( this, true ) )
				{
					m_bEnableDashCheck = true;
				}
			}
		}
	}
	else if( m_CharState == CS_JUMP )
	{
		if( m_CurJumpType == JT_BADGUY_JUMP && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		if( m_CurJumpType == JT_KISARAGI_JUMP && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		if( m_CurJumpType == JT_RAGNA_JUMP && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		if( m_CurJumpType == JT_RACHEL_JUMP && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		if( m_CurJumpType == JT_TRINITY_JUMP && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		if( m_CurJumpType == JT_HAKUMEN_JUMP && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		if( m_CurJumpType == JT_CHARGE_COMBO && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		if( m_CurJumpType == JT_CHARGE_COMBO2 && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		if( m_CurJumpType == JT_CHARGE_COMBO3 && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		if( m_CurJumpType == JT_CHARGE_COMBO4 && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		if( m_CurJumpType == JT_SUDDEN_ATTACK_JUMP && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		if( HasBuff(BT_AIR_ATTACK) && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		if( HasBuff(BT_LAND_ROLLING_BUFF) && m_JumpState == JS_LANDING )
			m_bEnableDashCheck = true;

		if( m_CurJumpType == JT_SKY_WALKER_JUMP && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;

		// 2020-06-02 권왕 추가
		if( m_CurJumpType == JT_GWONWANG_JUMP && m_JumpState == JS_JUMPPING )
			m_bEnableDashCheck = true;
		
		ioAttackableItem *pJumpItem = GetPriorityItem( SPT_JUMP );
		if( pJumpItem )
		{
			ioExtendJump *pExtendJump = pJumpItem->GetCurExtendJump();
			if( pExtendJump && pExtendJump->IsEnableJumpDash(this) )
				m_bEnableDashCheck = true;

			// 뉴클리어솔저 2020-02-14
			ioNuClearSoldierItem *pNuClearSoldierItem = ToNuClearSoldierItem( pJumpItem );
			if( pNuClearSoldierItem && pNuClearSoldierItem->IsEnableJumpDash(this) )
			{
				m_bEnableDashCheck = true;
			}

			ioShieldWeaponItem3 *pShieldWeaponItem3 = ToShieldWeaponItem3( pJumpItem );
			if( pShieldWeaponItem3 && pShieldWeaponItem3->IsJumpEndSpecialDash() && m_JumpState == JS_LANDING )
				m_bEnableDashCheck = true;
		}
	}
	else if ( m_CharState == CS_NEW_JUMP_ATTACK )
	{
		if( m_CurJumpType == JT_STRIDER_JUMP )
			m_bEnableDashCheck = true;
	}
	else if( m_CharState == CS_EXTEND_DEFENSE )
	{
		ioAttackableItem *pDefenseItem = GetPriorityItem( SPT_DEFENSE );
		if( pDefenseItem && pDefenseItem->HasFeature( IF_HAS_EXTEND_DEFENSE ) )
		{
			if( pDefenseItem->IsEnableExtendDefDash() )
				m_bEnableDashCheck = true;
		}
	}
	else if( m_CharState == CS_BLOW_WOUNDED ||
			 m_CharState == CS_BOUND_BLOW_WOUNDED ||
			 m_CharState == CS_BLOW_EXTEND_WOUND )
	{
		m_bEnableDashCheck = true;
	}
	else if( m_CharState == CS_DASH_ATTACK )
	{
		ioAttackableItem *pAttackable = GetPriorityItem( SPT_DASH );
		if( pAttackable)
		{
			ioExtendDash *pExtendDash = pAttackable->GetCurExtendDash();
			if( pExtendDash && pExtendDash->IsEnableDashFromDashAttack( this ) )
				m_bEnableDashCheck = true;
		}

		if( m_DashAttackEndDash != DAET_NONE )
			m_bEnableDashCheck = true;
	}
	else if( m_CharState == CS_EXTEND_DASH )
	{
		ioAttackableItem *pAttack = GetPriorityItem( SPT_ATTACK );
		if( pAttack && pAttack->IsConditionalSpecialDashReserve( this ) )
		{
			m_bEnableDashCheck = true;
		}
		else if( m_CurDashType == DT_DASH_ATTACK2 || m_CurDashType == DT_SUDDEN_ATTACK )
			m_bEnableDashCheck = true;
		else if ( pAttack && m_CurDashType == DT_EXTEND_ASSAULT )
		{
			ioExtendAssaultDash *pExtendAssaultDash = ToExtendAssaultDash( pAttack->GetCurExtendDash() );
			if ( pExtendAssaultDash )
				m_bEnableDashCheck = pExtendAssaultDash->IsDashEnable( this );
		}
	}
	else if( m_CharState == CS_USING_SKILL )
	{
		if( m_pActiveSkill && m_pActiveSkill->IsEnableDashCheck( this ) )
			m_bEnableDashCheck = true;
	}
	else if ( m_CharState == CS_DEFENCE_COUNTER )
	{
		if( pItem && pItem->IsUseDefenceCounterAttackEndDash() )
			m_bEnableDashCheck = true;
	}
	else if ( m_CharState == CS_COUNTER_ATTACK )
	{
		ioAttackableItem *pItem = GetPriorityItem( SPT_DEFENSE );
		ioCounterAttack *pCounter = NULL;
		if( pItem )
			pCounter = pItem->GetCurCounterAttack();

		if( pCounter && pCounter->IsEnableDashCheck() )
			m_bEnableDashCheck = true;
	}
	else if ( m_CharState == CS_WOUNDED )
	{
		if( pItem && pItem->IsEnableWoundedDashCheck( this, true ) )
			m_bEnableDashCheck = true;
	}
	else
	{
		if( m_pCharSpeicalState && m_pCharSpeicalState->IsEnableDashState( this ) )
		{
			m_bEnableDashCheck = true;
		}
	}
}

void ioBaseChar::ApplySkillExtraInfo( ioHashString szSkillName, SP2Packet &rkPacket )
{
	if( m_pActiveSkill && m_pActiveSkill->GetName() == szSkillName )
	{
		m_pActiveSkill->ApplyExtraSkillInfo( this, m_pCreator, rkPacket );
	}
}

void ioBaseChar::CheckEscapeState()
{
	if( m_AnimationTime.EndTime() < FRAMEGETTIME() )
	{
		SetProtectionMode( PM_ESCAPE , 500 );
		SetState( CS_DELAY );
	}
}

void ioBaseChar::SetEscapePrisonerState()
{
	m_pGroup->ClearAllActionAni( FLOAT100, true );
	m_pGroup->ClearAllLoopAni( FLOAT100, true );

	if( m_PrisonerEscapeAni.IsEmpty() )
	{
		LOG.PrintTimeAndLog( 0, "ioBaseChar::SetEscapePrisonerState() - EscapeMotion is Empty!" );
		SetState( CS_DELAY );
		return;
	}

	int iAniID = m_pGroup->GetAnimationIdx( m_PrisonerEscapeAni );

	m_pGroup->SetActionAni( iAniID, 0.0f, FLOAT100, FLOAT1, FLOAT1/m_fPrisonerEscapeAniRate, 0.0f, 0.0f, true );
	m_AnimationTime.dwStartTime = FRAMEGETTIME();
	m_AnimationTime.dwFullTime  = m_pGroup->GetAnimationFullTime( iAniID ) * m_fPrisonerEscapeAniRate;

	SetState( CS_ESCAPE_PRISONER );
	SetProtectionMode( PM_ESCAPE , m_AnimationTime.dwFullTime );

	SetJumpPower( m_fPrisonerEscapeJumpPower );
}

void ioBaseChar::SetFrozenState( bool bPreFrozen, DWORD dwMinTime, DWORD dwMaxTime )
{
	m_bBlowFrozenState = false;
	m_bFrozenState = true;

	DWORD dwCurTime = FRAMEGETTIME();

	if( m_CharState == CS_BLOW_WOUNDED ||
		m_CharState == CS_FALL ||
		m_CharState == CS_BOUND_BLOW_WOUNDED ||
		m_CharState == CS_BLOW_EXTEND_WOUND )
	{
		if( m_BlowState != BW_GETUP )
		{
			m_bBlowFrozenState = true;
		}

		m_pGroup->StopAllPlayingAnimation();
	}
	else
	{
		m_pGroup->ClearAllLoopAni( FLOAT100, true );
		m_pGroup->ClearAllActionAni( FLOAT100, true );

		float fTimeRate = m_fWeakAttackWoundedRate;

		int iAniID = GetWoundedAnimationIdx( m_AttackedSide, BTT_WEAK );
		m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fTimeRate, 0.0f, 0.0f, true );

		m_AnimationTime.dwStartTime = dwCurTime;
		m_AnimationTime.dwFullTime  = m_pGroup->GetAnimationFullTime( iAniID ) * fTimeRate;
		m_fWoundedDefenseEnableRate = 0.0f;

		SetFootDustEffect();
	}

	if( !bPreFrozen )
	{
		m_dwFrozenStartTime = FRAMEGETTIME();
		m_dwFrozenMinTime = dwMinTime;
		m_dwFrozenCurTime = dwMaxTime;
	}

	SetState( CS_FROZEN );

	ClearAttackFireTimeAndSkill();
	ClearReservedSliding();
}

void ioBaseChar::SetStopMotion( int iType )
{
	m_iStopMotionType = iType;

	m_bBlowStopMotion = false;
	if( m_iStopMotionType == ioStopMotionBuff::SMT_NORMAL ||
		m_iStopMotionType == ioStopMotionBuff::SMT_WEAK )
	{
		if( IsFloatingState() ||
			IsApplyDownState() ||
			(m_CharState == CS_ETC_STATE && m_bBlowEtcState ) ||
			(m_CharState == CS_FROZEN && m_bBlowFrozenState ) )
		{
			m_bBlowStopMotion = true;
		}

		m_pGroup->StopAllPlayingAnimation();
	}

	SetState( CS_STOP_MOTION );

	ClearAttackFireTimeAndSkill();
	ClearReservedSliding();
}

bool ioBaseChar::IsCanMiniMapVisible()
{
	if( m_CharState == CS_DIE ||
		m_CharState == CS_VIEW ||
		m_CharState == CS_OBSERVER ||
		m_CharState == CS_READY ||
		m_CharState == CS_LOADING )
		return false;

	for( int i=0; i<m_aBuffArray->MaxCount(); ++i )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioCreateDummyCharBuff *pCreateDummyBuff = ToCreateDummyCharBuff( pBuff );
		if( pCreateDummyBuff && pCreateDummyBuff->IsHideMiniMap() )
			return false;

		ioCreateDummyChar5Buff *pCreateDummy5Buff = ToCreateDummyChar5Buff( pBuff );
		if( pCreateDummy5Buff && pCreateDummy5Buff->IsHideMiniMap() )
			return false;
	}

	// 2010.10.28 강시모드에서 BT_STEALTH 사용하면서 !m_bPrisonerMode && !m_bCatchState 조건 제거
	if( !IsHasCrown() )
	{
		if( HasBuff( BT_STEALTH ) && GetTeam() != m_pCreator->GetOwnerTeam() )
			return false;
	}

	return true;
}

bool ioBaseChar::IsCanChangeTeamInMiniMap()
{
	ioBuff* pBuff = GetBuff( BT_CHANGE_TEAM );
	ioChangeTeamBuff *pChangeTeamBuff = ToChangeTeamBuff( pBuff );
	if( pChangeTeamBuff )
	{
		if( pChangeTeamBuff->EnableChangeTeamInMinimap() )
			return true;
	}
	return false;
}

bool ioBaseChar::IsCanChangeCharState( int iCharArray, bool bInputCheck, bool bRequestBankrupt, bool bSystemMsg )
{
	//알림 메시지 없이 예외 처리
	if( GetState() == CS_CONSTRUCT_HOUSE )
		return false;
	
	bool bBomb = false;
	ioItem *pItem = NULL;
	if( m_pEquipSlot )
		pItem = m_pEquipSlot->GetEquipedItem( ES_WEAPON );
	if( pItem )
	{
		ioHookItem *pHookItem = ToHookItem( pItem );
		ioGunnerItem *pGunnerItem = ToGunnerItem( pItem );
		if( (pHookItem && pHookItem->CheckOnHand()) || (pGunnerItem && pGunnerItem->CheckOnHand()) )
		{
			bBomb = true;
		}
	}
	
	if( GetObject() )
	{
		bBomb = true;
	}

	if( bInputCheck )
	{
		DWORD dwCurTime = FRAMEGETTIME();

		bool bInputEnable = false;
		if( m_dwChangeCharCheckTime > dwCurTime )
		{
			bInputEnable = false;
		}
		else
		{
			m_dwChangeCharCheckTime = dwCurTime;
			m_dwChangeCharCheckTime += m_dwChangeCharInputGap;
			bInputEnable = true;
		}

		if( !bInputEnable )
		{
			return false;
		}
	}

	if( ToFightClubMode( m_pModeParent ) )
	{
		g_ChatMgr.SetSystemMsg( STR(10) );
		return false;
	}

	// 배틀모드 중 출전하고 있는 상태라면 용병 교체 불가
	if( ToBattleMode( m_pModeParent ) && g_BattleRoomMgr.CheckUserBattleFightFlag(GetCharName()))
	{
		g_ChatMgr.SetSystemMsg( STR(10) );
		return false;
	}

	
	bool bEnableChangeSoldierBuff = false;
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);

		ioChangeSoldierBuff *pChangeSoldierBuff = ToChangeSoldierBuff( pBuff );

		if( !pChangeSoldierBuff )
			continue;

		if( pChangeSoldierBuff->EnableChangeSoldier() )
		{
			if( IsOwnerChar() )
			{
				if( m_bPrisonerMode || IsHasCrownByAllMode() || bBomb || IsGangsi() )
				{
					if( !bSystemMsg )
						return false;

					if( IsGangsi() )
						g_ChatMgr.SetSystemMsg( STR(9) );
					else if( !bRequestBankrupt )
						g_ChatMgr.SetSystemMsg( STR(1) );
					else
					{
						if( IsChatModeState( true ) )
							g_ChatMgr.SetSystemMsg( STR(2) );
						else
							g_ChatMgr.SetSystemMsg( STR(3) );
					}
					return false;
				}

				bool bChangeExtraItem = false;
				const CHARACTERDATA* pChar = g_MyInfo.GetCharacterData( iCharArray );
				if( !pChar )
					return false;

				ioUserExtraItem *pExtraItem = g_MyInfo.GetUserExtraItem();
				EXTRAITEMSLOT kSlot;
				int iCurWeapon = ConvertPowerUpCharToItem( m_CharInfo.m_eCharPowerUpType ) + m_CharInfo.m_class_type;
				if( pExtraItem->GetExtraItem( m_CharInfo.m_extra_item[ES_WEAPON], kSlot ) )
					iCurWeapon = kSlot.m_iItemCode;

				int iBaseWeapon = pChar->m_equip_item[ES_WEAPON].m_item_code;
				if( iCurWeapon != iBaseWeapon )
					bChangeExtraItem = true;

				if( bChangeExtraItem )
					bEnableChangeSoldierBuff = true;
			}
		}
	}

	if( !bEnableChangeSoldierBuff )
	{
		if( ( m_CharState != CS_DELAY && m_CharState != CS_RUN && m_CharState != CS_SPECIAL_MOTION && m_CharState != CS_ETCITEM_MOTION && m_CharState != CS_NOT_MOVE_PROTECT && m_CharState != CS_BATTLE_WAITING ) ||
			m_CharState == CS_DIE ||
			m_CharState == CS_VIEW ||
			m_CharState == CS_OBSERVER ||
			m_bPrisonerMode ||
			m_bCatchState ||
			IsHasCrownByAllMode() ||
			bBomb ||
			IsGangsi() )
		{
			if( !IsOwnerChar() )
				return false;

			if( !bSystemMsg )
				return false;

			if( IsGangsi() )
			{
				g_ChatMgr.SetSystemMsg( STR(9) );
				return false;
			}
			else if( CheckImmediatelyChange( iCharArray ) )
			{
				m_bCharacterImmediatelyChange = true;
				//m_pCreator->GetPlayMode()->SetCharacterChangeImmediatelyTime( FRAMEGETTIME() );
			}
			else if( !bRequestBankrupt )
			{
				g_ChatMgr.SetSystemMsg( STR(1) );
				return false;
			}
			else
			{
				if( IsChatModeState( true ) )
					g_ChatMgr.SetSystemMsg( STR(2) );
				else
					g_ChatMgr.SetSystemMsg( STR(3) );

				return false;
			}
		}
	}

	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		if( !pBuff ) continue;
		
		if( bEnableChangeSoldierBuff && m_bCatchState )
			continue;

		if( pBuff->IsDisableChange() )
		{
			if( IsOwnerChar() )
			{
				if( !bSystemMsg )
					return false;

				if( !bRequestBankrupt )
					g_ChatMgr.SetSystemMsg( STR(4) );
				else
					g_ChatMgr.SetSystemMsg( STR(5) );
			}
			return false;
		}
	}

	if( !m_PossessionName.IsEmpty() )
	{
		ioBaseChar *pPossession = GetBaseChar( m_PossessionName );
		if( pPossession )
		{
			LOG.PrintTimeAndLog( 0, "%s - m_PossessionName : %s", __FUNCTION__, m_PossessionName.c_str() );
			g_ChatMgr.SetSystemMsg( STR(1) );
			return false;
		}
	}

	if( m_pCreator->IsNetworkMode() )
	{
		if( !CheckCharChangeStateByEquipItem() )
		{
			//ioBattleMode* pBattleMode = ToBattleMode( m_pModeParent );
			//if( pBattleMode )
			//	return true;

			if( !IsOwnerChar() )
				return false;

			if( IsHasCrownByAllMode() )
				return false;

			if( !bSystemMsg )
				return false;

			if( !bRequestBankrupt )
				g_ChatMgr.SetSystemMsg( STR(6) );
			else
				g_ChatMgr.SetSystemMsg( STR(7) );

			return false;
		}


		if( g_BattleRoomMgr.IsBattleRoom() &&
			m_pModeParent &&
			m_pModeParent->GetModeType() != MT_TRAINING		&&
			m_pModeParent->GetModeType() != MT_MYROOM		&&
			m_pModeParent->GetModeType() != MT_HEADQUARTERS	&&
			m_pModeParent->GetModeType() != MT_HOUSE )
		{
			if( m_pCreator && !m_pCreator->CheckRoomChangeChar() )
			{
				g_ChatMgr.SetSystemMsg( STR(8) );
				return false;
			}
		}
	}

	if( m_bNoChangeCharOnExperienceChange )
		return false;

	iolupinItem *pLupinItem = ToLupinItem( m_pEquipSlot->GetWeapon() );
	if( pLupinItem && pLupinItem->IsLupinSpecialFixedState() )
		return false;

	return true;
}

bool ioBaseChar::IsChangeWaitState()
{
	if( m_CharState == CS_CHANGE_WAIT )
		return true;
	if( m_ExperienceMode == EMS_CHANGE_EXPERIENCE || m_ExperienceMode == EMS_SEND_EXPERIENCE )
		return true;

	return false;
}

void ioBaseChar::SetChangeWaitState( int iArray ,bool bSendChangeCharMsg, bool bClassType )
{
	if( m_CharState == CS_DIE || m_CharState == CS_VIEW || m_CharState == CS_OBSERVER )
	{
		return;
	}

	if ( m_pEquipSlot && m_pEquipSlot->IsEquipWait() )
		return;

	g_KeyManager.SetLastSoldierSelectKey(iArray);
	bool bEnableChangeBuff = false;
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioChangeSoldierBuff *pChangeSoldierBuff = ToChangeSoldierBuff( pBuff );

		if( !pChangeSoldierBuff ) continue;

		if( pChangeSoldierBuff->EnableChangeSoldier() )
		{
			bEnableChangeBuff = true;
		}
	}
	
	m_bDisableEquipObject = false;
	D3DXVECTOR3 vPos = GetWorldPosition();
	float fHeight = m_pCreator->GetMapHeight( vPos.x, vPos.z );

	if( !bEnableChangeBuff && !m_bCharacterImmediatelyChange )
	{
		m_pGroup->ClearAllActionAni( FLOAT100, true );
		m_pGroup->ClearAllLoopAni( FLOAT100, true );

		if( !m_ChangeWaitAni.IsEmpty() )
		{
			m_pGroup->SetLoopAni( m_ChangeWaitAni, FLOAT100 );
		}
		else
		{
			LOG.PrintTimeAndLog( 0, "ioBaseChar::SetChangeWaitState() - ChangeMotion is Empty!" );
		}

		SetState( CS_CHANGE_WAIT );
	}
	else if( m_bCharacterImmediatelyChange )
	{
		if( !IsWoundedState() )
		{
			InitForcePower();
			SetCurMoveSpeed( 0.0f );
			ClearReservedSliding();
		}

		/*m_fCurJumpPowerAmt = m_fCurSkillEndJumpAmt = 0.0f;
		m_vForceDir = ioMath::UNIT_Z;
		m_fForceAmt = 0.0f;
		m_fForceFrictionRate = FLOAT1;
		m_bForcePowerLinear = false;*/

		if( m_CharState == CS_JUMP )
		{
			SetSKillEndJumpState( m_fImmediatelyChangeJumpPower );
		}
		else if( !IsWoundedState() )
		{
			m_pGroup->ClearAllActionAni( FLOAT100, true );
			m_pGroup->ClearAllLoopAni( FLOAT100, true );

			if( !m_ChangeWaitAni.IsEmpty() )
			{
				m_pGroup->SetLoopAni( m_ChangeWaitAni, FLOAT100 );
			}
			else
			{
				LOG.PrintTimeAndLog( 0, "ioBaseChar::SetChangeWaitState() - ChangeMotion is Empty!" );
			}

			SetState( CS_CHANGE_WAIT );
		}
	}
	else
	{
		m_bDisableEquipObject  = true;
	}

	AttachEffect( m_ChangeWaitEffect );

	m_fCurHPRate = m_HP.m_fCurValue / m_HP.m_fMaxValue;

	if( bSendChangeCharMsg )
	{
		if( IsNeedSendNetwork() )
		{
			if( !bClassType )
				SendChangeChar(iArray);
			else
				TrainingChangeChar( iArray );
		}
	}
}

