void ioBaseChar::CustomTextureDownLoadComplete( const ioHashString &rkDstTex, const DWORD dwCustomIndex, const DWORD dwSubIndex )
{
	if( !m_pEquipSlot ) return;
	if( !m_pEquipSlot->IsCustomItemCheck( dwCustomIndex, IsMale() ) ) return;

	// 현재 착용중인 장비의 CustomIndex / SubIndex를 확인하여 교체한다.
	char szSrcName[MAX_PATH] = "";
	sprintf( szSrcName, "%d_%d.lsc", dwCustomIndex, dwSubIndex );
	Help::CustomEntityGroupTexture( m_pGroup, rkDstTex, szSrcName, dwSubIndex );
}

bool ioBaseChar::IsNeedCheckMapCollision() const
{
	if( IsSkipState() )
		return false;

	switch( m_CharState )
	{
	case CS_DROP_ZONE_DOWN:
	case CS_DIE:
	case CS_VIEW:
	case CS_OBSERVER:
	case CS_LOADING:
	case CS_SKIP_STUN:
		return false;
	case CS_SABER_ATTACK:
		{
			ioSaberItem *pSaber= ToSaberItem( GetPriorityItem(SPT_ATTACK) );
			if ( pSaber )
				return !pSaber->IsSaberCollisionSkipState();
		}
		break;
	case CS_BUFF_ACTION:
		{
			for( int i=0; i<m_aBuffArray->MaxCount(); i++ )
			{
				ioBuff *pBuff = m_aBuffArray->GetAt(i);
				if( pBuff )
				{
					ioDummyChainBuff *pDummyChainBuff = ToDummyChainBuff( pBuff );
					if ( pDummyChainBuff )
						return !pDummyChainBuff->IsCharCollisionSkipState();

					ioAttachedDummyBuff2 *pAttachedDummyBuff2 = ToAttachedDummyBuff2( pBuff );
					if ( pAttachedDummyBuff2 )
						return pAttachedDummyBuff2->IsCharCollisionSkipState();
				}
			}
		}
		break;
	}

	if( HasBuff(BT_DROP_ZONE) )
		return false;

	return true;
}

void ioBaseChar::DontMoveCollisionPushingTranslate( ioGameEntity *pPusher, const D3DXVECTOR3 &vMoveAmt )
{
	bool bCol = false;
	D3DXVECTOR3 vApplyAmt = vMoveAmt;
	if( m_pCreator->ReCalculateMoveVectorByTerrain( this, &vApplyAmt, bCol ) )
	{
		Translate( vApplyAmt );
	}
}

int ioBaseChar::DontMoveEntityLevel() const
{
	switch( m_CharState )
	{
	case CS_FROZEN:
	case CS_ICE_STATE:
	case CS_USING_SKILL:
	case CS_STOP_MOTION:
	case CS_NOT_MOVE_PROTECT:
		return 1;

	case CS_EXCAVATING:
	case CS_CONSTRUCT_HOUSE:
	case CS_ROULETTE:
		return 4;

	case CS_FISHING:
	case CS_BATTLE_WAITING:
		return 5;
	}

	if( m_bExcavating && g_ExcavationMgr.IsForkcraneLevel( g_ExcavationMgr.GetUserExcavationLv( m_Name ) ) )
	{
		return 4;
	}

	return 0;
}

