void ioBaseChar::SetCharChangeEffect()
{
	if( GetTeam() == TEAM_RED )
		AttachEffect( m_CharChangeRedEffect );
	else if( GetTeam() == TEAM_BLUE )
		AttachEffect( m_CharChangeBlueEffect );
	else // 개인전
	{
		if( GetSingleConvertTeam() == TEAM_BLUE )
			AttachEffect( m_CharChangeBlueEffect );
		else
			AttachEffect( m_CharChangeRedEffect );
	}

	SetAwakeChangeEffect();
}

void ioBaseChar::SetDefenseMoveEnable( bool bDefenseMove, bool bDefenseRoate )
{
	m_bDefenseMoveEnable = bDefenseMove;
	m_bDefenseMoveRotate = bDefenseRoate;
}

void ioBaseChar::SetReloadMoveEnable( bool bReloadMove )
{
	m_bReloadMoveEnable = bReloadMove;
}

void ioBaseChar::SetAttackMoveEnable( bool bAttackMove )
{
	m_bAttackMoveEnable = bAttackMove;

	if( bAttackMove )
	{
		ioAttackableItem *pItem = GetPriorityItem( SPT_ATTACK );
		bool bBowRoateMove = false;
		if( !IsJumpState() && ToBowItem(pItem) && ToBowItem(pItem)->IsChargeRotate() )
			bBowRoateMove = true;

		if( !IsJumpState() && ToBowItem2(pItem) && ToBowItem2(pItem)->IsChargeRotate() )
			bBowRoateMove = true;

		if( !IsJumpState() && ToRobinExpansionItem(pItem) && ToRobinExpansionItem(pItem)->IsChargeRotate() )
			bBowRoateMove = true;

		if( !IsJumpState() && ToSuddenAttackItem(pItem) && ToSuddenAttackItem(pItem)->IsChargeRotate() )
			bBowRoateMove = true;

		bool bRunChargeRoateMove = false;
		if( !IsJumpState() && ToRunChargeItem(pItem) && ToRunChargeItem(pItem)->IsChargeRotate() )
			bRunChargeRoateMove = true;

		bool bRunChargeRoateMove2 = false;
		if( !IsJumpState() && ToRunChargeItem2(pItem) && ToRunChargeItem2(pItem)->IsChargeRotate() )
			bRunChargeRoateMove2 = true;

		if( (ToBowItem(pItem) && !bBowRoateMove) ||
			(ToBowItem2(pItem) && !bBowRoateMove) ||
			(ToRobinExpansionItem(pItem) && !bBowRoateMove) ||
			(ToSuddenAttackItem(pItem) && !bBowRoateMove) ||
			(ToRunChargeItem(pItem) && !bRunChargeRoateMove) ||
			(ToRunChargeItem2(pItem) && !bRunChargeRoateMove2) ||
			(ToChargeShotItem(pItem) && !ToChargeShotItem(pItem)->IsChargeRotate()) ||
			(ToLinearChargeItem(pItem) && !ToLinearChargeItem(pItem)->IsChargeRotate()) ||
			(ToPowerChargeItem4(pItem) && !ToPowerChargeItem4(pItem)->IsChargeRotate()) ||
			ToRangeChargeItem(pItem) ||
			ToAutoShotItem(pItem) || 
			ToChargeComboBowItem(pItem) ||
			ToWestGunExtendItem(pItem) ||
			ToVulcanItem(pItem) ||
			ToLillyItem(pItem) )
		{
			ChangeDirectionByInputDir( true );
		}
		else
		{
			ChangeDirectionByInputDir( false );
		}
	}
}

void ioBaseChar::SetSkillMoveEnable( bool bSkillMove, bool bChangeDir )
{
	m_bSkillMoveEnable = bSkillMove;
	m_bSkillMoveChangeDir = bChangeDir;

	if( bSkillMove )
	{
		ChangeDirectionByInputDir( !m_bSkillMoveChangeDir );
	}
}

bool ioBaseChar::IsActionStop() const
{
	if( m_dwActionStopCurDelay > 0 )
		return true;

	return false;
}

void ioBaseChar::InitActionStopDelay( bool bAll )
{
	m_dwActionStopTotalDelay = 0;

	if( bAll )
	{
		m_dwActionStopCurAdd = 0;
		m_dwActionStopCurDelay = 0;
	}
}

void ioBaseChar::SetActionStopDelay( float fDamage, bool bDie, int iShakeCamera )
{
	if( IsOwnerChar() && iShakeCamera != 0 )
	{
		g_ShakeCameraMgr.SetShakeCamera( iShakeCamera );
	}

	if( !IsEnableActionStopDelay() )
		return;

	DWORD dwDuration = CalcActionStopDelay( fDamage, bDie );

	m_dwActionStopCurAdd = 0;
	m_dwActionStopCurDelay = dwDuration;
}

DWORD ioBaseChar::CalcActionStopDelay( float fDamage, bool bDie )
{
	if( !bDie )
	{
		return m_dwActionStopDefaultDelay + (DWORD)(fDamage * m_fActionStopDelayRate );
	}

	return m_dwActionStopDieDefaultDelay + (DWORD)( fDamage * m_fActionStopDelayRate );
}

float ioBaseChar::GetActionStopLooseRate( bool bDie )
{
	if( !bDie )
	{
		return m_fActionStopLooseRate;
	}

	return m_fActionStopDieLooseRate;
}

float ioBaseChar::GetRunDashAniRate() const
{
	float fAverageSpeed = g_StatAttribute.GetAverageMoveSpeed(m_fDefaultSpeed);
	float fDefaultRate = fAverageSpeed / m_fDefaultSpeed;
	float fMaxSpeed = GetMaxSpeed();
	float fCurRate = fMaxSpeed / m_fDefaultSpeed;

	if( fCurRate == 0.0f || fDefaultRate == 0.0f )
		return 0.0f;

	return fCurRate / fDefaultRate;
}

bool ioBaseChar::IsSettedDirection() const
{
	return m_KeyInput.IsSettedDirection();
}

bool ioBaseChar::IsChangeDirection()
{
	if( m_bChangeDirection )
	{
		m_bChangeDirection = false;
		return true;
	}

	return m_KeyInput.IsChangeDirection();
}

void ioBaseChar::ChangeDirection()
{
	if( !m_bChangeDirection )
		m_bChangeDirection = true;
}

