	if( rkRestore.IsEmpty() )	return;
	if( !m_pGroup || !m_pGroup->HasSkeleton() ) return;
	if( m_iEtcItemSkeleton != 0 ) return; // 권한 아이템으로 교체된 본은 바꾸지 않는다.
	
