void ioBaseChar::RemoveKingScaleRate( float fRate )
{
	float fNewRate;

	fNewRate = m_fKingScaleRate - FLOAT1;
	fNewRate -= (fRate - FLOAT1);
	fNewRate = max( -FLOAT1, fNewRate );
	fNewRate = min( fNewRate+1.0f, m_fMaxScaleRate );
	m_fKingScaleRate = fNewRate;

	RecalcStatusValue();

	//아이템쪽에 알린다.
	ioAttackableItem *pItem = GetPriorityItem( SPT_ATTACK );
	ioSuperDimensionItem* pSuperDimensionItem = ToSuperDimensionItem( pItem );
	if( pSuperDimensionItem )
		pSuperDimensionItem->RemoveCharScale( fRate, this );
}

void ioBaseChar::SetExtraMoveSpeed( float fExtraSpeed, float fExtraDashSpeedRate )
{
	if( fExtraSpeed == 0.0f )
		return;

	m_fTotalExtraMoveSpeed += fExtraSpeed;

	m_fExtraMoveSpeed = m_fTotalExtraMoveSpeed;
	m_fExtraMoveSpeed = max( m_fMinExtraSpeed, m_fExtraMoveSpeed );
	m_fExtraMoveSpeed = min( m_fExtraMoveSpeed, m_fMaxExtraSpeed );

	m_fExtraDashSpeedRate = fExtraDashSpeedRate;

	if( m_CharState == CS_DELAY )
		SetState( CS_DELAY );
	else if( m_CharState == CS_RUN )
		SetState( CS_RUN );
	else if( m_CharState == CS_DASH )
		SetState( CS_DASH );
	else if( m_CharState == CS_EXTEND_DASH )
		CheckRefreshExtendDashState();
}

void ioBaseChar::RemoveExtraMoveSpeed( float fExtraSpeed )
{
	if( fExtraSpeed == 0.0f )
		return;

	m_fTotalExtraMoveSpeed -= fExtraSpeed;

	m_fExtraMoveSpeed = m_fTotalExtraMoveSpeed;
	m_fExtraMoveSpeed = max( m_fMinExtraSpeed, m_fExtraMoveSpeed );
	m_fExtraMoveSpeed = min( m_fExtraMoveSpeed, m_fMaxExtraSpeed );

	m_fExtraDashSpeedRate = FLOAT1;
}

void ioBaseChar::ModifyWoundRate( AttackRateList &vWoundedRateList, AttackSide iSide )
{
	int iCnt = vWoundedRateList.size();
	for( int i=0; i < iCnt; i++ )
	{
		bool bAdd = true;
		int iListCnt = m_WoundedRateList.size();
		for( int j=0; j < iListCnt; j++ )
		{
			if( m_WoundedRateList[j].iType != vWoundedRateList[i].iType )
				continue;

			// Normal
			float fRate;
			float fGap = m_WoundedRateList[j].fRate;

			fRate = m_WoundedRateList[j].fRate + vWoundedRateList[i].fRate - 2.0f;
			fRate = max( -FLOAT1, fRate );
			fRate = min( fRate+1.0f, m_fMaxWoundedRate );
			m_WoundedRateList[j].fRate = fRate;

			fGap = FLOAT1 + fRate - fGap;
			vWoundedRateList[i].fRate = fGap;

			// Skill
			float fSkillRate;
			float fSkillGap = m_WoundedRateList[j].fSkillRate;

			fSkillRate = m_WoundedRateList[j].fSkillRate + vWoundedRateList[i].fSkillRate - 2.0f;
			fSkillRate = max( -FLOAT1, fSkillRate );
			fSkillRate = min( fSkillRate+1.0f, m_fMaxWoundedRate );
			m_WoundedRateList[j].fSkillRate = fSkillRate;

			fSkillGap = FLOAT1 + fSkillRate - fSkillGap;
			vWoundedRateList[i].fSkillRate = fSkillGap;
			m_WoundedRateList[j].szBuff = vWoundedRateList[i].szBuff;
			bAdd = false;
		}

		if( bAdd )
		{
			m_WoundedRateList.push_back( vWoundedRateList[i] );
		}
	}

	m_WoundedRateSideType = iSide;
}

void ioBaseChar::RemoveWoundRate( const AttackRateList &vWoundedRateList )
{
	if( m_WoundedRateList.empty() )
		return;

	int iCnt = vWoundedRateList.size();
	for( int i=0; i < iCnt; i++ )
	{
		int iListCnt = m_WoundedRateList.size();
		for( int j=0; j < iListCnt; j++ )
		{
			if( m_WoundedRateList[j].iType != vWoundedRateList[i].iType )
				continue;

			// Normal
			float fRate;
			fRate = m_WoundedRateList[j].fRate - FLOAT1;
			fRate -= vWoundedRateList[i].fRate - FLOAT1;
			fRate = max( -FLOAT1, fRate );
			fRate = FLOAT1 + fRate;

			m_WoundedRateList[j].fRate = min( fRate, m_fMaxWoundedRate );

			// Skill
			float fSkillRate;
			fSkillRate = m_WoundedRateList[j].fSkillRate - FLOAT1;
			fSkillRate -= vWoundedRateList[i].fSkillRate - FLOAT1;
			fSkillRate = max( -FLOAT1, fSkillRate );
			fSkillRate = FLOAT1 + fSkillRate;

			m_WoundedRateList[j].fSkillRate = min( fSkillRate, m_fMaxWoundedRate );
			m_WoundedRateList[j].szBuff = "";   // 자동 버프 제거
		}
	}
}

void ioBaseChar::ModifyDamageRate( AttackRateList &vAttackRateList )
{
	bool bAdd;

	int iCnt = vAttackRateList.size();
	for( int i=0; i < iCnt; i++ )
	{
		bAdd = true;
		int iListCnt = m_AttackRateList.size();
		for( int j=0; j < iListCnt; j++ )
		{
			if( m_AttackRateList[j].iType != vAttackRateList[i].iType )
				continue;

			float fRate;
			float fGap = m_AttackRateList[j].fRate;

			fRate = m_AttackRateList[j].fRate + vAttackRateList[i].fRate - 2.0f;
			fRate = max( -FLOAT1, fRate );
			fRate = min( fRate+1.0f, m_fMaxDamageRate );
			m_AttackRateList[j].fRate = fRate;

			fGap = FLOAT1 + fRate - fGap;
			vAttackRateList[i].fRate = fGap;
			bAdd = false;
		}
		
		if( bAdd )
		{
			m_AttackRateList.push_back( vAttackRateList[i] );
		}
	}
}

void ioBaseChar::RemoveDamageRate( const AttackRateList &vAttackRateList )
{
	if( m_AttackRateList.empty() )
		return;

	int iCount = vAttackRateList.size();
	for( int i=0; i < iCount; i++ )
	{
		int iListCnt = m_AttackRateList.size();
		for( int j=0; j < iListCnt; j++ )
		{
			if( m_AttackRateList[j].iType != vAttackRateList[i].iType )
				continue;

			float fRate;
			fRate = m_AttackRateList[j].fRate - FLOAT1;
			fRate -= vAttackRateList[i].fRate - FLOAT1;
			fRate = max( -FLOAT1, fRate );
			fRate = FLOAT1 + fRate;
			m_AttackRateList[j].fRate = min( fRate, m_fMaxDamageRate );
		}
	}
}

void ioBaseChar::ModifyNPCDamageRate( AttackRateList &vAttackRateList )
{
	bool bAdd;

	int iCnt = vAttackRateList.size();
	for( int i=0; i < iCnt; i++ )
	{
		bAdd = true;
		int iListCnt = m_AttackRateNPCList.size();
		for( int j=0; j < iListCnt; j++ )
		{
			if( m_AttackRateNPCList[j].iType != vAttackRateList[i].iType )
				continue;

			float fRate;
			float fGap = m_AttackRateNPCList[j].fRate;

			fRate = m_AttackRateNPCList[j].fRate + vAttackRateList[i].fRate - 2.0f;
			fRate = max( -FLOAT1, fRate );
			fRate = min( fRate+1.0f, m_fMaxDamageRate );
			m_AttackRateNPCList[j].fRate = fRate;

			fGap = FLOAT1 + fRate - fGap;
			vAttackRateList[i].fRate = fGap;
			bAdd = false;
		}

		if( bAdd )
		{
			m_AttackRateNPCList.push_back( vAttackRateList[i] );
		}
	}
}

void ioBaseChar::RemoveNPCDamageRate( const AttackRateList &vAttackRateList )
{
	if( m_AttackRateNPCList.empty() )
		return;

	int iCount = vAttackRateList.size();
	for( int i=0; i < iCount; i++ )
	{
		int iListCnt = m_AttackRateNPCList.size();
		for( int j=0; j < iListCnt; j++ )
		{
			if( m_AttackRateNPCList[j].iType != vAttackRateList[i].iType )
				continue;

			float fRate;
			fRate = m_AttackRateNPCList[j].fRate - FLOAT1;
			fRate -= vAttackRateList[i].fRate - FLOAT1;
			fRate = max( -FLOAT1, fRate );
			fRate = FLOAT1 + fRate;
			m_AttackRateNPCList[j].fRate = min( fRate, m_fMaxDamageRate );
		}
	}
}

