void ioBaseChar::SetBuffCamera( const ioHashString &szName, int iCamType, float fDistance, float fHeight, float fFov, DWORD dwZoomTime, bool bPriority )
{
	m_fBuffCamDistance = fDistance;
	m_fBuffCamHeight = fHeight;
	m_fBuffCamFov = fFov;
	m_dwBuffCamZoomTime = dwZoomTime;
	m_bPriorityOverSkill = bPriority;

	m_iCameraTypeByBuff = iCamType;

	if( m_iCameraTypeByBuff == CT_BUFF )
	{
		m_bSetNewCamBuff = true;
	}

	BuffCameraInfo kInfo;
	kInfo.m_BuffName = szName;
	kInfo.m_iBuffCamType = iCamType;
	kInfo.m_fBuffCamDistance = fDistance;
	kInfo.m_fBuffCamHeight = fHeight;
	kInfo.m_fBuffCamFov = fFov;
	kInfo.m_dwBuffCamZoomTime = dwZoomTime;
	kInfo.m_bPriorityOverSkill = bPriority;

	m_BuffCamInfoList.push_back( kInfo );
}

void ioBaseChar::GetBuffCamera( float &fDistance, float &fHeight, float &fFov, DWORD &dwZoomTime )
{
	fDistance = m_fBuffCamDistance;
	fHeight = m_fBuffCamHeight;
	fFov = m_fBuffCamFov;

	if( CheckCameraType() == CT_BUFF )
		dwZoomTime = m_dwBuffCamZoomTime;
	else
		dwZoomTime = GetCamZoomTime();
}

void ioBaseChar::SetBuffCameraEnd( const ioHashString &szName )
{
	BuffCamInfoList::iterator iter = m_BuffCamInfoList.begin();

	while( iter != m_BuffCamInfoList.end() )
	{
		if( (*iter).m_BuffName == szName )
		{
			m_BuffCamInfoList.erase( iter );
			break;
		}

		++iter;
	}

	if( m_BuffCamInfoList.empty() )
	{
		m_iCameraTypeByBuff = CT_DEFAULT;
	}
	else
	{
		BuffCameraInfo kInfo = m_BuffCamInfoList.back();

		m_fBuffCamDistance = kInfo.m_fBuffCamDistance;
		m_fBuffCamHeight = kInfo.m_fBuffCamHeight;
		m_fBuffCamFov = kInfo.m_fBuffCamFov;
		m_dwBuffCamZoomTime = kInfo.m_dwBuffCamZoomTime;
		m_bPriorityOverSkill = kInfo.m_bPriorityOverSkill;

		m_iCameraTypeByBuff = kInfo.m_iBuffCamType;

		if( m_iCameraTypeByBuff == CT_BUFF )
		{
			m_bSetNewCamBuff = true;
		}
	}
}

bool ioBaseChar::CheckBuffKillException( ioBuff *pBuff )
{
	bool bSuccess = false;

	const ioHashStringVec &eExceptList = pBuff->GetExceptKillingList();
	ioHashStringVec::const_iterator iter;

	for( iter=eExceptList.begin() ; iter!=eExceptList.end() ; ++iter )
	{
		if( RemoveBuff( *iter, false ) )
		{
			bSuccess = true;
		}
	}

	return bSuccess;
}

bool ioBaseChar::CheckBuffSuicideExcetion( ioBuff *pBuff )
{
	const ioHashStringVec &eExceptList = pBuff->GetExceptSuicideList();

	ioHashStringVec::const_iterator iter;
	for( iter=eExceptList.begin() ; iter!=eExceptList.end() ; ++iter )
	{
		for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
		{
			ioBuff *pTargetBuff = m_aBuffArray->GetAt(i);
			if( !pTargetBuff ) continue;

			if( pTargetBuff->GetName() == (*iter) )
			{
				return true;
			}
		}
	}

	return false;
}

bool ioBaseChar::CheckBuffRemoveByType( ioBuff *pBuff )
{
	IntVec::const_iterator iter;
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pOriginBuff = m_aBuffArray->GetAt(i);
		if( !pOriginBuff ) continue;

		const IntVec &eRemoveList = pOriginBuff->GetRemoveByTypeList();

		for( iter = eRemoveList.begin(); iter != eRemoveList.end(); ++iter )
		{
			if( pBuff->GetTypeID() == *iter )
			{
				pOriginBuff->PlayPassiveBuffEffect();

				if( IsNeedProcess() && P2PNetwork::IsNetworkPlaying() )
				{
					SP2Packet kPacket( CUPK_PREVENT_TARGET_BUFF );
					kPacket << GetCharName();
					kPacket << pOriginBuff->GetName();
					P2PNetwork::SendToAllPlayingUser( kPacket );
				}
				return true;
			}
		}
	}

	return false;
}

void ioBaseChar::SetCameraTypeByBuff( int iType )
{
	m_iCameraTypeByBuff = iType;

	if( m_iCameraTypeByBuff == CT_BUFF )
	{
		m_bSetNewCamBuff = true;
	}
}

int ioBaseChar::CheckCameraType()
{
	int iType = CT_DEFAULT;
	CharState eState = GetState();

	if( eState == CS_USING_SKILL )
	{
		if( m_iCameraTypeByBuff != CT_DEFAULT && m_bPriorityOverSkill )
			iType = m_iCameraTypeByBuff;
		else
			iType = CT_SKILL;
	}
	else if( m_iCameraTypeByBuff != CT_DEFAULT )
		iType = m_iCameraTypeByBuff;
	else if( m_bChargingState )
		iType = CT_EXTEND;
	else if( eState == CS_RUN || eState == CS_DASH || eState == CS_JUMP || eState == CS_EXTEND_DASH )
		iType = CT_RUNDASH;

	return iType;
}

int ioBaseChar::CheckCameraType( bool &bCamState )
{
	if( m_bSetNewCamBuff )
	{
		m_bSetNewCamBuff = false;
		bCamState = false;
	}

	return CheckCameraType();
}

int ioBaseChar::GetEquipItemCnt()
{
	if( m_pEquipSlot )
		return m_pEquipSlot->GetEquipedItemCnt();

	return 0;
}

void ioBaseChar::SetMineInfo( SP2Packet &rkPacket )
{
	int iMineCnt = 0;
	rkPacket >> iMineCnt;

	for( int i=0; i < iMineCnt; ++i )
	{
		int iAttributeIndex, iResistanceIndex;
		DWORD dwWeaponIndex;
		int iAniCollisionType;
		D3DXVECTOR3 vStartPos;
		DWORD dwGapTime;
		int nUniqID;

		ioHashString szCreateItem;

		rkPacket >> iAttributeIndex >> iResistanceIndex;
		rkPacket >> szCreateItem;
		rkPacket >> dwWeaponIndex >> iAniCollisionType;
		rkPacket >> vStartPos;
		rkPacket >> dwGapTime;
		rkPacket >> nUniqID;

		ioWeapon *pWeapon = g_WeaponMgr.CreateWeapon( iAttributeIndex, this );
		if( !pWeapon ) continue;

		pWeapon->InitResource();

		float fDamageRate = GetAttackDamageRate( pWeapon );
		switch( pWeapon->GetStatType() )
		{
		case ATT_STAT_STR:
			fDamageRate = g_StatAttribute.GetCalcStatAttribute( fDamageRate, SA_STR_DAMAGE_UP, this );
			break;
		case ATT_STAT_DEX:
			fDamageRate = g_StatAttribute.GetCalcStatAttribute( fDamageRate, SA_DEX_DAMAGE_UP, this );
			break;
		case ATT_STAT_INT:
			fDamageRate = g_StatAttribute.GetCalcStatAttribute( fDamageRate, SA_INT_DAMAGE_UP, this );
			break;
		}

		float fNPCDamageRate = GetAttackNPCDamageRate( pWeapon );
		switch( pWeapon->GetStatType() )
		{
		case ATT_STAT_STR:
			fNPCDamageRate = g_StatAttribute.GetCalcStatAttribute( fNPCDamageRate, SA_STR_DAMAGE_UP, this );
			break;
		case ATT_STAT_DEX:
			fNPCDamageRate = g_StatAttribute.GetCalcStatAttribute( fNPCDamageRate, SA_DEX_DAMAGE_UP, this );
			break;
		case ATT_STAT_INT:
			fNPCDamageRate = g_StatAttribute.GetCalcStatAttribute( fNPCDamageRate, SA_INT_DAMAGE_UP, this );
			break;
		}
		
		pWeapon->SetCreateItem( szCreateItem );
		pWeapon->SetOwnerDamageRate( fDamageRate, fNPCDamageRate );
		pWeapon->SetGameOwnerWeapon( m_bOwnerChar );
		pWeapon->SetWeaponIndex( dwWeaponIndex );
		pWeapon->SetAniCollisionType( (AniCollisionType)iAniCollisionType );
		pWeapon->SetTeam( m_pCreator, GetTeam() );
		pWeapon->SetUniqID( nUniqID );

		if( m_pPushPowerEnhance )
		{
			pWeapon->EnhancePushPower( m_pPushPowerEnhance->GetEnhanceRate( EOT_PUSH ),
									   m_pPushPowerEnhance->GetEnhanceRate( EOT_BLOW ),
									   m_pPushPowerEnhance->GetEnhanceRate( EOT_AIR_PUSH ),
									   m_pPushPowerEnhance->GetEnhanceRate( EOT_AIR_BLOW ) );
		}

		pWeapon->SetStartCollisionBox();
		vStartPos.y += FLOAT1;
		pWeapon->SetStartPosition( vStartPos, m_pCreator );

		pWeapon->PlayLoopSound();

		if( iResistanceIndex > 0 )
			pWeapon->SetResistanceAttr( iResistanceIndex );

		ioMineWeapon	*pMine	= ToMineWeapon( pWeapon );
		ioMineWeapon2	*pMine2 = ToMineWeapon2( pWeapon );
		ioMineWeapon3	*pMine3 = ToMineWeapon3( pWeapon );
		ioMineWeapon4	*pMine4 = ToMineWeapon4( pWeapon );
		ioMineWeapon6	*pMine6 = ToMineWeapon6( pWeapon );
		if( !pMine && !pMine2 && !pMine3 && !pMine4 && !pMine6 ) 
			return;

		DWORD dwSensingStartTime = 0;
		DWORD dwCurTime = FRAMEGETTIME();
		
		if( dwCurTime > dwGapTime )
			dwSensingStartTime = dwCurTime - dwGapTime;

		if( pMine )
			pMine->SetSensingStartTime( dwSensingStartTime );
		else if( pMine2 )
			pMine2->SetSensingStartTime( dwSensingStartTime );
		else if( pMine4 )
			pMine4->SetSensingStartTime( dwSensingStartTime );
		else if( pMine6 )
			pMine6->SetSensingStartTime( dwSensingStartTime );
	}
}

