	if( IsNeedSendNetwork() )
	{
		SP2Packet kPacket( CUPK_EMOTICON_SYNC );
		kPacket << m_Name;
		kPacket << EMOTICON_COIN_EVENT;
		P2PNetwork::SendToAllPlayingUser( kPacket );
	}

	if( !IsOwnerChar() )
		g_SoundMgr.PlaySound( m_CoinEventSound );
