bool ioBaseChar::CheckAndSetNetworkBadEmoticon( int iServerDelayMS )
{
	if( !m_bOwnerChar )
		return false;

	if( iServerDelayMS >= m_iNetworkBadMS )
		m_cNetworkBad++;
	else
		m_cNetworkBad = 0;

	if( m_cNetworkBad < m_iMaxNetworkBad )
		return false;
	m_cNetworkBad = 0;

	switch( m_CharState )
	{
	case CS_ENDMOTION:
	case CS_READY:
	case CS_VIEW:
	case CS_OBSERVER:
	case CS_STARTMOTION:
	case CS_CREATEMOTION:
	case CS_LOADING:
	case CS_COIN_REBIRTH:
	case CS_CHANGE_GANGSI:
	case CS_GRADEUP_MOTION:
		return false;
	}

	// 결과 중에는 표기하지 않는다.
	if( m_pModeParent && 
		m_pModeParent->GetModeState() == ioPlayMode::MS_RESULT ) 
	{
		return false;
	}

	SetNetworkBadEmoticon();
	return true;
}

void ioBaseChar::SetNoInputEmoticon( DWORD dwDuration )
{
	const ioHashString *szIcon = g_ModeHelpMgr.GetIconName( ioModeHelpManager::HT_NO_INPUT );
	const vHelpText *pHelpList = g_ModeHelpMgr.GetHelpText( ioModeHelpManager::HT_NO_INPUT );
	if( !pHelpList || !szIcon )
	{
		LOG.PrintTimeAndLog( 0, "ioBaseChar::SetNoInputEmoticon() Emoticon is Not Exist" );
		return;
	}

	if( pHelpList->empty() ) 
		return;

	const HelpText &rkText = (*pHelpList->begin());

	ioHashString szDesc = rkText.m_szHelp;
	DWORD dwColor = rkText.m_dwColor;

	SetNamedEmoticon( *szIcon, szDesc, dwColor, dwDuration );

	if( IsNeedSendNetwork() )
	{
		if( m_dwNoInputDelayEndTime == 0 )
		{
			SP2Packet kPacket( CUPK_EMOTICON_SYNC );
			kPacket << m_Name;
			kPacket << EMOTICON_NO_INPUT;
			kPacket << dwDuration;
			P2PNetwork::SendToAllPlayingUser( kPacket );
		}
	}
	if( GetState() == CS_BLOW_WOUNDED )
	{
		SetState( CS_DELAY );
	}
}

void ioBaseChar::SetChangeMotion( bool bEnable, const ioHashString& szDelayAni, const ioHashString &szMoveAni )
{
	if( bEnable )
	{
		m_bChangeMotion = true;
		if( !szDelayAni.IsEmpty() )
			m_ChangeDelayAni = szDelayAni;

		if( !szMoveAni.IsEmpty() )
			m_ChangeMoveAni = szMoveAni;
	}
	else
	{
		m_bChangeMotion = false;
		m_ChangeDelayAni.Clear();
		m_ChangeMoveAni.Clear();
	}
}

void ioBaseChar::SetChangeJumpMotion( bool bEnable,
									  const ioHashString& szReadyAni,
									  const ioHashString& szJumpAni,
									  const ioHashString& szEndAni,
									  float fEndAniRate )
{
	if( bEnable )
	{
		m_bChangeMotion = true;
		if( !szReadyAni.IsEmpty() )
			m_ChangeJumpReadyAni = szReadyAni;

		if( !szJumpAni.IsEmpty() )
			m_ChangeJumppingAni = szJumpAni;

		if( !szEndAni.IsEmpty() )
			m_ChangeJumpEndAni = szEndAni;

		if( fEndAniRate != 0.0f )
			m_fChangeJumpEndAniRate = fEndAniRate;
	}
	else
	{
		m_bChangeMotion = false;
		m_ChangeJumpReadyAni.Clear();
		m_ChangeJumppingAni.Clear();
		m_ChangeJumpEndAni.Clear();

		m_fChangeJumpEndAniRate = 0.0f;
	}
}

void ioBaseChar::SetEnableHide( bool bEnable, ioHashString szDelayAni, ioHashString szMoveAni )
{
	m_bEnableHide = bEnable;

	if( bEnable )
	{
		m_HideDelayAni = szDelayAni;
		m_HideMoveAni = szMoveAni;
	}
	else
	{
		m_HideDelayAni.Clear();
		m_HideMoveAni.Clear();
	}
}

bool ioBaseChar::IsCanHide()
{
	if( m_CharState == CS_DELAY ||
		m_CharState == CS_RUN ||
		m_CharState == CS_DEFENSE ||
		m_CharState == CS_FALL ||
		m_CharState == CS_WEREWOLF ||
		m_CharState	== CS_OBJECT_EQUIP )
	{
		return true;
	}

	if( m_CharState == CS_JUMP && m_bEnableHide )
		return true;

	if( m_pActiveSkill && m_CharState == CS_USING_SKILL )
	{
		ioBuffSkill *pBuffSkill = ToBuffSkill(m_pActiveSkill);
		if( pBuffSkill && pBuffSkill->HasBuff(BT_HIDE) )
			return true;

		ioAngleFire5Skill *pAngleFire5Skill = ToAngleFire5Skill(m_pActiveSkill);
		if( pAngleFire5Skill )
			return true;
	}

	if( HasBuff(BT_HIDE) && m_CharState == CS_DASH && m_bEnableDashOnHideBuff )
		return true;

	return false;
}

bool ioBaseChar::IsCanLimitMove( const ioHashString &szBuffName )
{
	if( m_CharState == CS_DELAY || m_CharState == CS_RUN )
		return true;

	if( m_CharState == CS_JUMP && m_bChangeMotion )
		return true;

	if( m_pActiveSkill && m_CharState == CS_USING_SKILL )
	{
		ioBuffSkill *pBuffSkill = ToBuffSkill(m_pActiveSkill);
		if( pBuffSkill && pBuffSkill->HasBuff(BT_LIMIT_MOVE) && pBuffSkill->HasOwnerBuff(szBuffName) )
			return true;
	}

	return false;
}

void ioBaseChar::SetNoWoundState( bool bNoWound )
{
	m_bNoWoundState = bNoWound;
}

void ioBaseChar::SetInvisibleState( bool bInvisible, bool bNow, bool bINvisiblePass )
{
	m_bInvisibleState = bInvisible;

	if( bInvisible && bNow )
		m_bInvisibleNowState = true;
	else if( !bInvisible && bNow )
		m_bInvisibleNowState = false;

	if( bNow )
		m_pGroup->SetVisibleNow( !m_bInvisibleState, bINvisiblePass );
	else
		m_pGroup->SetVisible( !m_bInvisibleState );

	// 2013.01.31 악어가 웨어울프 먹었을때 보완 위한것
	if( !m_bInvisibleState && m_bInvisibleNowState )
	{
		ClearAllEquipEffect();
	}
	else if( !m_bInvisibleState && !m_bInvisibleNowState && bNow )
	{
		RestoreAllEquipEffect();
	}

	if ( !GetObject() )
	{
		if( bInvisible == false && m_pEquipSlot )
		{
			ioHelmetItem *pHelmet = m_pEquipSlot->GetHelmet();
			if( pHelmet )
				pHelmet->ReCalcVisible(this);
		}
	}
}

bool ioBaseChar::IsCanInvisible()
{
	return m_bInvisibleState;
}

bool ioBaseChar::IsCanNoWound()
{
	if( !m_bNoWoundState )
		return false;

	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioNoWoundBuff *pNoWoundBuff = ToNoWoundBuff( pBuff );
		if( pNoWoundBuff )
		{
			if( pNoWoundBuff->EnableBuffCheck( this ) )
				return true;

			if( pNoWoundBuff->DisableBuffCheck( this ) )
				return false;
		}
	}

	if( m_CharState == CS_RUN ||
		m_CharState == CS_FALL ||
		m_CharState == CS_JUMP ||
		m_CharState == CS_DASH ||
		m_CharState == CS_DELAY ||
		m_CharState == CS_DEFENSE ||
		m_CharState == CS_EXTEND_DASH ||
		m_CharState == CS_LOCKUP_BUFF )
	{
		return true;
	}

	ioFlyingTeleportSkill *pFlyingTeleportSkill = ToFlyingTeleportSkill( m_pActiveSkill );
	if( pFlyingTeleportSkill )
	{
		return true;
	}
	ioMultiLightAttack* pMultiLightAttack = ToMultiLightAttack( m_pActiveSkill );
	if( pMultiLightAttack )
	{
		return true;
	}
	ioLightAttack* pLightAttack = ToLightAttack( m_pActiveSkill );
	if( pLightAttack )
	{
		return true;
	}

	if( m_pActiveSkill && m_CharState == CS_USING_SKILL )
	{
		ioBuffSkill *pBuffSkill = ToBuffSkill(m_pActiveSkill);
		if( pBuffSkill )
		{
			if( pBuffSkill->HasBuff(BT_NOWOUND) )
				return true;
			if( pBuffSkill->HasBuff(BT_CREATE_DUMMY_CHAR) )
				return true;
		}
	}

	if( m_pCharSpeicalState && m_pCharSpeicalState->IsCanNoWound( this ) )
		return true;

	return false;
}

