bool ioBaseChar::IsEnableDashState()
{
	ioObjectItem *pObject = GetObject();
	if( pObject && !pObject->IsEnableDash() )
		return false;

	if( IsBuffLimitDash() )
		return false;

	bool bResult = true;
	if( m_CharState == CS_DELAY				||
		m_CharState == CS_RUN				||
		m_CharState == CS_SPECIAL_MOTION	||
		m_CharState == CS_ETCITEM_MOTION	||
		m_CharState == CS_NOT_MOVE_PROTECT	||
		m_CharState == CS_LUCIFER_FLY		||
		m_CharState == CS_NANGIN_SPECIAL	||
		m_CharState == CS_DRUID_EAGLE_FLY	||
		m_CharState == CS_MEGA_AGENT_FLY	||
		m_CharState == CS_SABER_ATTACK		||
		m_CharState == CS_SANTA_SPECIAL		||
		m_CharState == CS_WITCH_FLY			||
		m_CharState == CS_CHANGE_ON_GRIFFIN_FLY ||
		m_CharState == CS_GHOST_FLY			||
		m_CharState == CS_MIDNIGHT_SPECIAL	)
	{
		DWORD dwDashFailDuration = m_dwDashFailStartTime + m_dwDashFailDuration;
		
		if( m_bExceptionDashFail )
		{
			if( m_dwDashFailStartTime <= 0 || dwDashFailDuration < FRAMEGETTIME() )
			{
				m_dwDashFailStartTime = 0;
				m_bExceptionDashFail = false;
			}
			else
			{
				bResult = false;
			}
		}
		else
		{
			if( m_dwDashFailStartTime > 0 )
			{
				m_bExceptionDashFail = true;
				bResult = false;
			}
		}
	}
	else
	{
		if( m_CharState == CS_DEFENSE )
		{
			ioAttackableItem *pItem = GetPriorityItem( SPT_ATTACK );
			ioFireWeaponItem *pFireItem = ToFireWeaponItem( pItem);
			if( pFireItem && pFireItem->IsDefenseDashEnable() )
				return bResult;

			ioExcaliburItem *pExcalibur = ToExcaliburItem( pItem );
			if( pExcalibur && pExcalibur->IsDefenseDashEnable() )
				return bResult;

			ioGhostItem *pGhostItem = ToGhostItem( pItem );
			if( pGhostItem && pGhostItem->IsDefenseDashEnable() )
				return bResult;

			ioHanzoItem *pHanzoItem = ToHanzoItem( pItem );
			if( pHanzoItem )
				return bResult;
		}
		if( m_dwDashFailStartTime != 0 )
			m_dwDashFailStartTime = 0;

		m_bExceptionDashFail = false;
		bResult = false;
	}

	return bResult;
}

void ioBaseChar::SetDashFailStart()
{
	m_dwDashFailStartTime = FRAMEGETTIME();
}

void ioBaseChar::ResetRealComboHit( const ioHashString &rkName )
{
	RealComboVec::iterator iter = m_RealComboList.begin();
	for(;iter != m_RealComboList.end();iter++)
	{
		RealCombo &rkCombo = *iter;
		if( rkCombo.m_iRealComboCnt <= 0 ) continue;

		if( rkCombo.m_szCharName == rkName )
		{
			if( m_pModeParent && m_pModeParent->GetModeType() != MT_FOOTBALL )
				g_AwardMgr.AddCombo( GetCharName(), rkCombo.m_iRealComboCnt );
			rkCombo.m_iRealComboCnt = 0;
			break;
		}
	}
}

bool ioBaseChar::CheckComboSkillHit()
{
	DWORD dwCurTime = FRAMEGETTIME();
	if( dwCurTime < m_dwCurSkillCombo )
		m_iSkillComboCnt++;
	else
	{
		if( m_iSkillComboCnt >= m_iSkillComboViewCnt)
		{
			if( m_pModeParent && m_pModeParent->GetModeType() != MT_FOOTBALL )
				g_AwardMgr.AddCombo( GetCharName(), m_iSkillComboCnt );
		}

		m_iSkillComboCnt = 1;
	}
	m_dwCurSkillCombo = dwCurTime + m_dwSkillComboTime;

	// 퀘스트
	if( IsOwnerChar() )
	{
		g_QuestMgr.QuestCompleteTerm( QC_ATTACK_HIT );
	}

	if( IsOnlyMyEmoticon() && !IsOwnerChar() ) return false;      // 콤보킹 시상을 위함.

	if( m_iSkillComboCnt > m_iSkillComboViewCnt || ( IsOwnerChar() && m_iSkillComboCnt == m_iSkillComboViewCnt ) )
	{
		ioHashString szComboIcon;
		switch( GetTeam() )
		{
		case TEAM_BLUE:
			{
				int iComboIndex = m_iSkillComboCnt - 1;
				if ( COMPARE( iComboIndex, 0, (int)m_ComboEmotionBlueList.size() ) )
					szComboIcon = m_ComboEmotionBlueList[iComboIndex];
				else if( m_iSkillComboCnt > m_iSkillComboMaxCnt )
					szComboIcon = m_MaxComboEmotionBlue;
			}
			break;
		case TEAM_RED:
			{
				int iComboIndex = m_iSkillComboCnt - 1;
				if ( COMPARE( iComboIndex, 0, (int)m_ComboEmotionRedList.size() ) )
					szComboIcon = m_ComboEmotionRedList[iComboIndex];
				else if( m_iSkillComboCnt > m_iSkillComboMaxCnt )
					szComboIcon = m_MaxComboEmotionRed;
			}
			break;
		default:
			if( GetSingleConvertTeam() == TEAM_BLUE )
			{
				int iComboIndex = m_iSkillComboCnt - 1;
				if ( COMPARE( iComboIndex, 0, (int)m_ComboEmotionBlueList.size() ) )
					szComboIcon = m_ComboEmotionBlueList[iComboIndex];
				else if( m_iSkillComboCnt > m_iSkillComboMaxCnt )
					szComboIcon = m_MaxComboEmotionBlue;
			}
			else
			{
				int iComboIndex = m_iSkillComboCnt - 1;
				if ( COMPARE( iComboIndex, 0, (int)m_ComboEmotionRedList.size() ) )
					szComboIcon = m_ComboEmotionRedList[iComboIndex];
				else if( m_iSkillComboCnt > m_iSkillComboMaxCnt )
					szComboIcon = m_MaxComboEmotionRed;
			}
			break;
		}

		char szComboNumber[MAX_PATH] = "";
		ioHashString szComboSound;
		szComboSound.Clear();
		if( m_iSkillComboCnt > m_iSkillComboMaxCnt )
		{
			sprintf( szComboNumber, "%s", m_IconComboMax.c_str() );
			//Max에는 사운드 없음.
		}
		else
		{
			int iComboIndex = m_iSkillComboCnt - 1;
			if ( COMPARE( iComboIndex, 0, (int)m_IconComboNumberList.size() ) )
				sprintf( szComboNumber, m_IconComboNumberList[iComboIndex].c_str() );
			
			if ( Setting::IsPlayComboSound() )
			{
				ComboSoundMap::iterator iter = m_ComboSoundMap.find( m_iSkillComboCnt );
				if ( iter != m_ComboSoundMap.end() )
					szComboSound = iter->second;;
			}
		}
		if( !szComboIcon.IsEmpty() )
			SetHitEmoticon( szComboIcon, szComboNumber, m_iSkillComboCnt );

		if ( Setting::IsPlayComboSound() )
		{
			if ( !szComboSound.IsEmpty() )
			{
				if ( m_szCurSkillComboSound.IsEmpty() )
					m_szCurSkillComboSound = szComboSound;
				else
				{
					g_SoundMgr.StopSound( m_szCurSkillComboSound, 0 );
					m_szCurSkillComboSound = szComboSound;
				}
				g_SoundMgr.PlaySound( m_szCurSkillComboSound );
			}
		}
	}
	else if( IsOwnerChar() )
	{
		ioHashString szHitIcon;
		switch( GetTeam() )
		{
		case TEAM_BLUE:
			szHitIcon = m_HitBlueIcon;
			break;
		case TEAM_RED:
			szHitIcon = m_HitRedIcon;
			break;
		default:
			if( GetSingleConvertTeam() == TEAM_BLUE )
				szHitIcon = m_HitBlueIcon;
			else
				szHitIcon = m_HitRedIcon;
			break;
		}
		m_szCurSkillComboSound.Clear();
		SetEmoticon( szHitIcon, EMT_GAME_EVENT );
	}
	return true;
}

