void ioBaseChar::ShowWeaponItemMesh( bool bShow, bool bBombAlso )
{
	ioWeaponItem *pWeapon = GetWeapon();

	if( pWeapon )
	{
		bool bCurShow = pWeapon->IsVisible();
		pWeapon->SetVisible( this, bShow );

		ioHashString szNewMeshName = Help::ConvertName( pWeapon->GetEquipMesh(this), IsMale() );
		if( !IsMale() )
		{
			char szFullName[MAX_PATH]="";
			StringCbPrintf( szFullName, sizeof( szFullName ), "resource\\mesh\\%s.msh" , szNewMeshName.c_str() );
			if( !g_ResourceLoader.IsFileExist( szFullName ) )
			{
				szNewMeshName = Help::ConvertName( pWeapon->GetEquipMesh(this), true );
			}
		}

		m_pGroup->SetEntityVisible( szNewMeshName, bShow );

		if( !bShow )
		{
			m_pGroup->HideMeshExceptionCheck( szNewMeshName );

			ioHashString szEquipEffect = pWeapon->GetItemEquipEffect(IsMale());
			if( !szEquipEffect.IsEmpty() )
				EndEffect( szEquipEffect, false );
		}
		else
		{
			ioHashString szEquipEffect = pWeapon->GetItemEquipEffect(IsMale());
			if( !szEquipEffect.IsEmpty() )
			{
				// 기존에 있을수 있으므로 종료후 다시 적용
				EndEffect( szEquipEffect, false );
				AttachEffect( szEquipEffect );
			}
		}

		ioHookItem *pHook = ToHookItem( pWeapon );
		ioGunnerItem *pGunnerItem = ToGunnerItem( pWeapon );
		if( pHook )
		{
			ioHashString szName;
			if( m_pEquipSlot )
				szName = m_pEquipSlot->GetDefaultHandMesh();

			if( !szName.IsEmpty() )
			{
				DestroyEntity( szName );

				if( !bShow )
				{
					AddEntity( szName );
					ApplyModifiedMaterial();
				}
			}

			if( pHook->CheckOnHand() )
			{
				pHook->SetVisible( this, bShow );
				m_pGroup->SetEntityVisible( pHook->GetBombMeshName(), bShow );

				if( !bShow )
				{
					m_pGroup->HideMeshExceptionCheck( pHook->GetBombMeshName() );
				}
			}
		}
	}
}

