bool ioBaseChar::ChangeSkillWeaponMesh( ioSkill *pSkill, const ioHashString &szAddEntity, bool bVisibleEquipMesh )
{
	ioItem *pItem = pSkill->GetOwnerItem();
	if( !pItem )	return false;

	AddEntity( szAddEntity );

	if( bVisibleEquipMesh )
		return true;

	ioHelmetItem *pHelmet = ToHelmetItem( pItem );
	if( pHelmet )
	{
		if( m_pEquipSlot )
			m_pEquipSlot->CheckCurHair( pHelmet, true );
		pHelmet->SetVisible( this, false );

		ioHashString szNewMeshName = Help::ConvertName( pHelmet->GetEquipMesh(this), IsMale() );
		if( !IsMale() )
		{
			char szFullName[MAX_PATH]="";
			StringCbPrintf( szFullName, sizeof( szFullName ), "resource\\mesh\\%s.msh" , szNewMeshName.c_str() );
			if( !g_ResourceLoader.IsFileExist( szFullName ) )
			{
				szNewMeshName = Help::ConvertName( pHelmet->GetEquipMesh(this), true );
			}
		}

		m_pGroup->SetEntityVisible( szNewMeshName, false );
		m_pGroup->HideMeshExceptionCheck( szNewMeshName );

		ioHashString szEquipEffect = pHelmet->GetItemEquipEffect(IsMale());
		if( !szEquipEffect.IsEmpty() )
			EndEffect( szEquipEffect, false );

		return true;
	}

	ioCloakItem *pCloak = ToCloakItem( pItem );
	if( pCloak )
	{
		pCloak->SetVisible( this, false );

		ioHashString szNewMeshName = Help::ConvertName( pCloak->GetEquipMesh(this), IsMale() );
		if( !IsMale() )
		{
			char szFullName[MAX_PATH]="";
			StringCbPrintf( szFullName, sizeof( szFullName ), "resource\\mesh\\%s.msh" , szNewMeshName.c_str() );
			if( !g_ResourceLoader.IsFileExist( szFullName ) )
			{
				szNewMeshName = Help::ConvertName( pCloak->GetEquipMesh(this), true );
			}
		}

		m_pGroup->SetEntityVisible( szNewMeshName, false );
		m_pGroup->HideMeshExceptionCheck( szNewMeshName );

		ioHashString szEquipEffect = pCloak->GetItemEquipEffect(IsMale());
		if( !szEquipEffect.IsEmpty() )
			EndEffect( szEquipEffect, false );

		return true;
	}

	return false;
}

bool ioBaseChar::RestoreSkillWeaponMesh( ioSkill *pSkill, const ioHashString &szRemoveEntity, bool bVisibleEquipMesh, bool bRemoveHair )
{
	ioItem *pItem = pSkill->GetOwnerItem();
	if( !pItem )	return false;

	DestroyEntity( szRemoveEntity );

	if( bVisibleEquipMesh )
		return true;

	ioHelmetItem *pHelmet = ToHelmetItem( pItem );
	if( pHelmet )
	{
		if( m_pEquipSlot )
			m_pEquipSlot->CheckCurHair( pHelmet, bRemoveHair );
		pHelmet->SetVisible( this, true );

		ioHashString szNewMeshName = Help::ConvertName( pHelmet->GetEquipMesh(this), IsMale() );
		if( !IsMale() )
		{
			char szFullName[MAX_PATH]="";
			StringCbPrintf( szFullName, sizeof( szFullName ), "resource\\mesh\\%s.msh" , szNewMeshName.c_str() );
			if( !g_ResourceLoader.IsFileExist( szFullName ) )
			{
				szNewMeshName = Help::ConvertName( pHelmet->GetEquipMesh(this), true );
			}
		}

		m_pGroup->SetEntityVisible( szNewMeshName, true );

		ioHashString szEquipEffect = pHelmet->GetItemEquipEffect(IsMale());
		if( !szEquipEffect.IsEmpty() )
		{
			// 기존에 있을수 있으므로 종료후 다시 적용
			EndEffect( szEquipEffect, false );
			AttachEffect( szEquipEffect );
		}

		return true;
	}

	ioCloakItem *pCloak = ToCloakItem( pItem );
	if( pCloak )
	{
		pCloak->SetVisible( this, true );

		ioHashString szNewMeshName = Help::ConvertName( pCloak->GetEquipMesh(this), IsMale() );
		if( !IsMale() )
		{
			char szFullName[MAX_PATH]="";
			StringCbPrintf( szFullName, sizeof( szFullName ), "resource\\mesh\\%s.msh" , szNewMeshName.c_str() );
			if( !g_ResourceLoader.IsFileExist( szFullName ) )
			{
				szNewMeshName = Help::ConvertName( pCloak->GetEquipMesh(this), true );
			}
		}

		m_pGroup->SetEntityVisible( szNewMeshName, true );

		ioHashString szEquipEffect = pCloak->GetItemEquipEffect(IsMale());
		if( !szEquipEffect.IsEmpty() )
		{
			// 기존에 있을수 있으므로 종료후 다시 적용
			EndEffect( szEquipEffect, false );
			AttachEffect( szEquipEffect );
		}

		return true;
	}

	return false;
}

void ioBaseChar::ShowEquipItemMesh( bool bShow, int iSlot )
{
	if( !COMPARE( iSlot, 0, 4 ) )
		return;

	ioItem *pItem = m_pEquipSlot->GetEquipedItem( iSlot );
	if( !pItem ) return;

	ioWeaponItem *pWeapon = ToWeaponItem( pItem );
	if( pWeapon )
	{
		ShowWeaponItemMesh( bShow );
		return;
	}

	ioHelmetItem *pHelmet = ToHelmetItem( pItem );
	if( pHelmet )
	{
		if( m_pEquipSlot )
			m_pEquipSlot->CheckCurHair( pHelmet, true );
		pHelmet->SetVisible( this, bShow );

		ioHashString szNewMeshName = Help::ConvertName( pHelmet->GetEquipMesh(this), IsMale() );
		if( !IsMale() )
		{
			char szFullName[MAX_PATH]="";
			StringCbPrintf( szFullName, sizeof( szFullName ), "resource\\mesh\\%s.msh" , szNewMeshName.c_str() );
			if( !g_ResourceLoader.IsFileExist( szFullName ) )
			{
				szNewMeshName = Help::ConvertName( pHelmet->GetEquipMesh(this), true );
			}
		}

		m_pGroup->SetEntityVisible( szNewMeshName, bShow );
		if( !bShow )
			m_pGroup->HideMeshExceptionCheck( szNewMeshName );
		return;
	}

	ioCloakItem *pCloak = ToCloakItem( pItem );
	if( pCloak )
	{
		pCloak->SetVisible( this, bShow );

		ioHashString szNewMeshName = Help::ConvertName( pCloak->GetEquipMesh(this), IsMale() );
		if( !IsMale() )
		{
			char szFullName[MAX_PATH]="";
			StringCbPrintf( szFullName, sizeof( szFullName ), "resource\\mesh\\%s.msh" , szNewMeshName.c_str() );
			if( !g_ResourceLoader.IsFileExist( szFullName ) )
			{
				szNewMeshName = Help::ConvertName( pCloak->GetEquipMesh(this), true );
			}
		}

		m_pGroup->SetEntityVisible( szNewMeshName, bShow );
		if( !bShow )
			m_pGroup->HideMeshExceptionCheck( szNewMeshName );
		return;
	}
}

void ioBaseChar::ShowHeadMesh( bool bShow )
{
	if( bShow )
		m_bInvisibleHead = false;
	else
		m_bInvisibleHead = true;

	ioHelmetWearItem *pWear = ToHelmetWearItem( m_pEquipSlot->GetEquipedItem( ES_WEAR ) );
	ioHelmetItem *pHelmet = ToHelmetItem( m_pEquipSlot->GetEquipedItem( ES_HELMET ) );

	if( pWear )
	{
		if( m_pEquipSlot && !m_bInvisibleFace )
			m_pEquipSlot->ShowHeadMesh( pWear, bShow );

		pWear->SetVisible( this, bShow );

		ioHashString szNewMeshName = Help::ConvertName( pWear->GetEquipMesh(this), IsMale() );
		if( !IsMale() )
		{
			char szFullName[MAX_PATH]="";
			StringCbPrintf( szFullName, sizeof( szFullName ), "resource\\mesh\\%s.msh" , szNewMeshName.c_str() );
			if( !g_ResourceLoader.IsFileExist( szFullName ) )
			{
				szNewMeshName = Help::ConvertName( pWear->GetEquipMesh(this), true );
			}
		}

		m_pGroup->SetEntityVisible( szNewMeshName, bShow );
		if( !bShow )
			m_pGroup->HideMeshExceptionCheck( szNewMeshName );
	}
	else if( pHelmet )
	{
		if( m_pEquipSlot && !m_bInvisibleFace )
			m_pEquipSlot->ShowHeadMesh( pHelmet, bShow );

		pHelmet->SetVisible( this, bShow );

		ioHashString szNewMeshName = Help::ConvertName( pHelmet->GetEquipMesh(this), IsMale() );
		if( !IsMale() )
		{
			char szFullName[MAX_PATH]="";
			StringCbPrintf( szFullName, sizeof( szFullName ), "resource\\mesh\\%s.msh" , szNewMeshName.c_str() );
			if( !g_ResourceLoader.IsFileExist( szFullName ) )
			{
				szNewMeshName = Help::ConvertName( pHelmet->GetEquipMesh(this), true );
			}
		}

		m_pGroup->SetEntityVisible( szNewMeshName, bShow );
		if( !bShow )
			m_pGroup->HideMeshExceptionCheck( szNewMeshName );

	}
	else
	{
		if( m_pEquipSlot && !m_bInvisibleFace )
			m_pEquipSlot->ShowHeadMesh( NULL, bShow );
	}
}

void ioBaseChar::CheckSkillItemHide( bool bShow, int iItemType )
{
	int iSlot = iItemType - 1;

	if( COMPARE( iSlot, 0, ES_OBJECT ) )
	{
		ioSkill *pSkill = GetEquipedSkill( iSlot );
		if( pSkill && pSkill->IsHideEquipItemByRotationWeapon() )
		{
			ShowEquipItemMesh( bShow, iSlot );
		}
	}
}

void ioBaseChar::SetKOHPRecover( float fRate, const ioHashString &szEffect )
{
	if( fRate > 0.0f && !m_pModeParent->IsZeroHP() )
	{
		float fRecoverHP = m_HP.m_fMaxValue * fRate;

		fRecoverHP += m_HP.m_fCurValue;

		fRecoverHP = min( fRecoverHP, m_HP.m_fMaxValue );
		fRecoverHP = max( 0.0f, fRecoverHP );

		m_HP.m_fCurValue = fRecoverHP;
	}
	
	if ( !m_szExtendKillEffect.IsEmpty() )
		AttachEffect( m_szExtendKillEffect );
	else if( !szEffect.IsEmpty() )
		AttachEffect( szEffect );
}

// ApplyDownState Check
bool ioBaseChar::IsApplyDownState( bool bApplyAir )
{
	if( bApplyAir )
	{
		switch( m_CharState )
		{
		case CS_FALL:
		case CS_CREEPING:
		case CS_BLOW_WOUNDED:
		case CS_BOUND_BLOW_WOUNDED:
		case CS_BLOW_EXTEND_WOUND:
			return true;
		case CS_ETC_STATE:
			if( GetBlowEtcState() )
			{
				return true;
			}
			break;
		case CS_USING_SKILL:
			if( m_pActiveSkill && m_pActiveSkill->IsDownState() )
			{
				return true;
			}
			break;
		}
	}
	else
	{
		if( ( m_CharState == CS_BLOW_WOUNDED || m_CharState == CS_BOUND_BLOW_WOUNDED ) &&
			( m_BlowState != BW_BLOWING && m_BlowState != BW_BOUND_BLOWING ) )
			return true;

		if( m_CharState == CS_ETC_STATE && GetBlowEtcState() && !IsFloating() )
			return true;

		if( m_CharState == CS_CREEPING && !IsFloating() )
			return true;

		if( m_CharState == CS_FALL && m_FallState != FS_FALLING )
			return true;

		if( m_CharState == CS_USING_SKILL && m_pActiveSkill && m_pActiveSkill->IsDownState() )
			return true;
	}

	return false;
}

void ioBaseChar::CheckAttackCnt( ioBaseChar *pChar )
{
	if( m_pModeParent && pChar )
	{
		// 팀 제외
		if( GetTeam() != pChar->GetTeam() )
		{
			m_pModeParent->AttackCntContribute( GetCharName(), pChar->GetCharName(), pChar->GetWeaponItemCode() );

			if( m_pModeParent && m_pModeParent->GetModeType() != MT_FOOTBALL )
				g_AwardMgr.AddWounded( pChar->GetCharName(), FLOAT100 * m_pModeParent->ContributeTeamPerA( pChar->GetTeam(), FLOAT1, 0.1f ) );
		}		
	}
	
	// 팀 히트 제외
	if( pChar && GetTeam() != pChar->GetTeam() )
	{
		if( m_pModeParent && m_pModeParent->GetModeType() != MT_FOOTBALL )
			g_AwardMgr.AddHit( GetCharName() );
	}
}

void ioBaseChar::CheckTeamBuffAttackCnt( ioBaseChar *pChar )
{
	if( m_pModeParent && pChar )
	{
		m_pModeParent->AttackCntContribute( GetCharName(), pChar->GetCharName(), pChar->GetWeaponItemCode(), 50 );
	}
}

