void ioBaseChar::CheckSkillEvent( int iBuffType )
{
	if( Setting::IsHideSkillBuffEmoticon() )
		return;

	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		if( !pBuff ) continue;

		if( pBuff->GetTypeID() != iBuffType )
			continue;

		ioSkill *pSkill = NULL;
		if( m_pEquipSlot )
			pSkill = m_pEquipSlot->GetEquipedSkill( pBuff->GetSkillName() );
		if( pSkill )
		{
			const vHelpText *pHelpList = g_ModeHelpMgr.GetHelpText( ioModeHelpManager::HT_SKILL );

			if( !pHelpList )
			{
				LOG.PrintTimeAndLog( 0, "ioBaseChar::CheckSkillEvent() Emoticon is Not Exist" );
				return;
			}

			if( pHelpList->empty() ) return;


			const HelpText &rkText = *(pHelpList->begin());
			
			DWORD dwColor = rkText.m_dwColor;

			SetNamedEmoticon( pSkill->GetIconName(), pSkill->GetDescName(), dwColor );
			break;
		}
	}
}

void ioBaseChar::CheckNonePlayTime( bool bClear, bool bPlayerChanged )
{
	if( bClear )
	{
		m_dwNonePlayCheckTime = 0;
	}
	else
	{
		if( bPlayerChanged )
		{
			if( m_dwNonePlayCheckTime == 0 )
				m_dwNonePlayCheckTime = FRAMEGETTIME();
		}
		else
		{
			m_dwNonePlayCheckTime = FRAMEGETTIME();
		}
	}
}

bool ioBaseChar::IsNonePlayState()
{
#ifndef SHIPPING
	return false;
#endif

	if( m_pModeParent && ( m_pModeParent->GetModeType() == MT_CATCH || m_pModeParent->GetModeType() == MT_CATCH_RUNNINGMAN ||
		m_pModeParent->GetModeType() == MT_UNDERWEAR || m_pModeParent->GetModeType() == MT_CBT || m_pModeParent->GetModeType() == MT_ARENA || m_pModeParent->GetModeType() == MT_FARMING ) )
	{
		DWORD dwCurGap = m_dwNonePlayCheckTime + m_dwNonePlayCareTime;
		
		if( m_dwNonePlayCheckTime > 0 && m_dwNonePlayCareTime > 0 && dwCurGap < FRAMEGETTIME() )
		{
			return true;
		}
	}

	return false;
}

void ioBaseChar::SetNonePlayEmoticon()
{
	if( IsOwnerChar() && m_pCharEmoticon )
	{
		DWORD dwCurCare = m_dwNonePlayCheckTime + m_dwNonePlayCareTime;
		DWORD dwCurWarning = m_dwNonePlayCheckTime + m_dwNonePlayWarningTime;

		NonePlayState ePreState = m_NonePlayState;

		// Warning 먼저 확인
		if( m_dwNonePlayCheckTime > 0 && m_dwNonePlayWarningTime > 0 && dwCurWarning < FRAMEGETTIME() )
			m_NonePlayState = NPS_WARNING;
		else if( m_dwNonePlayCheckTime > 0 && m_dwNonePlayCareTime > 0 && dwCurCare < FRAMEGETTIME() )
			m_NonePlayState = NPS_CARE;

		if( m_NonePlayState == NPS_NONE )
		{
			EndUnLimitedEmoticon();

			if( ePreState == NPS_WARNING )
			{
				ApplyNonePlayStateBuff( false );

				if( IsNeedSendNetwork() )
				{
					SP2Packet kPacket( CUPK_NONE_PLAY_STATE );
					kPacket << m_Name;
					kPacket << false;
					P2PNetwork::SendToAllPlayingUser( kPacket );
				}
			}
		}
		else if( m_NonePlayState == NPS_CARE )
		{
			if( ePreState == NPS_NONE )
			{
				if( IsOwnerChar() )
					CheckNamedEmoticon( ioModeHelpManager::HT_STOP_GAUGE1, true );
			}
		}
		else if( m_NonePlayState == NPS_WARNING )
		{
			if( ePreState == NPS_CARE )
			{
				if( IsOwnerChar() )
					CheckNamedEmoticon( ioModeHelpManager::HT_STOP_GAUGE2, true );

				ApplyNonePlayStateBuff( true );

				if( IsNeedSendNetwork() )
				{
					SP2Packet kPacket( CUPK_NONE_PLAY_STATE );
					kPacket << m_Name;
					kPacket << true;
					P2PNetwork::SendToAllPlayingUser( kPacket );
				}
			}
		}
	}
}

void ioBaseChar::ApplyNonePlayStateBuff( bool bNonePlayState )
{
	int iBuffCnt = m_NonePlayWarningBuff.size();
	
	for( int i=0; i < iBuffCnt; ++i )
	{
		if( bNonePlayState )
			AddNewBuff( m_NonePlayWarningBuff[i], m_Name, "", NULL );
		else
			RemoveBuff( m_NonePlayWarningBuff[i] );
	}
}

void ioBaseChar::FloatModeEventBuffEnd()
{
	ErrorReport::SetPosition( 3001, 1 );
	if( GetState() == CS_VIEW ) return;

	ErrorReport::SetPosition( 3001, 2 );
	SetState( CS_VIEW );

	ErrorReport::SetPosition( 3001, 3 );
	if( !IsNpcChar( this ) )
	{
		ErrorReport::SetPosition( 3001, 4 );
		if( IsOwnerChar() )
		{
			ErrorReport::SetPosition( 3001, 5 );
			// 서버로 상태 변경 전송
			SP2Packet kPacket( CTPK_TURN_END_VIEW_STATE );
			TCPNetwork::SendToServer( kPacket );
		}

		ErrorReport::SetPosition( 3001, 6 );
		m_pCreator->ChangeCurViewCharByView( this );
	}

	ErrorReport::SetPosition( 3001, 7 );
}

