void ioBaseChar::CheckWoundPassiveSkill( ioBaseChar *pAttacker )
{
	for( int i=0; i < 4; i++ )
	{
		ioSkill *pSkill = NULL;
		if( m_pEquipSlot )
			pSkill = m_pEquipSlot->GetEquipedSkill( i );

		ioPassiveSkill *pPassiveSkill = ToPassiveSkill( pSkill );
		if( pPassiveSkill )
		{
			pPassiveSkill->CheckWoundProcess( this, pAttacker );
		}
	}

	for( int i=ES_RING; i < MAX_EQUIP_SLOT; i++ )
	{
		ioSkill *pSkill = NULL;
		if( m_pEquipSlot )
			pSkill = m_pEquipSlot->GetEquipedSkill( i );

		ioPassiveSkill *pPassiveSkill = ToPassiveSkill( pSkill );
		if( pPassiveSkill )
		{
			pPassiveSkill->CheckWoundProcess( this, pAttacker );
		}
	}
}

int ioBaseChar::GetReflectInfoIndex( AttackSide iAttackSide )
{
	int iIndex = -1;
	int iCnt = m_vReflectInfoList.size();

	for( int i=0; i < iCnt; ++i )
	{
		if( !m_vReflectInfoList[i] )
			continue;

		//우선순위에 상관없이 적용되어야 할 Reflect일 경우
		if( m_vReflectInfoList[i]->m_bIgnoreOtherReflect && 
			(m_vReflectInfoList[i]->m_ReflectSideType == iAttackSide ||
			 m_vReflectInfoList[i]->m_ReflectSideType == AS_NONE))
		{
			return i;
		}

		if( m_vReflectInfoList[i]->m_ReflectSideType == iAttackSide )
		{
			iIndex = i;
		}
		else if( m_vReflectInfoList[i]->m_ReflectSideType == AS_NONE )
		{
			if( iIndex == -1 )
				iIndex = i;
		}
	}

	return iIndex;
}

void ioBaseChar::SetEtcState( const ioHashString &szName, float fRate )
{
	if( szName.IsEmpty() ) return;
	if( fRate <= 0.0f ) return;

	int iAniID = m_pGroup->GetAnimationIdx( szName );
	if( iAniID == -1 ) return;

	m_pGroup->ClearAllLoopAni( FLOAT100, true );
	m_pGroup->ClearAllActionAni( FLOAT100, true );

	m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fRate );

	m_dwEtcCheckTime = FRAMEGETTIME();
	m_dwEtcCheckTime += m_pGroup->GetAnimationFullTime( iAniID ) * fRate;

	SetState( CS_ETC_STATE );
}

void ioBaseChar::SetMissFireState( const ioHashString &szName, float fRate )
{
	if( szName.IsEmpty() || fRate <= 0.0f )
	{
		SetState( CS_DELAY );
		return;
	}

	int iAniID = m_pGroup->GetAnimationIdx( szName );
	if( iAniID == -1 ) 
	{
		SetState( CS_DELAY );
		return;
	}

	m_pGroup->ClearAllLoopAni( FLOAT100, true );
	m_pGroup->ClearAllActionAni( FLOAT100, true );

	m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1/fRate );

	m_AnimationTime.dwStartTime = FRAMEGETTIME();
	m_AnimationTime.dwFullTime  = m_pGroup->GetAnimationFullTime( iAniID ) * fRate;

	SetState( CS_MISS_FIRE );
}

void ioBaseChar::SetBreakFallState( const ioHashString &szName )
{
	const ioBreakFallBuff *pBreakFall = ToBreakFallConst( g_BuffMaker.GetBuffConst( szName ) );
	if( !pBreakFall )
		return;

	BreakFallInfo kInfo = pBreakFall->GetBreakFallInfo();

	ioHashString szAniName = kInfo.m_BreakFallAttack.m_AttackAnimation;
	float fTimeRate = kInfo.m_BreakFallAttack.m_fAttackAniRate;
	if( fTimeRate <= 0.0f )
		fTimeRate = FLOAT1;

	int iAniID = m_pGroup->GetAnimationIdx( szAniName );
	if( iAniID == -1 ) return;

	m_bUsedFlashJump = false;

	m_pGroup->ClearAllLoopAni( FLOAT100, true );
	m_pGroup->ClearAllActionAni( FLOAT100, true );

	m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fTimeRate, 0.0f, 0.0f, true );

	switch( kInfo.m_BreakFallType )
	{
	case BFT_NORMAL:
		break;
	case BFT_JUMP:
		break;
	case BFT_ATTACK:
		{
			m_fForceAmt = 0.0f;

			if( IsNeedProcess() )
			{
				SetTargetRotToRotate( GetTargetRot(), true, false );
			}

			RefreshFireTimeList( iAniID, kInfo.m_BreakFallAttack.m_vWeaponInfoList, FTT_JUMP_ATTACK, fTimeRate, 0 );
			SetReservedSliding( kInfo.m_BreakFallAttack.m_vForceInfoList, iAniID, fTimeRate, 0 );
		}
		break;
	}

	SetState( CS_JUMP );
	m_JumpState = JS_BREAK_FALL;

	m_fCurMoveSpeed = FLOAT1;

	if( IsNeedSendNetwork() )
	{
		SP2Packet kPacket( CUPK_BREAK_FALL );
		kPacket << GetCharName();
		kPacket << szName;
		kPacket << GetTargetRot();
		P2PNetwork::SendToAllPlayingUser( kPacket );
	}
}

void ioBaseChar::SetBreakFallLanding( DWORD dwEndTime )
{
	ClearAttackFireTimeAndSkill();
	ClearReservedSliding();

	m_fCurMoveSpeed = 0.0f;
	m_fForceAmt = 0.0f;

	m_dwJumpStateEndTime = dwEndTime;

	ioAttackableItem *pItem = GetPriorityItem( SPT_ATTACK );
	if( pItem )
	{
		pItem->CheckLanding( this );
	}
	else
	{
		SetTargetMarkerState( ioTargetMarker::MS_NONE );
		m_pGroup->ReleaseAllExtraRotate();
	}

	m_CharLandType = CLT_LAND_ATTACK;

	m_JumpState = JS_LANDING;
	m_bUsedJumpDefense = false;
	m_bReleaseJumpDefense = false;

	m_bUsedJumpAttack = false;
	m_bUsedChangeJump = false;
	m_bUsedBuffJumpAttack = false;
	m_bUsedJumpReload = false;
	
	m_bSuccessJumpAttack = false;
	m_bCrossBowJump = false;
}

