std::string ioBaseChar::GetWoundedSoundName( const ioHashString &szName )
{
	int iSoundType = 0;

	// 피격시 갑옷 아이템
	ioArmorItem *pArmor = GetArmor();
	if( pArmor )
	{
		iSoundType = pArmor->GetArmorSoundType();
	}

	//임시 수정 타입값을 0으로 고정
	iSoundType = 0;

	std::string szWoundedSound;
	if( iSoundType > 0 )
	{
		char szType[MAX_PATH] = "";
		wsprintf( szType, "_%d", iSoundType );

		szWoundedSound = ioStringConverter::AddTailToFileName( szName.c_str(), szType );
	}
	else
	{
		szWoundedSound = szName.c_str();
	}

	return szWoundedSound;
}

std::string ioBaseChar::GetDefensedSoundName( const ioHashString &szName )
{
	int iSoundType = 0;

	// 방어시 무기 아이템
	ioWeaponItem *pWeapon = GetWeapon();
	if( pWeapon )
	{
		iSoundType = pWeapon->GetWeaponSoundType();
	}

	std::string szDefensedSound;
	if( iSoundType > 0 )
	{
		char szType[MAX_PATH] = "";
		wsprintf( szType, "_%d", iSoundType );

		szDefensedSound = ioStringConverter::AddTailToFileName( szName.c_str(), szType );
	}
	else
	{
		szDefensedSound = szName.c_str();
	}

	return szDefensedSound;
}

std::string ioBaseChar::GetMotionSoundName( const ioHashString &szName )
{
	int iSoundType = 0;

	std::string szMotionSound;
	ioHashString szSoundName;

	const StringVector &vParam = ioStringConverter::Split( szName.c_str(), " " );
	if( vParam.size() >= 1 )
		szSoundName = vParam[0].c_str();

	if( szSoundName.IsEmpty() )
	{
		szMotionSound = szName.c_str();
		return szMotionSound;
	}

	if( vParam.size() == 2 )
	{
		int iMap = ioStringConverter::ParseInt( vParam[1].c_str() );
		if( iMap == 1 && m_pModeParent )
			iSoundType = m_pModeParent->GetModeMotionSoundType();
	}
	else
	{
		// 동작시 갑옷 아이템
		ioArmorItem *pArmor = GetArmor();
		if( pArmor )
			iSoundType = pArmor->GetArmorSoundType();
	}

	if( iSoundType > 0 )
	{
		char szType[MAX_PATH] = "";
		wsprintf( szType, "_%d", iSoundType );
		szMotionSound = ioStringConverter::AddTailToFileName( szSoundName.c_str(), szType );
	}
	else
	{
		szMotionSound = szSoundName.c_str();
	}

	return szMotionSound;
}

ioHashString ioBaseChar::GetVoiceSoundName( const ioHashString &szName )
{
	std::string szVoiceSound;

	int iVoiceType = m_iVoiceType;
	if( iVoiceType > 0 )
	{
		char szType[MAX_PATH] = "";
		wsprintf( szType, "_%d", iVoiceType );
		szVoiceSound = ioStringConverter::AddTailToFileName( szName.c_str(), szType );
	}
	else
	{
		char szType[MAX_PATH] = "";
		wsprintf( szType, "_1" );
		szVoiceSound = ioStringConverter::AddTailToFileName( szName.c_str(), szType );
	}

	ioHashString szNewVoiceSound = Help::ConvertTailName( ioHashString( szVoiceSound.c_str() ), m_bMale );

	return szNewVoiceSound;
}

