void ioBaseChar::ProcessNetworkTimeOutEmoticon()
{
	switch( m_CharState )
	{
	case CS_ENDMOTION:
	case CS_READY:
	case CS_VIEW:
	case CS_OBSERVER:
	case CS_STARTMOTION:
	case CS_CREATEMOTION:
	case CS_COIN_REBIRTH:
	case CS_LOADING:
	case CS_CHANGE_GANGSI:
	case CS_GRADEUP_MOTION:
		return;
	}
	
	if( m_bOwnerChar || ToNpcChar( this ) )
		return;

	// 결과 중에는 표기하지 않는다.
	if( m_pModeParent && m_pModeParent->GetModeState() == ioPlayMode::MS_RESULT ) 
	{
		if( m_bSetNetworkTimeOutEmoticon )
		{
			EndUnLimitedEmoticon();
			m_bSetNetworkTimeOutEmoticon = false;
		}
		return;
	}

	if( m_bSetNetworkTimeOutEmoticon )
	{
		if( !P2PNetwork::IsNetworkTimeOut( GetCharName() ) )
		{
			EndUnLimitedEmoticon();
			m_bSetNetworkTimeOutEmoticon = false;
			SetChatMode( m_iNetworkTimeOutReserveChatMode );
		}
	}
	else
	{
		if( P2PNetwork::IsNetworkTimeOut( GetCharName() ) )
		{
			m_iNetworkTimeOutReserveChatMode = GetChatModeState();
			CheckNamedEmoticon( ioModeHelpManager::HT_NETWORK_DISCONNECT, true );
			m_bSetNetworkTimeOutEmoticon = true;			
		}
	}
}

