DWORD ioBaseChar::GetEventGapTime()
{
	DWORD dwEventTime = 0;

	// 시작 시점 체크
	if( m_bOwnerChar && m_dwSetStartTime > 0 )
		dwEventTime = m_dwSetStartTime;

	// 포로 시점 체크
	if( m_dwSetPrisonerTime > 0 )
	{
		if( dwEventTime == 0 )
			dwEventTime = m_dwSetPrisonerTime;
		else
			dwEventTime = max( dwEventTime, m_dwSetPrisonerTime );
	}

	// 포로해제 시점 체크
	if( m_dwEscapePrisonerTime > 0 )
	{
		if( dwEventTime == 0 )
			dwEventTime = m_dwEscapePrisonerTime;
		else
			dwEventTime = max( dwEventTime, m_dwEscapePrisonerTime );
	}

	// 왕관집기 시점 체크
	if( m_dwCrownPickTime > 0 )
	{
		if( dwEventTime == 0 )
			dwEventTime = m_dwCrownPickTime;
		else
			dwEventTime = max( dwEventTime, m_dwCrownPickTime );
	}

	if( dwEventTime == 0 )
		return dwEventTime;

	return (FRAMEGETTIME() - dwEventTime);
}

