void ioBaseChar::SetTeleportState( const ioHashString &szStartAni,
								   float fStartRate,
								   const ioHashString &szEndAni,
								   float fEndRate,
								   const D3DXVECTOR3 &vEndPos )
{
	m_szTeleportStart = szStartAni;
	m_szTeleportEnd = szEndAni;

	m_fTeleportStartRate = fStartRate;
	m_fTeleportEndRate = fEndRate;

	m_vTeleportEndPos = vEndPos;

	int iAniID = m_pGroup->GetAnimationIdx( m_szTeleportStart );
	if( iAniID == -1 )
		return;
	
	m_dwTeleportStartEndTime = 0;
	m_dwTeleportEndEndTime = 0;

	m_pGroup->ClearAllActionAni( FLOAT100, true );
	m_pGroup->ClearAllLoopAni( FLOAT100, true );

	m_pGroup->SetActionAni( m_szTeleportStart, FLOAT100, FLOAT100, FLOAT1, FLOAT1/m_fTeleportStartRate );
	
	m_dwTeleportStartEndTime = FRAMEGETTIME();
	m_dwTeleportStartEndTime += m_pGroup->GetAnimationFullTime( iAniID ) * m_fTeleportStartRate;

	SetState( CS_TELEPORT );

	if( IsNeedSendNetwork() )
	{
		SP2Packet kPacket( CUPK_TELEPORT_STATE );
		kPacket << GetCharName();
		kPacket << m_szTeleportStart;
		kPacket << m_fTeleportStartRate;
		kPacket << m_szTeleportEnd;
		kPacket << m_fTeleportEndRate;
		kPacket << m_vTeleportEndPos;
		P2PNetwork::SendToAllPlayingUser( kPacket );
	}
}

void ioBaseChar::CheckTeleportState()
{
	DWORD dwCurTime = FRAMEGETTIME();

	if( m_dwTeleportStartEndTime > 0 && m_dwTeleportStartEndTime < dwCurTime )
	{
		int iAniID = m_pGroup->GetAnimationIdx( m_szTeleportEnd );
		if( iAniID == -1 )
		{
			SetState( CS_DELAY );
			return;
		}

		SetWorldPosition( m_vTeleportEndPos );

		m_pGroup->ClearAllActionAni( FLOAT100, true );
		m_pGroup->ClearAllLoopAni( FLOAT100, true );
		m_pGroup->SetActionAni( m_szTeleportEnd, FLOAT100, FLOAT100, FLOAT1, FLOAT1/m_fTeleportEndRate );

		m_dwTeleportEndEndTime = dwCurTime;
		m_dwTeleportEndEndTime += m_pGroup->GetAnimationFullTime( iAniID ) * m_fTeleportEndRate;

		m_dwTeleportStartEndTime = 0;
	}
	else if( m_dwTeleportEndEndTime > 0 && m_dwTeleportEndEndTime < dwCurTime )
	{
		m_dwTeleportEndEndTime = 0;
		SetState( CS_DELAY );
	}
}

void ioBaseChar::SetReservedSliding( const ForceInfoList &vForceInfoList,
									 int iAniID,
									 float fTimeRate,
									 DWORD dwPreDelay,
									 float fExtraForceRate,
									 bool bMoveDir )
{
	if( iAniID == -1 ) return;

	ClearReservedSliding();

	std::list<float> vTimeList;
	m_pGroup->GetAnimationEventTimeList_e( iAniID, "fire_sliding", vTimeList );

	int iListCnt = vForceInfoList.size();
	int iCurList = 0;

	std::list< float >::iterator iter = vTimeList.begin();
	while( iter != vTimeList.end() )
	{
		DWORD dwTime = (DWORD)*iter;
		dwTime *= fTimeRate;
		dwTime += dwPreDelay;

		float fForceAmt = 0.0f;
		float fForceFriction = FLOAT1;
		float fForceAngle = 0.0f;

		if( iListCnt > iCurList )
		{
			fForceAmt = vForceInfoList[iCurList].m_fForceMovePower;
			fForceAmt = g_StatAttribute.GetCalcStatAttribute( fForceAmt, SA_STR_FORCE_AMT_UP, this );
			fForceAmt *= fExtraForceRate;
			fForceFriction = vForceInfoList[iCurList].m_fForceMoveFriction;
			fForceAngle = vForceInfoList[iCurList].m_fForceAngle;
			iCurList++;

			AddReservedSliding( dwTime, fForceAmt, fForceFriction, fForceAngle, bMoveDir );
		}
		else
		{
			LOG.PrintTimeAndLog( 0, "ForceMoveLog - %s fire_sliding / forcemove ( %d / %d )",
									m_pGroup->GetAnimationName(iAniID).c_str(),
									iCurList+1,
									iListCnt );

			iCurList++;
		}

		iter++;
	}
}

