ioBuff* ioBaseChar::GetBuff( const ioHashString &rkName, const ioHashString &szCreatorName )
{
	ioBuff* pTempBuff = NULL;
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		if( pBuff )
		{
			if( pBuff->GetName() == rkName && pBuff->GetCreatorName() == szCreatorName )\
			{
				// 발동 조건 없는 패시브 버프는 따로 담아둔 다음 검색 후 같은 타입의 다른 버프가 없다면 그 버프를 리턴(무제한 패시브는 후순위)
				if(pBuff->IsUnlimitedPassiveType())
				{
					pTempBuff = pBuff;
					continue;
				}
				return pBuff;
			}
		}
	}

	return pTempBuff;
}

