bool ioBaseChar::CheckMustBlowWoundBuff()
{
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioCloseOrderBuff *pCloseOrder = ToCloseOrderBuff( m_aBuffArray->GetAt(i) );
		if( pCloseOrder && pCloseOrder->IsMustBlowWound() )
		{
			return true;
		}
	}

	return false;
}

float ioBaseChar::CheckCarefulStepCloseOrder()
{
	if( m_CharState != CS_CLOSEORDER )
		return 0.0f;

	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioCloseOrderBuff *pCloseOrder = ToCloseOrderBuff( m_aBuffArray->GetAt(i) );
		if( pCloseOrder )
		{
			return pCloseOrder->GetCarefulStepHeight();
		}
	}

	return 0.0f;
}

