{
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioWoundColorChangeBuff *pChangeColor = ToWoundColorChange( m_aBuffArray->GetAt(i) );
		if( pChangeColor )
		{
			pChangeColor->ApplyWoundState();
		}
	}
}

bool ioBaseChar::CheckInvisibleWeaponSkill()
{
	if( m_pActiveSkill )
	{
		if( m_CharState != CS_USING_SKILL )
		{
			return false;
		}

		return m_pActiveSkill->CheckUseItemMesh();
	}
	else if( m_CharState == CS_FISHING )
	{
		return true;
	}

	return false;
}

void ioBaseChar::ClearAllEquipEffect()
{
	for( int i=0; i < ES_OBJECT; ++i )
	{
		ioItem *pItem = GetEquipedItem( i );
		if( !pItem )
			continue;
		
		ioHashString szEquipEffect = pItem->GetItemEquipEffect(IsMale());
		if( !szEquipEffect.IsEmpty() )
			EndEffect( szEquipEffect, false );
	}
}

void ioBaseChar::RestoreAllEquipEffect()
{
	for( int i=0; i < ES_OBJECT; ++i )
	{
		ioItem *pItem = GetEquipedItem( i );
		if( !pItem )
			continue;

		ioHashString szEquipEffect = pItem->GetItemEquipEffect(IsMale());
	
		if( !szEquipEffect.IsEmpty() )
		{
			// 기존에 있을수 있으므로 종료후 다시 적용
			EndEffect( szEquipEffect, false );
			AttachEffect( szEquipEffect );
		}
	}
}

void ioBaseChar::RestroeAllEquipItemCustomize()
{
	m_pEquipSlot->RestoreWeaponCustomize();
	m_pEquipSlot->RestoreArmorCustomize();
	m_pEquipSlot->RestoreHelmetCustomize();
	m_pEquipSlot->RestoreCloakCustomize();
}

bool ioBaseChar::CheckEnableLandAttackByGravity( float fGravity )
{
	if( m_fCurGravityGapAmt < fGravity )
		return false;

	ioAttackableItem *pItem = GetPriorityItemByAttackType( AT_JUMP_ATTACK );

	if( m_CurJumpType == JT_LAND_ATTACK_JUMP) 
	{
		if( m_bUsedJumpAttack && !m_bObjectItemJumpAttack && !m_bUsedBuffJumpAttack )
			return true;
	}
	else if( pItem && m_CurJumpType == JT_GRAPPLING_EXPANSION_JUMP) 
	{
		ioExtendJump *pExtendJump = pItem->GetCurExtendJump();

		ioGrapplingExpansionJump *pGrapplerExpasionItem = ToGrapplingExpansionJump( pExtendJump );
		if( pGrapplerExpasionItem && pGrapplerExpasionItem->IsEnableLandAttack() )
		{
			if( m_bUsedJumpAttack && !m_bObjectItemJumpAttack && !m_bUsedBuffJumpAttack )
				return true;
		}
	}
	else if( m_CurJumpType == JT_POWER_CHARGE_JUMP )
	{
		ioPowerChargeJump *pPower = ToPowerChargeJump( pItem->GetCurExtendJump() );
		if( pPower && pPower->IsUseLandJumpAttack() )
		{
			if( m_bUsedJumpAttack && !m_bObjectItemJumpAttack && !m_bUsedBuffJumpAttack )
				return true;
		}
	}
	else if( m_CurJumpType == JT_CHARGE_COMBO3 )
	{
		ioChargeComboJump3 *pChargeCombo3 = ToChargeComboJump3( pItem->GetCurExtendJump() );
		if( pChargeCombo3 && pChargeCombo3->IsUseLandJumpAttack() )
		{
			if( m_bUsedJumpAttack && !m_bObjectItemJumpAttack && !m_bUsedBuffJumpAttack )
				return true;
		}
	}
	else if( pItem && m_CurJumpType == JT_COLLECT_JUMP )
	{
		ioCollectJump *pCollectJump = ToCollectJump( pItem->GetCurExtendJump() );
		if( pCollectJump && pCollectJump->GetJumpAttackType() == ioCollectJump::JAT_LAND )
		{
			if( m_bUsedJumpAttack && !m_bObjectItemJumpAttack && !m_bUsedBuffJumpAttack )
				return true;
		}
	}
	else if( pItem && m_CurJumpType == JT_DOUBLE_JUMP )
	{
		ioDoubleJump *pDouble = ToDoubleJump( pItem->GetCurExtendJump() );
		if( pDouble && pDouble->IsUseLandJumpAttack() )
		{
			if( m_bUsedJumpAttack && !m_bObjectItemJumpAttack && !m_bUsedBuffJumpAttack )
				return true;
		}
	}
	else if( pItem && m_CurJumpType == JT_HIGH_JUMP )
	{
		ioHighJump *pHigh = ToHighJump( pItem->GetCurExtendJump() );
		if( pHigh && pHigh->IsUseLandJumpAttack() )
		{
			if( m_bUsedJumpAttack && !m_bObjectItemJumpAttack && !m_bUsedBuffJumpAttack )
			{
				return true;
			}
		}
	}
	else if( pItem && m_CurJumpType == JT_GWONWANG_JUMP) // 권왕 2020-06-03
	{
		ioExtendJump *pExtendJump = pItem->GetCurExtendJump();

		ioGwonwangJump *pGwonwangJump = ToGwonwangJump( pExtendJump );
		if( pGwonwangJump && pGwonwangJump->IsEnableLandAttack() )
		{
			if( m_bUsedJumpAttack && !m_bObjectItemJumpAttack && !m_bUsedBuffJumpAttack )
				return true;
		}
	}

	return false;
}

float ioBaseChar::GetCharGravity()
{
	float fGravity = 0.0f;
	if( m_pCreator )
	{
		float fBuffGravityRate = FLOAT1;
		if( m_CharState == CS_JUMP && m_JumpState == JS_JUMPPING )
		{
			if( m_UsedBuffMultiFlyJump != BJUT_NONE )
			{
				if( !m_vBuffMultiFlyJumpInfoList.empty() )
				{
					if( m_UsedBuffMultiFlyJump == BJUT_CUR )
						fBuffGravityRate = m_vBuffMultiFlyJumpInfoList[0].m_fBuffJumpExtraGravityRate;
					else if( m_UsedBuffMultiFlyJump == BJUT_USED )
						fBuffGravityRate = m_vBuffMultiFlyJumpInfoList[0].m_fBuffJumpGravityRate;
				}
			}
			else if( m_UsedBuffFlyJump == BJUT_CUR || m_UsedBuffFlyJump == BJUT_CONTINUE )
			{
				if( !m_vBuffFlyJumpInfoList.empty() )
					fBuffGravityRate = m_vBuffFlyJumpInfoList[0].m_fBuffJumpGravityRate;
			}
			else if( m_UsedBuffJump == BJUT_CUR )
			{
				if( !m_vBuffJumpInfoList.empty() )
					fBuffGravityRate = m_vBuffJumpInfoList[0].m_fBuffJumpGravityRate;
			}
			else if( m_UsedBuffFlyJump == BJUT_WALK )
			{
				if( !m_vBuffFlyJumpInfoList.empty() )
					fBuffGravityRate = m_vBuffFlyJumpInfoList[0].m_fBuffJumpGravityRate;
			}
		}

		fGravity = m_pCreator->GetRoomGravity() * fBuffGravityRate * GetBuffGravityRate();
		fGravity *= m_fSylphidJumpGravityRate;
	}

	return fGravity;
}

bool ioBaseChar::IsEnableTeamAttack()
{
	if( IsNpcChar( this ) ) 
		return false;

	if( m_pModeParent && m_pModeParent->IsTeamAttackMode() ) 
		return true;

	if( g_BattleRoomMgr.IsBattleRoom() &&
		m_pModeParent &&
		m_pModeParent->GetModeType() != MT_TRAINING		&&
		m_pModeParent->GetModeType() != MT_MYROOM		&&
		m_pModeParent->GetModeType() != MT_HEADQUARTERS	&&
		m_pModeParent->GetModeType() != MT_HOUSE		&&
		g_BattleRoomMgr.IsUseExtraOption() )
	{
		int iType = g_BattleRoomMgr.GetTeamAttackType();
		return g_RoomOptionMgr.CheckEnableTeamAttack( iType );
	}

	return false;
}

bool ioBaseChar::IsEnableTeamDamage()
{
	if( IsNpcChar( this ) ) 
		return false;

	if( m_pModeParent && m_pModeParent->IsTeamDamageMode() )
		return true;

	if( g_BattleRoomMgr.IsBattleRoom() &&
		m_pModeParent &&
		m_pModeParent->GetModeType() != MT_TRAINING		&&
		m_pModeParent->GetModeType() != MT_MYROOM		&&
		m_pModeParent->GetModeType() != MT_HEADQUARTERS	&&
		m_pModeParent->GetModeType() != MT_HOUSE		&&
		g_BattleRoomMgr.IsUseExtraOption() )
	{
		int iType = g_BattleRoomMgr.GetTeamAttackType();
		return g_RoomOptionMgr.CheckEnableTeamDamage( iType );
	}

	return false;
}

