bool ioBaseChar::IsEnableTarget( bool bCheckHide /*= true */, bool bCheckState /*= true */ )
{
	//그외
	if ( bCheckState )
	{
		switch( GetState() )
		{
		case CS_SKIP_STUN:
		case CS_ADHESIVE_BUFF:
			return false;
		}
	}

	if( IsExcavating() ) 
		return false;

	if( GetExperienceMode() == EMS_EXPERIENCE ) 
		return false;

	if( IsChatModeState( false ) )
		return false;

	if( HasHideBuff() )
		return false;

	if( IsSkipState() )
		return false;

	if( Help::CheckTargetNoCollision( GetState() ) )
		return false;

	if( !HasCollisionAvailableBuff() )
		return false;

	if( !CheckGrapplingExceptionState() )
		return false;

	if( bCheckHide && !IsVisibleChar() )
		return false;

	if( GetCreator() && !GetCreator()->IsCollisionCheckByMode() )
		return false;

	ioMephistoItem* pMephistoItem = ToMephistoItem( GetPriorityItem( SPT_ATTACK ) );
	if( pMephistoItem && pMephistoItem->IsFlyState() )
		return false;

	if( HasChangeTeamBuff( true ) )
	{
		iolupinItem *pLupinItem = ToLupinItem( m_pEquipSlot->GetWeapon() );
		if( pLupinItem )
			return false;
	}

	return true;
}

void ioBaseChar::CheckRefreshExtendDashState()
{
	ioAttackableItem *pItem = GetPriorityItem( SPT_DASH );
	if( pItem )
	{
		ioSimpleDash *pSimpleDash = ToSimpleDash( pItem->GetCurExtendDash() );
		if( pSimpleDash )
		{
			pSimpleDash->CheckRefreshDashAction( this );
		}
	}
}

void ioBaseChar::CheckExcavatingState()
{
	ioExcavationItem *pExcavationItem = ToExcavationItem( GetObject() );
	if( !pExcavationItem )	
		return;

	if( pExcavationItem->GetAniType() == ioExcavationItem::AT_EXCAVATING_STRT )
	{
		if( pExcavationItem->IsVisible() )
		{
			pExcavationItem->SetVisible( this, false );
			if( m_pGroup )
			{
				m_pGroup->SetEntityVisible( pExcavationItem->GetEquipMesh(this), false );
				m_pGroup->HideMeshExceptionCheck( pExcavationItem->GetEquipMesh(this) );
			}
			pExcavationItem->SetExcavatingToolMesh( this, true );
		}
	}

	if( !pExcavationItem->IsAnimationEndTime( this ) ) 
	{
		return;
	}

	switch( pExcavationItem->GetAniType() )
	{
	case ioExcavationItem::AT_EXCAVATING_STRT:
		{
			pExcavationItem->SetExcavatingAni( this );
			return;
		}
		break;
	case ioExcavationItem::AT_RESULT_FAIL:
	case ioExcavationItem::AT_RESULT_SUCCESS:
		{
			if( IsOwnerChar() && pExcavationItem->GetAniType() == ioExcavationItem::AT_RESULT_FAIL )
			{
				g_ExcavationMgr.SetChargingState();
			}

			pExcavationItem->SetResultEquipAni( this );

			if( pExcavationItem->CheckChangeMesh() )
			{
				ioHashString szName = GetCharName();
				g_ExcavationMgr.SetExcavation( szName, false );
				g_ExcavationMgr.SetExcavation( szName, true );
			}

			pExcavationItem = ToExcavationItem( GetObject() );
			if( !pExcavationItem )
				return;

			// searcing tool show
			if( !pExcavationItem->IsVisible() )
			{
				pExcavationItem->SetVisible( this, true );
				if( m_pGroup )
				{
					m_pGroup->SetEntityVisible( pExcavationItem->GetEquipMesh(this), true );
				}
				pExcavationItem->SetExcavatingToolMesh( this, false );
			}

			if( !IsOwnerChar() )
			{
				SetLongTimeLiveEmoticonAndScale( g_ExcavationMgr.GetExcavatingEmoticon(), false );
			}
			return;
		}
		break;
	}

	if( pExcavationItem->GetAniType() != ioExcavationItem::AT_RELEASE )
	{
		pExcavationItem->ClearAniInfo();
		SetState( CS_DELAY );
		return;
	}

	// release
	pExcavationItem->ClearAniInfo();

	if( m_pEquipSlot )
	{
		ioItem *pItem =	m_pEquipSlot->ReleaseObjectSlot();
		if( pItem )	
		{
			SAFEDELETE( pItem );
		}
	}

	SetExcavating( false );
	SetState( CS_DELAY );

	DestroyExcavationGuide();
	DestroyExcavationPoint();
	//
}

void ioBaseChar::ClearExcavatingState()
{
	if( !m_bExcavating )
		return;

	ioExcavationItem *pExcavationItem = ToExcavationItem( GetObject() );
	if( !pExcavationItem )	
		return;

	// searcing tool show
	if( !pExcavationItem->IsVisible() )
	{
		pExcavationItem->SetVisible( this, true );
		if( m_pGroup )
			m_pGroup->SetEntityVisible( pExcavationItem->GetEquipMesh(this), true );
		pExcavationItem->SetExcavatingToolMesh( this, false );
	}

	if( pExcavationItem->GetAniType() == ioExcavationItem::AT_RELEASE )
	{
		pExcavationItem->ClearAniInfo();
		ReleaseObjectItem( __FUNCTION__, CS_DELAY );
		//OnReleaseObjectItem( CS_DELAY );
		SetExcavating( false );
	}
}

