void ioBaseChar::CheckCharColSkipTime( int iAniID, float fTimeRate, DWORD dwPreDelay )
{
	ClearCharColSkipTime();

	DWORD dwCurTime = FRAMEGETTIME();

	float fColSkipS = 0.0f;
	float fColSkipE = 0.0f;

	AniEventConstPtrList vColSkipList;
	m_pGroup->GetAnimationEventConstPtrList( iAniID, "col_skip_s", vColSkipList );

	if( vColSkipList.empty() )
		return;

	AniEventConstPtrList::iterator iter = vColSkipList.begin();
	if( iter != vColSkipList.end() )
	{
		fColSkipS = (*iter)->fEventTime * fTimeRate;

		if( !(*iter)->szSubInfo.IsEmpty() )
		{
			const StringVector &vParam = ioStringConverter::Split( (*iter)->szSubInfo.c_str(), " " );
			if( vParam.size() == 1 )
			{
				m_dwCharColSkipType = (DWORD)ioStringConverter::ParseInt( vParam[0].c_str() );

				if( (m_dwCharColSkipType%10) == 1 )
					m_bOnlyTeamCharColSkip = true;
			}
		}
	}

	fColSkipE = m_pGroup->GetAnimationEventTime_e( iAniID, "col_skip_e" ) * fTimeRate;

	if( fColSkipS > 0.0f && fColSkipE > 0.0f )
	{
		fColSkipS += dwCurTime + dwPreDelay;
		fColSkipE += dwCurTime + dwPreDelay;

		SetCharCollisionSkipTime( (DWORD)fColSkipS, (DWORD)fColSkipE, m_bOnlyTeamCharColSkip );
	}
}

