void ioBaseChar::SetBoundWoundedState( float fBoundJump,
									   float fBoundForce,
									   float fBoundGravity,
									   float fBoundDamage,
									   bool bGetUpState )
{
	CheckWearItemDrop();

	m_UsedBuffJump = BJUT_NONE;
	m_UsedBuffFlyJump = BJUT_NONE;
	m_UsedBuffMultiFlyJump = BJUT_NONE;

	m_bBlowEndAni = false;

	if( m_pCreator && m_pCreator->CheckRoomFastGetUp() )
		bGetUpState = true;

	m_bJumpedBlowWounded = true;

	m_fBoundBlowJumpAmt = fBoundJump;
	m_fBoundBlowForceAmt = fBoundForce;
	m_fBoundBlowGravityRate = fBoundGravity;
	m_fBoundBlowBoundDamage = fBoundDamage;
	m_fPreBoundBlowJumpAmt = fBoundJump;
	m_fPreBoundBlowForceAmt = fBoundForce;

	if( m_bPrisonerMode || m_bCatchState )
	{
		m_CurBlowWoundAction = m_AniBoundRopeBlow;
		m_CurBlowDownAction = m_AniRopeBlowDown;
	}
	else if( m_AttackedSide == AS_BACK )
	{
		m_CurBlowWoundAction = m_AniBoundBlowBackAction;
		m_CurBlowDownAction = m_AniBoundDownBackAction;
	}
	else
	{
		m_CurBlowWoundAction = m_AniBoundBlowAction;
		m_CurBlowDownAction = m_AniBoundDownAction;
	}

	m_pGroup->ClearAllActionAni( FLOAT100, true );
	m_pGroup->ClearAllLoopAni( FLOAT100, true );

	DWORD dwCurTime = FRAMEGETTIME();
	if( m_bJumpedBlowWounded )		// 공중 피격상황
	{
		int iAniID = m_pGroup->GetAnimationIdx( m_CurBlowWoundAction );
		DWORD dwKOAniTime = m_pGroup->GetAnimationFullTime( iAniID );

		m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1, 0.0f, 0.0f, true );
		m_AnimationTime.dwStartTime = dwCurTime;
		m_AnimationTime.dwFullTime  = dwKOAniTime;
		m_dwBlowAniEndTime = dwCurTime + dwKOAniTime;
	}

	if( m_bPrisonerMode )
		m_dwMaxBlowWoundedGetUpTime = m_dwPrisonerBlowWoundedGetUpTime * m_fBlowGetUpTimeRate;
	else if( m_bCatchState )
		m_dwMaxBlowWoundedGetUpTime = m_dwCatchedBlowWoundedGetUpTime * m_fBlowGetUpTimeRate;
	else
		m_dwMaxBlowWoundedGetUpTime = m_dwGeneralBlowWoundedGetUpTime * m_fBlowGetUpTimeRate;

	if( m_bUseGetUpTimeRefresh )
	{
		m_dwCurBlowGetUpTime = m_dwMaxBlowWoundedGetUpTime;

		float fRate = GetMemberBalanceRateForBlowTime( GetTeam() );
		if( fRate > 0.0f )
			m_dwCurBlowGetUpTime *= fRate;

		m_dwCurBlowGetUpTime *= GetGetUpRateOnBuff();

		m_dwBlowGetUpCheckStartTime = 0;
		m_dwGetUpDurationTime = 0;
	}
	else if( m_BlowTargetType == BTT_FLATTEN )
	{
		if( !HasBuff( BT_FLAME_STATUE ) )
		{
			m_dwCurBlowGetUpTime = m_dwMaxBlowWoundedGetUpTime;

			float fRate = GetMemberBalanceRateForBlowTime( GetTeam() );
			if( fRate > 0.0f )
				m_dwCurBlowGetUpTime *= fRate;

			m_dwCurBlowGetUpTime *= GetGetUpRateOnBuff();
		}

		m_dwBlowGetUpCheckStartTime = 0;
		m_dwGetUpDurationTime = 0;
	}
	else
	{
		if( !bGetUpState && m_dwBlowGetUpCheckStartTime == 0 )
		{
			if( !HasBuff( BT_FLAME_STATUE ) )
			{
				m_dwCurBlowGetUpTime = m_dwMaxBlowWoundedGetUpTime;

				float fRate = GetMemberBalanceRateForBlowTime( GetTeam() );
				if( fRate > 0.0f )
					m_dwCurBlowGetUpTime *= fRate;

				m_dwCurBlowGetUpTime *= GetGetUpRateOnBuff();

				m_dwCurBlowGetUpTime = max( 0, m_dwCurBlowGetUpTime );
			}

			m_dwGetUpDurationTime = 0;

			if( bGetUpState )
			{
				m_dwBlowGetUpCheckStartTime = dwCurTime;
				m_dwCurBlowGetUpTime = 0;
			}
		}
	}

	ClearAttackFireTimeAndSkill();
	ClearReservedSliding();

	CheckFastGetup();

	SetState( CS_BOUND_BLOW_WOUNDED );

	// Check RotationWeapon
	g_WeaponMgr.RemoveRotationWeaponByWound( GetCharName() );

	m_dwPreBackAttackedTime = 0;
	m_iBackAttackedCnt = 0;	

	if( m_bJumpedBlowWounded )
		m_BlowState = BW_BLOWING;
	else
		m_BlowState = BW_BOUND_BLOWING;

	// Flatten
	if( m_BlowTargetType != BTT_FLATTEN )
	{
		D3DXVECTOR3 vCurScale = GetWorldScale();
		if( vCurScale.x != vCurScale.y )
		{
			vCurScale.y = vCurScale.x;
			SetWorldScale( vCurScale );
		}
	}
}

void ioBaseChar::CheckBoundBlowWoundedState()
{
	DWORD dwCurTime = FRAMEGETTIME();

	CheckWearItemDrop();

	if( m_BlowState != BW_GETUP && CheckBlowWoundSkill() )
	{
		// 스킬상태로 전환됨
		return;
	}
	else if( m_BlowState == BW_BLOW_ENDED )
	{
		if( CheckDownSkill() )	// 스킬로 전환
			return;
	}

	ioAttackableItem* pItem = GetPriorityItem( SPT_ATTACK );
	if( pItem && pItem->IsWoundAfterUseExtendState() )
	{
		//피격중 용병 특별 사용
		if( pItem->CheckWoundAfterUseExtendState( this, m_BlowTargetType ) )
			return;
	}

	switch( m_BlowState )
	{
	case BW_BLOWING:
		if( IsDownState() && !IsFloating() )	// 쓰러져서 바닥에 쿵하고 부딪히는 상태
		{
			int iAniID = -1;

			if( m_bPrisonerMode || m_bCatchState )
			{
				iAniID = m_pGroup->GetAnimationIdx( m_AniBoundRopeBlow2 );
			}
			else
			{
				if( m_AttackedSide == AS_BACK )
					iAniID = m_pGroup->GetAnimationIdx(m_AniBoundBlowBackAction2);
				else
					iAniID = m_pGroup->GetAnimationIdx(m_AniBoundBlowAction2);
			}

			m_pGroup->ClearAllActionAni( 0.0f, true );
			m_pGroup->ClearAllLoopAni( 0.0f, true );
			m_pGroup->SetActionAni( iAniID, 0.0f, FLOAT100, FLOAT1, FLOAT1, 0.0f, 0.0f, true );

			// 모션 바꾸면서 튀어오르기, 밀림주기
			m_fGravityAmt = 0.0f;
			m_fCurJumpPowerAmt = 0.0f;
			m_fCurGravityGapAmt = 0.0f;
			m_bCurFrameDrop = false;

			SetJumpPower( m_fBoundBlowJumpAmt );
			SetForcePowerAmt( m_fBoundBlowForceAmt );

			if( !m_vBoundBlowGravityAmt.empty() )
			{
				m_iBoundBlowGravityAmtIndex = min( m_iBoundBlowGravityAmtIndex, (int)m_vBoundBlowGravityAmt.size() - 1 );
				m_fGravityAmt = m_vBoundBlowGravityAmt[m_iBoundBlowGravityAmtIndex];
				m_iBoundBlowGravityAmtIndex++;
			}

			if( !m_bHideFootDustEffect )
				AttachEffect( "sp2_knock_down_dust.txt" );

			// Damage 처리
			ioBaseChar *pAttacker = m_pCreator->GetBaseChar( m_LastAttackerName );

			if( m_pModeParent->GetModeState() == ioPlayMode::MS_RESULT )
				m_fBoundBlowBoundDamage = 0.0f;

			if( IsDamageProtect() )
				m_fBoundBlowBoundDamage = 0.0f;

			if( m_bPrisonerMode || IsChatModeState( false ) )
				m_fBoundBlowBoundDamage = 0.0f;

			ApplyDamage( m_fBoundBlowBoundDamage, false );

			if( pAttacker && m_fBoundBlowBoundDamage > 0.0f )
			{
				pAttacker->CheckComboSkillHit();
				pAttacker->CheckAttackCnt( this );
				m_pModeParent->DamageContribute( GetLastAttackerName(), GetCharName(), m_fBoundBlowBoundDamage, GetLastAttackerItemCode() );
			}

			CheckExplosionItemWoundedDrop( m_vMoveDir, false );

			if( IsNeedProcess() )
			{
				if( CheckBoundDie() )
				{
					return;
				}
			}

			m_AnimationTime.dwStartTime = 0;
			m_AnimationTime.dwFullTime  = 0;

			m_BlowState = BW_BOUND_BLOWING;
			m_bJumpedBlowWounded = true;
			m_bBlowEndAni = false;
		}
		break;
	case BW_BOUND_BLOWING:
		if( m_bJumpedBlowWounded )
		{
			if( !m_bBlowEndAni )
			{
				if( IsDownState() && !IsFloating() )	// 쓰러져서 바닥에 쿵하고 부딪히는 상태
				{
					int iAniID = CheckBlowEndAni();

					m_pGroup->ClearAllActionAni( 0.0f, true );
					m_pGroup->ClearAllLoopAni( 0.0f, true );
					m_pGroup->SetActionAni( iAniID, 0.0f, FLOAT100, FLOAT1, FLOAT1, 0.0f, 0.0f, true );

					m_AnimationTime.dwStartTime = 0;
					m_AnimationTime.dwFullTime  = 0;

					m_BlowState = BW_BLOW_ENDED;
				}
				else
				{
					if( m_dwBlowAniEndTime + m_dwActionStopTotalDelay < dwCurTime && !IsFloating() )
					{
						int iAniID = CheckBlowEndAni();

						m_pGroup->ClearAllActionAni( 0.0f, true );
						m_pGroup->ClearAllLoopAni( 0.0f, true );
						m_pGroup->SetActionAni( iAniID, 0.0f, FLOAT100, FLOAT1, FLOAT1, 0.0f, 0.0f, true );

						m_AnimationTime.dwStartTime = 0;
						m_AnimationTime.dwFullTime  = 0;

						m_BlowState = BW_BLOW_ENDED;
					}
				}
			}
			else
			{
				if( m_dwBlowAniEndTime < dwCurTime )
				{
					m_AnimationTime.dwStartTime = 0;
					m_AnimationTime.dwFullTime  = 0;

					m_BlowState = BW_BLOW_ENDED;
				}
			}
		}
		else
		{
			if( m_dwBlowAniEndTime + m_dwActionStopTotalDelay < dwCurTime && !IsFloating() )
			{
				m_AnimationTime.dwStartTime = 0;
				m_AnimationTime.dwFullTime  = 0;

				m_BlowState = BW_BLOW_ENDED;
			}
		}

		if( m_BlowState == BW_BLOW_ENDED )
		{
			if( m_dwBlowGetUpCheckStartTime == 0 )
			{
				m_dwBlowGetUpCheckStartTime = max( dwCurTime, m_AnimationTime.EndTime() );
			}

			m_dwBlowAniEndTime = 0;
			m_dwStickCheckTime = 0;

			#ifndef SHIPPING
			if( Setting::ShowExtraInfo() )
			{
				LOG.PrintTimeAndLog( 0, "ShowGetUp - %s, BlowEndState: %d", m_Name.c_str(), dwCurTime );
			}
			#endif

			if( !m_bHideFootDustEffect )
				AttachEffect( "sp2_knock_down_dust.txt" );
			m_iFloatingWoundedCnt = 0;
		}
		break;
	case BW_BLOW_ENDED:	// 바닥에 떨어진 시점부터 - 일어나기 전까지
		if( IsNeedProcess() )
		{
			bool bLeft = m_KeyInput.IsLeftKeyPress();
			bool bRight = m_KeyInput.IsRightKeyPress();
			DWORD dwPreGap = 0;

			if( bLeft || bRight || IsShowGetUpStick2() )
			{
				if( m_dwCurBlowGetUpTime > 0 && dwCurTime > m_dwBlowGetUpCheckStartTime )
				{
					bool bEnableCheck = false;
					if( bLeft && bRight )
					{
						if( m_dwStickCheckTime > 0 )
							dwPreGap = dwCurTime - m_dwStickCheckTime;
					}
					else if( m_dwStickCheckTime == 0 )
					{
						m_dwStickCheckTime = dwCurTime;
						bEnableCheck = true;

						if( bLeft )
							m_bPreLeftInput = true;
						else
							m_bPreLeftInput = false;
					}
					else
					{
						dwPreGap = dwCurTime - m_dwStickCheckTime;

						if( m_dwStickCheckTime+m_dwStickTicTime < dwCurTime )
						{
							if( m_bPreLeftInput && bRight )
							{
								bEnableCheck = true;
								m_dwStickCheckTime = dwCurTime;

								m_bPreLeftInput = false;
							}
							else if( !m_bPreLeftInput && bLeft )
							{
								bEnableCheck = true;
								m_dwStickCheckTime = dwCurTime;

								m_bPreLeftInput = true;
							}
						}
					}

					if( IsShowGetUpStick2() )
						bEnableCheck = true;

					if( bEnableCheck )
					{
						float fFastGetUp = g_StatAttribute.GetCalcStatAttribute( (float)m_dwFastGetupValue,
							SA_DEX_FASTGETUP_SPEED_UP,
							this );

						DWORD dwBlowGapTime = dwCurTime - m_dwBlowGetUpCheckStartTime;
						if( HasBuff( BT_FLAME_STATUE ) )
						{
							if( dwBlowGapTime > m_dwFlameMinTime )
							{
								if( m_dwCurBlowGetUpTime > m_dwFastGetupValue )
									m_dwCurBlowGetUpTime -= m_dwFastGetupValue;
								else
									m_dwCurBlowGetUpTime = 0;
							}
						}
						else if( IsShowGetUpStick2() &&
							(m_KeyInput.IsAttackKeyDown() ||
							m_KeyInput.IsDefenseKeyDown() ||
							m_KeyInput.IsJumpKeyDown() ||
							m_KeyInput.IsSettedDirection()) )
						{
							m_dwCurBlowGetUpTime = 0;
						}
					}
				}
			}

			if( m_bFastGetUp || m_dwBlowGetUpCheckStartTime+m_dwCurBlowGetUpTime <= dwCurTime )
			{
				SetBlowWoundedGetUp();

				if( IsNeedSendNetwork() )
				{
					SP2Packet kPacket( CUPK_BLOW_GET_UP );
					kPacket << GetCharName();
					P2PNetwork::SendToAllPlayingUser( kPacket );
				}
			}
		}

		//m_iBoundBlowGravityAmtIndex = 0;
		break;
	case BW_GETUP:
		if( m_dwGetUpDurationTime < dwCurTime )
		{
			if( !m_bUseGetUpTimeRefresh )
				m_dwBlowGetUpCheckStartTime = 0;

			SetState( CS_DELAY );
			SetDashFailStart();

			if( m_ProtectionMode == PM_NONE )
			{
				SetProtectionMode( PM_GETUP, GetBlowStateProtectionTime(), false );
			}
		}
		break;
	}
}

void ioBaseChar::SetBlowExtendWoundedState( const ioHashString& szExtendWoundAni,
										    DWORD dwExtendWoundDuration,
										    float fExtendWoundJump,
										    float fExtendWoundForce,
											float fDefenseRate,
											bool bWoundAniLoop )
{
	CheckWearItemDrop();

	m_UsedBuffJump = BJUT_NONE;
	m_UsedBuffFlyJump = BJUT_NONE;
	m_UsedBuffMultiFlyJump = BJUT_NONE;

	m_bBlowEndAni = false;

	m_ExtendWoundAni = szExtendWoundAni;
	m_dwExtendWoundDuration = dwExtendWoundDuration;

	m_fExtendWoundJumpAmt = fExtendWoundJump;
	m_fExtendWoundForceAmt = fExtendWoundForce;

	m_pGroup->ClearAllActionAni( FLOAT100, true );
	m_pGroup->ClearAllLoopAni( FLOAT100, true );

	DWORD dwCurTime = FRAMEGETTIME();
	
	if( m_AttackedSide == AS_BACK )
	{
		m_CurBlowWoundAction = m_AniBlowExtendWoundBackAction;
		m_CurBlowDownAction.Clear();
	}
	else
	{
		m_CurBlowWoundAction = m_AniBlowExtendWoundAction;
		m_CurBlowDownAction.Clear();
	}

	int iAniID = m_pGroup->GetAnimationIdx( m_CurBlowWoundAction );
	DWORD dwKOAniTime = m_pGroup->GetAnimationFullTime( iAniID );

	m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1, 0.0f, 0.0f, true );
	m_AnimationTime.dwStartTime = dwCurTime;
	m_AnimationTime.dwFullTime  = dwKOAniTime;
	m_dwBlowAniEndTime = dwCurTime + dwKOAniTime;

	ClearAttackFireTimeAndSkill();
	ClearReservedSliding();

	SetState( CS_BLOW_EXTEND_WOUND );

	m_dwPreBackAttackedTime = 0;
	m_iBackAttackedCnt = 0;	

	m_BlowState = BW_BLOWING;

	// Check RotationWeapon
	g_WeaponMgr.RemoveRotationWeaponByWound( GetCharName() );

	// Flatten
	if( m_BlowTargetType != BTT_FLATTEN )
	{
		D3DXVECTOR3 vCurScale = GetWorldScale();
		if( vCurScale.x != vCurScale.y )
		{
			vCurScale.y = vCurScale.x;
			SetWorldScale( vCurScale );
		}
	}
}

void ioBaseChar::CheckBlowExtendWoundedState()
{
	DWORD dwCurTime = FRAMEGETTIME();

	CheckWearItemDrop();

	if( m_BlowState != BW_GETUP && CheckBlowWoundSkill() )
	{
		// 스킬상태로 전환됨
		return;
	}

	//피격중 용병 특별 사용
	ioAttackableItem* pItem = GetPriorityItem( SPT_ATTACK );
	if( pItem && pItem->IsWoundAfterUseExtendState() )
	{
		//피격중 용병 특별 사용
		if( pItem->CheckWoundAfterUseExtendState( this, m_BlowTargetType ) )
			return;
	}

	switch( m_BlowState )
	{
	case BW_BLOWING:
		if( IsDownState() && !IsFloating() )	// 쓰러져서 바닥에 쿵하고 부딪히는 상태
		{
			int iAniID = -1;

			// 지상 피격 상태로 전환
			m_AnimationTime.dwStartTime = 0;
			m_AnimationTime.dwFullTime  = 0;

			m_BlowState = BW_NONE;
			m_bJumpedBlowWounded = false;
			m_bBlowEndAni = false;

			m_fGravityAmt = 0.0f;
			m_fCurJumpPowerAmt = 0.0f;
			m_fCurGravityGapAmt = 0.0f;
			m_bCurFrameDrop = false;

			SetJumpPower( m_fExtendWoundJumpAmt );
			SetForcePowerAmt( m_fExtendWoundForceAmt );

			SetWoundedState( m_ExtendWoundAni, m_dwExtendWoundDuration, m_fExtendWoundDefenseRate, m_bExtendWoundLoop, false );
			return;
		}
		break;
	}
}

void ioBaseChar::SetDashAttackEndJumpInfo( int iAniID, float fTimeRate, DWORD dwPreDelay )
{
	m_dwDashAttackEndTime = 0;
	m_fDashAttackEndJumpAmt = 0.0f;

	AniEventConstPtrList vAttackEndList;
	m_pGroup->GetAnimationEventConstPtrList( iAniID, "attack_end", vAttackEndList );

	if( vAttackEndList.empty() )
		return;

	DWORD dwCurTime = FRAMEGETTIME();

	AniEventConstPtrList::iterator iter = vAttackEndList.begin();
	while( iter != vAttackEndList.end() )
	{
		DWORD dwTime = (*iter)->fEventTime * fTimeRate;
		if( dwTime > 0 )
		{
			m_dwDashAttackEndTime = dwTime;
			m_dwDashAttackEndTime += dwCurTime;
			m_dwDashAttackEndTime += dwPreDelay;

			if( !(*iter)->szSubInfo.IsEmpty() )
			{
				const StringVector &vParam = ioStringConverter::Split( (*iter)->szSubInfo.c_str(), " " );
				if( vParam.size() == 1 )
				{
					m_fDashAttackEndJumpAmt = ioStringConverter::ParseFloat( vParam[0].c_str() );
				}
			}

			break;
		}

		++iter;
	}
}

void ioBaseChar::SetExtendAttackEndJumpInfo( int iAniID, float fTimeRate, DWORD dwPreDelay )
{
	m_dwExtendAttackEndTime = 0;
	m_fExtendAttackEndJumpAmt = 0.0f;

	AniEventConstPtrList vAttackEndList;
	m_pGroup->GetAnimationEventConstPtrList( iAniID, "attack_end", vAttackEndList );

	if( vAttackEndList.empty() )
		return;

	DWORD dwCurTime = FRAMEGETTIME();

	AniEventConstPtrList::iterator iter = vAttackEndList.begin();
	while( iter != vAttackEndList.end() )
	{
		DWORD dwTime = (*iter)->fEventTime * fTimeRate;

		m_dwExtendAttackEndTime = dwTime;
		m_dwExtendAttackEndTime += dwCurTime;
		m_dwExtendAttackEndTime += dwPreDelay;

		if( !(*iter)->szSubInfo.IsEmpty() )
		{
			const StringVector &vParam = ioStringConverter::Split( (*iter)->szSubInfo.c_str(), " " );
			if( vParam.size() == 1 )
			{
				m_fExtendAttackEndJumpAmt = ioStringConverter::ParseFloat( vParam[0].c_str() );
			}
		}

		break;

		++iter;
	}
}

void ioBaseChar::SetBaseAttackExtraAniJump( int iAniID, float fTimeRate, DWORD dwPreDelay )
{
	m_iCurExtraAniJump = 0;
	m_dwExtraAniJumpTime = 0;
	m_fExtraAniJumpPower = 0.0f;
	m_vExtraAniJumpList.clear();

	AniEventConstPtrList vExtraAniJumpList;
	m_pGroup->GetAnimationEventConstPtrList( iAniID, "extra_ani_jump", vExtraAniJumpList );

	if( vExtraAniJumpList.empty() )
		return;

	DWORD dwCurTime = FRAMEGETTIME();

	AniEventConstPtrList::iterator iter = vExtraAniJumpList.begin();
	while( iter != vExtraAniJumpList.end() )
	{
		ExtraAniJump kInfo;

		kInfo.m_dwTime = (*iter)->fEventTime * fTimeRate;
		kInfo.m_dwTime += dwCurTime;
		kInfo.m_dwTime += dwPreDelay;

		if( !(*iter)->szSubInfo.IsEmpty() )
		{
			const StringVector &vParam = ioStringConverter::Split( (*iter)->szSubInfo.c_str(), " " );
			if( vParam.size() == 1 )
			{
				kInfo.m_fPower = ioStringConverter::ParseFloat( vParam[0].c_str() );
			}
		}

		m_vExtraAniJumpList.push_back(kInfo);

		++iter;
	}

	if( !m_vExtraAniJumpList.empty() )
	{
		m_iCurExtraAniJump = 0;
		m_dwExtraAniJumpTime = m_vExtraAniJumpList[m_iCurExtraAniJump].m_dwTime;
		m_fExtraAniJumpPower = m_vExtraAniJumpList[m_iCurExtraAniJump].m_fPower;
	}
}

void ioBaseChar::CheckExtraAniJump()
{
	if( m_vExtraAniJumpList.empty() ) return;

	DWORD dwCurTime = FRAMEGETTIME();
	if( m_dwExtraAniJumpTime > 0 && m_dwExtraAniJumpTime < dwCurTime )
	{
		if( m_fExtraAniJumpPower > 0.0f )
		{
			SetJumpPower( m_fExtraAniJumpPower );
		}

		m_iCurExtraAniJump++;

		int iSize = m_vExtraAniJumpList.size();
		if( COMPARE(m_iCurExtraAniJump, 0, iSize) )
		{
			m_dwExtraAniJumpTime = m_vExtraAniJumpList[m_iCurExtraAniJump].m_dwTime;
			m_fExtraAniJumpPower = m_vExtraAniJumpList[m_iCurExtraAniJump].m_fPower;
		}
		else
		{
			m_dwExtraAniJumpTime = 0;
			m_fExtraAniJumpPower = 0.0f;
		}
	}
}

bool ioBaseChar::IsMiniHomePageState()
{
	switch( GetState() )
	{
	case CS_DELAY:
	case CS_DIE:
	case CS_ENDMOTION:
	case CS_READY:
	case CS_VIEW:
	case CS_LOADING:
	case CS_SPECIAL_MOTION:
	case CS_ETCITEM_MOTION:
	case CS_OBSERVER:
	case CS_FISHING:
	case CS_DUMMY_STATE:
	case CS_EXCAVATING:
	case CS_CONSTRUCT_HOUSE:
		return true;
	}

	if( IsExcavating() )
		return true;
	return false;
}

