void ioBaseChar::SetAttackSkillGrapplingState( const ioHashString &szTarget )
{
	if( !CheckGrapplingExceptionState() )
		return;

	if( m_CharState != CS_USING_SKILL )
		return;

	if( !m_pActiveSkill )
		return;

	if( !m_pActiveSkill->SetSkillGrapplingState( this, szTarget ) )
		return;

	m_GrapplingTarget = szTarget;
}

void ioBaseChar::SetAttackItemGrapplingState( const ioHashString &szTarget )
{
	if( !CheckGrapplingExceptionState() )
		return;

	ioWeaponItem *pAttackItem = GetWeapon();
	if( !pAttackItem )
		return;

	ioLuciferItem *pLuciferItem = ToLuciferItem( pAttackItem );
	ioNakoruruItem *pNakoruru = ToNakoruruItem( pAttackItem );
	ioMichaelItem *pMichael = ToMichaelItem( pAttackItem );
	ioSuperDimensionItem *pSuperDimensionItem = ToSuperDimensionItem( pAttackItem );
	ioStrikerItem *pStrikerItem = ToStrikerItem( pAttackItem );
	ioJumperItem* pJumperItem = ToJumperItem( pAttackItem );
	ioGrapplingExpansionItem *pGrapplingExpansionItem = ToGrapplingExpansionItem( pAttackItem );
	ioGalfordItem *pGalford = ToGalfordItem( pAttackItem );
	ioGunnerItem *pGunnerItem = ToGunnerItem( pAttackItem );
	ioWarpItem* pWarpItem = ToWarpItem( pAttackItem );
	ioSantaItem* pSantaItem = ToSantaItem( pAttackItem );
	ioAutomatonItem *pAutomatonItem = ToAutomatonItem( pAttackItem );
	ioChangeOnItem* pChangeOn = ToChangeOnItem( pAttackItem );
	ioGwonwangItem* pGwonwangItem = ToGwonwangItem( pAttackItem );	// 권왕 2020-06-03

	if( pLuciferItem )
	{
		if( !( m_CharState == CS_LUCIFER_FLY || m_CharState == CS_JUMP ) )
			return;

		if( !pLuciferItem->SetItemGrapplingState( this, szTarget) )
			return;

		m_GrapplingTarget = szTarget;
	}
	else if( pNakoruru && m_CharState == CS_JUMP )
	{
		if( !pNakoruru->SetItemGrapplingState( this, szTarget ) )
			return;

		m_GrapplingTarget = szTarget;
	}
	else if( pGrapplingExpansionItem && m_CharState == CS_JUMP )
	{
		if( !pGrapplingExpansionItem->SetItemGrapplingState( this, szTarget ) )
			return;

		m_GrapplingTarget = szTarget;
	}
	else if( pMichael && m_CharState == CS_MICHAEL_FLY )
	{
		if( !pMichael->SetItemGrapplingState( this, szTarget ) )
			return;

		m_GrapplingTarget = szTarget;
	}
	else if( pSuperDimensionItem && m_CharState == CS_SUPER_DIMENSION_DASH )
	{
		if( !pSuperDimensionItem->SetItemGrapplingState( this, szTarget) )
			return;

		m_GrapplingTarget = szTarget;
	}
	else if( pStrikerItem )
	{
		ioAttackableItem *pItem = GetPriorityItem( SPT_JUMP );
		if( pItem )
		{
			ioExtendJump *pExtendJump = pItem->GetCurExtendJump();
			if( pExtendJump && ToChargeComboJump3( pExtendJump) && 
				ToChargeComboJump3( pExtendJump )->GetCurChargeComboState() == ioChargeComboJump3::CCS_STRIKER_MOVE_ADD_ATTACK )
			{
				if( !pStrikerItem->SetJumpDashGrapplingState( this, szTarget) )
					return;

				m_GrapplingTarget = szTarget;
			}
		}
	}
	else if( pJumperItem )
	{
		if( !pJumperItem->SetItemGrapplingState( this, szTarget) )
			return;

		m_GrapplingTarget = szTarget;
	}
	else if ( pGalford )
	{
		if( !pGalford->SetItemGrapplingState( this, szTarget) )
			return;

		m_GrapplingTarget = szTarget;
	}
	else if( pGunnerItem )
	{
		if( !pGunnerItem->SetItemGrapplingState( this, szTarget) )
			return;
	}
	else if( pWarpItem )
	{
		if( !pWarpItem->SetItemGrapplingState( this, szTarget) )
			return;

		m_GrapplingTarget = szTarget;
	}
	else if( pSantaItem )
	{
		if( m_CharState != CS_SANTA_SPECIAL )
			return;

		if( !pSantaItem->SetItemGrapplingState( this, szTarget) )
			return;

		m_GrapplingTarget = szTarget;
	}
	else if( pAutomatonItem )
	{
		if( m_CharState != CS_AUTOMATON_SPECIAL )
			return;

		if( !pAutomatonItem->SetItemGrapplingState( this, szTarget) )
			return;

		m_GrapplingTarget = szTarget;
	}
	else if( pChangeOn )
	{
		if( m_CharState != CS_CHANGE_ON_GRIFFIN_FLY )
			return;

		if( !pChangeOn->SetItemGrapplingState( this, szTarget) )
			return;

		m_GrapplingTarget = szTarget;
	}
	else if( pGwonwangItem && m_CharState == CS_JUMP )	// 권왕 2020-06-03
	{
		// 2020-06-09 변신 했을 경우
		if( pGwonwangItem->IsBUsedWereWolf() )
		{
			ioObjectBankruptcyItem* pObjectBankruptcyItem = ToObjectBankruptcyItem( GetObject() );
			if( pObjectBankruptcyItem )
			{
				if( !pObjectBankruptcyItem->SetItemGrapplingState( this, szTarget ) )
					return;
			}
		}
		else
		{
			if( !pGwonwangItem->SetItemGrapplingState( this, szTarget ) )
				return;
		}

		m_GrapplingTarget = szTarget;
	}
}

bool ioBaseChar::SetItemGrapplingState( const ioHashString &szAttacker, GrapplingSkillWoundedInfo kWoundedInfo )
{
	if( !CheckGrapplingExceptionState() )
		return false;

	if( m_CharState != CS_WOUNDED &&
		m_CharState != CS_BLOW_WOUNDED &&
		m_CharState != CS_BOUND_BLOW_WOUNDED &&
		m_CharState != CS_BLOW_EXTEND_WOUND )
	{
		return false;
	}

	if( m_GrapplingType == GPT_WRESTLING && IsFloatingState() )
	{
		bool bEnableFloat = false;

		if( m_CharState == CS_BLOW_WOUNDED && m_BlowState == BW_BLOWING )
		{
			if( !IsFloating() )
				bEnableFloat = true;
		}
		else if( m_CharState == CS_BLOW_EXTEND_WOUND && m_BlowState == BW_BLOWING )
		{
			if( !IsFloating() )
				bEnableFloat = true;
		}
		else if( m_CharState == CS_BOUND_BLOW_WOUNDED &&
			(m_BlowState == BW_BLOWING || m_BlowState == BW_BOUND_BLOWING) )
		{
			if( !IsFloating() )
				bEnableFloat = true;
		}

		if( !bEnableFloat )
			return false;
	}

	ioBaseChar *pAttacker = GetBaseChar( szAttacker );
	if( !pAttacker ) return false;

	SetState( CS_GRAPPLING_WOUNDED_ITEM );

	m_GrapplingAttacker.Clear();
	m_GrapplingTarget.Clear();
	m_GrapplingSkillName.Clear();

	m_GrapplingAttacker = szAttacker;

	m_SkillGrapplingInfo.Init();
	m_SkillGrapplingInfo = kWoundedInfo;

	if( m_GrapplingType == GPT_MULTI )
		m_GrapplingSkillState = GSS_MULTI;
	else if( m_GrapplingType == GPT_COMPETE )
		m_GrapplingSkillState = GSS_COMPETE;
	else
		m_GrapplingSkillState = GSS_LOOP;

	m_pGroup->ClearAllActionAni( FLOAT100, true );
	m_pGroup->ClearAllLoopAni( FLOAT100, true );

	int iAniID = m_pGroup->GetAnimationIdx( m_SkillGrapplingInfo.m_GrapplingLoopMotion2 );

	float fAniRate = FLOAT1;
	if( m_SkillGrapplingInfo.m_fGrapplingLoopMotionRate > 0.0f )
		fAniRate = m_SkillGrapplingInfo.m_fGrapplingLoopMotionRate;

	if( iAniID != -1 )
		m_pGroup->SetLoopAni( iAniID, FLOAT100, FLOAT1, FLOAT1/fAniRate );

	return true;
}

void ioBaseChar::SetSkillGrapplingState( const ioHashString &szAttacker, GrapplingSkillWoundedInfo kWoundedInfo, const ioHashString &szSkillName )
{
	if( !CheckGrapplingExceptionState() )
		return;

	//레이드 모드일때만 체크로 변경
	ModeType eType = m_pModeParent->GetModeType();
	if ( eType == MT_RAID )
	{
		// for NPC
		bool bNPC = false;
		if( ToNpcChar( this ) )
		{
			bNPC = true;
		}

		if ( bNPC && HasBuff( BT_STATE_PROTECTION ))
			return;
	}
	
	if( m_CharState != CS_WOUNDED &&
		m_CharState != CS_BLOW_WOUNDED &&
		m_CharState != CS_BOUND_BLOW_WOUNDED &&
		m_CharState != CS_BLOW_EXTEND_WOUND )
	{
		return;
	}

	if( m_GrapplingType == GPT_WRESTLING && IsFloatingState() )
	{
		bool bEnableFloat = false;

		if( m_CharState == CS_BLOW_WOUNDED && m_BlowState == BW_BLOWING )
		{
			if( !IsFloating() )
				bEnableFloat = true;
		}
		else if( m_CharState == CS_BLOW_EXTEND_WOUND && m_BlowState == BW_BLOWING )
		{
			if( !IsFloating() )
				bEnableFloat = true;
		}
		else if( m_CharState == CS_BOUND_BLOW_WOUNDED &&
			(m_BlowState == BW_BLOWING || m_BlowState == BW_BOUND_BLOWING) )
		{
			if( !IsFloating() )
				bEnableFloat = true;
		}

		if( !bEnableFloat )
			return;
	}

	ioBaseChar *pAttacker = GetBaseChar( szAttacker );
	if( !pAttacker ) return;

	SetState( CS_GRAPPLING_WOUNDED_SKILL );

	m_GrapplingAttacker.Clear();
	m_GrapplingTarget.Clear();
	m_GrapplingSkillName.Clear();

	m_GrapplingAttacker = szAttacker;
	m_GrapplingSkillName = szSkillName;

	m_SkillGrapplingInfo.Init();
    m_SkillGrapplingInfo = kWoundedInfo;

	if( m_GrapplingType == GPT_MULTI )
		m_GrapplingSkillState = GSS_MULTI;
	else if( m_GrapplingType == GPT_COMPETE )
		m_GrapplingSkillState = GSS_COMPETE;
	else
		m_GrapplingSkillState = GSS_LOOP;

	m_pGroup->ClearAllActionAni( FLOAT100, true );
	m_pGroup->ClearAllLoopAni( FLOAT100, true );

	int iAniID = m_pGroup->GetAnimationIdx( m_SkillGrapplingInfo.m_GrapplingLoopMotion );

	float fAniRate = FLOAT1;
	if( m_SkillGrapplingInfo.m_fGrapplingLoopMotionRate > 0.0f )
		fAniRate = m_SkillGrapplingInfo.m_fGrapplingLoopMotionRate;

	if( iAniID != -1 )
		m_pGroup->SetLoopAni( iAniID, FLOAT100, FLOAT1, FLOAT1/fAniRate );

	if( IsNeedSendNetwork() )
	{
		SP2Packet kPacket( CUPK_GRAPPLING_SYNC );
		kPacket << GetCharName();
		kPacket << GRAPPLING_WOUNDED_SKILL;
		kPacket << GSS_LOOP;
		kPacket << pAttacker->GetTargetRot();
		kPacket << szAttacker;
		kPacket << szSkillName;
		FillGrapplingSkillWoundedInfo( kPacket );
		P2PNetwork::SendToAllPlayingUser( kPacket );
	}
}

void ioBaseChar::SetNoChangeGrapplingState( int iType )
{
	if( !CheckGrapplingExceptionState() )
		return;

	switch( iType )
	{
	case GPT_NO_CHANGE:
		SetState( CS_GRAPPLING_WOUNDED_SKILL );
		m_GrapplingSkillState = GSS_NO_CHANGE;
		break;
	case GPT_NO_CHANGE2:
		SetState( CS_GRAPPLING_WOUNDED_SKILL );
		m_GrapplingSkillState = GSS_NO_CHANGE2;
		break;
	case GPT_NO_CHANGE3:
		SetState( CS_GRAPPLING_WOUNDED_SKILL );
		m_GrapplingSkillState = GSS_NO_CHANGE3;
		break;
	case GPT_NO_CHANGE4:
		SetState( CS_GRAPPLING_WOUNDED );
		break;
	default:
		SetState( CS_GRAPPLING_WOUNDED_SKILL ); 
		break;
	}
}

void ioBaseChar::FillGrapplingSkillWoundedInfo( SP2Packet &rkPacket )
{
	int i=0;
	int iSwingBuffCnt = m_SkillGrapplingInfo.m_SwingBuff.size();
	int iSwingWoundCnt = m_SkillGrapplingInfo.m_SwingWoundBuff.size();
	int iSwingCancelCnt = m_SkillGrapplingInfo.m_SwingCancelBuff.size();

	rkPacket << (int)m_SkillGrapplingInfo.m_GrapplingColType;
	rkPacket << m_SkillGrapplingInfo.m_bReverseTargetRot;
	rkPacket << m_SkillGrapplingInfo.m_GrapplingLoopMotion;
	rkPacket << m_SkillGrapplingInfo.m_fGrapplingLoopMotionRate;

	rkPacket << iSwingBuffCnt;
	for( i=0; i < iSwingBuffCnt; ++i )
	{
		rkPacket << m_SkillGrapplingInfo.m_SwingBuff[i];
	}

	rkPacket << iSwingWoundCnt;
	for( i=0; i < iSwingWoundCnt; ++i )
	{
		rkPacket << m_SkillGrapplingInfo.m_SwingWoundBuff[i];
	}

	rkPacket << iSwingCancelCnt;
	for( i=0; i < iSwingCancelCnt; ++i )
	{
		rkPacket << m_SkillGrapplingInfo.m_SwingCancelBuff[i];
	}
}

void ioBaseChar::ApplyGrapplingSkillWoundedInfo( SP2Packet &rkPacket, GrapplingSkillWoundedInfo &rkWoundedInfo )
{
	int i=0;
	rkWoundedInfo.m_SwingBuff.clear();
	rkWoundedInfo.m_SwingWoundBuff.clear();
	rkWoundedInfo.m_SwingCancelBuff.clear();

	int iType;
	rkPacket >> iType;
	rkWoundedInfo.m_GrapplingColType = (GrapplingColType)iType;
	rkPacket >> rkWoundedInfo.m_bReverseTargetRot;
	rkPacket >> rkWoundedInfo.m_GrapplingLoopMotion;
	rkPacket >> rkWoundedInfo.m_fGrapplingLoopMotionRate;

	int iSwingBuffCnt = 0;
	rkPacket >> iSwingBuffCnt;
	for( i=0; i < iSwingBuffCnt; ++i )
	{
		ioHashString szBuffName;
		rkPacket >> szBuffName;

		rkWoundedInfo.m_SwingBuff.push_back( szBuffName );
	}

	int iSwingWoundCnt = 0;
	rkPacket >> iSwingWoundCnt;
	for( i=0; i < iSwingWoundCnt; ++i )
	{
		ioHashString szBuffName;
		rkPacket >> szBuffName;

		rkWoundedInfo.m_SwingWoundBuff.push_back( szBuffName );
	}

	int iSwingCancelCnt = 0;
	rkPacket >> iSwingCancelCnt;
	for( i=0; i < iSwingCancelCnt; ++i )
	{
		ioHashString szBuffName;
		rkPacket >> szBuffName;

		rkWoundedInfo.m_SwingCancelBuff.push_back( szBuffName );
	}
}

void ioBaseChar::CheckGrapplingSkillState()
{
	switch( m_GrapplingSkillState )
	{
	case GSS_PULL:
		break;
	case GSS_LOOP:
		ProcessSkillWoundGrapplingLoop();
		break;
	case GSS_NO_CHANGE:
	case GSS_NO_CHANGE2:
	case GSS_NO_CHANGE3:
		ProcessSkillWoundGrapplingNoChange();
		break;
	case GSS_MULTI:
		ProcessSkillWoundGrapplingMulti();
		break;
	case GSS_COMPETE:
		ProcessSkillWoundGrapplingCompete();
		break;
	}
}

// 루시퍼, 나코루루, 미카엘, 초시공전사, 스트라이커, 갈포드
void ioBaseChar::CheckGrapplingItemState()
{
	ioBaseChar *pAttacker = GetBaseChar( m_GrapplingAttacker );
	bool bFail = false;

	if( !pAttacker )
	{
		m_GrapplingAttacker.Clear();

		BlowWoundAniInfo kInfo;
		SetBlowWoundedState( true, kInfo );
		return;
	}
	else if( pAttacker->GetState() == CS_LUCIFER_FLY			||
			 pAttacker->GetState() == CS_NAKORURU_JUMP_ATTACK	||
			 pAttacker->GetState() == CS_GRAPPLER_JUMP_GRAP		||
			 pAttacker->GetState() == CS_MICHAEL_FLY			||
			 pAttacker->GetState() == CS_SUPER_DIMENSION_DASH	||			 
			 pAttacker->GetState() == CS_JUMPER_SPECIAL			||
			 pAttacker->GetState() == CS_STRIKER_LAND_ATTACK	||
			 pAttacker->GetState() == CS_GRAPPLING_EXPANSION 	||
			 pAttacker->GetState() == CS_GALFORD_CMD_STATE		||
			 pAttacker->GetState() == CS_CMD_STATE				||
			 pAttacker->GetState() == CS_WARP_SPECIAL			||
			 pAttacker->GetState() == CS_SANTA_SPECIAL			|| 
			 pAttacker->GetState() == CS_AUTOMATON_SPECIAL		||
			 pAttacker->GetState() == CS_CHANGE_ON_GRIFFIN_FLY	||
			 pAttacker->GetState() == CS_GWONWANG_SPECIAL		||		// 권왕 2020-06-03
			 pAttacker->GetState() == CS_OBJECT_BANKRUPTCY_SPECIAL )	// 권왕 변신 2020-06-09
	{
		ProcessItemWoundGrapplingLoop( pAttacker );
	}
	else
	{
		m_GrapplingAttacker.Clear();

		BlowWoundAniInfo kInfo;
		SetBlowWoundedState( true, kInfo );
		return;
	}
}

void ioBaseChar::ProcessItemWoundGrapplingLoop( ioBaseChar *pAttacker )
{
	if( !pAttacker )
		return;

	D3DXVECTOR3 vPos = pAttacker->GetGrapplingItemGapPosition();
	if( vPos == ioMath::VEC3_ZERO )
		return;

	// 미카엘의 경우는 m_bReverseTargetRot 기능 처리함
	if( pAttacker->GetState() == CS_MICHAEL_FLY || pAttacker->GetState() == CS_SUPER_DIMENSION_DASH || 
		pAttacker->GetState() == CS_SANTA_SPECIAL || pAttacker->GetState() == CS_CHANGE_ON_GRIFFIN_FLY )
	{
		D3DXQUATERNION qtBaseRot = pAttacker->GetTargetRot();
		D3DXQUATERNION qtTargetRot = qtBaseRot;

		if( m_SkillGrapplingInfo.m_bReverseTargetRot )
		{
			D3DXVECTOR3 vDir = qtBaseRot * D3DXVECTOR3( 0.0f, 0.0f, -FLOAT1 );

			D3DXQUATERNION qtRot;
			D3DXQuaternionRotationYawPitchRoll( &qtRot, DEGtoRAD(180.0f), 0.0f, 0.0f );
			vDir = qtRot * vDir;

			ioMath::CalcDirectionQuaternion( qtTargetRot, -vDir );
		}

		SetTargetRotToRotate( qtTargetRot, true, false );
	}

	SetWorldPosition( vPos );
}

void ioBaseChar::ProcessSkillWoundGrapplingLoop()
{
	ioBaseChar *pAttacker = GetBaseChar( m_GrapplingAttacker );
	if( !pAttacker )
	{
		CheckSkillGrapplingCancelBuff( "", false );
		return;
	}
	else
	{
		if( pAttacker->GetState() != CS_USING_SKILL )
		{
			CheckSkillGrapplingCancelBuff( "", false );
			return;
		}
		else if( pAttacker->GetCurActiveSkill() == NULL || pAttacker->GetCurActiveSkill()->GetName() != m_GrapplingSkillName )
		{
			CheckSkillGrapplingCancelBuff( "", false );
			return;
		}
	}

	ioSkill *pSkill = pAttacker->GetCurActiveSkill();
	if( pSkill && pSkill->EnableChangeGrapplingTargetPos() )
	{
		D3DXVECTOR3 vPos = pAttacker->GetGrapplingSkillGapPosition();
		if( vPos == ioMath::VEC3_ZERO )
			return;

		D3DXQUATERNION qtBaseRot = pAttacker->GetTargetRot();
		D3DXQUATERNION qtTargetRot = qtBaseRot;

		if( m_SkillGrapplingInfo.m_bReverseTargetRot )
		{
			D3DXVECTOR3 vDir = qtBaseRot * D3DXVECTOR3( 0.0f, 0.0f, -FLOAT1 );

			D3DXQUATERNION qtRot;
			D3DXQuaternionRotationYawPitchRoll( &qtRot, DEGtoRAD(180.0f), 0.0f, 0.0f );
			vDir = qtRot * vDir;

			ioMath::CalcDirectionQuaternion( qtTargetRot, -vDir );
		}

		SetWorldPosition( vPos );
		SetTargetRotToRotate( qtTargetRot, true, false );
	}
}

void ioBaseChar::ProcessSkillWoundGrapplingNoChange()
{
	DWORD dwCurTime = FRAMEGETTIME();

	if(  m_AnimationTime.EndTime() < dwCurTime )
	{
		switch( m_GrapplingSkillState )
		{
		case GSS_NO_CHANGE:
			SetState( CS_DELAY );
			break;
		case GSS_NO_CHANGE2:
			{
				BlowWoundAniInfo kInfo;
				SetBlowWoundedState( true, kInfo );
			}
			break;
		case GSS_NO_CHANGE3:
			break;
		default:
			SetState( CS_DELAY );
			break;
		}

		if( m_GrapplingSkillState != GSS_NO_CHANGE3 )
			return;
	}

	ioBaseChar *pAttacker = GetBaseChar( m_GrapplingAttacker );
	if( !pAttacker || pAttacker->GetState() != CS_USING_SKILL )
	{
		if( m_GrapplingSkillState == GSS_NO_CHANGE2 || m_GrapplingSkillState == GSS_NO_CHANGE3 )
		{
			BlowWoundAniInfo kInfo;
			SetBlowWoundedState( true, kInfo );
		}

		return;
	}

	ioSkill *pSkill = pAttacker->GetCurActiveSkill();
	if( pSkill && pSkill->EnableChangeGrapplingTargetPos() )
	{
		D3DXVECTOR3 vPos = pAttacker->GetGrapplingSkillGapPosition();
		if( vPos == ioMath::VEC3_ZERO )
			return;

		D3DXQUATERNION qtBaseRot = pAttacker->GetTargetRot();
		D3DXQUATERNION qtTargetRot = qtBaseRot;

		if( m_SkillGrapplingInfo.m_bReverseTargetRot )
		{
			D3DXVECTOR3 vDir = qtBaseRot * D3DXVECTOR3( 0.0f, 0.0f, -FLOAT1 );

			D3DXQUATERNION qtRot;
			D3DXQuaternionRotationYawPitchRoll( &qtRot, DEGtoRAD(180.0f), 0.0f, 0.0f );
			vDir = qtRot * vDir;

			ioMath::CalcDirectionQuaternion( qtTargetRot, -vDir );
		}

		SetWorldPosition( vPos );
		SetTargetRotToRotate( qtTargetRot, true, false );
	}
}

