D3DXVECTOR3 ioBaseChar::GetGrapplingItemGapPosition()
{
	ioWeaponItem *pWeaponItem =	GetWeapon();
	if( !pWeaponItem )
		return ioMath::VEC3_ZERO;

	ioLuciferItem *pLuciferItem = ToLuciferItem( pWeaponItem );
	ioNakoruruItem *pNakoruru = ToNakoruruItem( pWeaponItem );
	ioMichaelItem *pMichael = ToMichaelItem( pWeaponItem );
	ioSuperDimensionItem *pSuperDimensionItem = ToSuperDimensionItem( pWeaponItem );
	ioStrikerItem *pStrikerItem = ToStrikerItem( pWeaponItem );
	ioJumperItem *pJumperItem = ToJumperItem( pWeaponItem );
	ioGrapplingExpansionItem *pGrapplingExpansionItem = ToGrapplingExpansionItem( pWeaponItem );
	ioGalfordItem *pGalford = ToGalfordItem( pWeaponItem );
	ioGunnerItem *pGunner = ToGunnerItem( pWeaponItem );
	ioWarpItem* pWarpItem = ToWarpItem( pWeaponItem );
	ioSantaItem *pSantaItem = ToSantaItem( pWeaponItem );
	ioAutomatonItem	*pAutomatonItem = ToAutomatonItem( pWeaponItem );
	ioChangeOnItem* pChangeOn = ToChangeOnItem( pWeaponItem );
	ioGwonwangItem* pGwonwangItem = ToGwonwangItem( pWeaponItem );	// 권왕 2020-06-03

	if( pLuciferItem )
	{
		D3DXVECTOR3 vPos = pLuciferItem->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if( pNakoruru )
	{
		D3DXVECTOR3 vPos = pNakoruru->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if( pMichael )
	{
		D3DXVECTOR3 vPos = pMichael->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if( pSuperDimensionItem )
	{
		D3DXVECTOR3 vPos = pSuperDimensionItem->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if( pStrikerItem )
	{
		D3DXVECTOR3 vPos = pStrikerItem->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if( pJumperItem )
	{
		D3DXVECTOR3 vPos = pJumperItem->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if( pGrapplingExpansionItem )
	{
		D3DXVECTOR3 vPos = pGrapplingExpansionItem->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if ( pGalford )
	{
		D3DXVECTOR3 vPos = pGalford->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if( pGunner )
	{
		D3DXVECTOR3 vPos = pGunner->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if( pWarpItem )
	{
		D3DXVECTOR3 vPos = pWarpItem->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if( pSantaItem )
	{
		D3DXVECTOR3 vPos = pSantaItem->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if( pAutomatonItem )
	{
		D3DXVECTOR3 vPos = pAutomatonItem->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if( pChangeOn )
	{
		D3DXVECTOR3 vPos = pChangeOn->GetGrapplingTargetPos( this );
		return vPos;
	}
	else if( pGwonwangItem )	// 권왕 2020-06-03
	{
		if( pGwonwangItem->IsBUsedWereWolf() )
		{
			ioObjectBankruptcyItem* pObjectBankruptcyItem = ToObjectBankruptcyItem( GetObject() );	// 2020-06-09
			if( pObjectBankruptcyItem )
			{
				D3DXVECTOR3 vPos = pObjectBankruptcyItem->GetGrapplingTargetPos( this );
				return vPos;
			}
		}
		else
		{
			D3DXVECTOR3 vPos = pGwonwangItem->GetGrapplingTargetPos( this );
			return vPos;
		}

	}
	return ioMath::VEC3_ZERO;
}

D3DXVECTOR3 ioBaseChar::GetGrapplingSkillGapPosition()
{
	if( m_CharState != CS_USING_SKILL )
		return ioMath::VEC3_ZERO;

	if( !m_pActiveSkill )
		return ioMath::VEC3_ZERO;

	D3DXVECTOR3 vPos = m_pActiveSkill->GetGrapplingTargetPos( this );

	return vPos;
}

D3DXVECTOR3 ioBaseChar::GetGrapplingSkillMultiGapPosition( ioBaseChar *pChar )
{
	if( !pChar )
		return ioMath::VEC3_ZERO;

	if( m_CharState != CS_USING_SKILL )
		return ioMath::VEC3_ZERO;

	if( !m_pActiveSkill )
		return ioMath::VEC3_ZERO;

	D3DXVECTOR3 vPos = m_pActiveSkill->GetGrapplingTargetPos( this, pChar );

	return vPos;
}

void ioBaseChar::ApplySkillGrapplingState( SP2Packet &rkPacket )
{
	int iState;
	rkPacket >> iState;

	switch( iState )
	{
	case GSS_LOOP:
		{
			D3DXQUATERNION qtRot;
			rkPacket >> qtRot;

			SetTargetRotToRotate( qtRot, true, false );

			ioHashString szAttacker;
			rkPacket >> szAttacker;

			ioHashString szSkillName;
			rkPacket >> szSkillName;

			GrapplingSkillWoundedInfo kGrapplingInfo;
			ApplyGrapplingSkillWoundedInfo( rkPacket, kGrapplingInfo );

			SetSkillGrapplingState( szAttacker, kGrapplingInfo, szSkillName );
		}
		break;
	case GSS_CANCEL:
		{
			BlowWoundAniInfo kInfo;
			SetBlowWoundedState( true, kInfo );
		}
		break;
	}
}

void ioBaseChar::CheckSkillGrapplingCancelBuff( ioHashString szColChar, bool bCol )
{
	if( !IsNeedProcess() ) return;

	if( !CheckGrapplingExceptionState() )
		return;

	if( !szColChar.IsEmpty() )
	{
		if( m_GrapplingAttacker == szColChar )
			return;
	}

	if( bCol )
	{
		switch( m_SkillGrapplingInfo.m_GrapplingColType )
		{
		case GCT_NONE:
			return;
		case GCT_CHAR:
			if( szColChar.IsEmpty() )
				return;

			break;
		case GCT_MAP:
			if( !szColChar.IsEmpty() )
				return;

			break;
		}
	}

	if( m_SkillGrapplingInfo.m_SwingCancelBuff.empty() )
	{
		BlowWoundAniInfo kInfo;
		SetBlowWoundedState( true, kInfo );

		if( IsNeedSendNetwork() )
		{
			SP2Packet kPacket( CUPK_GRAPPLING_SYNC );
			kPacket << GetCharName();
			kPacket << GRAPPLING_WOUNDED_SKILL;
			kPacket << GSS_CANCEL;
			P2PNetwork::SendToAllPlayingUser( kPacket );
		}
		return;
	}

	DWORD dwSeed = GetRandomSeed();
	DWORD dwNewSeed = timeGetTime();

	SetRandomSeed( dwNewSeed );

	bool bResult = false;
	ioHashStringVec vBuffList;

	ioHashString szCreator = m_GrapplingAttacker;

	int iCnt = m_SkillGrapplingInfo.m_SwingCancelBuff.size();
	for( int i=0; i < iCnt; ++i )
	{
		const ioHashString& szBuffName = m_SkillGrapplingInfo.m_SwingCancelBuff[i];

		if( !szBuffName.IsEmpty() )
		{
			ioBuff *pBuff = AddNewBuffWithAnimateTime( szBuffName, szCreator, "", NULL, 0 );
			if( pBuff )
			{
				SetLastAttackerName( szCreator, "" );
				vBuffList.push_back( szBuffName );
				bResult = true;
			}
		}
	}

	int iCurBuffCnt = vBuffList.size();
	if(iCurBuffCnt > 0 && bResult )
	{
		if( IsNeedSendNetwork() )
		{
			if( Help::CheckEnableTimeGapUser() )
			{
				LOG.PrintTimeAndLog( 0, "PC -CharAddBuff5 : %s, %d", GetCharName().c_str(), FRAMEGETTIME() );
			}
			SP2Packet kPacket( CUPK_ADD_NEW_BUFF );
			kPacket << GetCharName();
			kPacket << szCreator;
			kPacket << "";
			kPacket << GetRandomSeed();
			kPacket << true;					// 타격횟수 체크
			kPacket << 0.0f;
			kPacket << 0.0f;
			kPacket << 0.0f;
			kPacket << COWT_NONE;				// Check CloseOrderBuff(12.07.13 수정)
			kPacket << iCurBuffCnt;

			for( i=0; i < iCurBuffCnt; i++ )
			{
				kPacket << vBuffList[i];
			}

			kPacket << false;
			P2PNetwork::SendToAllPlayingUser( kPacket );
		}
	}
	else
	{
		// 복구
		SetRandomSeed( dwSeed );
	}
}

void ioBaseChar::CheckCollisionSwingGrapplingBuff( const ioHashString &szAttacker, const ioHashStringVec &rkBuffList )
{
	if( !IsNeedProcess() ) return;
	if( GetCharName() == szAttacker ) return;

	if( CheckGrapplingSwingCollision() ) return;

	if( rkBuffList.empty() )
		return;

	if( HasBuff( BT_ABSOLUTE_PROTECTION ) )
		return;

	if( HasBuff(BT_NOT_MOVE_PROTECT) )
		return;

	if( IsCanNoWound() )
		return;

	if( IsProtectState() )
		return;


	DWORD dwSeed = GetRandomSeed();
	DWORD dwNewSeed = timeGetTime();

	SetRandomSeed( dwNewSeed );

	bool bResult = false;
	ioHashStringVec vBuffList;

	ioHashString szCreator = szAttacker;

	int iCnt = rkBuffList.size();
	for( int i=0; i < iCnt; ++i )
	{
		const ioHashString& szBuffName = rkBuffList[i];

		if( !szBuffName.IsEmpty() )
		{
			ioBuff *pBuff = AddNewBuffWithAnimateTime( szBuffName, szCreator, "", NULL, 0 );
			if( pBuff )
			{
				SetLastAttackerName( szCreator, "" );
				vBuffList.push_back( szBuffName );
				bResult = true;
			}
		}
	}

	int iCurBuffCnt = vBuffList.size();
	if(iCurBuffCnt > 0 && bResult )
	{
		if( IsNeedSendNetwork() )
		{
			if( Help::CheckEnableTimeGapUser() )
			{
				LOG.PrintTimeAndLog( 0, "PC -CharAddBuff6 : %s, %d", GetCharName().c_str(), FRAMEGETTIME() );
			}
			SP2Packet kPacket( CUPK_ADD_NEW_BUFF );
			kPacket << GetCharName();
			kPacket << szCreator;
			kPacket << "";
			kPacket << GetRandomSeed();
			kPacket << true;				// 타격횟수 체크
			kPacket << 0.0f;
			kPacket << 0.0f;
			kPacket << 0.0f;
			kPacket << COWT_NONE;			// Check CloseOrderBuff(12.07.13 수정)
			kPacket << iCurBuffCnt;

			for( i=0; i < iCurBuffCnt; i++ )
			{
				kPacket << vBuffList[i];
			}

			kPacket << false;
			P2PNetwork::SendToAllPlayingUser( kPacket );
		}
	}
	else
	{
		// 복구
		SetRandomSeed( dwSeed );
	}
}

void ioBaseChar::SetGrapplingWoundSwing( const ioHashString &szAttacker, GrapplingSkillWoundedInfo kWoundedInfo,
										 const ioHashString &szWoundAni, float fWoundAniRate )
{
	if( !CheckGrapplingExceptionState() )
		return;

	ioBaseChar *pAttacker = GetBaseChar( szAttacker );
	if( !pAttacker ) return;

	// for NPC
	bool bNPC = false;
	bool bAttackerNPC = false;
	if( ToNpcChar( this ) )
	{
		bNPC = true;
	}

	if( ToNpcChar( pAttacker ) )
	{
		bAttackerNPC = true;
	}
	
	if ( bNPC && HasBuff( BT_STATE_PROTECTION ))
		return;

	if( !szWoundAni.IsEmpty() )
	{
		DWORD dwCurTime = FRAMEGETTIME();

		int iAniID = m_pGroup->GetAnimationIdx( szWoundAni );
		if( iAniID != -1 )
		{
			m_pGroup->ClearAllLoopAni( FLOAT100, true );
			m_pGroup->ClearAllActionAni( FLOAT100, true );

			float fTimeRate = fWoundAniRate;
			if( fTimeRate <= 0.0f )
				fTimeRate = FLOAT1;

			m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fTimeRate, 0.0f, 0.0f, true );

			CheckCharColSkipTime( iAniID, fTimeRate, 0 );
		}
	}

	m_GrapplingAttacker = szAttacker;
	m_SkillGrapplingInfo = kWoundedInfo;
	
	SetState( CS_GRAPPLING_WOUNDED_SWING );

	if( IsNeedSendNetwork() )
	{
		bool bResult = false;
		ioHashStringVec vBuffList;
		if( !m_SkillGrapplingInfo.m_SwingBuff.empty() )
		{
			DWORD dwSeed = GetRandomSeed();
			DWORD dwNewSeed = timeGetTime();

			SetRandomSeed( dwNewSeed );

			ioHashString szCreator = m_GrapplingAttacker;

			int iCnt = m_SkillGrapplingInfo.m_SwingBuff.size();
			for( int i=0; i < iCnt; ++i )
			{
				const ioHashString& szBuffName = m_SkillGrapplingInfo.m_SwingBuff[i];

				if( !szBuffName.IsEmpty() )
				{
					ioBuff *pBuff = AddNewBuffWithAnimateTime( szBuffName, szCreator, "", NULL, 0 );
					if( pBuff )
					{
						SetLastAttackerName( szCreator, "" );
						vBuffList.push_back( szBuffName );
						bResult = true;
					}
				}
			}

			int iCurBuffCnt = vBuffList.size();
			if(iCurBuffCnt <= 0 || !bResult )
			{
				// 복구
				SetRandomSeed( dwSeed );
			}
		}

		int iCurBuffCnt = vBuffList.size();
		if( !bResult )
		{
			iCurBuffCnt = 0;
		}

		SP2Packet kPacket( CUPK_GRAPPLING_SYNC );
		kPacket << GetCharName();
		kPacket << GRAPPLING_WOUNDED_SWING;
		kPacket << pAttacker->GetTargetRot();
		kPacket << szAttacker;
		kPacket << szWoundAni;
		kPacket << fWoundAniRate;
		FillGrapplingSkillWoundedInfo( kPacket );

		kPacket << iCurBuffCnt;
		kPacket << GetRandomSeed();
		for( int i=0; i < iCurBuffCnt; i++ )
		{
			kPacket << vBuffList[i];
		}

		P2PNetwork::SendToAllPlayingUser( kPacket );
	}
	
	// local or 훈련소 or NPC
	if( !P2PNetwork::IsNetworkPlaying() || !m_pCreator->IsNetworkMode() || (bNPC || bAttackerNPC) )
	{
		bool bResult = false;
		ioHashStringVec vBuffList;
		if( !m_SkillGrapplingInfo.m_SwingBuff.empty() )
		{
			DWORD dwSeed = GetRandomSeed();
			DWORD dwNewSeed = timeGetTime();

			SetRandomSeed( dwNewSeed );

			ioHashString szCreator = m_GrapplingAttacker;

			int iCnt = m_SkillGrapplingInfo.m_SwingBuff.size();
			for( int i=0; i < iCnt; ++i )
			{
				const ioHashString& szBuffName = m_SkillGrapplingInfo.m_SwingBuff[i];

				if( !szBuffName.IsEmpty() )
				{
					ioBuff *pBuff = AddNewBuffWithAnimateTime( szBuffName, szCreator, "", NULL, 0 );
					if( pBuff )
					{
						SetLastAttackerName( szCreator, "" );
						vBuffList.push_back( szBuffName );
						bResult = true;
					}
				}
			}

			int iCurBuffCnt = vBuffList.size();
			if(iCurBuffCnt <= 0 || !bResult )
			{
				// 복구
				SetRandomSeed( dwSeed );
			}
		}
	}
}

void ioBaseChar::ApplyGrapplingWoundSwingState( SP2Packet &rkPacket )
{
	D3DXQUATERNION qtRot;
	rkPacket >> qtRot;

	SetTargetRotToRotate( qtRot, true, false );

	ioHashString szAttacker;
	rkPacket >> szAttacker;

	ioHashString szWoundAni;
	float fWoundAniRate;
	rkPacket >> szWoundAni >> fWoundAniRate;

	GrapplingSkillWoundedInfo kGrapplingInfo;
	ApplyGrapplingSkillWoundedInfo( rkPacket, kGrapplingInfo );

	SetGrapplingWoundSwing( szAttacker, kGrapplingInfo, szWoundAni, fWoundAniRate );

	int iBuffCnt;
	rkPacket >> iBuffCnt;

	DWORD dwSeed;
	rkPacket >> dwSeed;

	SetRandomSeed( dwSeed );

	ioHashString szBuffName;
	for( int i=0; i<iBuffCnt; i++ )
	{
		rkPacket >> szBuffName;

		if( !szBuffName.IsEmpty() )
		{
			AddNewBuffWithAnimateTime( szBuffName, szAttacker, "", NULL, 0 );
		}
	}
}

void ioBaseChar::FillGrapplingPushedInfo( SP2Packet &rkPacket )
{
	rkPacket << m_PushedGrapplingInfo.m_dwGrapplingPushedDuration;
	rkPacket << m_PushedGrapplingInfo.m_fGrapplingPushedSpeed;
	rkPacket << m_PushedGrapplingInfo.m_dwGrapplingPushedRotSpeed;
	rkPacket << m_PushedGrapplingInfo.m_dwGrapplingPushedColTime;
	rkPacket << m_PushedGrapplingInfo.m_GrapplingPushedMotion;
	rkPacket << m_PushedGrapplingInfo.m_fGrapplingPushedMotionRate;
	rkPacket << m_PushedGrapplingInfo.m_GrapplingPushedLoopMotion;
	rkPacket << m_PushedGrapplingInfo.m_fGrapplingPushedLoopMotionRate;
	rkPacket << m_PushedGrapplingInfo.m_GrapplingPushedReturnMotion;
	rkPacket << m_PushedGrapplingInfo.m_fGrapplingPushedReturnMotionRate;

	int iPushedBuffCnt = m_PushedGrapplingInfo.m_GrapplingPushedBuffList.size();
	int iColBuffCnt = m_PushedGrapplingInfo.m_GrapplingColBuffList.size();

	rkPacket << iPushedBuffCnt;
	for( int i=0; i < iPushedBuffCnt; ++i )
	{
		rkPacket << m_PushedGrapplingInfo.m_GrapplingPushedBuffList[i];
	}

	rkPacket << iColBuffCnt;
	for( int i=0; i < iColBuffCnt; ++i )
	{
		rkPacket << m_PushedGrapplingInfo.m_GrapplingColBuffList[i];
	}
}

void ioBaseChar::ApplyGrapplingPushedInfo( SP2Packet &rkPacket, GrapplingPushedInfo &rkWoundedInfo )
{
	rkPacket >> rkWoundedInfo.m_dwGrapplingPushedDuration;
	rkPacket >> rkWoundedInfo.m_fGrapplingPushedSpeed;
	rkPacket >> rkWoundedInfo.m_dwGrapplingPushedRotSpeed;
	rkPacket >> rkWoundedInfo.m_dwGrapplingPushedColTime;
	rkPacket >> rkWoundedInfo.m_GrapplingPushedMotion;
	rkPacket >> rkWoundedInfo.m_fGrapplingPushedMotionRate;
	rkPacket >> rkWoundedInfo.m_GrapplingPushedLoopMotion;
	rkPacket >> rkWoundedInfo.m_fGrapplingPushedLoopMotionRate;
	rkPacket >> rkWoundedInfo.m_GrapplingPushedReturnMotion;
	rkPacket >> rkWoundedInfo.m_fGrapplingPushedReturnMotionRate;

	int iPushedBuffCnt = 0;
	int iColBuffCnt = 0;

	rkWoundedInfo.m_GrapplingPushedBuffList.clear();
	rkPacket >> iPushedBuffCnt;
	for( int i=0; i < iPushedBuffCnt; ++i )
	{
		ioHashString szBuffName;
		rkPacket >> szBuffName;
		rkWoundedInfo.m_GrapplingPushedBuffList.push_back( szBuffName );
	}

	rkWoundedInfo.m_GrapplingColBuffList.clear();
	rkPacket >> iColBuffCnt;
	for( int i=0; i < iColBuffCnt; ++i )
	{
		ioHashString szBuffName;
		rkPacket >> szBuffName;
		rkWoundedInfo.m_GrapplingColBuffList.push_back( szBuffName );
	}
}

void ioBaseChar::CheckLandAfterState()
{
	DWORD dwCurTime = FRAMEGETTIME();

	if( m_AnimationTime.EndTime() < dwCurTime )
	{
		if( IsReserveKeyInput() )
			ProcessReserveKeyInput();
		else
			SetState( CS_DELAY );
	}
	else
	{
		if( IsNeedProcess() )
		{
			if( IsEnableReserveKeyInput() )
				CheckReserveKeyInput();
		}
	}
}

