bool ioBaseChar::IsCanJumpReload( ioAttackableItem *pItem, float fHeightGap )
{
	if( !pItem ) return false;
	if( !pItem->IsCanJumpReload( this ) )
		return false;

	if( m_iChangeJumppingLimit > 0 && m_iChangeJumppingLimit <= m_iChangeJumppingCnt )
		return false;

	if( m_bCatchState || m_bPrisonerMode || m_bUsedJumpDefense || m_bUsedBuffJumpAttack )
	{
		return false;
	}

	if( m_bUsedJumpAttack || m_bUsedBuffJumpAttack )
	{
		return false;
	}

	// KeyCheck
	if( m_UsedBuffMultiFlyJump == BJUT_CUR )
	{
		if( !m_KeyInput.IsDefenseKeyDown() )
			return false;
	}
	else if( m_UsedBuffFlyJump == BJUT_CUR )
	{
		if( !m_KeyInput.IsDefenseKeyDown() )
			return false;
	}
	else if( m_UsedBuffFlyJump == BJUT_WALK )
	{
		if( !m_KeyInput.IsDefenseKeyDown() )
			return false;
	}
	else
	{
		if( !m_KeyInput.IsDefenseKey() )
			return false;
	}

	if( ToDrinkItem( GetObject() ) )
		return false;

	float fEnableHeight = m_fMinJumpAttackEnableHeight;
	ioAttackableItem *pAttackable = GetPriorityItem( SPT_JUMP );
	if( pAttackable )
	{
		float fItemEnableHeight = pAttackable->GetJumpAttackEnableHeight();
		if( fItemEnableHeight > 0.0f )
			fEnableHeight = fItemEnableHeight;
	}

	if( m_fCurJumpPowerAmt - m_fGravityAmt < 0.0f && fHeightGap < fEnableHeight )
	{
		return false;
	}

	DWORD dwCurTime = FRAMEGETTIME();
	DWORD dwEnableTime = m_dwMinJumpAttackEnableTime;
	if( pAttackable )
	{
		DWORD dwItemEnableTime = pAttackable->GetJumpAttackEnableTime();
		if( dwItemEnableTime > 0 )
			dwEnableTime = dwItemEnableTime;
	}

	if( m_dwJumpMoveStartTime > 0 && dwCurTime < m_dwJumpMoveStartTime + dwEnableTime )
		return false;

	return true;
}

void ioBaseChar::SetJumpReload()
{
	ioAttackableItem *pItem = GetPriorityItem( SPT_JUMP );
	if( !pItem ) return;

	if( !pItem->SetJumpReloadState( this ) )
		return;

	m_bEnableHide = false;
	m_bChangeMotion = false;
	m_bNoWoundState = false;
	m_bChangeTeamBuff = false;

	m_bUsedJumpReload = true;
	m_JumpState = JS_JUMP_RELOAD;

	if( IsNeedSendNetwork() )
	{
		SP2Packet kPacket( CUPK_JUMP_RELOAD );
		kPacket << GetCharName();
		kPacket << JUMP_RELOAD_SET;
		kPacket << m_HP.m_fCurValue;
		kPacket << m_qtTargetRot;
		P2PNetwork::SendToAllPlayingUser( kPacket );
	}
}

void ioBaseChar::ApplyJumpReload( SP2Packet &rkPacket )
{
	int iType;
	rkPacket >> iType;

	switch( iType )
	{
	case JUMP_RELOAD_SET:
		{
			float fCurHP;
			rkPacket >> fCurHP;
			SetCurHP( fCurHP );

			D3DXQUATERNION qtRotate;
			rkPacket >> qtRotate;

			SetTargetRot( qtRotate );
			SetJumpReload();
		}
		break;
	case JUMP_RELOAD_SYNC:
		{
			if( m_CharState != CS_JUMP )
				return;
			if( m_JumpState != JS_JUMP_RELOAD )
				return;

			ioAttackableItem *pItem = GetPriorityItem( SPT_JUMP );
			if( !pItem ) return;

			pItem->ApplyJumpReload( this, rkPacket );
		}
		break;
	}
}

void ioBaseChar::SetSkillCreateWeaponDependency( const ioHashString &szSkillName )
{
	if( m_CharState != CS_USING_SKILL )
		return;

	if( !m_pActiveSkill )
		return;

	if( m_pActiveSkill->GetName() != szSkillName )
		return;

	m_pActiveSkill->SetCreateWeaponDependency( this, m_pCreator );
	return;
}

void ioBaseChar::SetPsycGrappling( const ioHashString &szTarget )
{
	if( !CheckGrapplingExceptionState() )
		return;

	if( m_CharState != CS_USING_SKILL )
		return;

	if( !m_pActiveSkill )
		return;

	if( !ToPsycGrappling( m_pActiveSkill ) && !ToPsycGrappling2(m_pActiveSkill ) )
		return;

	if( !m_pActiveSkill->SetSkillGrapplingState( this, szTarget ) )
		return;
}

void ioBaseChar::SetWoundPsycGrappling( const ioHashString &szAttacker,
									    const ioHashString &szSkillName,
									    PsycGrapplingWoundedInfo kWoundInfo )
{
	if( m_CharState != CS_WOUNDED &&
		m_CharState != CS_BLOW_WOUNDED &&
		m_CharState != CS_BOUND_BLOW_WOUNDED &&
		m_CharState != CS_BLOW_EXTEND_WOUND )
	{
		return;
	}

	ioBaseChar *pAttacker = GetBaseChar( szAttacker );
	if( !pAttacker ) return;

	m_PsycGrapplingAttacker = szAttacker;
	m_PsycGrapplingInfo = kWoundInfo;

	// for NPC
	bool bNPC = false;
	if( ToNpcChar( this ) )
	{
		bNPC = true;
	}

	// local or 훈련소 or NPC
	if( !P2PNetwork::IsNetworkPlaying() || !m_pCreator->IsNetworkMode() || bNPC )
	{
		bool bResult = false;
		ioHashStringVec vBuffList;

		DWORD dwSeed = GetRandomSeed();
		DWORD dwNewSeed = timeGetTime();

		SetRandomSeed( dwNewSeed );

		int iCnt = m_PsycGrapplingInfo.m_StartBuffList.size();
		for( int i=0; i < iCnt; ++i )
		{
			const ioHashString& szBuffName = m_PsycGrapplingInfo.m_StartBuffList[i];

			if( !szBuffName.IsEmpty() )
			{
				ioBuff *pBuff = AddNewBuffWithAnimateTime( szBuffName, szAttacker, "", NULL, 0 );
				if( pBuff )
				{
					SetLastAttackerName( szAttacker, "" );
					vBuffList.push_back( szBuffName );
					bResult = true;
				}
			}
		}

		int iCurBuffCnt = vBuffList.size();
		if(iCurBuffCnt <= 0 || !bResult )
		{
			// 복구
			SetRandomSeed( dwSeed );
		}
	}
	else if( IsNeedSendNetwork() )
	{
		bool bResult = false;
		ioHashStringVec vBuffList;

		DWORD dwSeed = GetRandomSeed();
		DWORD dwNewSeed = timeGetTime();

		SetRandomSeed( dwNewSeed );

		int iCnt = m_PsycGrapplingInfo.m_StartBuffList.size();
		for( int i=0; i < iCnt; ++i )
		{
			const ioHashString& szBuffName = m_PsycGrapplingInfo.m_StartBuffList[i];

			if( !szBuffName.IsEmpty() )
			{
				ioBuff *pBuff = AddNewBuffWithAnimateTime( szBuffName, szAttacker, "", NULL, 0 );
				if( pBuff )
				{
					SetLastAttackerName( szAttacker, "" );
					vBuffList.push_back( szBuffName );
					bResult = true;
				}
			}
		}

		int iCurBuffCnt = vBuffList.size();
		if(iCurBuffCnt <= 0 || !bResult )
		{
			// 복구
			SetRandomSeed( dwSeed );
		}

		SP2Packet kPacket( CUPK_GRAPPLING_SYNC );
		kPacket << GetCharName();
		kPacket << GRAPPLING_PSYC;
		kPacket << pAttacker->GetTargetRot();
		kPacket << szAttacker;
		kPacket << szSkillName;

		kPacket << iCurBuffCnt;
		kPacket << GetRandomSeed();
		for( int i=0; i < iCurBuffCnt; i++ )
		{
			kPacket << vBuffList[i];
		}
		P2PNetwork::SendToAllPlayingUser( kPacket );
	}
}

void ioBaseChar::CheckWoundPsycGrappling()
{
	if( m_PsycGrapplingAttacker.IsEmpty() )
		return;

	ioBaseChar *pAttacker = GetBaseChar( m_PsycGrapplingAttacker );
	if( !pAttacker )
	{
		// BuffEnd
		int iSize = m_PsycGrapplingInfo.m_StartBuffList.size();
		for( int i=0; i < iSize; ++i )
		{
			RemoveBuff( m_PsycGrapplingInfo.m_StartBuffList[i] );
		}

		m_PsycGrapplingAttacker.Clear();
		return;
	}
	else
	{
		if( pAttacker->GetState() != CS_USING_SKILL )
		{
			// BuffEnd
			int iSize = m_PsycGrapplingInfo.m_StartBuffList.size();
			for( int i=0; i < iSize; ++i )
			{
				RemoveBuff( m_PsycGrapplingInfo.m_StartBuffList[i] );
			}

			m_PsycGrapplingAttacker.Clear();
			return;
		}
	}

	bool bExist = false;
	int iSize = m_PsycGrapplingInfo.m_StartBuffList.size();
	for( int i=0; i < iSize; ++i )
	{
		if( HasBuff( m_PsycGrapplingInfo.m_StartBuffList[i] ) )
		{
			bExist = true;
			break;
		}
	}

	if( !bExist )
	{
		m_PsycGrapplingAttacker.Clear();
		return;
	}
}

void ioBaseChar::SetPsycGrapplingAction( const ioHashString &szAttacker,
										 const ioHashString &szSkillName,
										 PsycGrapplingWoundedInfo kWoundInfo,
										 int iKeyType )
{
	ioBaseChar *pAttacker = GetBaseChar( szAttacker );
	if( !pAttacker ) return;

	m_PsycGrapplingInfo = kWoundInfo;

	// for NPC
	bool bNPC = false;
	if( ToNpcChar( this ) )
	{
		bNPC = true;
	}

	// local or 훈련소 or NPC
	if( !P2PNetwork::IsNetworkPlaying() || !m_pCreator->IsNetworkMode() || bNPC )
	{
		bool bResult = false;

		ioHashStringVec vBuffList;
		ioHashStringVec vResultBuffList;

		switch( iKeyType )
		{
		case ioPsycGrapplingSkill::SEK_ATTACK:
			vBuffList = m_PsycGrapplingInfo.m_PushBuffList;
			break;
		case ioPsycGrapplingSkill::SEK_DEFENSE:
			vBuffList = m_PsycGrapplingInfo.m_BoomBuffList;
			break;
		case ioPsycGrapplingSkill::SEK_JUMP:
			vBuffList = m_PsycGrapplingInfo.m_PullBuffList;
			break;
		}

		if( !vBuffList.empty() )
		{
			DWORD dwSeed = GetRandomSeed();
			DWORD dwNewSeed = timeGetTime();

			SetRandomSeed( dwNewSeed );

			ioHashString szCreator = m_PsycGrapplingAttacker;

			int iCnt = vBuffList.size();
			for( int i=0; i < iCnt; ++i )
			{
				const ioHashString& szBuffName = vBuffList[i];

				if( !szBuffName.IsEmpty() )
				{
					ioBuff *pBuff = AddNewBuffWithAnimateTime( szBuffName, szCreator, "", NULL, 0 );
					if( pBuff )
					{
						SetLastAttackerName( szCreator, "" );
						vResultBuffList.push_back( szBuffName );
						bResult = true;
					}
				}
			}

			int iCurBuffCnt = vResultBuffList.size();
			if(iCurBuffCnt <= 0 || !bResult )
			{
				// 복구
				SetRandomSeed( dwSeed );
			}
		}
	}
	else if( IsNeedSendNetwork() )
	{
		int iCurBuffCnt = 0;
		bool bResult = false;

		ioHashStringVec vBuffList;
		ioHashStringVec vResultBuffList;

		switch( iKeyType )
		{
		case ioPsycGrapplingSkill::SEK_ATTACK:
			vBuffList = m_PsycGrapplingInfo.m_PushBuffList;
			break;
		case ioPsycGrapplingSkill::SEK_DEFENSE:
			vBuffList = m_PsycGrapplingInfo.m_BoomBuffList;
			break;
		case ioPsycGrapplingSkill::SEK_JUMP:
			vBuffList = m_PsycGrapplingInfo.m_PullBuffList;
			break;
		}

		if( !vBuffList.empty() )
		{
			DWORD dwSeed = GetRandomSeed();
			DWORD dwNewSeed = timeGetTime();

			SetRandomSeed( dwNewSeed );

			ioHashString szCreator = m_PsycGrapplingAttacker;

			int iCnt = vBuffList.size();
			for( int i=0; i < iCnt; ++i )
			{
				const ioHashString& szBuffName = vBuffList[i];

				if( !szBuffName.IsEmpty() )
				{
					ioBuff *pBuff = AddNewBuffWithAnimateTime( szBuffName, szCreator, "", NULL, 0 );
					if( pBuff )
					{
						SetLastAttackerName( szCreator, "" );
						vResultBuffList.push_back( szBuffName );
						bResult = true;
					}
				}
			}

			iCurBuffCnt = vResultBuffList.size();
			if(iCurBuffCnt <= 0 || !bResult )
			{
				// 복구
				iCurBuffCnt = 0;
				SetRandomSeed( dwSeed );
			}
		}

		SP2Packet kPacket( CUPK_GRAPPLING_SYNC );
		kPacket << GetCharName();
		kPacket << GRAPPLING_PSYC_ACTION;
		kPacket << pAttacker->GetTargetRot();
		kPacket << szAttacker;
		kPacket << szSkillName;
		kPacket << iKeyType;

		kPacket << iCurBuffCnt;
		kPacket << GetRandomSeed();
		for( int i=0; i < iCurBuffCnt; i++ )
		{
			kPacket << vResultBuffList[i];
		}

		P2PNetwork::SendToAllPlayingUser( kPacket );
	}
}

void ioBaseChar::ApplyWoundPsycGrappling( SP2Packet &rkPacket )
{
	D3DXQUATERNION qtRot;
	rkPacket >> qtRot;

	SetTargetRotToRotate( qtRot, true, false );

	ioHashString szAttacker, szSkillName;
	rkPacket >> szAttacker >> szSkillName;

	const ioSkill *pSkill = g_SkillMaker.GetSkillConst( szSkillName );
	if( ToPsycGrapplingConst(pSkill) )
	{
		SetWoundPsycGrappling( szAttacker, szSkillName, ToPsycGrapplingConst(pSkill)->GetPsycGrapplingInfo() );
	}

	int iBuffCnt;
	rkPacket >> iBuffCnt;

	DWORD dwSeed;
	rkPacket >> dwSeed;

	SetRandomSeed( dwSeed );

	ioHashString szBuffName;
	for( int i=0; i<iBuffCnt; i++ )
	{
		rkPacket >> szBuffName;

		if( !szBuffName.IsEmpty() )
		{
			AddNewBuffWithAnimateTime( szBuffName, szAttacker, "", NULL, 0 );
		}
	}
}

void ioBaseChar::ApplyWoundPsycGrapplingAction( SP2Packet &rkPacket )
{
	D3DXQUATERNION qtRot;
	rkPacket >> qtRot;

	SetTargetRotToRotate( qtRot, true, false );

	ioHashString szAttacker, szSkillName;
	rkPacket >> szAttacker >> szSkillName;

	int iKeyType;
	rkPacket >> iKeyType;

	const ioSkill *pSkill = g_SkillMaker.GetSkillConst( szSkillName );
	if( ToPsycGrapplingConst(pSkill) )
	{
		SetPsycGrapplingAction( szAttacker, szSkillName, ToPsycGrapplingConst(pSkill)->GetPsycGrapplingInfo(), iKeyType );
	}

	int iBuffCnt;
	rkPacket >> iBuffCnt;

	DWORD dwSeed;
	rkPacket >> dwSeed;

	SetRandomSeed( dwSeed );

	ioHashString szBuffName;
	for( int i=0; i<iBuffCnt; i++ )
	{
		rkPacket >> szBuffName;

		if( !szBuffName.IsEmpty() )
		{
			AddNewBuffWithAnimateTime( szBuffName, szAttacker, "", NULL, 0 );
		}
	}
}

void ioBaseChar::CheckWallCollisionBuff()
{
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioWallCollisionBuff *pWallCollisionBuff = ToWallCollisionBuff( pBuff );
		if( pWallCollisionBuff )
			pWallCollisionBuff->CheckWallCollision();

		ioAttachedDummyBuff *pAttachedDummyBuff = ToAttachedDummyBuff( pBuff );
		if( pAttachedDummyBuff )
			pAttachedDummyBuff->CheckWallCollision();
	}
}

void ioBaseChar::ApplyCrossBowAimState( SP2Packet &rkPacket )
{
	bool bAim, bJump;
	rkPacket >> bAim >> bJump;

	ioAttackableItem *pItem = GetPriorityItem( SPT_ATTACK );
	if( pItem )
	{
		if( bJump && m_CurJumpType == JT_AIM_JUMP2 )
		{
			if( bAim )
			{
				if( pItem->SetAimState( this ) )
				{
					SetCurNormalAttackItem( pItem );
				}
				else
				{
					SetState( CS_DELAY );
				}
			}
			else
			{
				SetState( CS_DELAY );
			}
		}
		else
		{
			SetState( CS_DELAY );
		}
	}
	else
	{
		SetState( CS_DELAY );
	}
}

