void ioBaseChar::SetWarpTargetList( const ioHashString &szAttacker, const ioHashString &szCharName )
{
	ioPlayStage *pStage = GetCreator();
	if( !pStage) return;

	ioBaseChar *pAttacker = pStage->GetBaseChar( szAttacker );
	ioBaseChar *pTarget = pStage->GetBaseChar(szCharName );

	ioSkill *pAttackerSkill = pAttacker->GetCurActiveSkill();
	if( pAttackerSkill )
	{
		ioTraceWarpSkill *pSkillWarp = ToTraceWarpSkill( pAttackerSkill );
		ioTraceSkill2    *pSkillTrace2 = ToTraceSkill2( pAttackerSkill );
		ioTraceSkill3	 *pSkillTrace3 = ToTraceSkill3( pAttackerSkill );
		if( pSkillWarp )
		{
			if( pTarget->GetProtectionMode() == PM_NONE ) // 시스템 무적은 제외. 나머지 사항은 스킬에서 처리.
			{
				pSkillWarp->SetWarpTargetList( szCharName );
			}
		}
		else if( pSkillTrace2 )
		{
			if( pTarget->GetProtectionMode() == PM_NONE ) // 시스템 무적은 제외. 나머지 사항은 스킬에서 처리.
			{
				pSkillTrace2->SetWarpTargetList( szCharName );
			}
		}
		else if( pSkillTrace3 )
		{
			if( pTarget->GetProtectionMode() == PM_NONE ) // 시스템 무적은 제외. 나머지 사항은 스킬에서 처리.
			{
				pSkillTrace3->SetWarpTargetList( szCharName );
			}
		}
	}
}

void ioBaseChar::SetBlowDashAttackByAttribute( const AttackAttribute &rkAttr, const BlowDashInfo &rkBlowDashInfo )
{
	m_BlowDashInfo.Init();
	m_BlowDashInfo = rkBlowDashInfo;
	m_dwBlowDashCheckTime = 0;

	SetAutoTarget( ATT_DASH );

	ClearReserveKeyInput();
	ClearCharColSkipTime();

	DWORD dwCurTime = FRAMEGETTIME();

	SetState( CS_BLOW_DASH_ATTACK );
	m_BlowDashState = BDS_BLOWING;

	int iAniID		 = m_pGroup->GetAnimationIdx( rkAttr.m_AttackAnimation );
	float fTimeRate  = rkAttr.m_fAttackAniRate;
	if( fTimeRate <= 0.0f )
		fTimeRate = FLOAT1;

	DWORD dwPreDelay = rkAttr.m_dwPreDelay;

	RefreshFireTimeList( iAniID, rkAttr.m_vWeaponInfoList, FTT_DASH_ATTACK, fTimeRate, dwPreDelay );
	IncreaseWeaponIndexBase();

	DWORD dwEndTime = m_pGroup->GetAnimationFullTime( iAniID );

	CheckCharColSkipTime( iAniID, fTimeRate, dwPreDelay );

	m_pGroup->ClearAllLoopAni( 100, true );
	m_pGroup->ClearAllActionAni( FLOAT100, true );
	m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fTimeRate );

	m_AnimationTime.dwStartTime = dwCurTime;
	m_AnimationTime.dwFullTime = dwEndTime * fTimeRate + dwPreDelay + rkAttr.m_dwEndDelay;

	m_dwBlowDashCheckTime = 0;

	float fValue = m_pGroup->GetAnimationEventTime_e( iAniID, "extra_ani_jump" ) * fTimeRate;
	if( fValue > 0.0f )
	{
		m_dwBlowDashCheckTime = dwCurTime + dwPreDelay;
		m_dwBlowDashCheckTime += fValue;
	}

	ForceInfoList vForceInfoList = rkAttr.m_vForceInfoList;
	SetReservedSliding( vForceInfoList, iAniID, fTimeRate, dwPreDelay );

	DWORD dwTrackingTime = dwCurTime + dwPreDelay;
	dwTrackingTime += m_pGroup->GetAnimationEventTime_e( iAniID, "tracking_e" ) * fTimeRate;
	SetAutoTargetTrackingEndTime( dwTrackingTime );

	SetBaseAttackExtraAniJump( iAniID, fTimeRate, dwPreDelay );

	if( IsJumpingState() )
		m_fCurSkillEndNextLandRate = m_fSkillEndNextLandRate;
}

void ioBaseChar::CheckBlowDashAttackState()
{
	DWORD dwCurTime = FRAMEGETTIME();

	switch( m_BlowDashState )
	{
	case BDS_BLOWING:
		{
			CheckExtraAniJump();

			// CheckLand
			bool bLanding = true;
			float fHeightGap = GetWorldPosition().y - GetBottomHeight();
			if( fHeightGap > 0.0f || ( !m_bCurFrameDrop && !IsDownState() ) ||
				(m_fCurJumpPowerAmt > 0.0f && m_fCurJumpPowerAmt > m_fGravityAmt) )
			{
				bLanding = false;
			}

			bool bChangeDownState = false;
			if( m_dwBlowDashCheckTime == 0 )
			{
				if( m_AnimationTime.EndTime() < dwCurTime )
					bChangeDownState = true;
			}
			else if( bLanding && m_dwBlowDashCheckTime < dwCurTime )
			{
				bChangeDownState = true;
			}

			if( bChangeDownState )
			{
				m_BlowDashState = BDS_DOWN;
				m_dwBlowDashCheckTime = dwCurTime;

				m_pGroup->ClearAllActionAni( FLOAT100, true );
				m_pGroup->ClearAllLoopAni( FLOAT100, true );

				int iAniID = m_pGroup->GetAnimationIdx( m_BlowDashInfo.m_BlowDashDownAni );
				if( iAniID != -1 )
					m_pGroup->SetLoopAni( iAniID, FLOAT100 );

				m_dwBlowDashCheckTime += m_BlowDashInfo.m_dwBlowDashDownDuration;
				return;
			}
		}
		break;
	case BDS_DOWN:
		if( CheckDownSkill() )	// 스킬로 전환
			return;

		if( m_dwBlowDashCheckTime > 0 && m_dwBlowDashCheckTime < dwCurTime )
		{
			m_BlowDashState = BDS_GETUP;
			m_dwBlowDashCheckTime = dwCurTime;

			m_pGroup->ClearAllActionAni( FLOAT100, true );
			m_pGroup->ClearAllLoopAni( FLOAT100, true );

			int iAniID = m_pGroup->GetAnimationIdx( m_BlowDashInfo.m_BlowDashGetUpAni );
			float fTimeRate = m_BlowDashInfo.m_fBlowDashGetUpAniRate;
			if( fTimeRate <= 0.0f )
				fTimeRate = FLOAT1;

			m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fTimeRate );
			m_dwBlowDashCheckTime += m_pGroup->GetAnimationFullTime( iAniID ) * fTimeRate;

			m_dwReserveEnableTime = 0;
			CheckKeyReserveTime( iAniID, fTimeRate );
			return;
		}
		else
		{
			// 공격키 체크
			if( IsNeedProcess() && IsAttackKey() )
			{
				ioUserKeyInput::DirKeyInput eDir = CheckCurDirKey();
				if( eDir != ioUserKeyInput::DKI_NONE )
				{
					float fYawD = 180.0f + 45.0f * ( eDir - ioUserKeyInput::DKI_UP );
					fYawD = ioMath::ArrangeHead( fYawD );

					float fYawR = DEGtoRAD( fYawD );
					D3DXQUATERNION qtRotate;
					D3DXQuaternionRotationYawPitchRoll( &qtRotate, fYawR, 0.0f, 0.0f );

					SetTargetRotToRotate( qtRotate, true, false );
				}

				m_BlowDashState = BDS_GETUP_ATTACK;
				m_dwBlowDashCheckTime = dwCurTime;

				SetAutoTarget( ATT_DASH );
				ClearReserveKeyInput();

				const AttackAttribute &rkAttr = m_BlowDashInfo.m_BlowDashGetUpAttack;

				int iAniID = m_pGroup->GetAnimationIdx( rkAttr.m_AttackAnimation );
				DWORD dwPreDelay = rkAttr.m_dwPreDelay;
				float fTimeRate = rkAttr.m_fAttackAniRate;
				if( fTimeRate <= 0.0f )
					fTimeRate = FLOAT1;

				RefreshFireTimeList( iAniID, rkAttr.m_vWeaponInfoList, FTT_DASH_ATTACK, fTimeRate, dwPreDelay );
				IncreaseWeaponIndexBase();

				DWORD dwEndTime = m_pGroup->GetAnimationFullTime( iAniID );

				m_pGroup->ClearAllLoopAni( 100, true );
				m_pGroup->ClearAllActionAni( FLOAT100, true );
				m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fTimeRate );

				ForceInfoList vForceInfoList = rkAttr.m_vForceInfoList;
				SetReservedSliding( vForceInfoList, iAniID, fTimeRate, dwPreDelay );

				DWORD dwTrackingTime = dwCurTime + dwPreDelay;
				dwTrackingTime += m_pGroup->GetAnimationEventTime_e( iAniID, "tracking_e" ) * fTimeRate;
				SetAutoTargetTrackingEndTime( dwTrackingTime );

				m_dwReserveEnableTime = 0;
				CheckKeyReserveTime( iAniID, fTimeRate );

				m_dwBlowDashCheckTime += dwEndTime * fTimeRate;

				if( IsNeedSendNetwork() )
				{
					SP2Packet kPacket( CUPK_BLOW_DASH );
					kPacket << GetCharName();
					kPacket << GetTargetRot();
					FillAutoTargetInfo( kPacket );
					P2PNetwork::SendToAllPlayingUser( kPacket );
				}

				return;
			}
		}
		break;
	case BDS_GETUP:
	case BDS_GETUP_ATTACK:
		if( m_dwBlowDashCheckTime > 0 && m_dwBlowDashCheckTime < dwCurTime )
		{
			ClearAttackFireTimeAndSkill();
			ClearReservedSliding();

			ProcessReserveKeyInput();
			return;
		}
		else
		{
			if( IsEnableReserveKeyInput() )
				CheckReserveKeyInput();
		}
		break;
	}
}

void ioBaseChar::ApplyBlowDash( SP2Packet &rkPacket )
{
	if( m_CharState != CS_BLOW_DASH_ATTACK )
		return;

	D3DXQUATERNION qtRot;
	rkPacket >> qtRot;

	SetTargetRotToRotate( qtRot, true, false );

	DWORD dwCurTime = FRAMEGETTIME();

	SetAutoTarget( ATT_DASH );
	ClearReserveKeyInput();

	m_BlowDashState = BDS_GETUP_ATTACK;
	m_dwBlowDashCheckTime = dwCurTime;

	const AttackAttribute &rkAttr = m_BlowDashInfo.m_BlowDashGetUpAttack;

	int iAniID = m_pGroup->GetAnimationIdx( rkAttr.m_AttackAnimation );
	DWORD dwPreDelay = rkAttr.m_dwPreDelay;
	float fTimeRate = rkAttr.m_fAttackAniRate;
	if( fTimeRate <= 0.0f )
		fTimeRate = FLOAT1;

	RefreshFireTimeList( iAniID, rkAttr.m_vWeaponInfoList, FTT_DASH_ATTACK, fTimeRate, dwPreDelay );
	IncreaseWeaponIndexBase();

	DWORD dwEndTime = m_pGroup->GetAnimationFullTime( iAniID );

	m_pGroup->ClearAllLoopAni( 100, true );
	m_pGroup->ClearAllActionAni( FLOAT100, true );
	m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fTimeRate );

	ForceInfoList vForceInfoList = rkAttr.m_vForceInfoList;
	SetReservedSliding( vForceInfoList, iAniID, fTimeRate, dwPreDelay );

	DWORD dwTrackingTime = dwCurTime + dwPreDelay;
	dwTrackingTime += m_pGroup->GetAnimationEventTime_e( iAniID, "tracking_e" ) * fTimeRate;
	SetAutoTargetTrackingEndTime( dwTrackingTime );

	m_dwReserveEnableTime = 0;
	CheckKeyReserveTime( iAniID, fTimeRate );

	m_dwBlowDashCheckTime += dwEndTime * fTimeRate;

	ApplyAutoTargetInfo( rkPacket );
}

