void ioBaseChar::ProcessRealComboResetCheck()
{
	return; 
    ioBaseChar *pOwnerChar = m_pCreator->GetOwnerChar();
	if( !pOwnerChar ) return;

	//방어 가능 상태가 되면 Owner의 콤보를 초기화한다.
	bool bDefensePossible = true;

	// 불가능한 상태
	switch( GetState() )
	{
	case CS_BLOW_WOUNDED:
	case CS_FROZEN:
	case CS_BOUND_BLOW_WOUNDED:
	case CS_GRAPPLING_WOUNDED:
	case CS_GRAPPLING_WOUNDED_SKILL:
	case CS_GRAPPLING_WOUNDED_SWING:
	case CS_BLOW_EXTEND_WOUND:
	case CS_JUMP_GRAPPLING_WOUNDED:
	case CS_ETC_STATE:
	case CS_CLOSEORDER:
	case CS_SKIP_STUN:
	case CS_ADHESIVE_BUFF:
	case CS_MAGIC_STUN:
	case CS_GRAPPLING_WOUNDED_ITEM:
	case CS_GRAPPLING_WOUNDED_BUFF:
		bDefensePossible = false;
		break;		
	}

	if( bDefensePossible )
	{
		// 애니 시점에 따라서 가능한 상태
		if( GetState() == CS_WOUNDED )
		{
			bDefensePossible = false;
			DWORD dwCurTime = FRAMEGETTIME();
			if( m_AnimationTime.EndTime() + m_dwActionStopTotalDelay > dwCurTime )
			{
				if( m_BlowTargetType != BTT_BLOW &&
					m_BlowTargetType != BTT_BLOW2 &&
					m_BlowTargetType != BTT_BLOW3 &&
					m_BlowTargetType != BTT_STAND_KO &&
					m_BlowTargetType != BTT_STAND_KO2 )
				{
					DWORD dwEnableTime = m_AnimationTime.dwStartTime;					
					if( dwEnableTime < dwCurTime )
					{
						dwEnableTime += m_AnimationTime.dwFullTime * m_fWoundedDefenseEnableRate;
						if( dwEnableTime < dwCurTime )
						{
							if( !m_bPrisonerMode && !m_bCatchState && !IsBuffLimitDefense() )
							{
								if( IsEnableDefenseByObject() )
								{
									bDefensePossible = true;
								}
							}
						}
					}
				}
			}
		}
	}	

	// 방어 가능한 상태면 콤보 해제
	if( bDefensePossible )
	{
		if( FRAMEGETTIME() - m_dwRealComboDefenseCheckTime < 100 )
			return;

		pOwnerChar->ResetRealComboHit( GetCharName() );
	}
	else
	{
		m_dwRealComboDefenseCheckTime = FRAMEGETTIME();
	}
}

void ioBaseChar::ProcessDefenceCounter( float fTimerPerSec )
{
	ioAttackableItem *pAttackable = GetPriorityItem( SPT_ATTACK );
	if( !pAttackable || !pAttackable->IsUseDefenceCounterAttack() )
	{
		SetState( CS_DELAY );
		return;
	}

	pAttackable->ProcessDefenceCounterAttack( this );

	ProcessMove( fTimerPerSec );
}

bool ioBaseChar::IsCanChargeComboJumpAttack( float fHeightGap )
{
	if( m_CurJumpType != JT_CHARGE_COMBO &&
		m_CurJumpType != JT_CHARGE_COMBO2 &&
		m_CurJumpType != JT_CHARGE_COMBO3 &&
		m_CurJumpType != JT_CHARGE_COMBO4 &&
		m_CurJumpType != JT_CHARGE_COMBO_DEFENSE &&
		m_CurJumpType != JT_GATOTKACA_JUMP &&
		m_CurJumpType != JT_SUDDEN_ATTACK_JUMP &&
		m_CurJumpType != JT_TRACE_JUMP &&
		m_CurJumpType != JT_JORO_EXPANSION_JUMP &&
		m_CurJumpType != JT_SABER_JUMP &&
		m_CurJumpType != JT_NATA_JUMP && 
		m_CurJumpType != JT_GRAPPLING_EXPANSION_JUMP &&
		m_CurJumpType != JT_STRIDER_JUMP &&
		m_CurJumpType != JT_SKY_WALKER_JUMP &&
		m_CurJumpType != JT_GWONWANG_JUMP &&	// 권왕 2020-06-03
		m_CurJumpType != JT_EVACOMBO_JUMP )	// 이브 2020-11-05
	{
		return false;
	}

	ioAttackableItem *pAttackable = GetPriorityItem( SPT_JUMP );
	if( !pAttackable )
		return false;

	if( IsBuffLimitAttack() )
		return false;

	ioChargeComboJump2 *pChargeCombo2_Tmp = ToChargeComboJump2( pAttackable->GetCurExtendJump() );
	ioTraceJump *pTraceJump = ToTraceJump( pAttackable->GetCurExtendJump() );
	ioGrapplingExpansionJump *pGrapplinExpansionJump = ToGrapplingExpansionJump( pAttackable->GetCurExtendJump() );
	ioGwonwangJump *pGwonwangJump = ToGwonwangJump( pAttackable->GetCurExtendJump() );	// 권왕 2020-06-03
	ioEvaComboJump *pEvaComboJump = ToEvaComboJump( pAttackable->GetCurExtendJump() );	// 이브 2020-11-13

	if( pGrapplinExpansionJump && pGrapplinExpansionJump->IsUsedHighJump() )
		return false;

	if( pGwonwangJump && pGwonwangJump->IsUsedHighJump() )	// 권왕 2020-06-03
		return false;

	if( m_iChangeJumppingLimit > 0 && m_iChangeJumppingLimit <= m_iChangeJumppingCnt )
	{
		//메이드 점프 때문에 추가
		if( pChargeCombo2_Tmp && pChargeCombo2_Tmp->IsCanMaxJumpAndChargeAttack() )
		{
			if( m_iChangeJumppingLimit > 0 && m_iChangeJumppingLimit < m_iChangeJumppingCnt )
				return false;
		}
		else if( pTraceJump && pTraceJump->IsCanMaxJumpAndChargeAttack( this ) )
		{
			if( m_iChangeJumppingLimit > 0 && m_iChangeJumppingLimit < m_iChangeJumppingCnt )
				return false;
		}
		else
			return false;
	}

	if( m_bCatchState || m_bPrisonerMode || m_bUsedJumpDefense || m_bUsedBuffJumpAttack || m_bUsedJumpReload )
	{
		return false;
	}

	// KeyCheck
	if( m_UsedBuffMultiFlyJump == BJUT_CUR )
	{
		if( !m_KeyInput.IsDefenseKeyDown() )
			return false;
	}
	else if( m_UsedBuffFlyJump == BJUT_CUR )
	{
		if( !m_KeyInput.IsAttackKeyDown() )
			return false;
	}
	else if( m_UsedBuffFlyJump == BJUT_WALK )
	{
		if( !m_KeyInput.IsAttackKeyDown() )
			return false;
	}
	else
	{
		if( !m_KeyInput.IsAttackKey() )
		{
			ioChargeComboJump *pChargeCombo = ToChargeComboJump( pAttackable->GetCurExtendJump() );
			ioChargeComboJump2 *pChargeCombo2 = ToChargeComboJump2( pAttackable->GetCurExtendJump() );
			ioChargeComboJump3 *pChargeCombo3 = ToChargeComboJump3( pAttackable->GetCurExtendJump() );
			ioChargeComboJump4 *pChargeCombo4 = ToChargeComboJump4( pAttackable->GetCurExtendJump() );
			ioChargeComboDefenseJump *pChargeComboDefense = ToChargeComboDefenseJump( pAttackable->GetCurExtendJump() );
			ioSuddenAttackJump *pSuddenJump = ToSuddenAttackJump( pAttackable->GetCurExtendJump() );
			ioTraceJump *pTraceJump = ToTraceJump( pAttackable->GetCurExtendJump() );
			ioGatotkacaJump *pGatotkacaJump = ToGatotkacaJump( pAttackable->GetCurExtendJump() );
			ioJoroExpansionJump *pJoroExpansionJump = ToJoroExpansionJump( pAttackable->GetCurExtendJump() );
			ioSaberJump *pSaberJump = ToSaberJump( pAttackable->GetCurExtendJump() );
			ioNataJump *pNataJump = ToNataJump( pAttackable->GetCurExtendJump() );
			ioSkyWalkerJump *pSkyWalkerJump = ToSkyWalkerJump( pAttackable->GetCurExtendJump() );

			if( pChargeCombo && !pChargeCombo->IsJumpAttackReserve() )
				return false;
			else if( pChargeCombo2 && !pChargeCombo2->IsJumpAttackReserve() )
				return false;
			else if( pGatotkacaJump && !pGatotkacaJump->IsJumpAttackReserve() )
				return false;
			else if( pChargeCombo3 && !pChargeCombo3->IsJumpAttackReserve() ) 
				return false;
			else if( pChargeCombo4 && !pChargeCombo4->IsJumpAttackReserve() )
				return false;
			else if( pChargeComboDefense && !pChargeComboDefense->IsJumpAttackReserve() )
				return false;
			else if( pSuddenJump && !pSuddenJump->IsJumpAttackReserve() )
				return false;
			else if( pTraceJump && !pTraceJump->IsJumpAttackReserve() )
				return false;
			else if( pJoroExpansionJump && !pJoroExpansionJump->IsJumpAttackReserve() )
				return false;
			else if( pSaberJump && !pSaberJump->IsJumpAttackReserve() )
				return false;
			else if( pNataJump && !pNataJump->IsJumpAttackReserve() )
				return false;
			else if( pGrapplinExpansionJump && !pGrapplinExpansionJump->IsJumpAttackReserve() )
				return false;
			else if( pSkyWalkerJump && !pSkyWalkerJump->IsJumpAttackReserve() )
				return false;
			else if( pGwonwangJump && !pGwonwangJump->IsJumpAttackReserve() )	// 권왕 2020-06-03
				return false;
			else if( pEvaComboJump && !pEvaComboJump->IsJumpAttackReserve() )	// 이브 2020-11-13
				return false;
		}
	}

	// check buff
	if( !CheckBuffJumpEnableAttack() )
		return false;

	if( IsChatModeState( true ) )
	{
		SetChatModeBox();
		return false;
	}

	if( ToDrinkItem( GetObject() ) )
		return false;

	float fEnableHeight = m_fMinJumpAttackEnableHeight;
	if( pAttackable )
	{
		float fItemEnableHeight = pAttackable->GetJumpAttackEnableHeight();
		if( fItemEnableHeight > 0.0f )
			fEnableHeight = fItemEnableHeight;
	}

	if( m_fCurJumpPowerAmt - m_fGravityAmt < 0.0f && fHeightGap < fEnableHeight )
	{
		return false;
	}

	DWORD dwCurTime = FRAMEGETTIME();
	DWORD dwEnableTime = m_dwMinJumpAttackEnableTime;
	if( pAttackable )
	{
		DWORD dwItemEnableTime = pAttackable->GetJumpAttackEnableTime();
		if( dwItemEnableTime > 0 )
			dwEnableTime = dwItemEnableTime;
	}

	if( m_dwJumpMoveStartTime > 0 && dwCurTime < m_dwJumpMoveStartTime + dwEnableTime )
		return false;

	if( pAttackable )
	{
		if( !pAttackable->IsCanJumpAttack( this ) )
		{
			return false;
		}

		if( !pAttackable->IsCanFire( this, 1 ) )
		{
			return false;
		}
	}
	else
	{
		if(	!m_bJumpAttackEnable )
		{
			return false;
		}
	}

	return true;
}

void ioBaseChar::InitExtendJumpAttackTagInfo()
{
	m_dwExtendJumpAttackEndTime = 0;
	m_fExtendJumpAttackEndJumpAmt = 0.0f;
}

void ioBaseChar::SetExtendJumpAttackEndJumpInfo( int iAniID, float fTimeRate, DWORD dwPreDelay )
{
	m_dwExtendJumpAttackEndTime = 0;
	m_fExtendJumpAttackEndJumpAmt = 0.0f;

	AniEventConstPtrList vAttackEndList;
	m_pGroup->GetAnimationEventConstPtrList( iAniID, "attack_end", vAttackEndList );

	if( vAttackEndList.empty() )
		return;

	DWORD dwCurTime = FRAMEGETTIME();

	AniEventConstPtrList::iterator iter = vAttackEndList.begin();
	while( iter != vAttackEndList.end() )
	{
		DWORD dwTime = (*iter)->fEventTime * fTimeRate;

		m_dwExtendJumpAttackEndTime = dwTime;
		m_dwExtendJumpAttackEndTime += dwCurTime;
		m_dwExtendJumpAttackEndTime += dwPreDelay;

		if( !(*iter)->szSubInfo.IsEmpty() )
		{
			const StringVector &vParam = ioStringConverter::Split( (*iter)->szSubInfo.c_str(), " " );
			if( vParam.size() == 1 )
			{
				m_fExtendJumpAttackEndJumpAmt = ioStringConverter::ParseFloat( vParam[0].c_str() );
			}
		}

		break;

		++iter;
	}
}

bool ioBaseChar::CheckExtendJumpAttackEndJump()
{
	DWORD dwCurTime = FRAMEGETTIME();

	if( m_dwExtendJumpAttackEndTime > 0 && m_dwExtendJumpAttackEndTime < dwCurTime )
	{
		if( IsJumpingState() )
			m_fCurSkillEndNextLandRate = m_fSkillEndNextLandRate;

		if( m_fExtendJumpAttackEndJumpAmt > 0.0f )
			SetSKillEndJumpState( m_fExtendJumpAttackEndJumpAmt, false, true );
		else
			SetSKillEndJumpState( 0.1f, false, true );

		m_dwExtendJumpAttackEndTime = 0;
		m_fExtendJumpAttackEndJumpAmt = 0.0f;

		return true;
	}

	return false;
}

ioSkill* ioBaseChar::GetCurActiveSkill()
{
	if( m_CharState != CS_USING_SKILL )
		return NULL;

	return m_pActiveSkill;
}

ioSkill* ioBaseChar::GetMustActiveSkill()
{
	return m_pActiveSkill;
}

bool ioBaseChar::CheckIceStateSkill()
{
	if( !IsNeedProcess() )
		return false;

	if( m_CharState != CS_FROZEN && m_CharState != CS_ICE_STATE )
	{
		return false;
	}

	// 충돌체 상황 체크
	if( !m_bEnableWoundSkill )
		return false;

	// 불가 버프 체크
	if( HasDisableSkillFlameBuff() )
	{
		return false;
	}

	// 스킬키 입력체크
	int iSkillNum = m_KeyInput.GetSkillInput();
	if( iSkillNum < 0 || IsBuffLimitSkill() )
		return false;

	// 스킬 존재체크
	ioSkill *pSkill = GetEquipedSkill( iSkillNum );
	if( !pSkill ) return false;

	// 페시브 스킬은 페스
	if( ToPassiveSkill( pSkill ) ) return false;

	// IceState중 사용가능한 스킬인지 체크
	if( !pSkill->IsCanIceStateSkill() )
		return false;

	SetUseSkill( iSkillNum, SUT_NORMAL );

	return true;
}

void ioBaseChar::CheckWoundCancelBuff( int iTypeID )
{
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		if( !pBuff )	continue;

		if( pBuff->GetTypeID() == iTypeID && pBuff->IsEnableWoundCancel() )
		{
			m_aBuffArray->Remove(i);
			pBuff->EndBuff();
			delete pBuff;
		}
	}
}

void ioBaseChar::CheckExtraCallBuff()
{
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioExtraCallBuff *pCallBuff = ToExtraCallBuff( pBuff );
		if( !pCallBuff )	continue;

		pCallBuff->SetReserveExtraCall();
	}
}

bool ioBaseChar::EnableDecoChangeByEquipItem( int iDecoType )
{
	if( iDecoType != UID_KINDRED )
		return true;

	for( int i=0; i<4; i++ )
	{
		if( m_pEquipSlot )
		{
			ioItem *pItem = m_pEquipSlot->GetEquipedItem( i );
			if( pItem && pItem->GetCharOnlySexType() != ioSetItemInfo::CST_ALL )
				return false;
		}
	}

	for( int i=ES_RING; i<MAX_EQUIP_SLOT; i++ )
	{
		if( m_pEquipSlot )
		{
			ioItem *pItem = m_pEquipSlot->GetEquipedItem( i );
			if( pItem && pItem->GetCharOnlySexType() != ioSetItemInfo::CST_ALL )
				return false;
		}
	}

	return true;
}

