void ioBaseChar::SetObjectEquipState( const AttackAttribute* pAttribute )
{
	if( !pAttribute )
		return;

	ioEntityGroup *pGrp	= GetGroup();
	if( !pGrp )
		return;

	int iAniID			= pGrp->GetAnimationIdx( pAttribute->m_AttackAnimation );
	float fTimeRate		= pAttribute->m_fAttackAniRate;
	DWORD dwPreDelay	= pAttribute->m_dwPreDelay;

	if( fTimeRate <= 0.0f )
		fTimeRate = FLOAT1;
		
	pGrp->ClearAllActionAni( FLOAT100, true );
	pGrp->ClearAllLoopAni( FLOAT100, true );	
	pGrp->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fTimeRate, 0.0f, 0.0f, true );

	m_AnimationTime.dwStartTime = FRAMEGETTIME();
	m_AnimationTime.dwFullTime  = m_pGroup->GetAnimationFullTime( iAniID ) * fTimeRate;

	SetObjectEquipJumpState( iAniID, fTimeRate, m_AnimationTime.dwStartTime, dwPreDelay );

	RefreshFireTimeList( iAniID, pAttribute->m_vWeaponInfoList, FTT_NORMAL_ATTACK, fTimeRate, dwPreDelay );
	IncreaseWeaponIndexBase();

	SetReservedSliding( pAttribute->m_vForceInfoList, iAniID, fTimeRate, dwPreDelay );

	SetState( CS_OBJECT_EQUIP );
}

void ioBaseChar::SetObjectEquipJumpState( int iAniID, float fTimeRate, DWORD dwStartTime, DWORD dwPreDelay )
{
	m_vObjectEquipAniJumpList.clear();

	AniEventConstPtrList vExtraAniJumpList;
	m_pGroup->GetAnimationEventConstPtrList( iAniID, "extra_ani_jump", vExtraAniJumpList );

	if( vExtraAniJumpList.empty() )
		return;
		
	AniEventConstPtrList::iterator iter = vExtraAniJumpList.begin();
	while( iter != vExtraAniJumpList.end() )
	{
		ExtraAniJump kInfo;
		kInfo.m_dwTime = (*iter)->fEventTime * fTimeRate;
		kInfo.m_dwTime += dwStartTime;
		kInfo.m_dwTime += dwPreDelay;

		if( !(*iter)->szSubInfo.IsEmpty() )
		{
			const StringVector &vParam = ioStringConverter::Split( (*iter)->szSubInfo.c_str(), " " );
			if( vParam.size() == 1 )
			{
				kInfo.m_fPower = ioStringConverter::ParseFloat( vParam[0].c_str() );
			}
		}

		m_vObjectEquipAniJumpList.push_back( kInfo );

		++iter;
	}
}

void ioBaseChar::CheckObjectEquipJump()
{
	if( m_vObjectEquipAniJumpList.empty() )
		return;

	float fJumpPower = 0.0f;
	DWORD dwCurTime = FRAMEGETTIME();
	for( vExtraAniJumpList::iterator iter = m_vObjectEquipAniJumpList.begin(); iter != m_vObjectEquipAniJumpList.end(); ++iter )
	{
		const ExtraAniJump& kInfo = *iter;
		if( kInfo.m_dwTime <= dwCurTime )
		{
			fJumpPower = kInfo.m_fPower;
			break;
		}
	}

	if( 0.0f < fJumpPower )
	{
		m_vObjectEquipAniJumpList.clear();
		SetSKillEndJumpState( fJumpPower );
	}
}

void ioBaseChar::CheckObjectEquipState()
{
	DWORD dwCurTime = FRAMEGETTIME();
	if( m_AnimationTime.EndTime() < dwCurTime && m_vReservedSlidingList.empty() )
	{
		SetState( CS_DELAY );
	}
}

