void ioBaseChar::ApplyPassiveGauge( SP2Packet &rkPacket )
{
	int iSlot;
	float fCurGauge;

	rkPacket >> iSlot;
	rkPacket >> fCurGauge;

	ioSkill *pSkill = GetEquipedSkill( iSlot );
	ioPassiveSkill *pPassiveSkill = ToPassiveSkill(pSkill);
	if( pPassiveSkill )
		pPassiveSkill->SetCurPassiveGauge( fCurGauge );

	// 패시브 게이지 관련 처리를 아래에 추가해 준다.
	bool bUsePassiveGhost = false;
	bool bUseActiveGhost = false;
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioGhostStateBuff *pGhostStateBuff = ToGhostStateBuff( pBuff );
		if( pGhostStateBuff )
		{
			if( pGhostStateBuff->CheckPassiveGauge() )
				bUsePassiveGhost = true;
			else if ( pGhostStateBuff->CheckDuration() )
				bUseActiveGhost = true;
			else
				m_bUseGhostState = false;
		}
	}
	if ( bUsePassiveGhost || bUseActiveGhost )
		m_bUseGhostState = true;
}

bool ioBaseChar::CheckSummonDummyChar( int iSubState )
{
	if( !IsNeedProcess() )
		return false;

	if( !EnableSummonDummyChar( iSubState ) )
		return false;

	ioAttackableItem *pAttackItem = GetWeapon();
	if( !pAttackItem )
		return false;

	SummonDummyChar* pInfo = pAttackItem->GetSummonDummyCharInfo( iSubState );
	if( !pInfo )
		return false;

	if( pInfo->m_DummyCharList.empty() )
		return false;

	ioAlterEgoItem *pAlterEgoItem = ToAlterEgoItem( pAttackItem );
	ioHadesItem *pHadesItem = ToHadesItem( pAttackItem );

	if( pAlterEgoItem )
	{
		int iNeedGauge = pInfo->m_iNeedGauge;
		if( pAlterEgoItem->GetCurBullet() < iNeedGauge )
			return false;

		pAlterEgoItem->DecreaseCoolTime( iNeedGauge );
	}
	else if( pHadesItem )
	{
		int iNeedGauge = pInfo->m_iNeedGauge;
		if( pHadesItem->GetCurBullet() < iNeedGauge )
			return false;

		pHadesItem->CheckDecreaseGauge();
	}

	int iCurCombo = pInfo->m_iCurCombo;
	if( iCurCombo < 0 || iCurCombo >= (int)pInfo->m_DummyCharList.size() )
		iCurCombo = 0;

	D3DXVECTOR3 vCreatePos = GetWorldPosition();
	D3DXVECTOR3 vDir = GetTargetRot() * D3DXVECTOR3( 0.0f, 0.0f, -FLOAT1 );
	D3DXVec3Normalize( &vDir, &vDir );

	D3DXVECTOR3 vSideDir;
	D3DXVec3Cross( &vSideDir, &ioMath::UNIT_Y, &vDir );
	D3DXVec3Normalize( &vSideDir, &vSideDir );

	ioHashString szDummyCharName = pInfo->m_DummyCharList[iCurCombo].m_DummyCharName;
	int iCurIndex = g_DummyCharMgr.GetCurLocalIndex();
	float fOffset = pInfo->m_DummyCharList[iCurCombo].m_fDummyCharOffset;
	float fSideOffset = pInfo->m_DummyCharList[iCurCombo].m_fDummyCharSideOffset;
	float fStartAngle = pInfo->m_DummyCharList[iCurCombo].m_fDummyCharStartAngle;

	D3DXVECTOR3 vTargetPos = vCreatePos + (fOffset * vDir);
	vTargetPos += fSideOffset * vSideDir;

	ioDummyChar *pDummy = m_pCreator->CreateDummyChar( szDummyCharName, iCurIndex,
													   GetCharName(),
													   vTargetPos,
													   fStartAngle,
													   0, true );

	if( pDummy )
	{
		m_dwSummonDummyCharTime = FRAMEGETTIME();

		pInfo->m_iCurCombo = iCurCombo + 1;

		if( pDummy->GetType() == DCT_NO_CONTROL )
			pDummy->SetWorldOrientation( m_qtTargetRot );

		if( IsNeedSendNetwork() )
		{
			SP2Packet kPacket( CUPK_CHAR_ACTION_INFO );
			kPacket << GetCharName();
			kPacket << CHAR_ACTION_DUMMY;

			kPacket << GetTargetRot();
			kPacket << szDummyCharName;
			kPacket << iCurIndex;
			kPacket << fStartAngle;
			kPacket << vTargetPos;

			P2PNetwork::SendToAllPlayingUser( kPacket );
		}

		return true;
	}

	return false;
}

void ioBaseChar::CheckInitSummonDummyChar( int iSubState )
{
	if( !IsNeedProcess() )
		return;

	ioAttackableItem *pAttackItem = GetWeapon();
	if( !pAttackItem )
		return;

	if( !pAttackItem->IsEnableSummonDummyChar() )
		return;

	SummonDummyChar* pInfo = pAttackItem->GetSummonDummyCharInfo( iSubState );
	if( !pInfo )
		return;

	if( pInfo->m_DummyCharList.empty() )
		return;

	pInfo->InitCombo();
}

void ioBaseChar::ApplySummonDummyChar( SP2Packet &rkPacket )
{
	D3DXQUATERNION qtRot;
	rkPacket >> qtRot;

	SetTargetRotToRotate( qtRot, true, false );

	int iCurIndex;
	ioHashString szDummyCharName;
	float fStartAngle;
	D3DXVECTOR3 vTargetPos;

	rkPacket >> szDummyCharName >> iCurIndex;
	rkPacket >> fStartAngle;
	rkPacket >> vTargetPos;

	ioDummyChar *pDummy = m_pCreator->CreateDummyChar( szDummyCharName, iCurIndex,
													   GetCharName(),
													   vTargetPos,
													   fStartAngle,
													   0, false );

	if( pDummy && pDummy->GetType() == DCT_NO_CONTROL )
		pDummy->SetWorldOrientation( m_qtTargetRot );
}

bool ioBaseChar::EnableSummonDummyChar( int iSubState )
{
	if( !IsNeedProcess() )
		return false;

	if( m_bCatchState || m_bPrisonerMode || m_bExcavating )
		return false;

	if( IsChatModeState( true ) )
		return false;

	ioAttackableItem *pAttackItem = GetWeapon();
	if( !pAttackItem )
		return false;

	if( !pAttackItem->IsEnableSummonDummyChar() )
		return false;

	// 가능 시간 체크
	DWORD dwCurTime = FRAMEGETTIME();
	DWORD dwGapTime = pAttackItem->GetSummonDummyCharGapTime();
	if( m_dwSummonDummyCharTime > 0 && m_dwSummonDummyCharTime+dwGapTime > dwCurTime  )
		return false;

	switch( iSubState )
	{
	case ioAttackableItem::SDT_DASH:
	case ioAttackableItem::SDT_DASH_ATT:
		return true;
	case ioAttackableItem::SDT_JUMP:
		if( m_CurJumpType == JT_CHARGE_COMBO2 || m_CurJumpType == JT_CHARGE_COMBO4 )
		{
			return true;
		}
		return true;
	case ioAttackableItem::SDT_JUMP_ATT:
		if( m_CurJumpType == JT_CHARGE_COMBO2 || m_CurJumpType == JT_CHARGE_COMBO4 || m_CurJumpType == JT_CHARGE_COMBO3 )
		{
			return true;
		}
		break;
	case ioAttackableItem::SDT_EXTEND_ATT:
		return true;
	case ioAttackableItem::SDT_NORMAL_ATT:
	case ioAttackableItem::SDT_COUNTER:
	case ioAttackableItem::SDT_NEW_JUMP_ATT:
		return true;
	default:
		return false;
	}

	return false;
}

void ioBaseChar::SetPanicMoveInfo( const FloatVec &rkAngleList,
								   const ioHashString &szMoveAni,
								   const ioHashString &szCatchMoveAni,
								   DWORD dwBaseSeed,
								   DWORD dwMinTime, DWORD dwMaxTime,
								   float fMoveSpeed )
{
	m_PanicMoveInfo.Init();

	m_PanicMoveInfo.m_AngleList = rkAngleList;
	m_PanicMoveInfo.m_MoveAni = szMoveAni;
	m_PanicMoveInfo.m_dwBaseSeed = dwBaseSeed;
	m_PanicMoveInfo.m_dwMoveMinTime = dwMinTime;
	m_PanicMoveInfo.m_dwMoveMaxTime = dwMaxTime;
	m_PanicMoveInfo.m_fMoveSpeed = fMoveSpeed;

	SetState( CS_PANIC_MOVE );

	int iAniID = m_pGroup->GetAnimationIdx( m_PanicMoveInfo.m_MoveAni );
	if( m_bPrisonerMode || m_bCatchState )
	{
		iAniID = m_pGroup->GetAnimationIdx( m_PanicMoveInfo.m_MoveAni );
	}

	m_pGroup->ClearAllLoopAni( FLOAT100, true );
	m_pGroup->ClearAllActionAni( FLOAT100, true );

	if( iAniID != -1 )
		m_pGroup->SetLoopAni( iAniID, FLOAT100 );

	m_dwNextPanicMoveTime = FRAMEGETTIME();
	m_fCurMoveSpeed = m_PanicMoveInfo.m_fMoveSpeed;
}

void ioBaseChar::CheckNextPanicMove()
{
	DWORD dwCurTime = FRAMEGETTIME();

	m_dwNextPanicMoveTime = dwCurTime;

	IORandom random;
	DWORD dwSeed = m_PanicMoveInfo.m_dwBaseSeed + m_PanicMoveInfo.m_iCurCount;

	random.SetRandomSeed( dwSeed );

	int iAngleRand = random.Random( m_PanicMoveInfo.m_AngleList.size() );
	float fCurAngle = m_PanicMoveInfo.m_AngleList[iAngleRand];

	D3DXVECTOR3 vCurDir = m_qtTargetRot * D3DXVECTOR3( 0.0f, 0.0f, -FLOAT1 );
	D3DXVec3Normalize( &vCurDir, &vCurDir );

	D3DXQUATERNION qtRot;
	D3DXQuaternionRotationAxis( &qtRot, &ioMath::UNIT_Y, DEGtoRAD(fCurAngle) );
	D3DXVECTOR3 vMoveDir = qtRot * vCurDir;
	D3DXVec3Normalize( &vMoveDir, &vMoveDir );

	D3DXQUATERNION qtTargetRot;
	ioMath::CalcDirectionQuaternion( qtTargetRot, vMoveDir );

	SetTargetRotAndMoveDirChange( qtTargetRot );

	DWORD dwCurMoveTime = m_PanicMoveInfo.m_dwMoveMinTime;
	if( m_PanicMoveInfo.m_dwMoveMaxTime > m_PanicMoveInfo.m_dwMoveMinTime )
	{
		DWORD dwGap = m_PanicMoveInfo.m_dwMoveMaxTime - m_PanicMoveInfo.m_dwMoveMinTime;
		int iTimeRand = random.Random( dwGap );
		dwCurMoveTime += iTimeRand;
	}

	m_dwNextPanicMoveTime += dwCurMoveTime;
	m_PanicMoveInfo.m_iCurCount++;
}

void ioBaseChar::CheckPanicMoveState()
{
	if( !HasBuff( BT_RANDOM_MOVE ) )
	{
		SetState( CS_DELAY );
		return;
	}

	DWORD dwCurTime = FRAMEGETTIME();
	if( m_dwNextPanicMoveTime < dwCurTime )
		CheckNextPanicMove();

	m_fCurMoveSpeed = m_PanicMoveInfo.m_fMoveSpeed;
}

