void ioBaseChar::CheckEnablePossessionState( const ioHashString &szTargetName )
{
	if( !CheckGrapplingExceptionState() )
		return;

	if( !IsNeedProcess() )
		return;

	ioPhantomItem *pPhantomItem = ToPhantomItem( GetPriorityItem( SPT_ATTACK ) );
	if( pPhantomItem && pPhantomItem->IsEnablePossessionState() )
		pPhantomItem->ChangePhantomFlyPossession( this, szTargetName );

	ioGhostItem *pGhostItem = ToGhostItem( GetPriorityItem( SPT_ATTACK ) );
	if( pGhostItem && pGhostItem->IsEnablePossessionState() )
		pGhostItem->ChangeGhostFlyPossession( this, szTargetName );
}

