bool ioBaseChar::CheckEnableDashAttEndDash()
{
	switch( m_DashAttackEndDash )
	{
	case DAET_NONE:
		return false;
	case DAET_NORMAL:
		if( !m_bSetExtraDashAttack && !m_bSetExtraOtherDashAttack &&
			( m_iCurExtraOtherDashAttack < GetExtraOtherDashAttackMax() ) )
		{
			return true;
		}
		break;
	case DAET_EXTRA:
		if( m_bSetExtraOtherDashAttack )
		{
			return false;
		}
		else if( (m_iCurExtraDashAttack < GetExtraDashAttackMax()) &&
				 (m_iCurExtraOtherDashAttack < GetExtraOtherDashAttackMax()) )
		{
			return true;
		}
		break;
	}

	return false;
}

