bool ioBaseChar::IsMachineTakeEnableState( bool bKey )
{
	bool bResult = true;

	if( m_CharState != CS_DELAY )
		bResult = false;

	if( m_bCatchState || m_bPrisonerMode )
		bResult = false;

	if( GetObject() )
		bResult = false;

	if( IsGangsi() )
		bResult = false;

	if( IsObejctEquipState() )
		bResult = false;
	
	if( m_pEquipSlot && m_pEquipSlot->IsEquipWait( ES_OBJECT ) )
		bResult = false;

	if( ToHookItem( GetWeapon() ) && ToHookItem( GetWeapon() )->CheckOnHand() )	// 폭탄 장착시에는 아이템을 집을수 없음
		bResult = false;

	if( ToGunnerItem( GetWeapon() ) && ToGunnerItem( GetWeapon() )->CheckOnHand() )	// 폭탄 장착시에는 아이템을 집을수 없음
		bResult = false;

	if( m_ChatModeState != CMS_NONE )
		bResult = false;

	return bResult;
}

