void ioBaseChar::SetCmdInputStart( int iType )
{
	ioChargeCommandItem *pCmdItem = ToChargeCommandItem( GetPriorityItem( SPT_ATTACK ) );
	ioNakoruruItem *pCmdItem2 = ToNakoruruItem( GetPriorityItem( SPT_ATTACK ) );
	ioParkilpyoItem *pParkilpyoItem = ToParkilpyoItem( GetWeapon() );
	ioAttackableItem *pAttackable = GetPriorityItem( SPT_ATTACK );
	ioGanesa *pGanesa = ToGanesa( GetPriorityItem( SPT_ATTACK ) );
	ioGalfordItem *pGalford = ToGalfordItem( GetPriorityItem( SPT_ATTACK ) );
	ioGunnerItem *pGunnerItem = ToGunnerItem( GetPriorityItem( SPT_ATTACK ) );
	ioMurimGosuItem *pMurim = ToMurimGosuItem( GetPriorityItem( SPT_ATTACK ) );
	ioMidnightItem* pMidnight = ToMidnightItem( GetPriorityItem( SPT_ATTACK ) );
	ioMidnightScytheObjectItem* pMidnightScythe = ToObjectMidnightScytheItem( GetPriorityItem( SPT_ATTACK ) );
	ioSkyWalkerItem *pSkyWalker = ToSkyWalkerItem( GetPriorityItem( SPT_ATTACK ) );

	if( pAttackable )
	{
		ioTrinityJump *pTrinityJump = ToTrinityJump( pAttackable->GetCurExtendJump() );
		if( pTrinityJump )
			pTrinityJump->SetSwallowInput( iType, this );
	}

	if( pCmdItem )
		pCmdItem->SetCmdInputStart( iType, this );
	else if( pCmdItem2 )
		pCmdItem2->SetCmdInputStart( iType, this );
	else if ( pParkilpyoItem )
		pParkilpyoItem->SetCmdInputStart( iType, this );
	else if( pGanesa )
		pGanesa->SetCmdInputStart( iType, this );
	else if ( pGalford )
		pGalford->SetCmdInputStart( iType, this );
	else if( pGunnerItem )
		pGunnerItem->SetCmdInputStart( iType, this );
	else if( pMurim )
		pMurim->SetCmdInputStart( iType, this );
	else if( pMidnight )
		pMidnight->SetCmdInputStart( iType, this );
	else if( pMidnightScythe )
		pMidnightScythe->SetCmdInputStart( iType, this );
}

