bool ioBaseChar::IsEnableReserveKeyInput()
{
	if( m_dwReserveEnableTime > 0 && m_dwReserveEnableTime + m_dwActionStopTotalDelay < FRAMEGETTIME() )
		return true;

	return false;
}

D3DXVECTOR3 ioBaseChar::GetAimTargetPos()
{
	D3DXVECTOR3 vTargetPos = ioMath::VEC3_ZERO;

	ioAttackableItem *pAttackItem = GetPriorityItem( SPT_ATTACK );
	if( !pAttackItem )
		return vTargetPos;

	ioBaseChar *pTarget = GetBaseChar( pAttackItem->GetAimedTarget() );
	if( pTarget )
	{
		vTargetPos = pTarget->GetMidPositionByRate();
	}

	return vTargetPos;
}

void ioBaseChar::SetCounterAttackByAttribute( const AttackAttribute &rkAttr )
{
	ClearReserveKeyInput();

	ioAttackableItem *pItem = GetPriorityItem( SPT_DEFENSE );

	int iAniID	     = m_pGroup->GetAnimationIdx( rkAttr.m_AttackAnimation );
	float fTimeRate  = rkAttr.m_fAttackAniRate;
	DWORD dwPreDelay = rkAttr.m_dwPreDelay;

	RefreshFireTimeList( iAniID,
						 rkAttr.m_vWeaponInfoList,
						 FTT_COUNTER_ATTACK,
						 fTimeRate,
						 dwPreDelay );

	m_pGroup->ClearAllLoopAni( FLOAT100, true );
	m_pGroup->ClearAllActionAni( FLOAT100, true );

	DWORD dwCurTime = FRAMEGETTIME();
	DWORD dwEndTime = m_pGroup->GetAnimationFullTime( iAniID );
	m_AnimationTime.dwStartTime = dwCurTime;
	m_AnimationTime.dwFullTime  = dwEndTime * fTimeRate + dwPreDelay;
	m_AnimationTime.dwFullTime += rkAttr.m_dwEndDelay;

	ClearInputCancelInfo();
	m_szInputCancelAni = m_pGroup->GetAnimationName( iAniID );
	m_fInputCancelAniRate = fTimeRate;

	m_dwCancelCheckTime = dwCurTime;
	m_dwInputCancelCheckTime = dwCurTime;

	CheckCharColSkipTime( iAniID, fTimeRate, dwPreDelay );

	int iEndAniID = m_pGroup->GetAnimationIdx( rkAttr.m_AttackEndAnimation );
	if( iEndAniID == -1 )
	{
		m_pGroup->SetActionAni( iAniID, FLOAT100, FLOAT100, FLOAT1, FLOAT1/fTimeRate, 0.0f, dwPreDelay, true );

		CheckKeyReserveTime( iAniID, fTimeRate, dwPreDelay );
	}
	else
	{
		m_pGroup->SetActionAni( iAniID, FLOAT100, 0.0f, FLOAT1, FLOAT1/fTimeRate, 0.0f, dwPreDelay );

		float fWaitTime = m_pGroup->GetAnimationFullTime( iAniID ) * fTimeRate + dwPreDelay;
		float fEndAniRate = rkAttr.m_fAttackEndAniRate;
		m_pGroup->SetActionAni( iEndAniID, 0.0f, FLOAT100, FLOAT1, 1.0/fEndAniRate, 0.0, 0.0f, true );

		m_AnimationTime.dwFullTime += m_pGroup->GetAnimationFullTime( iEndAniID ) * fEndAniRate;

		CheckKeyReserveTime( iEndAniID, fTimeRate, dwPreDelay );
		if( m_dwReserveEnableTime > 0 )
		{
			m_dwReserveEnableTime += m_AnimationTime.dwFullTime;
		}
	}

	if( pItem )
	{
		pItem->SetAniRotate( this, iAniID, fTimeRate );
	}

	SetReservedSliding( rkAttr.m_vForceInfoList, iAniID, fTimeRate, dwPreDelay );
	SetState( CS_COUNTER_ATTACK );
}

void ioBaseChar::ProcessDefaultCAT()
{
	DWORD dwCurTime = FRAMEGETTIME();
	if( m_AnimationTime.EndTime() + m_dwActionStopTotalDelay < dwCurTime )
	{
		ClearAttackFireTimeAndSkill();
		ClearReservedSliding();
	
		ProcessReserveKeyInput();
	}
	else
	{
		if( IsNeedProcess() )
		{
			CheckCancelReserve();
			
			ioAttackableItem *pItem = GetPriorityItem( SPT_DEFENSE );
			if( pItem && ToJoroExpansionItem( pItem ) )
			{
				if( ToJoroExpansionItem( pItem )->IsEnableGauge() && ProcessCancel() )
				{
					ToJoroExpansionItem( pItem )->DecreaseGauge( this );
					return;
				}		
			}
			else if( ProcessCancel() )
				return;

			// HARDCODE :: Check Cmd Input
			ioChargeCommandItem *pCmdItem = ToChargeCommandItem( GetPriorityItem( SPT_ATTACK ) );
			ioNakoruruItem *pCmdItem2 = ToNakoruruItem( GetPriorityItem( SPT_ATTACK ) );
			ioParkilpyoItem *pParkilpyoItem = ToParkilpyoItem( GetWeapon() );
			ioGanesa* pGanesa = ToGanesa( GetPriorityItem( SPT_ATTACK ) );
			ioGalfordItem *pGalford = ToGalfordItem( GetPriorityItem( SPT_JUMP ) );
			ioGunnerItem *pGunnerItem = ToGunnerItem( GetPriorityItem( SPT_ATTACK ) );
			ioMidnightItem* pMidnight = ToMidnightItem( GetPriorityItem( SPT_ATTACK ) );
			ioMidnightScytheObjectItem* pMidnightScythe = ToObjectMidnightScytheItem( GetPriorityItem( SPT_ATTACK ) );

			if( pCmdItem )
			{
				if( pCmdItem->CheckCmdInputState( this ) )
					return;

				if( pCmdItem->CheckSkillInputState( this ) )
					return;
			}
			else if( pCmdItem2 )
			{
				if( pCmdItem2->CheckCmdInputState( this ) )
					return;

				if( pCmdItem2->CheckSkillInputState( this ) )
					return;
			}
			else if( pParkilpyoItem )
			{
				if( pParkilpyoItem->CheckCmdInputState( this ) )
					return;
			}
			else if( pGanesa )
			{
				if( pGanesa->CheckCmdInputState( this ) )
					return;

				if( pGanesa->CheckSkillInputState( this ) )
					return;
			}
			else if ( pGalford )
			{
				if( pGalford->CheckCmdInputState( this ) )
					return;
			}
			else if( pGunnerItem )
			{
				if( pGunnerItem->CheckCmdInputState( this ) )
					return;
			}
			else if( pMidnight )
			{
				if( pMidnight->CheckCmdInputState( this ) )
					return;
			}
			else if( pMidnightScythe )
			{
				if( pMidnightScythe->CheckCmdInputState( this ) )
					return;
			}
		}

		if( IsEnableReserveKeyInput() )
			CheckReserveKeyInput();

		ioAttackableItem *pItem = GetPriorityItem( SPT_DEFENSE );
		if( pItem )
		{
			pItem->CheckAniRotate( this );
		}
	}
}

void ioBaseChar::CheckCurCounterType()
{
	m_CurCAT = m_DefaultCAT;

	ioAttackableItem *pItem = GetPriorityItem( SPT_DEFENSE );
	if( pItem )
	{
		m_CurCAT = pItem->GetCounterAttackType();
	}
}

ioCounterAttack* ioBaseChar::CreateCounterAttack( ioINILoader &rkLoader )
{
	int iType = rkLoader.LoadInt_e( "counter_type", CAT_NONE );
	m_DefaultCAT = CAT_NONE;

	ioCounterAttack *pCounter = NULL;
	switch( iType )
	{
	case CAT_DEFAULT:
		pCounter = new ioDefaultCounter;
		break;
	case CAT_CHARGE:
		pCounter = new ioChargeCounter;
		break;
	case CAT_EXTRA:
		pCounter = new ioExtraCounter;
		break;
	case CAT_CHARGE_COMBO:
		pCounter = new ioChargeComboCounter;
		break;
	}

	if( pCounter )
	{
		pCounter->LoadProperty( rkLoader );
	}

	return pCounter;
}

void ioBaseChar::ApplyCounterAttack( SP2Packet &rkPacket )
{
	ioAttackableItem *pItem = GetPriorityItem( SPT_DEFENSE );
	if( pItem )
	{
		int iType;
		float fCurHP;
		rkPacket >> iType;

		if( pItem->GetCurCounterAttack() )
		{
			if( pItem->GetCurCounterAttack()->GetType() != iType )
				return;
		}

		rkPacket >> fCurHP;
		SetCurHP( fCurHP );

		pItem->ApplyCounterAttack( this, rkPacket );
	}
}

