void ioBaseChar::RemoveDisableRecoverySkillGaugeBuff( ioHashString szBuffName )
{
	ioHashStringVec::iterator iter = std::find( m_szDisableRecoverySkillGaugeBuffList.begin(),
												m_szDisableRecoverySkillGaugeBuffList.end(),
												szBuffName );

	if( iter != m_szDisableRecoverySkillGaugeBuffList.end() )
	{
		m_szDisableRecoverySkillGaugeBuffList.erase( iter );
	}	
}

bool ioBaseChar::IsBuffLimitAttack() const
{
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioLimitActionBuff *pLimitBuff = ToLimitActionBuff( pBuff );
		if( pLimitBuff && pLimitBuff->IsLimitAttack() )
			return true;
	}

	return false;
}

