bool ioBaseChar::IsBuffLimitSkill() const
{
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		ioLimitActionBuff *pLimitBuff = ToLimitActionBuff( pBuff );
		if( pLimitBuff && pLimitBuff->IsLimitSkill() )
		{
			if( pLimitBuff->EnableOwnerItemSkill() && m_pEquipSlot )
			{
				int iSkillNum = m_KeyInput.GetSkillInput();
				if( iSkillNum >= 0 )
				{
					ioSkill *pSkill = m_pEquipSlot->GetEquipedSkill( iSkillNum );
					if( pSkill && pLimitBuff->GetSkillName() == pSkill->GetName() )
					{
						return false;
					}
				}
			}

			return true;
		}
	}

	return false;
}

