bool ioBaseChar::IsEquipEnableObject()
{
	if( !CheckGrapplingExceptionState() )
		return false;

	switch( m_CharState )
	{
	case CS_USING_SKILL:
	case CS_FLY:
		return false;
	}

	if( ToHookItem( GetWeapon() ) && ToHookItem( GetWeapon() )->CheckOnHand() )
		return false;

	if( ToGunnerItem( GetWeapon() ) && ToGunnerItem( GetWeapon() )->CheckOnHand() )
		return false;

	if( IsHasCrown() )
		return false;

	if( IsGangsi() )
		return false;

	if( GetObject() )
		return false;

	if( m_pEquipSlot->IsEquipWait( ES_OBJECT ) )
		return false;

	if( m_bPrisonerMode || m_bCatchState )
		return false;

	if( m_iEtcItemSkeleton != 0 )
		return false;

	if( m_bDisableEquipObject )
		return false;

	return true;
}

void ioBaseChar::CheckUseExtraGauge( float fAmt )
{
	ioYuMiRaItem *pYuMiRa = ToYuMiRaItem( m_pEquipSlot->GetWeapon() );
	if( pYuMiRa && pYuMiRa->IsGPState() )
		pYuMiRa->SetUseExtraGauge( fAmt );

	ioJinMoRiItem *pJinMoRi = ToJinMoRiItem( m_pEquipSlot->GetWeapon() );
	if( pJinMoRi && pJinMoRi->IsGPState() )
		pJinMoRi->SetUseExtraGauge( fAmt );

	ioAliceItem *pAlice = ToAliceItem( m_pEquipSlot->GetWeapon() );
	if( pAlice && pAlice->IsEquipObject( this ) )
		pAlice->SetUseExtraGauge( fAmt );
}

void ioBaseChar::FillGPStateInfo( SP2Packet &rkPacket )
{
	ioYuMiRaItem *pYuMiRa = ToYuMiRaItem( GetWeapon() );
	if( pYuMiRa )
		rkPacket << pYuMiRa->GetCurExtraGauge();

	ioJinMoRiItem *pJinMoRi = ToJinMoRiItem( GetWeapon() );
	if( pJinMoRi )
		rkPacket << pJinMoRi->GetCurExtraGauge();
}

void ioBaseChar::SetGPStateInfo( SP2Packet &rkPacket )
{
	float fCurExtraGauge;
	rkPacket >> fCurExtraGauge;

	ioYuMiRaItem *pYuMiRa = ToYuMiRaItem( GetWeapon() );
	if( pYuMiRa )
	{
		pYuMiRa->SetCurExtraGauge( fCurExtraGauge );
		pYuMiRa->ApplyUseGPState( this );
	}

	ioJinMoRiItem *pJinMoRi = ToJinMoRiItem( GetWeapon() );
	if( pJinMoRi )
	{
		pJinMoRi->SetCurExtraGauge( fCurExtraGauge );
		pJinMoRi->ApplyUseGPState( this );
	}
}

void ioBaseChar::ApplyGPState( SP2Packet &rkPacket )
{
	int iType;
	rkPacket >> iType;

	float fCurExtraDamage;
	rkPacket >> fCurExtraDamage;

	ioYuMiRaItem *pYuMiRa = ToYuMiRaItem( m_pEquipSlot->GetWeapon() );
	if( pYuMiRa )
	{
		switch( iType )
		{
		case GP_STATE_SET:
			{
				pYuMiRa->SetCurExtraGauge( fCurExtraDamage );
				pYuMiRa->SetUseGPState( this );
			}
			break;
		case GP_STATE_RELEASE:
			{
				pYuMiRa->SetCurExtraGauge( fCurExtraDamage );
				pYuMiRa->ReleaseGPState( this );
			}
			break;
		}
	}

	ioJinMoRiItem *pJinMoRi = ToJinMoRiItem( m_pEquipSlot->GetWeapon() );
	if( pJinMoRi )
	{
		switch( iType )
		{
		case GP_STATE_SET:
			{
				pJinMoRi->SetCurExtraGauge( fCurExtraDamage );
				pJinMoRi->SetUseGPState( this );
			}
			break;
		case GP_STATE_RELEASE:
			{
				pJinMoRi->SetCurExtraGauge( fCurExtraDamage );
				pJinMoRi->ReleaseGPState( this );
			}
			break;
		}
	}
}

bool ioBaseChar::IsGPState()
{
	ioYuMiRaItem *pYuMiRa = ToYuMiRaItem(m_pEquipSlot->GetWeapon());
	if( pYuMiRa && pYuMiRa->IsGPState() )
		return true;

	ioJinMoRiItem *pJinMoRi = ToJinMoRiItem(m_pEquipSlot->GetWeapon());
	if( pJinMoRi && pJinMoRi->IsGPState() )
		return true;

	return false;
}

void ioBaseChar::ReleaseGPState()
{
	ioYuMiRaItem *pYuMiRa = ToYuMiRaItem(m_pEquipSlot->GetWeapon());
	if( pYuMiRa )
		pYuMiRa->ReleaseGPState( this );

	ioJinMoRiItem *pJinMoRi = ToJinMoRiItem(m_pEquipSlot->GetWeapon());
	if( pJinMoRi )
		pJinMoRi->ReleaseGPState( this );
}

ObjectEqipState ioBaseChar::GetCurrObjectEquipState()
{
	ObjectEqipState eCurrState = OES_NONE;
	ioWeaponItem *pWeapon = m_pEquipSlot->GetWeapon();
	if( pWeapon )
	{
		switch( pWeapon->GetSubType() )
		{
		case ioWeaponItem::WST_WEREWOLF:
			{
				ioAttackableItem *pAttackable = ToAttackableItem( pWeapon );
				if( pAttackable && pAttackable->IsWereWolfState() )
					eCurrState = OES_WEREWOLF;
			}
			break;
		case ioWeaponItem::WST_YUMIRA_ITEM:
			{
				ioYuMiRaItem *pYuMiRa = ToYuMiRaItem( pWeapon );
				if( pYuMiRa && pYuMiRa->IsGPState() )
					eCurrState = OES_GP;
			}
			break;
		case ioWeaponItem::WST_JINMORI_ITEM:
			{
				ioJinMoRiItem *pJinMoRi = ToJinMoRiItem( pWeapon );
				if( pJinMoRi && pJinMoRi->IsGPState() )
					eCurrState = OES_GP;
			}
			break;
		case ioWeaponItem::WST_GALAXY_ITEM:
			{
				ioGalaxyItem *pGalaxyItem = ToGalaxyItem( pWeapon );
				if( pGalaxyItem && pGalaxyItem->IsEquipObject( this ) )
					eCurrState = OES_GALAXY;
			}
			break;
		case ioWeaponItem::WST_THUNDER_BIRD_ITEM:
			{
				ioThunderBirdItem *pThunderBirdItem = ToThunderBirdItem( pWeapon );
				if( pThunderBirdItem && pThunderBirdItem->IsEquipObject( this ) )
					eCurrState = OES_THUNDER_BIRD;
			}
			break;
		case ioWeaponItem::WST_ALICE_ITEM:
			{
				ioAliceItem *pAliceItem = ToAliceItem( pWeapon );
				if( pAliceItem && pAliceItem->IsEquipObject( this ) )
					eCurrState = OES_ALICE;
			}
			break;
		case ioWeaponItem::WST_PARKILPYO_ITEM:
			{
				ioParkilpyoItem *pParkilpyoItem = ToParkilpyoItem( pWeapon );
				if( pParkilpyoItem && pParkilpyoItem->IsEquipObject( this ) )
					eCurrState = OES_PARKILPYO;
			}
			break;
		case ioWeaponItem::WST_DARKKNIGHT_ITEM:
			{
				ioDarkKnightItem *pDarkKnight = ToDarkKnightItem( pWeapon );
				if( pDarkKnight && pDarkKnight->IsEquipObject( this ) )
					eCurrState = OES_DARKKNIHT;
			}
			break;
		case ioWeaponItem::WST_ONIMUSHA_ITEM:
			{
				ioOniMushaItem *pOniMushaItem = ToOniMushaItem( pWeapon );
				if( pOniMushaItem && pOniMushaItem->IsEquipObject( this ) )
					eCurrState = OES_ONIMUSHA;
			}
			break;
		case ioWeaponItem::WST_DRUID:
			{
				ioDruidItem *pDruidItem = ToDruidItem( pWeapon );
				if( pDruidItem && pDruidItem->IsEquipObject( this ) )
					eCurrState = OES_DRUID;
			}
			break;
		case ioWeaponItem::WST_BUBBLE_ITEM:
		case ioWeaponItem::WST_CHANGE_ON_ITEM:
		case ioWeaponItem::WST_DR_SPIDER_ITEM:
			{
				ioAttackableItem *pAttackable = ToAttackableItem( pWeapon );
				if( pAttackable && pAttackable->IsWereWolfState() )
					eCurrState = OES_WEREWOLF;
			}
			break;
		case ioWeaponItem::WST_MIDNIGHT_ITEM:
			{
				ioMidnightItem *pMidnightItem = ToMidnightItem( pWeapon );
				if( pMidnightItem && pMidnightItem->IsEquipScytheObject( this ) )
					eCurrState = OES_MIDNIGHT_SCYTHE;
				else if( pMidnightItem && pMidnightItem->IsEquipGunObject( this ) )
					eCurrState = OES_MIDNIGHT_GUN;
			}
			break;
		}
	}

	return eCurrState;
}

bool ioBaseChar::IsObejctEquipState( ObjectEqipState eState )
{
	ObjectEqipState eCurrState = GetCurrObjectEquipState();
	if( eState == OES_ALL && eCurrState != OES_NONE )
		return true;
	else if( eState != OES_ALL && eState != OES_NONE && eCurrState == eState )
		return true;

	return false;
}

void ioBaseChar::ReleaseObejctEquipState( ObjectEqipState eState )
{
	ObjectEqipState eCurrState = GetCurrObjectEquipState();
	if( eCurrState == eState || eState == OES_ALL )
	{
		ioWeaponItem *pWeaponItem = m_pEquipSlot->GetWeapon();
		ioAttackableItem *pAttackable = ToAttackableItem( pWeaponItem );
		if( pAttackable )
			pAttackable->ReleseWereWolfState( this );

		ioYuMiRaItem *pYuMiRa = ToYuMiRaItem( pWeaponItem );
		if( pYuMiRa )
			pYuMiRa->ReleaseGPState( this );

		ioJinMoRiItem *pJinMoRi = ToJinMoRiItem( pWeaponItem );
		if( pJinMoRi )
			pJinMoRi->ReleaseGPState( this );

		ioGalaxyItem *pGalaxyItem = ToGalaxyItem( pWeaponItem );
		if( pGalaxyItem )
			pGalaxyItem->ReleaseObject( this );

		ioThunderBirdItem *pThunderBirdItem = ToThunderBirdItem( pWeaponItem );
		if( pThunderBirdItem )
			pThunderBirdItem->ReleaseObject( this );

		ioAliceItem *pAliceItem = ToAliceItem( pWeaponItem );
		if( pAliceItem && pAliceItem->IsEquipObject( this ) )
			pAliceItem->ReleaseObject( this );

		ioParkilpyoItem *pParkilpyoItem = ToParkilpyoItem( pWeaponItem );
		if( pParkilpyoItem )
			pParkilpyoItem->ReleaseObject( this );

		ioDarkKnightItem *pDarkKnight = ToDarkKnightItem( pWeaponItem );
		if( pDarkKnight && pDarkKnight->IsEquipObject( this ) )
			pDarkKnight->ReleaseObject( this );

		ioOniMushaItem *pOniMushaItem = ToOniMushaItem( pWeaponItem );
		if( pOniMushaItem )
			pOniMushaItem->ReleaseObject( this );
	}
}

const bool ioBaseChar::IsSkipState() const
{
	// CS_SKIP_STUN 과 같이 모든 프로세스(이동,낙하,충돌)를 무시하는 상태 체크.
	switch( m_CharState )
	{
	case CS_USING_SKILL:
		if( m_pActiveSkill && m_pActiveSkill->IsSkipState() )
			return true;
		break;
	case CS_BATTLE_WAITING:
		return true;
	}

	return false;
}

const bool ioBaseChar::HasHideBuff()
{
	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		if( pBuff )
		{
			if( pBuff->GetTypeID() == BT_HIDE || pBuff->GetTypeID() == BT_HIDE4 )
				return true;

			ioHide2Buff *pHide2Buff = ToHide2Buff( pBuff );
			if( pHide2Buff && pHide2Buff->IsHideState() )
				return true;

			ioHide3Buff *pHide3Buff = ToHide3Buff( pBuff );
			if( pHide3Buff && pHide3Buff->IsHideState() )
				return true;

			ioCreateDummyCharBuff *pCreateDummy = ToCreateDummyCharBuff( pBuff );
			if( pCreateDummy && pCreateDummy->GetAlphaRate() < FLOAT1 )
				return true;

			ioFlyJumpBuff *pFlyJumpBuff = ToFlyJumpBuff( pBuff );
			if( pFlyJumpBuff && pFlyJumpBuff->IsHideState() )
				return true;

			ioTargetDummyBuff *pTargetDummy = ToTargetDummyBuff( pBuff );
			if( pTargetDummy && pTargetDummy->GetAlphaRate() < FLOAT1 )
				return true;
				
			ioNoWoundBuff *pNoWoundBuff = ToNoWoundBuff( pBuff );
			if ( pNoWoundBuff && pNoWoundBuff->IsInvisibleState() )
				return true;

			ioDummyChainBuff *pDummyChainBuff = ToDummyChainBuff( pBuff );
			if( pDummyChainBuff && pDummyChainBuff->IsHideState() )
				return true;

			ioCreateWeaponBuff *pCreateWeaponBuff = ToCreateWeaponBuff( pBuff );
			if( pCreateWeaponBuff && pCreateWeaponBuff->IsHideState() )
				return true;
		}
	}

	return false;
}

