bool ioBaseChar::CheckTargetWoundType( TargetWoundType eType )
{
	// 쓰러짐 관련 체크
	if( eType == TWT_AIR_WOUND_EXCEPT ) // 쓰러짐중 공중상태는 패스
	{
		if( IsApplyDownState() && !IsApplyDownState(false) )
			return false;
	}
	else if( eType == TWT_DOWN_WOUND_EXCEPT ) // 쓰러짐중 바닥상태는 패스
	{
		if( IsApplyDownState(false) )
			return false;
	}
	else if( eType == TWT_ALL_WOUND_EXCEPT )
	{
		if( IsApplyDownState() )
			return false;
	}
	else if( eType == TWT_FLOATING_STATE )	// 공중에 뜬 상태가 아니면 패스
	{
		if( !IsFloating() )
			return false;
	}
	else if( eType == TWT_DOWN_WOUNDED ) //바닥에 쓰러져 있지 않거나 공중에 뜬 상태면 패스
	{
		if( !IsApplyDownState() || IsFloating() )
			return false;
	}

	return true;
}

void ioBaseChar::ProcessJumpBuffOnDoubleJumpBuff()
{
	if( GetState() != CS_JUMP || m_JumpState != JS_JUMPPING || m_UsedBuffJump != BJUT_CUR )
	{
		RemoveJumpBuffOnDoubleJumpBuff();
	}
}

void ioBaseChar::SetJumpBuffOnDoubleJumpBuff()
{
	if( !m_bSetBuffOnDoubleJumpBuff )
		return;

	if( m_vBuffOnDoubleJumpBuff.empty() )
		return;

	if( m_vBuffJumpInfoList.empty() )
		return;

	m_bSetBuffOnDoubleJumpBuff = false;

	ioBuff *pBuff = GetBuff( m_vBuffJumpInfoList[0].m_Name );
	ioDoubleJumpBuff *pDoubleJumpBuff = ToDoubleJumpBuff( pBuff );
	if( !pDoubleJumpBuff )
		return;
	
	DWORD dwSeed = pDoubleJumpBuff->GetRandomSeed();
	IORandom eRandom;
	eRandom.SetRandomSeed( dwSeed );
	int iValue = eRandom.Random( (int)m_vBuffOnDoubleJumpBuff.size() );

	if( m_vBuffOnDoubleJumpBuff[iValue].m_bLive && !HasBuff( m_vBuffOnDoubleJumpBuff[iValue].m_BuffName ) )
	{
		for( int i=ES_WEAPON; i < MAX_EQUIP_SLOT; ++i )
		{
			ioPassiveSkill *pPassiveSkill = ToPassiveSkill( GetEquipedSkill(i) );

			if( pPassiveSkill && pPassiveSkill->GetName() == pDoubleJumpBuff->GetSkillName() &&
				pPassiveSkill->GetCurPassiveGauge() >= pDoubleJumpBuff->GetBuffOnJumpingEnableGauge() )
			{
				AddNewBuff( m_vBuffOnDoubleJumpBuff[iValue].m_BuffName, GetCharName(), "", NULL, false );
			}
		}
	}
}

void ioBaseChar::SetJumpBuffOnDoubleJumpBuffName( ioHashStringVec vBuffList )
{
	RemoveJumpBuffOnDoubleJumpBuff();

	int iCnt = vBuffList.size();
	for( int i=0; i<iCnt; ++i )
	{
		BuffOnDoubleJumpBuff kBuffInfo( vBuffList[i], true );
		m_vBuffOnDoubleJumpBuff.push_back( kBuffInfo );
	}
}

void ioBaseChar::SetJumpBuffOnDoubleJumpBuffEnd()
{
	if( m_vBuffOnDoubleJumpBuff.empty() )
		return;

	int iCnt = m_vBuffOnDoubleJumpBuff.size();
	for( int i=0; i<iCnt; ++i )
	{
		m_vBuffOnDoubleJumpBuff[i].m_bLive = false;
	}
}

void ioBaseChar::RemoveJumpBuffOnDoubleJumpBuff()
{
	if( m_vBuffOnDoubleJumpBuff.empty() )
		return;

	int iCnt = m_vBuffOnDoubleJumpBuff.size();
	for( int i=0; i<iCnt; ++i )
	{
		if( HasBuff( m_vBuffOnDoubleJumpBuff[i].m_BuffName ) )
		{
			RemoveBuff( m_vBuffOnDoubleJumpBuff[i].m_BuffName, true );
		}
	}

	vBuffOnDoubleJumpBuff::iterator iter = m_vBuffOnDoubleJumpBuff.begin();
	while( iter != m_vBuffOnDoubleJumpBuff.end() )
	{
		BuffOnDoubleJumpBuff kBuffInfo = *iter;
		if( !kBuffInfo.m_bLive )
		{
			iter = m_vBuffOnDoubleJumpBuff.erase( iter );
		}
		else
		{
			++iter;
		}
	}
}

void ioBaseChar::SetBuffMultiFlyJump()
{
	if( m_vBuffMultiFlyJumpInfoList.empty() )
		return;

	DWORD dwCurTime = FRAMEGETTIME();

	int iCurMaxCnt = m_vBuffMultiFlyJumpInfoList[0].m_iBuffJumpMaxCnt;
	
	m_iBuffJumpCurCnt++;

	if( m_iBuffJumpCurCnt < iCurMaxCnt )
		m_UsedBuffMultiFlyJump = BJUT_USED;
	else
		m_UsedBuffMultiFlyJump = BJUT_CUR;

	float fRate = 0.0f;
	int iIndex = -1;
	int iIndex2 = -1;

	float fJumpPower = 0.0f;
	float fForcePower = 0.0f;

	D3DXVECTOR3 vJumpDir;
	CheckBuffJumpAniIndex( m_vBuffMultiFlyJumpInfoList[0], iIndex, iIndex2, fRate, vJumpDir, fJumpPower, fForcePower );

	if( IsNeedSendNetwork() )
	{
		SP2Packet kPacket( CUPK_BUFF_MULTI_FLY );
		kPacket << GetCharName();
		kPacket << m_UsedBuffMultiFlyJump;
		kPacket << vJumpDir;
		kPacket << iIndex;
		kPacket << iIndex2;
		kPacket << fRate;
		kPacket << GetTargetRot();

		kPacket << fJumpPower;
		kPacket << fForcePower;
		kPacket << m_vBuffMultiFlyJumpInfoList[0].m_bEnableMoveRotate;
		kPacket << m_vBuffMultiFlyJumpInfoList[0].m_dwMoveRotateSpeed;
		kPacket << (int)m_CurDirKey;
		
		P2PNetwork::SendToAllPlayingUser( kPacket );
	}
}

void ioBaseChar::SetBuffMultiFlyJumpEnd()
{
	int iAniID = GetJumppingAnimationIdx();
	m_pGroup->ClearAllActionAni( FLOAT100, true );
	m_pGroup->SetActionAni( iAniID,	0.0f, 0.0f, FLOAT1, FLOAT1,	0.0f, 0.0f,	true );

	if( !IsDisableEquipObject() )
		m_UsedBuffMultiFlyJump = BJUT_END;

	if( IsNeedSendNetwork() )
	{
		SP2Packet kPacket( CUPK_BUFF_MULTI_FLY );
		kPacket << GetCharName();
		kPacket << m_UsedBuffMultiFlyJump;
		P2PNetwork::SendToAllPlayingUser( kPacket );
	}
}

bool ioBaseChar::IsCanBuffMultiFlyJump( float fHeightGap )
{
	DWORD dwCurTime = FRAMEGETTIME();

	if( m_vBuffMultiFlyJumpInfoList.empty() )
		return false;

	if( m_bCatchState || m_bPrisonerMode || !m_KeyInput.IsJumpKeyPress() ||
		m_bUsedJumpDefense || m_bUsedJumpAttack ||
		m_bUsedJumpReload ||
		m_bUsedBuffJumpAttack )
		return false;
	
	if( m_KeyInput.IsAttackKey() || m_KeyInput.IsDefenseKey() )
		return false;

	if( m_KeyInput.IsAttackKeyPress() || m_KeyInput.IsDefenseKeyPress() )
		return false;

	if( m_KeyInput.GetSkillInput() >= 0 )
		return false;

	if( IsBuffLimitExtendJump() )
		return false;

	// 왕관에 대한 예외처리 필요.
	if( !HasBuff( BT_BUFF_MULTI_FLY_JUMP ) || IsHasCrown() )
		return false;

	ioHookItem *pHook = ToHookItem( GetWeapon() );
	ioGunnerItem *pGunnerItem = ToGunnerItem( GetWeapon() );
	if( (pHook && pHook->CheckOnHand()) || (pGunnerItem && pGunnerItem->CheckOnHand()) )
		return false;

	int iCurMaxCnt = m_vBuffMultiFlyJumpInfoList[0].m_iBuffJumpMaxCnt;
	DWORD dwEnableTime = m_vBuffMultiFlyJumpInfoList[0].m_dwBuffJumpEnableTime;
	float fEnableHeight = m_vBuffMultiFlyJumpInfoList[0].m_fBuffJumpHeight;

	if( (m_UsedBuffMultiFlyJump != BJUT_NONE) && m_iBuffJumpCurCnt >= iCurMaxCnt )
		return false;

	ioAttackableItem *pAttackable = GetPriorityItem( SPT_JUMP );
	if( pAttackable && pAttackable->CheckUseExtendJump( this ) )
		return false;

	bool bMulti = false;
	if( m_iBuffJumpCurCnt < (iCurMaxCnt-1) )
		bMulti = true;

	if( pAttackable && bMulti )
	{
		ioGatotkacaJump *pGatotkaca = ToGatotkacaJump( pAttackable->GetCurExtendJump() );
		if( pGatotkaca && pGatotkaca->IsUsedChargeFly() )
			return false;

		ioIljimaeJump *pIljimae = ToIljimaeJump( pAttackable->GetCurExtendJump() );
		if( pIljimae )
		{
			if( pIljimae->IsUsedTeleport() )
			{
				return false;
			}
		}
	}

	if( m_dwBuffJumpTime == 0 )
	{
		if( dwCurTime - m_dwJumpMoveStartTime < dwEnableTime )
			return false;
	}
	else
	{
		if( dwCurTime - m_dwBuffJumpTime < dwEnableTime )
			return false;
	}

	if( m_fCurJumpPowerAmt - m_fGravityAmt < 0.0f && fHeightGap < fEnableHeight )
		return false;

	return true;
}

void ioBaseChar::SetDispelBuff( int iGoodBadType, ioBuff *pBuff )
{
	if( !pBuff || iGoodBadType == ioBuff::GBT_NONE )
		return;

	for( int i=0; i < m_aBuffArray->MaxCount(); ++i )
	{
		ioBuff *pTargetBuff = m_aBuffArray->GetAt(i);
		if( pBuff == pTargetBuff )
			continue;

		if( pTargetBuff && pTargetBuff->GetGoodBadType() == iGoodBadType )
		{
			pTargetBuff->SetReserveEndBuff();
		}
	}
}

