void ioBaseChar::SetTargetControlState( int iState )
{
	ioPlayStage* pStage = GetCreator();
	if( !pStage )
		return;

	if( HasBuff( BT_TARGET_CONTROL ) )
		return;

	const BaseCharList& rkList = pStage->GetBaseCharList();
	for( BaseCharList::const_iterator iter = rkList.begin(); iter != rkList.end(); ++iter )
	{
		ioBaseChar* pChar = *iter;
		if( !pChar )
			continue;

		ioBuff* pBuff = pChar->GetBuff( BT_TARGET_CONTROL );
		if( !pBuff )
			continue;

		if( pBuff->GetCreatorName() != GetCharName() )
			continue;

		if( this == pChar )
			continue;

		switch( iState )
		{
		case CS_RUN:
			{
				switch( pChar->GetState() )
				{
				case CS_DELAY:				
					{
						pChar->SetState( CS_RUN );
					}
					break;
				}				
			}
			break;
		case CS_ATTACK:
			{
				switch( pChar->GetState() )
				{				
				case CS_DELAY:
				case CS_RUN:
					{
						pChar->SetNormalAttack( 0 );
					}
					break;
				}
			}
			break;
		case CS_JUMP:
			{
				switch( pChar->GetState() )
				{
				case CS_DELAY:
				case CS_RUN:
					{
						pChar->SetJumpState();
					}
					break;
				}
			}
			break;
		default:
			{
				switch( pChar->GetState() )
				{
				case CS_RUN:
				case CS_ATTACK:
				case CS_JUMP:
					pChar->SetState( CS_DELAY );
				}
			}
			break;
		}
	}
}

void ioBaseChar::CheckReflectDameage( bool bContactType, bool bStructWeapon, ioBaseChar* pAttacker, ioWeapon* pWeapon )
{
	if( bStructWeapon )
		return;

	if( !pAttacker )
		return;

	if( !pWeapon )
		return;

	//Reflect Demeage
	ioBuff* pBuff = GetBuff( BT_REFLECT_DAMAGE );
	if( !pBuff )
		return;
	
	ioReflectDamageBuff* pDameageBuff = ToReflectDamageBuff( pBuff );
	if( !pDameageBuff )
		return;
		
	if( m_CharState == CS_BLOW_WOUNDED || m_CharState == CS_BOUND_BLOW_WOUNDED || m_CharState == CS_BLOW_EXTEND_WOUND )
		return;

	if( !pDameageBuff->GetAirReflect() && IsFloating() )
		return;

	bool bEnableReflect = false;
	if( pDameageBuff->GetEnableEscapeCatchAttackReflect() && pWeapon->GetEnableEscapeCatchType() )
		bEnableReflect = true;
	else if( bContactType )
		bEnableReflect = true;

	if( !bEnableReflect )
		return;

	DWORD dwWeaponIndex = IncreaseWeaponIndexBase() + 1;
	D3DXVECTOR3 vPos = pAttacker->GetMidPositionByRate();
		
	const WeaponInfo& rkReflectAttack = pDameageBuff->GetReflectAttack( pWeapon->GetDamage( this ) );

	D3DXVECTOR3 vDir = GetWorldPosition() - pAttacker->GetWorldPosition();
	D3DXVec3Normalize( &vDir, &vDir );

	if( 0 < rkReflectAttack.m_iWeaponIdx )
		ReflectFireExplicit( rkReflectAttack, vPos, dwWeaponIndex, pAttacker->GetCharName(), pDameageBuff->GetName(), vDir );
}

//Reflect 이펙트 고정 때문에 추가 (jch)
void ioBaseChar::CreateReflectEffect()
{
	int iReflectIndex = GetReflectInfoIndex( m_AttackedSide );

	if( !m_pCreator )
		return;

	if( iReflectIndex < 0 || (int)m_vReflectInfoList.size() <= iReflectIndex )
		return;

	// 이펙트 적용
	m_pCreator->CreateMapEffect( m_vReflectInfoList[iReflectIndex]->m_ReflectEffect,
		GetMidPositionByRate(),
		GetWorldScale() );
};

bool ioBaseChar::IsHasBuffCheckCreator( ioHashString szBuffName, ioHashString szCreator ) const
{
	if ( szBuffName.IsEmpty() || szCreator.IsEmpty() )
		return false;

	for( int i=0 ; i<m_aBuffArray->MaxCount() ; i++ )
	{
		ioBuff *pBuff = m_aBuffArray->GetAt(i);
		if( pBuff )
		{
			if( pBuff->GetName() == szBuffName && pBuff->GetCreatorName() == szCreator )
				return true;
		}
	}

	return false;
}

void ioBaseChar::UsePassiveSkillGauge( ioHashString szSkillName, float fUseGauge )
{
	if ( szSkillName.IsEmpty() || fUseGauge == 0.0f )
		return;

	for( int i=0; i < 4; i++ )
	{
		ioSkill *pSkill = NULL;
		if( m_pEquipSlot )
			pSkill = m_pEquipSlot->GetEquipedSkill( i );

		ioPassiveSkill *pPassiveSkill = ToPassiveSkill( pSkill );
		if( pPassiveSkill && pPassiveSkill->GetName() == szSkillName )
		{
			pPassiveSkill->ReduceCurPassiveGauge( fUseGauge );
		}
	}
}

float ioBaseChar::GetPassiveSkillGaugeRate( ioHashString szSkillName )
{
	if ( szSkillName.IsEmpty() )
		return 0.0f;

	for( int i=0; i < 4; i++ )
	{
		ioSkill *pSkill = NULL;
		if( m_pEquipSlot )
			pSkill = m_pEquipSlot->GetEquipedSkill( i );

		ioPassiveSkill *pPassiveSkill = ToPassiveSkill( pSkill );
		if( pPassiveSkill && pPassiveSkill->GetName() == szSkillName )
		{
			return pPassiveSkill->GetCurPassiveGaugeRate();
		}
	}

	return 0.0f;
}

//위치를 기준(거리)으로 무기 리스트를 얻는다 (서든 어택 때 추가)
void ioBaseChar::GetTargetWeaponListBySphere( const D3DXVECTOR3 &vPos,
	float fRange,
	float fAngle,
	TargetWeaponList &vWeaponList )
{
	vWeaponList.clear();

	float fRangeSq = fRange * fRange;
	float fHalfCosine = cosf( DEGtoRAD( fAngle ) * FLOAT05 );
	D3DXVECTOR3 vCollisionDir = GetTargetRot() * D3DXVECTOR3( 0.0f, 0.0f, -FLOAT1 );

	ioWeaponManager::WeaponIterator kIter = g_WeaponMgr.GetWeaponIterator();
	while( kIter.HasMoreElements() )
	{
		ioWeapon *pWeapon = kIter.Next();
		//무기 상태 확인
		if ( !pWeapon || !pWeapon->IsLive() )
			continue;

		D3DXVECTOR3 vDir = pWeapon->GetPosition() - vPos;
		
		float fLengthSq = D3DXVec3LengthSq( &vDir );
		if ( fLengthSq > fRangeSq )
			continue;
		
		D3DXVec3Normalize( &vDir, &vDir );

		if( D3DXVec3Dot( &vCollisionDir, &vDir ) >= fHalfCosine )
		{
			vWeaponList.push_back( pWeapon );
		}
	}
}

//위치를 기준(거리)으로 더미 리스트를 얻는다 (서든 어택 때 추가)
void ioBaseChar::GetTargetDummyListBySphere( const D3DXVECTOR3 &vPos,
	float fRange,
	float fAngle,
	TargetDummyList &vDummyList )
{
	vDummyList.clear();

	float fRangeSq = fRange * fRange;
	float fHalfCosine = cosf( DEGtoRAD( fAngle ) * FLOAT05 );
	D3DXVECTOR3 vCollisionDir = GetTargetRot() * D3DXVECTOR3( 0.0f, 0.0f, -FLOAT1 );

	std::vector< ioDummyChar* > vList = g_DummyCharMgr.GetDummyCharList();

	std::vector< ioDummyChar* >::iterator iter = vList.begin();
	for ( ; iter != vList.end() ; iter++ )
	{
		ioDummyChar *pDummyChar = *iter;
		//더미 상태 확인
		if ( !pDummyChar || pDummyChar->GetState() == DCS_DIE )
			continue;

		D3DXVECTOR3 vDir = pDummyChar->GetWorldPosition() - vPos;

		float fLengthSq = D3DXVec3LengthSq( &vDir );
		if ( fLengthSq > fRangeSq )
			continue;

		D3DXVec3Normalize( &vDir, &vDir );

		if( D3DXVec3Dot( &vCollisionDir, &vDir ) >= fHalfCosine )
		{
			vDummyList.push_back( pDummyChar );
		}
	}
}

