//펫 능력치 적용
void ioBaseChar::GetPetGrowth( int &nGrowthLevel, bool bCharGrowth, int nGrowthArray ) const
{
	CurPetInfo sCurPetInfo;
	if ( !m_pCreator || 
		 !m_pCreator->GetCurPetInfo( m_Name, sCurPetInfo ) )
		return;

	if ( sCurPetInfo.m_nPetCode <= 0 )
		return;

	if( m_pModeParent->GetModeType() == MT_ARENA )
		return;

	if( bCharGrowth )
	{
		if( COMPARE( nGrowthArray, 0, MAX_CHAR_GROWTH ) )
			nGrowthLevel += g_PetInfoMgr.GetTotalStat( sCurPetInfo.m_nPetCode, nGrowthArray, sCurPetInfo.m_nCurLevel );

		if( ToGangsiMode( m_pModeParent ) && nGrowthArray == 2 )
			nGrowthLevel = 0;
	}
	else
	{
		if( COMPARE( nGrowthArray, 0, MAX_ITEM_GROWTH ) )
			nGrowthLevel += g_PetInfoMgr.GetTotalStat( sCurPetInfo.m_nPetCode, nGrowthArray + MAX_ITEM_GROWTH, sCurPetInfo.m_nCurLevel );
	}

	if( nGrowthLevel < 0 )
		nGrowthLevel = 0;
}

