void ioBaseChar::UpdateMoveDir2BYTE()
{
	//dir >> 각도 >> 255맵핑
	D3DXVECTOR2 v1( m_vMoveDir.x, m_vMoveDir.z );
	D3DXVECTOR2 vUP( 0.f, -FLOAT1 );
	float vDot = D3DXVec2Dot( &vUP, &v1 );
	float vCCW = D3DXVec2CCW( &vUP, &v1 );	
	float radian = acosf( vDot );
	float angle = RADtoDEG( radian );
	if( vCCW > 0.f )
		angle = 180.f + (180.f - angle);
	//반올림
	int iAangle = angle += FLOAT05;
	m_byAngleMoveDir = ConvertAngle2Byte( iAangle );
}

void ioBaseChar::UpdateInputDir2BYTE()
{
	D3DXVECTOR2 v1( m_vInputDir.x, m_vInputDir.z );
	D3DXVECTOR2 vUP( 0.f, -FLOAT1 );
	float vDot = D3DXVec2Dot( &vUP, &v1 );
	float vCCW = D3DXVec2CCW( &vUP, &v1 );	
	float radian = acosf( vDot );
	float angle = RADtoDEG( radian );
	if( vCCW > 0.f )
		angle = 180.f + (180.f - angle);
	int iAangle = angle += FLOAT05;
	m_byAngleInputDir = ConvertAngle2Byte( iAangle );
}

void ioBaseChar::UpdateForceDir2BYTE()
{
	D3DXVec3Normalize( &m_vForceDir, &m_vForceDir );

	m_byAngleForceDirX = CompactFNormalized( m_vForceDir.x );
	m_byAngleForceDirY = CompactFNormalized( m_vForceDir.y );
	m_byAngleForceDirZ = CompactFNormalized( m_vForceDir.z );
}

