void ioBaseChar::SetAttackBuffGrapplingState( const ioHashString &szTarget, int nBuffType )
{
	if( !CheckGrapplingExceptionState() )
		return;

	ioBuff *pBuff = GetBuff( nBuffType );
	if( pBuff )
	{
		if( !pBuff->SetBuffGrapplingState( this, szTarget ) )
			return;

		m_GrapplingTarget = szTarget;
	}
}

bool ioBaseChar::SetBuffGrapplingState( const ioHashString &szAttacker, GrapplingSkillWoundedInfo kWoundedInfo )
{
	if( !CheckGrapplingExceptionState() )
		return false;

	if( m_CharState != CS_WOUNDED &&
		m_CharState != CS_BLOW_WOUNDED &&
		m_CharState != CS_BOUND_BLOW_WOUNDED &&
		m_CharState != CS_BLOW_EXTEND_WOUND )
	{
		return false;
	}

	m_GrapplingAttacker.Clear();
	m_GrapplingTarget.Clear();
	m_GrapplingSkillName.Clear();

	m_GrapplingAttacker = szAttacker;

	m_SkillGrapplingInfo.Init();
	m_SkillGrapplingInfo = kWoundedInfo;

	SetState( CS_GRAPPLING_WOUNDED_BUFF );

	m_GrapplingSkillState = GSS_LOOP;

	ioBaseChar *pAttacker = GetBaseChar( szAttacker );
	if( !pAttacker ) 
		return false;
	
	float fAniRate = m_SkillGrapplingInfo.m_fGrapplingLoopMotionRate;

	int iAniID = m_pGroup->GetAnimationIdx( m_SkillGrapplingInfo.m_GrapplingLoopMotion );
	if( iAniID == -1 )
		return false;

	m_pGroup->ClearAllActionAni( FLOAT100, true );
	m_pGroup->ClearAllLoopAni( FLOAT100, true );
	m_pGroup->SetLoopAni( iAniID, FLOAT100, FLOAT1, FLOAT1/fAniRate );

	return true;
}

void ioBaseChar::CheckGrapplingBuffState()
{
	ioBaseChar *pAttacker = GetBaseChar( m_GrapplingAttacker );
	if( !pAttacker )
	{
		m_GrapplingAttacker.Clear();

		BlowWoundAniInfo kInfo;
		SetBlowWoundedState( true, kInfo );
		return;
	}
	else if( pAttacker->GetState() == CS_FLY_BUFF_EXTRA_ATTACK )
	{
		ProcessBuffWoundGrapplingLoop( pAttacker, BT_FLY_JUMP_EXTRA_ATTACK );
	}
	else
	{
		m_GrapplingAttacker.Clear();

		BlowWoundAniInfo kInfo;
		SetBlowWoundedState( true, kInfo );
		return;
	}
}

void ioBaseChar::ProcessBuffWoundGrapplingLoop( ioBaseChar *pAttacker, int nBuffType )
{
	if( !pAttacker )
		return;

	D3DXVECTOR3 vPos = pAttacker->GetGrapplingBuffGapPosition( nBuffType );
	if( vPos == ioMath::VEC3_ZERO )
		return;

	D3DXQUATERNION qtBaseRot = pAttacker->GetTargetRot();
	D3DXQUATERNION qtTargetRot = qtBaseRot;

	if( m_SkillGrapplingInfo.m_bReverseTargetRot )
	{
		D3DXVECTOR3 vDir = qtBaseRot * D3DXVECTOR3( 0.0f, 0.0f, -FLOAT1 );

		D3DXQUATERNION qtRot;
		D3DXQuaternionRotationYawPitchRoll( &qtRot, DEGtoRAD(180.0f), 0.0f, 0.0f );
		vDir = qtRot * vDir;

		ioMath::CalcDirectionQuaternion( qtTargetRot, -vDir );
	}

	SetTargetRotToRotate( qtTargetRot, true, false );
	SetWorldPosition( vPos );
}

D3DXVECTOR3 ioBaseChar::GetGrapplingBuffGapPosition( int nBuffType )
{
	ioBuff *pBuff = GetBuff( nBuffType );
	if ( pBuff )
		return pBuff->GetGrapplingTargetPos( this );

	return ioMath::VEC3_ZERO;
}

bool ioBaseChar::IsEnableJumpAttack()
{
	ioFlyJumpExtraAttackBuff *pFlyJumpExtraAttackBuff = ToFlyJumpExtraAttackBuff( GetBuff( BT_FLY_JUMP_EXTRA_ATTACK ) );
	if ( pFlyJumpExtraAttackBuff && pFlyJumpExtraAttackBuff->CheckSpecialState( this ) )
		return false;

	ioJumpAttackBuff* pJumpAttackBuff = ToJumpAttackBuff( GetBuff(BT_BUFF_JUMP_ATTACK) );
	if ( pJumpAttackBuff && pJumpAttackBuff->CheckEnableJumpAttackState( this ) )
		return false;

	return true;
}

